#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SENSITIVITY 0.040 // 40mV/A
#define SUPPLY_VOLTAGE 4.096 // 4.096V
#define OFFSET 0.0 // Zero current offset

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to write a 16-bit value to the ADS1115
int write_config(int handle, int reg, int value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    int result = i2cWriteI2CBlockData(handle, reg, buf + 1, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_conversion(int handle, int reg) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading conversion register: %d\n", result);
        return -1;
    }

    return ((buf[0] << 8) | buf[1]);
}

// Function to calculate current from ADC value
double calculate_current(int adc_value) {
    double voltage = (double)adc_value * SUPPLY_VOLTAGE / 32768.0; // 16-bit ADC
    double current = (voltage - OFFSET) / SENSITIVITY;
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-shot mode, AIN0, PGA = ±4.096V, 128 SPS
    // 0x8000: Start single-conversion, 0x4000: AIN0 single-ended, 0x0200: PGA = ±4.096V, 0x0060: 128 SPS
    if (write_config(i2c_handle, CONFIG_REG, 0x8000 | 0x4000 | 0x0200 | 0x0060) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger single conversion by writing to the config register again
        if (write_config(i2c_handle, CONFIG_REG, 0x8000 | 0x4000 | 0x0200 | 0x0060) < 0) {
            fprintf(stderr, "Error triggering conversion.\n");
            break;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        gpioDelay(10); // 10ms delay

        // Read conversion register
        int adc_value = read_conversion(i2c_handle, CONVERSION_REG);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            break;
        }

        // Calculate current
        double current = calculate_current(adc_value);

        // Log current to console
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500); // 500ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

