#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CSV_FILE "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Reads the flame sensor's digital output
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Reads the analog value from the specified MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculates the temperature based on the ADC value
float calculate_temperature(int adc_value) {
    return 10.0 + (float)adc_value * (40.0 - 10.0) / 1023.0;
}

// Logs the data to a CSV file
int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file for writing\n");
        return -1;
    }

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        float temperature = 0.0;

        if (adc_value >= 0) {
            temperature = calculate_temperature(adc_value);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value, skipping logging.\n");
            flame_detected = -1; // Indicate error
        }

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

