#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000
#define ADS1115_CONFIG_PGA_4_096V 0x0040
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADC_VREF 4.096
#define TEMP_MIN 20.0
#define TEMP_MAX 80.0
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_TIME_MS 50
#define BUZZER_DURATION_S 2

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;
static uint32_t last_flame_time = 0;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_temperature_sensor();
void log_event(const char *message);
void activate_buzzer();
void deactivate_buzzer();
void flame_detected_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set pull-up resistor on flame sensor GPIO
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register ISR for flame sensor
    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_detected_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to read the temperature sensor
int read_temperature_sensor() {
    uint16_t config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS;
    char buf[3];
    int16_t raw_value;
