#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Configuration
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000 // 1 MHz
#define DEFAULT_SPI_MODE SPI_MODE_0
#define DEFAULT_SPI_BITS_PER_WORD 8
#define DEFAULT_SENSOR_SENSITIVITY 0.1 // 100 mV/A
#define DEFAULT_CURRENT_THRESHOLD 5.0 // 5.0 A
#define DEFAULT_FAN_GPIO 18
#define DEFAULT_LOG_FILE "current_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold configuration parameters
typedef struct {
    char *spi_device;
    uint32_t spi_speed;
    uint8_t spi_mode;
    uint8_t spi_bits_per_word;
    double sensor_sensitivity;
    double current_threshold;
    int fan_gpio;
    char *log_file;
} config_t;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
double adc_to_current(int adc_value, double sensitivity);
int control_fan(int gpio_chip_num, int gpio_line_num, double current, double threshold);
int log_data(const char *timestamp, double current);
void signal_handler(int sig);
int setup_gpio(int chip_num, int line_num);
void cleanup_gpio(void);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = DEFAULT_SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = DEFAULT_SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }

    return 0;
}

// ADC to current conversion function
double adc_to_current(int adc_value, double sensitivity) {
    return (double)adc_value * sensitivity / 1023.0;
}

// Fan control function
int control_fan(int gpio_chip_num, int gpio_line_num, double current, double threshold) {
    if (current > threshold) {
        if (gpiod_line_set_value(fan_line, 1) < 0) {
            perror("Failed to set fan line value");
            return -1;
        }
        printf("Fan ON (Current: %.2f A, Threshold: %.2f A)\n", current, threshold);
    } else {
        if (gpiod_line_set_value(fan_line, 0) < 0) {
            perror("Failed to set fan line value");
            return -1;
        }
        printf("Fan OFF (Current: %.2f A, Threshold: %.2f A)\n", current, threshold);
    }
    return 0;
}

// Data logging function
int log_data(const char *timestamp, double current) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized.\n");
        return -1;
    }

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// GPIO setup function
int setup_gpio(int chip_num, int line_num) {
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip_num);

    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", chip_name, strerror(errno));
        return -1;
    }

    fan_line = gpiod_chip_get_line(gpio_chip, line_num);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", line_num, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(int argc, char *argv[]) {
    config_t config = {
        .spi_device = DEFAULT_SPI_DEVICE,
        .spi_speed = DEFAULT_SPI_SPEED,
        .spi_mode = DEFAULT_SPI_MODE,
        .spi_bits_per_word = DEFAULT_SPI_BITS_PER_WORD,
        .sensor_sensitivity = DEFAULT_SENSOR_SENSITIVITY,
        .current_threshold = DEFAULT_CURRENT_THRESHOLD,
        .fan_gpio = DEFAULT_FAN_GPIO,
        .log_file = DEFAULT_LOG_FILE
    };

    int opt;
    while ((opt = getopt(argc, argv, "s:t:g:l:")) != -1) {
        switch (opt) {
            case 's':
                config.sensor_sensitivity = atof(optarg);
                break;
            case 't':
                config.current_threshold = atof(optarg);
                break;
            case 'g':
                config.fan_gpio = atoi(optarg);
                break;
            case 'l':
                config.log_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold] [-g gpio] [-l logfile]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize SPI
    spi_fd = open(config.spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t spi_mode = config.spi_mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits_per_word = config.spi_bits_per_word;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = config.spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed hz");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio(0, config.fan_gpio) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpio();
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
        uint8_t rx_buf[3];

        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Check for sensor absence (all-zero or all-ones)
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or disconnected. ADC value: %d. Retrying in 1 second.\n", adc_value);
            sleep(1);
            continue;
        }

        double current = adc_to_current(adc_value, config.sensor_sensitivity);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        if (log_data(timestamp, current) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Control fan
        if (control_fan(0, config.fan_gpio, current, config.current_threshold) < 0) {
            fprintf(stderr, "Failed to control fan.\n");
        }

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    cleanup_gpio();
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

