                config.current_threshold = atof(optarg);
                break;
            case 'g':
                config.fan_gpio = atoi(optarg);
                break;
            case 'l':
                config.log_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold] [-g gpio] [-l logfile]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize SPI
    spi_fd = open(config.spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t spi_mode = config.spi_mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits_per_word = config.spi_bits_per_word;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = config.spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed hz");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio(0, config.fan_gpio) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpio();
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
        uint8_t rx_buf[3];

        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Check for sensor absence (all-zero or all-ones)
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or disconnected. ADC value: %d. Retrying in 1 second.\n", adc_value);
            sleep(1);
            continue;
        }

        double current = adc_to_current(adc_value, config.sensor_sensitivity);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        if (log_data(timestamp, current) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Control fan
        if (control_fan(0, config.fan_gpio, current, config.current_threshold) < 0) {
            fprintf(stderr, "Failed to control fan.\n");
        }

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    cleanup_gpio();
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

