#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CO_CHANNEL 0 // MICS-4514 CO element
#define NO2_CHANNEL 1 // MICS-4514 NO2 element
#define SENSITIVITY 0.1 // PPM/V (example value, calibrate for your sensor)
#define OFFSET 0.5 // PPM (example value, calibrate for your sensor)
#define LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t co_raw;
    int16_t no2_raw;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int16_t read_ads1115_channel(int channel);
float calculate_ppm(int16_t raw_value);
void log_ppm(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from specified ADS1115 channel
int16_t read_ads1115_channel(int channel) {
    uint8_t config[3];
    int16_t raw_value;

    // Configure the ADS1115 for single-ended mode, 4.096V range, continuous conversion
    config[0] = CONFIG_REG;
    config[1] = 0x44; // Single-shot mode, 4.096V, AIN0-GND
    config[2] = 0x83; // 128 SPS, disable comparator

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    char reg = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to conversion register\n");
        return -1;
    }

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from conversion register\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    raw_value = (buffer[0] << 8) | buffer[1];

    return raw_value;
}

// Calculate CO concentration in PPM from raw ADC value
float calculate_ppm(int16_t raw_value) {
    float voltage = (float)raw_value / 32768.0 * 4.096; // Assuming +/- 4.096V range
    float ppm = OFFSET * powf(voltage / SENSITIVITY, -1.0);
    return ppm;
}

// Log CO concentration to file
void log_ppm(float ppm_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", s, ppm_value);
    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC values from CO and NO2 channels
        int16_t co_raw = read_ads1115_channel(CO_CHANNEL);
        int16_t no2_raw = read_ads1115_channel(NO2_CHANNEL);

        if (co_raw == -1 || no2_raw == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(5000000); // Wait 5 seconds before retrying
            continue;
        }

        // Calculate CO concentration
        float co_ppm = calculate_ppm(co_raw);

        // Log CO concentration
        log_ppm(co_ppm);

        printf("CO: %.2f PPM\n", co_ppm);

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Cleanup and exit
    cleanup();
    printf("CO sensor monitoring stopped.\n");
    return 0;
}

