// Define GPIO pins
#define FLAME_SENSOR_GPIO 4
#define SPI_CE0_GPIO 8
#define SPI_SCLK_GPIO 11
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature range
#define TEMP_MIN 10.0
#define TEMP_MAX 40.0

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SPI_CE0_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_SCLK_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_MOSI_GPIO, PI_OUTPUT);
    gpioSetMode(SPI_MISO_GPIO, PI_INPUT);

    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read flame sensor data
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to temperature (linear scaling)
float convert_adc_to_temperature(int adc_value) {
    return TEMP_MIN + (float)adc_value * (TEMP_MAX - TEMP_MIN) / 1023.0;
}

// Log data to CSV file
int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("flame_data.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flame,Temperature\n"); // Write header if file is new
    }

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Flame sensor and temperature logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read temperature from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping log entry.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data, skipping log entry.\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

