#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 27
#define SPI_CE0 8
#define SPI_CE1 9
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 0.7

// Define sampling window size
#define SAMPLE_WINDOW_SIZE 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int channel;
    int spi_ce;
    int gpio_pin;
    double rms;
} Microphone;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int spi_handle, int channel);
double calculate_rms(int *samples, int num_samples);
void control_led(int gpio_pin, int on);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control LED
void control_led(int gpio_pin, int on) {
    gpioWrite(gpio_pin, on);
}

// Function to log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    Microphone mic1 = {0, SPI_CE0, LED_PIN, 0.0};
    Microphone mic2 = {1, SPI_CE1, LED_PIN, 0.0};

    int mic1_samples[SAMPLE_WINDOW_SIZE];
    int mic2_samples[SAMPLE_WINDOW_SIZE];
    int sample_index = 0;

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read samples from both microphones
        int mic1_value = read_mcp3008(spi_handle, mic1.channel);
        int mic2_value = read_mcp3008(spi_handle, mic2.channel);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error reading from ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        mic1_samples[sample_index] = mic1_value;
        mic2_samples[sample_index] = mic2_value;

        sample_index++;

        if (sample_index == SAMPLE_WINDOW_SIZE) {
            // Calculate RMS values
            mic1.rms = calculate_rms(mic1_samples, SAMPLE_WINDOW_SIZE);
            mic2.rms = calculate_rms(mic2_samples, SAMPLE_WINDOW_SIZE);

            // Log data
            log_data(mic1.rms, mic2.rms);

            // Check for threshold exceedance
            if (mic1.rms > RMS_THRESHOLD || mic2.rms > RMS_THRESHOLD) {
                control_led(LED_PIN, 1); // Turn on LED
                gpioDelay(500);          // Wait for 500 ms
                control_led(LED_PIN, 0); // Turn off LED
            }

            sample_index = 0; // Reset sample index
        }

        gpioDelay(1); // Sample at 1 ms intervals
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

