#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
int read_ads1115(int handle);
float convert_to_current(int raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(int on);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int handle) {
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // Single-ended A0, 4.096V, Continuous, Disable comparator
    config[2] = 0x83; // 128 SPS, Start single conversion

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    char read_config[1];
    read_config[0] = CONVERSION_REG;

    if (i2cWriteDevice(handle, read_config, 1) != 0) {
        fprintf(stderr, "Failed to write conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data\n");
        return -1;
    }

    int raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Convert raw ADC value to current (A)
float convert_to_current(int raw_value) {
    // Assuming 4.096V range and 0.5V offset
    float voltage = (float)raw_value * 4.096 / 32768.0; // 2^15 = 32768
    float current = (voltage - 0.5) / 4.0 * 100.0; // 0.5V to 4.5V, 0-100A
    return current;
}

// Update circular buffer with new current reading
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED (on/off)
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_value = read_ads1115(i2c_handle);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float current = convert_to_current(raw_value);
        update_circular_buffer(current);
        float average_current = calculate_average_current();

        printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);

        if (average_current > OVERCURRENT_THRESHOLD) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 10Hz
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

