#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Integration time values
#define TCS34725_INTEGRATION_TIME_2_4MS 0xFF

// Gain values
#define TCS34725_GAIN_4X 0x01

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_color_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_color_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable power and ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON)\n");
        return -1;
    }
    gpioDelay(3); // Wait 3ms
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register (AEN)\n");
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATION_TIME_2_4MS) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, TCS34725_GAIN_4X) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    return 0;
}

// Read color data from the sensor
int read_color_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    unsigned char buffer[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8);
    if (result < 0) {
        fprintf(stderr, "Error reading color data: %d\n", result);
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Log color data to a CSV file
int log_color_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the file in append mode
    fp = fopen("color_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_log.csv\n");
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
    }

    // Write the data to the file
    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);

    // Close the file
    fclose(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int clear, red, green, blue;

    // Main loop
    while (!terminate) {
        // Read color data
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            // Log color data
            if (log_color_data(clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging color data\n");
            }
        } else {
            fprintf(stderr, "Error reading color data, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

