#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int sig);
int initialize_gpio();
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int ret, i;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    for (i = 0; i < 3; ++i) {
        ret = write(spi_fd, &tx_buf[i], 1);
        if (ret != 1) {
            fprintf(stderr, "Error writing to SPI device: %s\n", strerror(errno));
            return -1;
        }
    }

    for (i = 0; i < 3; ++i) {
        ret = read(spi_fd, &rx_buf[i], 1);
        if (ret != 1) {
            fprintf(stderr, "Error reading from SPI device: %s\n", strerror(errno));
            return -1;
        }
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1023.0;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - 0.05) / 0.1;
}

// Function to log current reading to file
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }
        fprintf(log_file, "Timestamp,Current_Amperes\n"); // Write header if file is new
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
}

// Function to check for overcurrent condition
void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected! Disabling motor.\n");
        log_current(current); // Log the current reading before disabling

        // Disable motor
        int ret = gpiod_line_set_value(motor_shutdown_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting motor shutdown pin: %s\n", strerror(errno));
        }

        sleep(1);

        // Re-enable motor
        ret = gpiod_line_set_value(motor_shutdown_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting motor shutdown pin: %s\n", strerror(errno));
        }
        printf("Motor re-enabled.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Received signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    motor_shutdown_line = gpiod_chip_get_line(gpio_chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_shutdown_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    int ret = gpiod_line_request_output(motor_shutdown_line, "current_monitor", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode (CPOL=0, CPHA=0)
    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI bits per word to 8
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI max speed to 1 MHz
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (motor_shutdown_line) {
        gpiod_line_release(motor_shutdown_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current reading
        log_current(current);

        // Check for overcurrent condition
        check_overcurrent(current);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Current monitoring stopped.\n");
    return 0;
}

