int read_pressure(int i2c_handle, uint16_t *pressure) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure: %d\n", result);
        return -1;
    }

    *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

