        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = I2C_ADDRESS,
        .log_file_name = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (initialize_logging(config.log_file_name) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_pressure;
    float pressure_kPa;
    char timestamp[32];
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_pressure(i2c_handle, &raw_pressure) == 0) {
                pressure_kPa = convert_to_kPa(raw_pressure);
                get_iso8601_timestamp(timestamp, sizeof(timestamp));
                if (log_data(timestamp, pressure_kPa) == 0) {
                    printf("Logged: %s, %.2f kPa\n", timestamp, pressure_kPa);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
            }
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Skipping logging.\n");
        }

        sleep(1); // Read every second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

