volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_ads1115(int handle, int channel);
float convert_to_pressure(int adc_value);
float convert_to_temperature(int adc_value);
void set_led(int gpio, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the ADC value from the specified channel of the ADS1115
int read_ads1115(int handle, int channel) {
    int config = ADS1115_CONFIG_REG_VALUE;
    int retries = 3;
    int result;

    if (channel == 0) {
        config &= ~0x7000; // Clear MUX bits
    } else if (channel == 1) {
        config &= ~0x7000; // Clear MUX bits
        config |= 0x1000;  // Set MUX to AIN1
    } else {
        fprintf(stderr, "Error: Invalid channel specified.\n");
        return -1;
    }

    while (retries > 0) {
        // Write the configuration register
        result = i2cWriteWordData(handle, ADS1115_CONFIG_REG, config);
        if (result != 0) {
            fprintf(stderr, "Error writing to ADS1115 config register: %d. Retrying...\n", result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
            continue;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        gpioDelay(10000); // 10ms

        // Read the conversion register
        result = i2cReadWordData(handle, ADS1115_CONVERSION_REG);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Error reading from ADS1115 conversion register: %d. Retrying...\n", result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to read from ADS1115 after multiple retries.\n");
    return -1; // Indicate failure
}

// Converts the raw ADC value to pressure (kPa)
float convert_to_pressure(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // Assuming 4.096V reference
    return voltage * 400.0; // Linear transfer function: 0V = 0 kPa, 5V = 400 kPa
}

// Converts the raw ADC value to temperature (°C)
float convert_to_temperature(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // Assuming 4.096V reference
    return (voltage - 1.0) * 100.0 / 1.0; // Linear transfer function: 1V = 0°C, 2V = 100°C
}

// Sets the state of the LED (HIGH or LOW)
void set_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MLX90834 Pressure and Temperature Monitor\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int pressure_adc = read_ads1115(i2c_handle, 0); // AIN0
        int temperature_adc = read_ads1115(i2c_handle, 1); // AIN1

        if (pressure_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error reading ADC values. Skipping this iteration.\n");
            gpioDelay(1000000); // Wait 1 second
            continue;
        }

        // Convert ADC values to pressure and temperature
        float pressure = convert_to_pressure(pressure_adc);
        float temperature = convert_to_temperature(temperature_adc);

        // Display pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Check pressure threshold and set LED
        if (pressure > PRESSURE_THRESHOLD) {
            set_led(LED_GPIO, 1); // Turn LED on
        } else {
            set_led(LED_GPIO, 0); // Turn LED off
        }

        // Wait 1 second
        gpioDelay(1000000);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

