#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define PPM_MIN 0.0
#define PPM_MAX 5000.0
#define ALARM_THRESHOLD 1000.0
#define LOG_FILE "methane_log.txt"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm);
void alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx[2] = 0x00; // Dummy byte

    spiXfer(spi_handle, tx, rx, 3);

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (float)adc_value * (PPM_MAX - PPM_MIN) / 1023.0 + PPM_MIN;
}

// Function to log data to file
void log_data(float ppm) {
    time_t now = time(NULL);
    struct tm timeinfo;
    char timestamp[30];

    localtime_r(&now, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to trigger alarm
void alarm() {
    fprintf(stderr, "\nALARM: Methane concentration exceeds threshold!\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
