#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define MLX90830_OFFSET 0.5 // 0.5V offset
#define MLX90830_SENSITIVITY 0.1 // 0.1V/kPa
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float full_scale_voltage;
    float offset;
    float sensitivity;
    float pressure_min;
    float pressure_max;
    char *log_file;
} Config;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_ads1115(int handle);
int16_t read_ads1115(int handle);
float convert_to_voltage(int16_t raw_value, float full_scale_voltage);
float convert_to_pressure(float voltage, float offset, float sensitivity);
int validate_pressure(float pressure, float min_pressure, float max_pressure);
int log_pressure(float pressure, const char *filename);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure ADS1115 for single-ended AIN0, 1Hz sample rate
int configure_ads1115(int handle) {
    // Configuration register value: 0x4083 (Single-shot mode, AIN0, +/-4.096V, 128 SPS)
    // 0b0100001000000011
    char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x83; // MSB
    config[2] = 0x40; // LSB

    int result = i2cWriteDevice(handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int16_t read_ads1115(int handle) {
    char reg = ADS1115_CONVERSION_REG;
    char buffer[2];
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    int16_t raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value, float full_scale_voltage) {
    return ((float)raw_value / 32768.0) * full_scale_voltage;
}

// Convert voltage to pressure (kPa) using linear transfer function
float convert_to_pressure(float voltage, float offset, float sensitivity) {
    return (voltage - offset) / sensitivity;
}

// Validate pressure reading
int validate_pressure(float pressure, float min_pressure, float max_pressure) {
    if (pressure >= min_pressure && pressure <= max_pressure) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

// Log pressure reading to file
int log_pressure(float pressure, const char *filename) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configuration
    Config config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .full_scale_voltage = ADS1115_FULL_SCALE_VOLTAGE,
        .offset = MLX90830_OFFSET,
        .sensitivity = MLX90830_SENSITIVITY,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .log_file = LOG_FILE
    };

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.ads1115_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t raw_value = read_ads1115(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_value, config.full_scale_voltage);

        // Convert to pressure
        float pressure = convert_to_pressure(voltage, config.offset, config.sensitivity);

        // Validate pressure
        if (validate_pressure(pressure, config.pressure_min, config.pressure_max) == 0) {
            // Log pressure
            if (log_pressure(pressure, config.log_file) < 0) {
                fprintf(stderr, "Error logging pressure reading.\n");
            }
            printf("Pressure: %.2f kPa\n", pressure);
        } else {
            fprintf(stderr, "Invalid pressure reading: %.2f kPa\n", pressure);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Pressure monitoring stopped.\n");
    return 0;
