#define MAX_TEMP 125.0

// Define log file
#define LOG_FILE "temperature_log.csv"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *spi_ce_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_close(int fd);
int gpio_request(struct gpiod_chip *chip, int pin, const char *consumer);
int gpio_set_direction(struct gpiod_line *line, enum gpiod_line_direction direction);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_release(struct gpiod_line *line);
int read_adc(int fd);
float convert_to_celsius(int adc_value);
int log_temperature(float temperature);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI close function
int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// GPIO request function
int gpio_request(struct gpiod_chip *chip, int pin, const char *consumer) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = consumer;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    return (int)(intptr_t)line; // Cast line pointer to int
}

// GPIO set direction function
int gpio_set_direction(struct gpiod_line *line, enum gpiod_line_direction direction) {
    if (gpiod_line_set_direction(line, direction) < 0) {
        fprintf(stderr, "Error setting GPIO direction\n");
        return -1;
    }
    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        fprintf(stderr, "Error releasing GPIO line\n");
        return -1;
    }
    return 0;
}

// Read ADC function
int read_adc(int fd) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3208 single-ended read command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading ADC\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert to Celsius function
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 4095.0;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

// Log temperature function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }

        // Write header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,temperature_celsius\n");
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request SPI CE line
    spi_ce_line = (struct gpiod_line *)(intptr_t)gpio_request(gpio_chip, SPI_CE_PIN, "spi_ce");
    if (!spi_ce_line) {
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set SPI CE line direction to output
    if (gpio_set_direction(spi_ce_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        gpio_release(spi_ce_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        gpio_release(spi_ce_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Validate temperature
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
        } else {
            // Log temperature
            if (log_temperature(temperature) < 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up resources
    spi_close(spi_fd);
    gpio_release(spi_ce_line);
    gpiod_chip_close(gpio_chip);
    if (log_file != NULL) {
        fclose(log_file);
    }

