// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0
#define ADC_MIN 0
#define ADC_MAX 1023
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_flow_rate(int adc_value);
void log_flow_rate(float flow_rate);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Reads the MCP3008 ADC value from the specified channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Converts the ADC value to a flow rate using a linear scaling formula
float adc_to_flow_rate(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    float flow_rate = FLOW_RATE_MIN + (float)(adc_value - ADC_MIN) * (FLOW_RATE_MAX - FLOW_RATE_MIN) / (ADC_MAX - ADC_MIN);
    return flow_rate;
}

// Logs the current timestamp and flow rate to the log file
void log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s.%06d,%.2f\n", timestamp, (int)(time(NULL) * 1000000) % 1000000, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Initializes the pigpio library and SPI interface
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to flow rate
        float flow_rate = adc_to_flow_rate(adc_value);
        if (flow_rate < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value to flow rate\n");
            continue; // Skip to the next iteration
        }

        // Validate flow rate
        if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
            fprintf(stderr, "Warning: Flow rate out of range: %.2f L/min\n", flow_rate);
        }

        // Log flow rate
        log_flow_rate(flow_rate);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Flow monitoring stopped.\n");
    return 0;
}

