#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845
#define CSV_FILE "environmental_data.csv"
#define RETRY_DELAY_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg, uint8_t *value);
int read_block(int handle, uint8_t reg, char *buf, int count);
int trigger_measurement(int handle);
int read_sensor_data(int handle, uint32_t *pressure, uint32_t *temperature);
sensor_data_t convert_data(uint32_t raw_pressure, uint32_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write a byte to a specific register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read a byte from a specific register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Read a block of data from a specific register
int read_block(int handle, uint8_t reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement(int handle) {
    int result = write_register(handle, 0x7E, MEASUREMENT_COMMAND >> 8);
    if (result < 0) return -1;
    result = write_register(handle, 0x7F, MEASUREMENT_COMMAND & 0xFF);
    if (result < 0) return -1;
    return 0;
}

// Read sensor data (pressure and temperature)
int read_sensor_data(int handle, uint32_t *pressure, uint32_t *temperature) {
    char buf[6];
    int result = read_block(handle, 0x00, buf, 6);
    if (result < 0) return -1;

    *pressure = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | (uint32_t)buf[2];
    *temperature = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

    return 0;
}

// Convert raw data to temperature and pressure
sensor_data_t convert_data(uint32_t raw_pressure, uint32_t raw_temperature) {
    sensor_data_t data;
    // Calibration parameters (replace with actual values from sensor calibration)
    float T_cal[2] = {25.0, 0.0}; // Example values
    float P_cal[2] = {100000.0, 0.0}; // Example values

    // Conversion formulas (from ICP-10125 datasheet)
    data.temperature = T_cal[0] + (raw_temperature - T_cal[1]) * 0.01; // Example formula
    data.pressure = P_cal[0] + (raw_pressure - P_cal[1]) * 0.01; // Example formula

    return data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CSV_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fclose(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint32_t raw_pressure, raw_temperature;
        sensor_data_t data;

        // Trigger measurement
        if (trigger_measurement(i2c_handle) < 0) {
            fprintf(stderr, "Error triggering measurement, retrying in %d seconds...\n", RETRY_DELAY_SEC);
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Wait for conversion (adjust delay as needed)
        gpioDelay(100); // 100 ms delay

        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_pressure, &raw_temperature) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", RETRY_DELAY_SEC);
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Convert data
        data = convert_data(raw_pressure, raw_temperature);

        // Log data
        if (log_data(data) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Display data on console
        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", data.temperature, data.pressure);

        // Wait before next sample
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

