#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

// Global variables for SPI handle and program termination
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for gain
    float gain = 1.0f; // Default gain
    if (argc > 1) {
        gain = atof(argv[1]);
        printf("Using gain: %f\n", gain);
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio data from microphones
        int mic1_value = read_mcp3008(MCP3008_CHANNEL_0);
        int mic2_value = read_mcp3008(MCP3008_CHANNEL_1);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error reading from MCP3008, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Apply gain
        float mic1_scaled = mic1_value * gain;
        float mic2_scaled = mic2_value * gain;

        // Calculate noise-cancellation result
        float result = mic1_scaled - mic2_scaled;

        // Print result in CSV format
        printf("%f,%f\n", result, result);

        // Delay to control sampling rate
        gpioDelay(10); // 10 ms delay
    }

    // Clean up and exit
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

