    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the ADC reading from the received data
    int adc_reading = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_reading;
}

