#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define BUZZER_GPIO 18
#define VOLTAGE_THRESHOLD 1.0
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
static int spi_handle;
static int gpio_chip;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

