#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_FILE "water_levels.json"
#define JSON_BUFFER_SIZE 256

// Global variables
int spi_handle;
FILE *water_level_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level_percentage(int adc_value);
void log_water_level(float percentage);
void control_led(float percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI_MODE0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open water level file
    water_level_file = fopen(WATER_LEVEL_FILE, "a+");
    if (water_level_file == NULL) {
        fprintf(stderr, "Failed to open water level file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the opening bracket
    fseek(water_level_file, 0, SEEK_END);
    long file_size = ftell(water_level_file);
    if (file_size == 0) {
        fprintf(water_level_file, "[");
    } else {
        // If not empty, go back to the end of the file
        fseek(water_level_file, -1, SEEK_END);
        // Check if the last character is a closing bracket, if so, overwrite it
        char last_char;
        fseek(water_level_file, -1, SEEK_END);
        fread(&last_char, 1, 1, water_level_file);
        if (last_char == ']') {
            fseek(water_level_file, -1, SEEK_END);
            fprintf(water_level_file, ",");
        } else {
            fprintf(water_level_file, ",");
        }
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI channel
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close water level file
    fseek(water_level_file, -1, SEEK_END);
    fprintf(water_level_file, "]");
    fclose(water_level_file);

    printf("Cleanup complete.\n");
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Padding

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log water level to file
void log_water_level(float percentage) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(water_level_file, "{\"timestamp\": \"%s.%03d\", \"water_level\": %.2f}\n", buf, (int)((now % 1) * 1000), percentage);
    fflush(water_level_file);
}

// Function to control LED based on water level
void control_led(float percentage) {
    if (percentage > 75.0) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
    } else if (percentage < 70.0) {
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float percentage = calculate_water_level_percentage(adc_value);
            printf("Water level: %.2f%%\n", percentage);
            log_water_level(percentage);
            control_led(percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    cleanup();

    return 0;
}

