#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_RAW_VALUE 300
#define MAX_RAW_VALUE 700
#define MOISTURE_THRESHOLD 30.0
#define LOGGING_FREQUENCY 60 // seconds
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define MSMTPRC_PATH "/etc/msmtprc" // Replace with actual path

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw_value;
    int max_raw_value;
    float moisture_threshold;
    int logging_frequency;
    char email_recipient[100];
    char msmtp_config_path[100];
} Config;

// Function prototypes
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw);
void log_data(FILE *fp, float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize SPI
int initialize_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate moisture percentage
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (raw_value < min_raw) {
        return 0.0;
    }
    if (raw_value > max_raw) {
        return 100.0;
    }
    return ((float)(raw_value - min_raw) / (max_raw - min_raw)) * 100.0;
}

// Log data to file
void log_data(FILE *fp, float moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(fp); // Ensure data is written immediately
}

// Send email alert
void send_email_alert(float moisture_percentage) {
    char command[200];
    snprintf(command, sizeof(command), "echo \"Subject: Soil Moisture Alert\n\nPlant moisture is below threshold (%.2f%%).\" | msmtp -t %s", moisture_percentage, EMAIL_RECIPIENT);

    FILE *pipe = popen(command, "r");
    if (!pipe) {
        fprintf(stderr, "Error sending email: %s\n", strerror(errno));
        return;
    }

    int status = pclose(pipe);
    if (status != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", status);
    }
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config;

    // Default values
    config.spi_channel = SPI_CHANNEL;
    config.adc_channel = ADC_CHANNEL;
    config.min_raw_value = MIN_RAW_VALUE;
    config.max_raw_value = MAX_RAW_VALUE;
    config.moisture_threshold = MOISTURE_THRESHOLD;
    config.logging_frequency = LOGGING_FREQUENCY;
    strncpy(config.email_recipient, EMAIL_RECIPIENT, sizeof(config.email_recipient) - 1);
    config.email_recipient[sizeof(config.email_recipient) - 1] = '\0'; // Ensure null termination
    strncpy(config.msmtp_config_path, MSMTPRC_PATH, sizeof(config.msmtp_config_path) - 1);
    config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0'; // Ensure null termination

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:l:t:e:r:")) != -1) {
        switch (opt) {
            case 'c':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_raw_value = atoi(optarg);
                break;
            case 'l':
                config.max_raw_value = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atof(optarg);
                break;
            case 'e':
                strncpy(config.email_recipient, optarg, sizeof(config.email_recipient) - 1);
                config.email_recipient[sizeof(config.email_recipient) - 1] = '\0';
                break;
            case 'r':
                strncpy(config.msmtp_config_path, optarg, sizeof(config.msmtp_config_path) - 1);
                config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw_value] [-l max_raw_value] [-t moisture_threshold] [-e email_recipient] [-r msmtp_config_path]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config.spi_channel, 500000) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value = read_mcp3008(config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", config.logging_frequency);
            sleep(config.logging_frequency);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value, config.min_raw_value, config.max_raw_value);
        log_data(log_file, moisture_percentage);

        if (moisture_percentage < config.moisture_threshold) {
            send_email_alert(moisture_percentage);
        }

        sleep(config.logging_frequency);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

