#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins for SPI communication
#define SPI_CE 8   // Chip Enable (CE0)
#define SPI_MOSI 10 // Master Out Slave In
#define SPI_MISO 9  // Master In Slave Out
#define SPI_SCLK 11 // Serial Clock

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed (1 MHz)
#define SPI_SPEED 1000000

// Define calibration values
#define DRY_ADC 700
#define WET_ADC 300

// Define moisture percentage range
#define MIN_PERCENT 0
#define MAX_PERCENT 100

// Global variable for SPI file descriptor
int spi_fd = -1;

// Global variable for GPIO chip
struct gpiod_chip *chip = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int adc_value;

    // Construct SPI message (MCP3008 single-ended read command)
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("SPI write failed");
        return -1;
    }
    if (read(spi_fd, rx_buf, 3) != 3) {
        perror("SPI read failed");
        return -1;
    }

    // Extract ADC value from response
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

int main() {
    struct gpiod_line *ce_line = NULL;
    struct gpiod_line *mosi_line = NULL;
    struct gpiod_line *miso_line = NULL;
    struct gpiod_line *sclk_line = NULL;
    struct gpiod_line_request_config config;
    int adc_value;
    float moisture_percentage;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO lines for SPI communication
    ce_line = gpiod_chip_get_line(chip, SPI_CE);
    mosi_line = gpiod_chip_get_line(chip, SPI_MOSI);
    miso_line = gpiod_chip_get_line(chip, SPI_MISO);
    sclk_line = gpiod_chip_get_line(chip, SPI_SCLK);

    if (!ce_line || !mosi_line || !miso_line || !sclk_line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output (CE) and input (MISO, SCLK)
    memset(&config, 0, sizeof(config));
    config.consumer = "mcp3008_spi";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(ce_line, &config, 0) < 0) {
        perror("Failed to request CE line");
        goto cleanup;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "mcp3008_spi";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(mosi_line, &config, 0) < 0) {
        perror("Failed to request MOSI line");
        goto cleanup;
    }

    if (gpiod_line_request(miso_line, &config, 0) < 0) {
        perror("Failed to request MISO line");
        goto cleanup;
    }

    if (gpiod_line_request(sclk_line, &config, 0) < 0) {
        perror("Failed to request SCLK line");
        goto cleanup;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup;
    }

    // Configure SPI mode and speed
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read ADC value from channel 0
        adc_value = read_mcp3008(SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            goto cleanup;
        }

        // Calculate moisture percentage
        moisture_percentage = ((float)(adc_value - WET_ADC) / (float)(DRY_ADC - WET_ADC)) * 100.0;

        // Clamp moisture percentage to 0-100%
        if (moisture_percentage < MIN_PERCENT) {
            moisture_percentage = MIN_PERCENT;
        } else if (moisture_percentage > MAX_PERCENT) {
            moisture_percentage = MAX_PERCENT;
        }

        // Print raw ADC value and moisture percentage
        printf("ADC Value: %d, Moisture: %.2f%%\n", adc_value, moisture_percentage);

        // Wait 5 seconds
        sleep(5);
    }

cleanup:
    // Clean up resources
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (ce_line) {
        gpiod_line_release(ce_line);
    }
    if (mosi_line) {
        gpiod_line_release(mosi_line);
    }
    if (miso_line) {
        gpiod_line_release(miso_line);
    }
    if (sclk_line) {
        gpiod_line_release(sclk_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

