float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1.0;
    }

    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage out of range: %.2fV\n", voltage);
        return -1.0;
    }

    return ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
}

