#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for SPI communication
#define SPI_CE 8  // Chip Enable (GPIO8)
#define SPI_SCLK 11 // Serial Clock (GPIO11)
#define SPI_MOSI 10 // Master Out Slave In (GPIO10)
#define SPI_MISO 9  // Master In Slave Out (GPIO9)

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration constants
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

// Global variables
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *spi_ce_line;
static struct gpiod_line *spi_sclk_line;
static struct gpiod_line *spi_mosi_line;
static struct gpiod_line *spi_miso_line;
static int spi_fd = -1; // File descriptor for SPI device
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void log_data(float moisture);
void signal_handler(int sig);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize SPI communication
int spi_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    spi_ce_line = gpiod_chip_get_line(gpio_chip, SPI_CE);
    spi_sclk_line = gpiod_chip_get_line(gpio_chip, SPI_SCLK);
    spi_mosi_line = gpiod_chip_get_line(gpio_chip, SPI_MOSI);
    spi_miso_line = gpiod_chip_get_line(gpio_chip, SPI_MISO);

    if (!spi_ce_line || !spi_sclk_line || !spi_mosi_line || !spi_miso_line) {
        perror("Error getting SPI lines");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(spi_ce_line, "spi", 1) < 0) {
        perror("Error requesting CE line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(spi_sclk_line, "spi", 0) < 0) {
        perror("Error requesting SCLK line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(spi_mosi_line, "spi", 0) < 0) {
        perror("Error requesting MOSI line as output");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(spi_miso_line, "spi") < 0) {
        perror("Error requesting MISO line as input");
        cleanup();
        return -1;
    }

    return 0;
}

// Transfer data over SPI
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int i;
    unsigned char tx_byte, rx_byte;

    for (i = 0; i < len; i++) {
        tx_byte = tx_buf[i];
        rx_byte = 0;

        // Clock out the data
        for (int j = 0; j < 8; j++) {
            // Set MOSI line
            if (tx_byte & 0x80) {
                gpiod_line_set_value(spi_mosi_line, 1);
            } else {
                gpiod_line_set_value(spi_mosi_line, 0);
            }

            // Clock in the data
            gpiod_line_set_value(spi_sclk_line, 1);
            rx_byte <<= 1;
            if (gpiod_line_get_value(spi_miso_line)) {
                rx_byte |= 1;
            }
            gpiod_line_set_value(spi_sclk_line, 0);

            tx_byte <<= 1;
        }

        rx_buf[i] = rx_byte;
    }

    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Transfer SPI message
    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        perror("SPI transfer error");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    float moisture = (float)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE) * 100.0;

    // Clamp moisture percentage to 0-100%
    if (moisture < 0.0) {
        moisture = 0.0;
    } else if (moisture > 100.0) {
        moisture = 100.0;
    }

    return moisture;
}

// Log data with timestamp
void log_data(float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture);
}

// Cleanup resources
void cleanup(void) {
    if (spi_ce_line) {
        gpiod_line_release(spi_ce_line);
    }
    if (spi_sclk_line) {
        gpiod_line_release(spi_sclk_line);
    }
    if (spi_mosi_line) {
        gpiod_line_release(spi_mosi_line);
    }
    if (spi_miso_line) {
        gpiod_line_release(spi_miso_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("Soil Moisture Sensor Reader\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Basic sensor validation
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC value stuck at 0 or 1023. Check wiring. Value: %d\n", adc_value);
        }

        float moisture = adc_to_moisture(adc_value);
        log_data(moisture);

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

