#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0040
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003
#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_INTERVAL_MS 50
#define POLL_INTERVAL_MS 200
#define RELAY_ACTIVATION_DURATION_MS 3000
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *door_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int16_t read_ads1115();
float adc_to_distance(int16_t adc_value);
float calibrate_threshold();
int activate_relay();
int deactivate_relay();
int read_door_sensor();
void log_event(const char *message);
void signal_handler(int sig);

// I2C initialization function
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_control", 0) < 0) {
        perror("Error requesting relay GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    door_sensor_line = gpiod_chip_get_line(gpio_chip, DOOR_SENSOR_GPIO);
    if (!door_sensor_line) {
        perror("Error getting door sensor GPIO line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(door_sensor_line, "door_sensor") < 0) {
        perror("Error requesting door sensor GPIO line as input");
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// ADS1115 read function
int16_t read_ads1115() {
    uint8_t config[3];
    uint8_t data[2];
    int16_t adc_value;

    // Configure the ADS1115 for single-ended channel 0, 4.096V, 128 SPS
    config[0] = ADS1115_CONFIG_REG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) & 0xFF;

    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    config[0] = ADS1115_CONVERSION_REG;
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    adc_value = adc_value >> 4; // Shift right by 4 bits

    return adc_value;
}

// ADC value to distance conversion function
float adc_to_distance(int16_t adc_value) {
    // Approximate conversion based on GP2Y0A21YK0F datasheet
    // This is a simplified linear approximation.  A more accurate
    // conversion would involve a lookup table or a more complex
    // mathematical model.
    // The sensor outputs voltage inversely proportional to distance.
    // Assuming 0.3V at 10cm and 2.5V at 80cm, and 10-bit ADC.
    float voltage = (float)adc_value * 4.096 / 32768.0; // 4.096V is the max voltage
    float distance = 27.0 / (voltage + 0.3) - 10.0; // Linear approximation

    return distance;
}

// Calibration function
float calibrate_threshold() {
    float baseline_values[NUM_BASELINE_SAMPLES];
    float sum = 0.0;
    int16_t adc_value;

    printf("Calibrating threshold...\n");
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        adc_value = read_ads1115();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC during calibration, using default threshold\n");
            return 30.0; // Default threshold
        }
        baseline_values[i] = adc_to_distance(adc_value);
        sum += baseline_values[i];
        usleep(BASELINE_SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
    }

    float average_distance = sum / NUM_BASELINE_SAMPLES;
    float threshold = average_distance * 0.8; // 80% of average
    printf("Calibration complete. Threshold: %.2f cm\n", threshold);
    return threshold;
}

// Relay activation function
int activate_relay() {
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        perror("Error setting relay GPIO line value (HIGH)");
        return -1;
    }
    usleep(RELAY_ACTIVATION_DURATION_MS * 1000); // Wait for activation duration
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        perror("Error setting relay GPIO line value (LOW)");
        return -1;
    }
    return 0;
}

// Relay deactivation function
int deactivate_relay() {
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        perror("Error setting relay GPIO line value (LOW)");
        return -1;
    }
    return 0;
}

// Door sensor read function
int read_door_sensor() {
    int value = gpiod_line_get_value(door_sensor_line);
    if (value < 0) {
        perror("Error reading door sensor GPIO line value");
        return -1;
    }
    return value;
}

// Logging function
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate the threshold
    float threshold_distance = calibrate_threshold();

    printf("Threshold distance: %.2f cm\n", threshold_distance);

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_ads1115();
        if (adc_value == -1) {
            log_event("Error reading ADC, retrying...");
            usleep(POLL_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        float distance = adc_to_distance(adc_value);

        printf("Distance: %.2f cm\n", distance);

        if (distance < threshold_distance) {
            log_event("Distance below threshold, activating relay");
            if (activate_relay() < 0) {
                log_event("Error activating relay");
            }
            usleep(100000); // Debounce delay

            int door_open = read_door_sensor();
            if (door_open == -1) {
                log_event("Error reading door sensor");
            } else if (door_open == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Wait before next poll
    }

    // Cleanup
    deactivate_relay();
    gpiod_line_release(relay_line);
    gpiod_line_release(door_sensor_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    printf("Exiting cleanly\n");
    return 0;
}

