int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from MCP3008 chip
int read_mcp3008(int chip_select_pin, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int chip_index;

    // Determine chip index based on CS pin
    if (chip_select_pin == CS0_PIN) {
        chip_index = 0;
    } else if (chip_select_pin == CS1_PIN) {
        chip_index = 1;
    } else if (chip_select_pin == CS2_PIN) {
        chip_index = 2;
    } else {
        fprintf(stderr, "Error: Invalid chip select pin: %d\n", chip_select_pin);
        return -1;
    }

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;
    transfer[0].cs_change = 1; // Keep CS active after transfer

    // Activate chip select
    if (gpiod_line_set_value(cs_lines[chip_index], 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fds[chip_index], SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error performing SPI transfer");
        gpiod_line_set_value(cs_lines[chip_index], 1); // Deactivate chip select
        return -1;
    }

    // Deactivate chip select
    if (gpiod_line_set_value(cs_lines[chip_index], 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

