        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

    if (ioctl(spi_fds[1], SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode 1");
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

    if (ioctl(spi_fds[2], SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode 2");
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

    int bits = 8;
    if (ioctl(spi_fds[0], SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word 0");
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

    if (ioctl(spi_fds[1], SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
