    if (ioctl(spi_fds[2], SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word 2");
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

