        perror("Error getting CS lines");
        gpiod_chip_close(gpio_chip);
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

    // Request CS lines as output
    if (gpiod_line_request_output(cs_lines[0], "soil_moisture", 1) < 0) {
        perror("Error requesting CS0 line");
        gpiod_chip_close(gpio_chip);
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

