        gpiod_line_release(cs_lines[1]);
        gpiod_line_release(cs_lines[2]);
        gpiod_chip_close(gpio_chip);
        close(spi_fds[0]);
        close(spi_fds[1]);
        close(spi_fds[2]);
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_fp, 0, SEEK_END);
