    if (file_size == 0) {
        fprintf(log_fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    fseek(log_fp, 0, SEEK_END);

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1 = read_mcp3008(CS0_PIN, 0);
        sensor2 = read_mcp3008(CS1_PIN, 0);
        sensor3 = read_mcp3008(CS2_PIN, 0);

        // Log data if sensor readings are valid
        if (sensor1 >= 0 && sensor2 >= 0 && sensor3 >= 0) {
            if (log_data(log_fp, sensor1, sensor2, sensor3) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, logging -1\n");
            if (log_data(log_fp, -1, -1, -1) < 0) {
                fprintf(stderr, "Error logging error data\n");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_fp);
    gpiod_line_release(cs_lines[0]);
    gpiod_line_release(cs_lines[1]);
    gpiod_line_release(cs_lines[2]);
    gpiod_chip_close(gpio_chip);
    close(spi_fds[0]);
    close(spi_fds[1]);
    close(spi_fds[2]);

    return 0;
}

