#define DRY_ADC_VALUE 200
#define WET_ADC_VALUE 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"

// Global variables (minimize usage)
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int threshold;
    int duration;
    int sleep_interval;
} Config;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        log_message("Error: SPI transfer failed.");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    float moisture = (float)(adc_value - DRY_ADC_VALUE) / (WET_ADC_VALUE - DRY_ADC_VALUE) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Pump set to %s", state ? "ON" : "OFF");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    if (log_file == NULL) return;

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, CE0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("System initialized.");
    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    control_pump(0); // Turn off pump
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    log_message("Cleanup complete.");
}

int main(int argc, char *argv[]) {
    Config config = {DEFAULT_THRESHOLD, DEFAULT_DURATION, DEFAULT_SLEEP_INTERVAL};
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                config.threshold = atoi(optarg);
                break;
            case 'd':
                config.duration = atoi(optarg);
                break;
            case 's':
                config.sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        int adc_value = -1;
        int retries = 3;
        while (adc_value == -1 && retries > 0) {
            adc_value = read_mcp3008(0);
            if (adc_value == -1) {
                log_message("Error reading ADC, retrying...");
                retries--;
                gpioDelay(100); // Wait 100ms before retrying
            }
        }

        if (adc_value != -1) {
            float moisture = adc_to_moisture(adc_value);
            char message[100];
            snprintf(message, sizeof(message), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
            log_message(message);

            if (moisture < config.threshold) {
                log_message("Moisture below threshold, activating pump.");
                control_pump(1);
                gpioDelay(config.duration * 1000); // Convert seconds to milliseconds
                control_pump(0);
                log_message("Pump deactivated.");
            }
        } else {
            log_message("Failed to read ADC after multiple retries. Skipping irrigation cycle.");
        }

        gpioDelay(config.sleep_interval * 1000); // Convert seconds to milliseconds
    }

    cleanup();
    return 0;
}

