#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define EMA_ALPHA 0.1
#define PEAK_THRESHOLD 1.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema_value = 0.0;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
double calculate_ema(int new_value);
int detect_peak(double current_value, double ema_value);
void log_peak(int raw_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate exponential moving average
double calculate_ema(int new_value) {
    double alpha = EMA_ALPHA;
    double ema = ema_value + alpha * (new_value - ema_value);
    return ema;
}

// Function to detect peak
int detect_peak(double current_value, double ema_value) {
    double threshold = ema_value * PEAK_THRESHOLD;
    return (current_value > threshold);
}

// Function to log peak
void log_peak(int raw_value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Raw Value: %d\n", buf, raw_value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int raw_value = read_mcp3008(0);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        ema_value = calculate_ema(raw_value);

        if (detect_peak(raw_value, ema_value)) {
            log_peak(raw_value);
        }

        gpioDelay(10000); // 10 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

