#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define CONTROL_BYTE 0x40 // Single-ended AIN0, no auto-increment

int i2c_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Write control byte to start conversion
        if (write(i2c_fd, &CONTROL_BYTE, 1) != 1) {
            perror("Error writing control byte");
            close(i2c_fd);
            return 1;
        }

        // Read dummy byte (PCF8591 returns previous conversion)
        uint8_t dummy_byte;
        if (read(i2c_fd, &dummy_byte, 1) != 1) {
            perror("Error reading dummy byte");
            close(i2c_fd);
            return 1;
        }

        // Read analog value
        uint8_t analog_value;
        if (read(i2c_fd, &analog_value, 1) != 1) {
            perror("Error reading analog value");
            close(i2c_fd);
            return 1;
        }

        // Print analog value
        printf("Analog Value: %d\n", analog_value);

        // Wait 100ms
        usleep(100000);
    }

    return 0;
}

