#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SENSITIVITY 0.001 // V/Gauss
#define PGA_VOLTAGE 4.096 // V
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_ads1115();
double calculate_gauss(int raw_value);
void blink_led();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    return 0;
}

// Reads the ADC value from the ADS1115
int read_ads1115() {
    char config[3];
    char buffer[2];
    int16_t raw_value;

    // Configure for single-ended AIN0, PGA=4.096V, continuous conversion, start single conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // 0b11000011
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // 10 ms

    // Read the conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "I2C write (conversion reg select) failed\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];

    return raw_value;
}

// Converts the raw ADC value to Gauss
double calculate_gauss(int raw_value) {
    double voltage = (double)raw_value * PGA_VOLTAGE / 32768.0; // 16-bit ADC
    return voltage / SENSITIVITY;
}

// Blinks the LED rapidly for 1 second
void blink_led() {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(50); // 50 ms on
    gpioWrite(LED_GPIO, 0);
    gpioDelay(50); // 50 ms off
    gpioDelay(500); // 500 ms delay for 1 second
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring magnetic field... (Threshold: %.2f Gauss)\n", threshold);

    // Main loop
    while (!terminate) {
        int raw_value = read_ads1115();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        double gauss = calculate_gauss(raw_value);
        printf("Magnetic field: %.2f Gauss\n", gauss);

        if (fabs(gauss) > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            blink_led();
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

