#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_ON 30
#define MOISTURE_THRESHOLD_OFF 35
#define MQTT_BROKER_ADDRESS "localhost" // Change to your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define MQTT_QOS 1
#define PUBLISH_INTERVAL 60 // seconds

// Global variables
int spi_handle;
MQTTClient mqtt_client;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(int state);
void publish_moisture(float moisture);
void on_connect(void *context, MQTTClient_deliveryToken dt);
void on_disconnect(void *context, MQTTClient_disconnectReason reason);
void on_message(void *context, char *topicName, int topicLen, MQTTClient_message *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023 and moisture range is 0-100%
    // Adjust these values based on your sensor's characteristics
    float moisture = (float)adc_value / 1023.0 * 100.0;
    return moisture;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    syslog(LOG_INFO, "Relay set to: %s", state ? "ON" : "OFF");
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[20];

    snprintf(payload, sizeof(payload), "%.2f", moisture);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    syslog(LOG_INFO, "Published moisture: %s", payload);
}

// MQTT callback functions
void on_connect(void *context, MQTTClient_deliveryToken dt) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient_subscribe(mqtt_client, MQTT_CONTROL_TOPIC, MQTT_QOS);

    syslog(LOG_INFO, "Connected to MQTT broker");
}

void on_disconnect(void *context, MQTTClient_disconnectReason reason) {
    syslog(LOG_WARNING, "Disconnected from MQTT broker: %d", reason);
}

void on_message(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    char* payloadptr = message->payload;
    if (strcmp(topicName, MQTT_CONTROL_TOPIC) == 0) {
        if (strcmp(payloadptr, "pump_on") == 0) {
            control_relay(1);
        } else if (strcmp(payloadptr, "pump_off") == 0) {
            control_relay(0);
        } else {
            syslog(LOG_WARNING, "Invalid command received: %s", payloadptr);
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    int rc;
    MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.onSuccess = on_connect;
    conn_opts.onFailure = on_disconnect;
    conn_opts.context = NULL;

    MQTTClient_setCallbacks(mqtt_client, NULL, NULL, on_message, NULL);

    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker, return code %d", rc);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        float moisture = calculate_moisture(adc_value);

        // Publish moisture data
        publish_moisture(moisture);

        // Control relay based on moisture level with hysteresis
        static int relay_state = 0; // 0 = off, 1 = on
        if (moisture < MOISTURE_THRESHOLD_ON && !relay_state) {
            control_relay(1);
            relay_state = 1;
        } else if (moisture > MOISTURE_THRESHOLD_OFF && relay_state) {
            control_relay(0);
            relay_state = 0;
        }

        sleep(PUBLISH_INTERVAL);
    }

    // Cleanup
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    spiClose(spi_handle);
    control_relay(0); // Ensure relay is off on exit
    gpioTerminate();
    closelog();

    return 0;
}

