#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

volatile sig_atomic_t keep_running = 1;
int spi_fd = -1;

void sigint_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int spi_init(int fd) {
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        fprintf(stderr, "Error getting SPI mode: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error getting bits per word: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error getting max speed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended channel 0, dummy byte
    uint8_t rx_buf[3] = {0};
    int raw_value;
    float voltage;

    signal(SIGINT, sigint_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init(spi_fd) != 0) {
        close(spi_fd);
        return 1;
    }

    while (keep_running) {
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
            raw_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            voltage = raw_value * 3.3 / 1024.0;
            printf("Raw Value: %d, Voltage: %.3f V\n", raw_value, voltage);
        } else {
            fprintf(stderr, "SPI transfer failed. Retrying...\n");
        }
        usleep(500000); // 500 ms
    }

    close(spi_fd);
    return 0;
}

