#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int log_data(float voltages[NUM_CHANNELS]);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to log data to file
int log_data(float voltages[NUM_CHANNELS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file
    fp = fopen("sensor_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open sensor_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Channel0_Voltage,Channel1_Voltage,Channel2_Voltage\n");
    }
    fflush(fp);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        float voltages[NUM_CHANNELS];
        int adc_values[NUM_CHANNELS];

        // Read ADC values from each channel
        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read channel %d\n", i);
                terminate = 1; // Exit loop on error
                break;
            }
            voltages[i] = convert_to_voltage(adc_values[i]);
        }

        // Log data if no errors occurred
        if (!terminate) {
            if (log_data(voltages) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
                terminate = 1;
            }
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

