#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
void log_data(float sound_level, int light_level, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_fd, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB (example linear conversion)
float adc_to_db(int adc_value) {
    // Assuming ADC range is 0-1023 (10 bits)
    // Adjust the scaling factor as needed based on your microphone
    float db = 20 * log10((float)adc_value / 1023.0 * 100.0); // Example scaling
    return db;
}

// Function to read from BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux;

    if (write(i2c_fd, "\x11", 1) != 1) { // Send continuous high-resolution mode command
        fprintf(stderr, "Error: Failed to write to I2C device\n");
        return -1;
    }
    gpioDelay(180); // Wait 180 ms

    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from I2C device\n");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to log data to CSV file
void log_data(float sound_level, int light_level, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%.2f,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(csv_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire bus access and/or talk to slave.\n");
        close(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        close(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value, lux;
        float sound_level_db;
        int error_code = 0;

        // Read sound level from MCP3008
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            error_code |= 0x01; // Set error bit for sound level
        } else {
            sound_level_db = adc_to_db(adc_value);
        }

        // Read light level from BH1750
        lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error: Failed to read light level\n");
            error_code |= 0x02; // Set error bit for light level
        }

        // Log data
        log_data(sound_level_db, lux, error_code);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    fclose(csv_file);
    close(i2c_fd);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

