    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        perror("Error: SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate distance from ADC value (linear approximation)
float calculate_distance(int adc_value) {
    // Assuming ADC range is 0-1023 and distance is 4-80 cm
    float distance = 4.0 + (float)adc_value / 1023.0 * 76.0;
    return distance;
}

// Function to control the relay
void control_relay(int state) {
    if (relay_line != NULL) {
        if (gpiod_line_set_value(relay_line, state) != 0) {
            perror("Error: Failed to set relay state");
        } else {
            relay_state = state;
        }
    } else {
        fprintf(stderr, "Error: Relay line not initialized\n");
    }
}

// Function to log events to a file
void log_event(const char *event) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function to initialize resources
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open GPIO line for relay control
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error: Failed to open GPIO chip");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error: Failed to get GPIO line");
        gpiod_chip_close(chip);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_control", 0) != 0) {
        perror("Error: Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off relay
    control_relay(0);

    // Release GPIO line
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    if (setup() != 0) {
        fprintf(stderr, "Setup failed. Exiting.\n");
        return 1;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_event("Error: Failed to read ADC value");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate distance
        float distance = calculate_distance(adc_value);

        // Check proximity
        if (distance < PROXIMITY_THRESHOLD) {
            if (relay_state == 0) {
                control_relay(1);
                log_event("Door opened");
                gpioDelay(DEBOUNCE_DELAY); // Debounce delay
            }
        } else {
            if (relay_state == 1) {
                control_relay(0);
                log_event("Door closed");
            }
        }

        gpioDelay(POLLING_INTERVAL); // Polling interval
    }

    cleanup();
    return 0;
}

