        // Read sensor values
        int sensor1 = read_mcp3008(0);
        int sensor2 = read_mcp3008(1);
        int sensor3 = read_mcp3008(2);

        // Log errors if sensor readings failed
        if (sensor1 == -1) {
            fprintf(stderr, "Error: Failed to read sensor 1\n");
        }
        if (sensor2 == -1) {
            fprintf(stderr, "Error: Failed to read sensor 2\n");
        }
        if (sensor3 == -1) {
            fprintf(stderr, "Error: Failed to read sensor 3\n");
        }

        // Calculate average sensor reading
        float average = average_sensor_readings(sensor1, sensor2, sensor3);

        // Map average to valve position
        int valve_position = map_to_valve_position(average);

        // Set valve position
        gpioPWM(VALVE_GPIO, valve_position);

        // Log data
        log_data(sensor1, sensor2, sensor3, average, valve_position);

        // Wait for the next interval
        gpioDelay(LOG_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    gpioPWM(VALVE_GPIO, 0); // Close the valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation system stopped.\n");
    return 0;
}

