#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define BACKOFF_DELAY 100 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void log_data(float moisture);
void signal_handler(int signal);
int spi_transfer(int handle, char *tx_buf, char *rx_buf, int count);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spi_transfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            gpioDelay(BACKOFF_DELAY * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "SPI transfer failed after %d retries. Skipping reading.\n", MAX_RETRIES);
    }

    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
}

// SPI transfer function with retry and exponential backoff
int spi_transfer(int handle, char *tx_buf, char *rx_buf, int count) {
    int result = spiXfer(handle, tx_buf, rx_buf, count);
    if (result != count) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture = convert_to_moisture(adc_value);
            if (moisture != -1.0) {
                printf("Moisture: %.2f%%\n", moisture);
                log_data(moisture);
            } else {
                fprintf(stderr, "Error converting ADC value to moisture.\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

