#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CE 0 // Chip Enable for MCP3008 (GPIO8)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_FREQUENCY 440 // Initial PWM frequency (Hz)
#define PWM_RANGE 1000    // PWM range (0-1000)

// Define distance range and frequency mapping
#define MIN_DISTANCE 10.0  // cm
#define MAX_DISTANCE 100.0 // cm
#define MIN_FREQUENCY 220.0 // Hz
#define MAX_FREQUENCY 880.0 // Hz

// Define LDR ADC channel
#define LDR_ADC_CHANNEL 0

// Define timeout for HC-SR04 sensor (in seconds)
#define TIMEOUT 0.5

// Define SPI retry attempts
#define SPI_RETRIES 3

// Define SPI retry delay (in milliseconds)
#define SPI_RETRY_DELAY 10

// Define calibration data file
#define CALIBRATION_FILE "theremin_config.txt"

// Global variables
static volatile int running = 1;
static float distance = 0.0;
static float frequency = 440.0;
static int volume = 500; // Initial volume (50% duty cycle)
static int spi_handle;

// Function prototypes
void signal_handler(int signal);
float read_distance();
float map_distance_to_frequency(float distance);
int read_ldr();
int map_ldr_to_volume(int ldr_value);
int spi_read_adc(int channel);
void save_calibration_data();
void load_calibration_data();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT * 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT * 1000) {
        fprintf(stderr, "Error: Echo signal timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT * 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT * 1000) {
        fprintf(stderr, "Error: Echo signal timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance_cm = (time_taken * 34300) / 2; // Speed of sound: 343 m/s

    return distance_cm;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    int adc_value = spi_read_adc(LDR_ADC_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error: Failed to read LDR value\n");
        return -1; // Indicate error
    }
    return adc_value;
}

// Function to map LDR value to volume
int map_ldr_to_volume(int ldr_value) {
    // Invert the LDR value (assuming higher resistance = lower voltage = higher ADC value)
    int inverted_ldr = 1023 - ldr_value; // Assuming 10-bit ADC (0-1023)

    // Map the inverted LDR value to the volume range (0-1000)
    int volume = (int)(((float)inverted_ldr / 1023.0) * 1000.0);

    // Ensure volume is within the valid range
    if (volume < 0) {
        volume = 0;
    } else if (volume > 1000) {
        volume = 1000;
    }

    return volume;
}

// Function to read ADC value from MCP3008 via SPI
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    for (int i = 0; i < SPI_RETRIES; i++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d)\n", i + 1);
            gpioDelay(SPI_RETRY_DELAY); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after multiple retries\n");
    return -1; // Indicate error
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return;
    }

    fprintf(fp, "%.2f,%.2f,%d\n", distance, frequency, volume);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        printf("Calibration file not found, using default values\n");
        return;
    }

    float loaded_distance, loaded_frequency;
    int loaded_volume;

    if (fscanf(fp, "%f,%f,%d", &loaded_distance, &loaded_frequency, &loaded_volume) == 3) {
        distance = loaded_distance;
        frequency = loaded_frequency;
        volume = loaded_volume;
        printf("Calibration data loaded from %s: distance=%.2f, frequency=%.2f, volume=%d\n", CALIBRATION_FILE, distance, frequency, volume);
    } else {
        printf("Error: Invalid calibration data format in %s, using default values\n", CALIBRATION_FILE);
    }

    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    load_calibration_data();

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set PWM duty cycle to initial volume
    gpioPWM(PWM_PIN, volume);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read distance from HC-SR04 sensor
        float new_distance = read_distance();
        if (new_distance > 0) {
            distance = new_distance;
        } else {
            fprintf(stderr, "Error: Failed to read distance, using last valid value\n");
        }

        // Map distance to frequency
        frequency = map_distance_to_frequency(distance);

        // Read LDR value from MCP3008 ADC
        int ldr_value = read_ldr();
        if (ldr_value >= 0) {
            // Map LDR value to volume
            volume = map_ldr_to_volume(ldr_value);
        } else {
            fprintf(stderr, "Error: Failed to read LDR value, using last valid value\n");
        }

        // Set PWM duty cycle
        gpioPWM(PWM_PIN, volume);

        // Save calibration data periodically
        time_t current_time = time(NULL);
        if (current_time % 60 == 0) { // Save every 60 seconds
            save_calibration_data();
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(50); // 50ms delay
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

