int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buffer[2] = 0x00;                  // Don't care

    // Retry loop for SPI communication
    for (int i = 0; i < 3; ++i) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value from response
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    // If all retries failed, return -1
    fprintf(stderr, "Error: SPI read failed after multiple retries.\n");
    return -1;
}

// Function to convert ADC value to AQI
float adc_to_aqi(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    // Linear mapping: 0 ADC = 0 AQI, 1023 ADC = 500 AQI
    return (float)adc_value * 500.0 / 1023.0;
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

// Function to log AQI to file
void log_aqi(float aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, AQI: %.2f\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            // Convert ADC value to AQI
            float aqi = adc_to_aqi(adc_value);

            if (aqi >= 0) {
                // Control the ventilation fan
                control_fan((int)aqi);

                // Log the AQI
                log_aqi(aqi);

                printf("AQI: %.2f\n", aqi);
            } else {
                fprintf(stderr, "Error: Invalid AQI value\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

