#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// MCP3008 SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// ADC Channels
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1

// Speed Range
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion Profile Parameters
#define ACCELERATION_TIME 1.0 // seconds
#define HOLD_TIME 2.0         // seconds
#define DECELERATION_TIME 1.0 // seconds
#define PAUSE_TIME 5.0        // seconds

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_adc(int channel);
float map_potentiometer_value(int adc_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void accelerate(int motor, int target_speed);
void hold(int motor, int speed);
void decelerate(int motor, int target_speed);
void pause_motion(void);
void reverse_directions(void);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (read_adc)\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor using logarithmic function
float map_potentiometer_value(int adc_value) {
    float speed_factor = MIN_SPEED + (float)(adc_value) / 1023.0 * (MAX_SPEED - MIN_SPEED);
    speed_factor = log10(1 + speed_factor * 9) / log10(10); // Logarithmic mapping
    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
    }
}

// Function to set motor direction using GPIO
void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        gpioWrite(MOTOR1_DIRECTION, direction);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_DIRECTION, direction);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
    }
}

