void hold(int motor, int speed) {
    set_motor_speed(motor, speed);
    gpioDelay(HOLD_TIME * 1000); // Convert seconds to milliseconds
}

// Function to decelerate motor to target speed
void decelerate(int motor, int target_speed) {
    int current_speed = MAX_SPEED;
    float decrement = (float)(target_speed - MIN_SPEED) / (DECELERATION_TIME * 10); // Decrement every 100ms

    while (current_speed >= target_speed) {
        set_motor_speed(motor, current_speed);
        gpioDelay(100); // 100ms delay
        current_speed -= decrement;
    }
}

// Function to pause motion for a specified time
void pause_motion(void) {
    gpioDelay(PAUSE_TIME * 1000); // Convert seconds to milliseconds
}

// Function to reverse motor directions
void reverse_directions(void) {
    int direction1 = !gpioRead(MOTOR1_DIRECTION);
    int direction2 = !gpioRead(MOTOR2_DIRECTION);

    set_motor_direction(1, direction1);
    set_motor_direction(2, direction2);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

