    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure GPIO pins
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
