        // Read ADC values
        int adc_value_1 = read_adc(ADC_CHANNEL_1);
        int adc_value_2 = read_adc(ADC_CHANNEL_2);

        if (adc_value_1 == -1 || adc_value_2 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Map ADC values to speed factors
