        int target_speed_1 = (int)(speed_factor_1 * (MAX_SPEED - MIN_SPEED) + MIN_SPEED);
        int target_speed_2 = (int)(speed_factor_2 * (MAX_SPEED - MIN_SPEED) + MIN_SPEED);

