#define SPI_MISO 9
#define SPI_SCLK 11

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate the ambient noise level
float calibrate_noise_level(int duration_seconds)
{
    int num_samples = duration_seconds * 100; // Number of samples over the duration
    int sum = 0;
    int value;

    printf("Calibrating noise level for %d seconds...\n", duration_seconds);

    for (int i = 0; i < num_samples; i++) {
        value = read_mcp3008(0);
        if (value == -1) {
            fprintf(stderr, "Error: Failed to read ADC during calibration\n");
            return -1.0;
        }
        sum += value;
        gpioDelay(10000); // 10 ms delay
    }

    return (float)sum / num_samples;
}

// Function to check if the sound level exceeds the threshold
int check_threshold(int current_level, float ambient_level, float threshold)
{
    float difference = (float)current_level - ambient_level;
    float percentage = (difference / ambient_level) * 100.0;

    if (percentage > threshold) {
        return 1; // Threshold exceeded
    } else {
        return 0; // Threshold not exceeded
    }
}

// Function to control the LED with debouncing
void control_led(int led_pin, int state)
{
    static int last_state = 0; // Store the last LED state
    static uint32_t last_tick = 0; // Store the last tick when the LED was toggled

    if (state != last_state) {
        uint32_t current_tick = gpioTick();
        if (current_tick - last_tick > 10000) { // 10 ms debounce
            gpioWrite(led_pin, state);
            last_state = state;
            last_tick = current_tick;
        }
    }
}

