    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate the ambient noise level
    float ambient_level = calibrate_noise_level(5);
    if (ambient_level == -1.0) {
        fprintf(stderr, "Error: Noise level calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set noise threshold (10% above ambient)
    float threshold = ambient_level * 1.10;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int current_level = read_mcp3008(0);
        if (current_level == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        if (check_threshold(current_level, ambient_level, threshold)) {
            control_led(LED_PIN, 1); // Turn LED on
        } else {
            control_led(LED_PIN, 0); // Turn LED off
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Exiting...\n");
    control_led(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

