#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_PIN 8
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE) // Nanoseconds
#define ADC_CHANNEL 0

// Global variables (to be minimized, used for signal handling)
static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_configure(int fd, uint8_t mode, uint8_t bits_per_word, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_request(int gpio_pin);
int gpio_set_direction(int gpio_pin, const char *direction);
int gpio_write(int gpio_pin, int value);
int log_open(const char *filename);
int log_write(int fd, const char *timestamp, int adc_value);
int log_flush(int fd);
void signal_handler(int sig);
void cleanup(void);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

// SPI configure function
int spi_configure(int fd, uint8_t mode, uint8_t bits_per_word, uint32_t speed) {
    int ret;

    ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO request function
int gpio_request(int gpio_pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return (int)(unsigned long)line; // Store the line pointer as an integer
}

// GPIO set direction function
int gpio_set_direction(int gpio_pin, const char *direction) {
    int ret;
    if (strcmp(direction, "output") == 0) {
        ret = gpiod_line_set_direction((struct gpiod_line *)gpio_pin, GPIOD_LINE_DIRECTION_OUTPUT);
    } else if (strcmp(direction, "input") == 0) {
        ret = gpiod_line_set_direction((struct gpiod_line *)gpio_pin, GPIOD_LINE_DIRECTION_INPUT);
    } else {
        fprintf(stderr, "Invalid GPIO direction: %s\n", direction);
        return -1;
    }

    if (ret < 0) {
        perror("Error setting GPIO direction");
        return -1;
    }

    return 0;
}

// GPIO write function
int gpio_write(int gpio_pin, int value) {
    int ret = gpiod_line_set_value((struct gpiod_line *)gpio_pin, value);
    if (ret < 0) {
        perror("Error writing to GPIO line");
        return -1;
    }

    return 0;
}

// Log open function
int log_open(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }
    return fd;
}

// Log write function
int log_write(int fd, const char *timestamp, int adc_value) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%s|%d\n", timestamp, adc_value);
    ssize_t bytes_written = write(fd, buffer, strlen(buffer));
    if (bytes_written < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Log flush function
int log_flush(int fd) {
    int ret = fsync(fd);
    if (ret < 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure SPI
    if (spi_configure(spi_fd, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line for CS
    cs_line = (struct gpiod_line *)gpio_request(CS_GPIO_PIN);
    if (cs_line == NULL) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Set CS pin as output
    if (gpio_set_direction(CS_GPIO_PIN, "output") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = log_open("audio_log.txt");
    if (log_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    struct timespec sleep_time = {0, SAMPLE_PERIOD_NS};
    struct timespec remaining_time;
    uint8_t tx_buf[3] = {0x01, (0x08 | ADC_CHANNEL) << 4, 0x00};
    uint8_t rx_buf[3];
    struct timespec ts;
    char timestamp[32];

    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

        // Drive CS low
        if (gpio_write(CS_GPIO_PIN, 0) < 0) {
            break;
        }

        // Transfer data
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            break;
        }

        // Drive CS high
        if (gpio_write(CS_GPIO_PIN, 1) < 0) {
            break;
        }

        // Parse ADC value
        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Log data
        if (log_write(log_fd, timestamp, adc_value) < 0) {
            break;
        }
        if (log_flush(log_fd) < 0) {
            break;
        }

        // Sleep until next sample
        if (nanosleep(&sleep_time, &remaining_time) < 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Sleep interrupted by signal\n");
                break;
            } else {
                perror("Error sleeping");
                break;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

