#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define ADXL335 sensitivity (300 mV/g)
#define ADXL335_SENSITIVITY 300.0

// Define ADXL335 zero-g bias (1.5V)
#define ADXL335_ZERO_G_BIAS 1.5

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    float state;
    float covariance;
} KalmanState;

KalmanState kalman_x, kalman_y, kalman_z;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_g(int adc_value);
float kalman_filter(float measurement, KalmanState *state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter states
    kalman_x.state = 0.0;
    kalman_x.covariance = 1.0;
    kalman_y.state = 0.0;
    kalman_y.covariance = 1.0;
    kalman_z.state = 0.0;
    kalman_z.covariance = 1.0;

    return 0;
}

// Read MCP3008 function
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to g function
float convert_to_g(int adc_value) {
    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value / 1023.0 * 3.3;

    // Convert voltage to acceleration (g)
    float acceleration = (voltage - ADXL335_ZERO_G_BIAS) / (ADXL335_SENSITIVITY / 1000.0);
    return acceleration;
}

// Kalman filter function
float kalman_filter(float measurement, KalmanState *state) {
    // Prediction step
    float prediction = state->state;
    float prediction_covariance = state->covariance + PROCESS_NOISE;

    // Update step
    float kalman_gain = prediction_covariance / (prediction_covariance + MEASUREMENT_NOISE);
    float updated_state = prediction + kalman_gain * (measurement - prediction);
    float updated_covariance = (1 - kalman_gain) * prediction_covariance;

    // Update Kalman state
    state->state = updated_state;
    state->covariance = updated_covariance;

    return updated_state;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("ADXL335 Accelerometer Reader\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to g
        float g_x = convert_to_g(adc_x);
        float g_y = convert_to_g(adc_y);
        float g_z = convert_to_g(adc_z);

        // Apply Kalman filter
        float filtered_x = kalman_filter(g_x, &kalman_x);
        float filtered_y = kalman_filter(g_y, &kalman_y);
        float filtered_z = kalman_filter(g_z, &kalman_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x, filtered_y, filtered_z);

        // Delay for 100 ms (10 Hz)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated\n");
    return 0;
}

