#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define quiescent voltage and sensitivity
#define V_QUISSENT 1.65
#define SENSITIVITY 0.025

// Define magnetic field range
#define MIN_MILLITESLA 0.0
#define MAX_MILLITESLA 100.0

// Define sampling interval (in milliseconds)
#define SAMPLE_INTERVAL_MS 100

// Global variables for GPIO lines and chip
static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static struct gpiod_line *sensor3_line;

// File pointer for logging
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int pin);
float calculate_magnetic_field(int digital_value);
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor3_line) {
        gpiod_line_release(sensor3_line);
    }

    // Close log file
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    // Unexport GPIO pins (optional, but good practice)
    // system("gpio unexport 4");
    // system("gpio unexport 17");
    // system("gpio unexport 27");

    // Release GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the digital value from a sensor pin
int read_sensor(int pin) {
    int value;

    if (pin == SENSOR1_PIN) {
        value = gpiod_line_get_value(sensor1_line);
    } else if (pin == SENSOR2_PIN) {
        value = gpiod_line_get_value(sensor2_line);
    } else if (pin == SENSOR3_PIN) {
        value = gpiod_line_get_value(sensor3_line);
    } else {
        fprintf(stderr, "Error: Invalid sensor pin: %d\n", pin);
        return -1; // Indicate an error
    }

    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", pin, strerror(-value));
        return -1; // Indicate an error
    }

    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int digital_value) {
    float voltage = (float)digital_value * 3.3; // Assuming 3.3V VCC
    float magnetic_field = (voltage - V_QUISSENT) / SENSITIVITY;

    // Validate magnetic field value
    if (magnetic_field < MIN_MILLITESLA || magnetic_field > MAX_MILLITESLA) {
        fprintf(stderr, "Warning: Magnetic field value out of range: %.2f mT\n", magnetic_field);
    }

    return magnetic_field;
}

// Function to log the sensor data to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int sensor1_value, sensor2_value, sensor3_value;
    float sensor1_mT, sensor2_mT, sensor3_mT;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines for the sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting sensor1 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting sensor2 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(sensor3_line, "sensor3") < 0) {
        fprintf(stderr, "Error requesting sensor3 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        sensor1_value = read_sensor(SENSOR1_PIN);
        sensor2_value = read_sensor(SENSOR2_PIN);
        sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            sleep(SAMPLE_INTERVAL_MS / 1000); // Sleep for the specified interval
            continue;
        }

        // Calculate magnetic field strengths
        sensor1_mT = calculate_magnetic_field(sensor1_value);
        sensor2_mT = calculate_magnetic_field(sensor2_value);
        sensor3_mT = calculate_magnetic_field(sensor3_value);

        // Log the data
