#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 command format
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED(channel) (0x80 | ((channel) << 4))

// Define CSV file name
#define CSV_FILE "sensor_data.csv"

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008_channel(int fd, int channel);
float convert_to_moisture(int adc_value);
int log_data(FILE *fp, float moisture0, float moisture1, float moisture2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize SPI device
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Transfer data over SPI
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read data from MCP3008 channel
int read_mcp3008_channel(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI command
    tx_buf[0] = MCP3008_START_BIT;
    tx_buf[1] = MCP3008_SINGLE_ENDED(channel);
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transfer
    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading channel %d\n", channel);
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    // Simple linear conversion (adjust as needed)
    return (float)adc_value / 1023.0 * 100.0;
}

// Log data to CSV file
int log_data(FILE *fp, float moisture0, float moisture1, float moisture2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, moisture0, moisture1, moisture2) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read ADC values from channels 0, 1, and 2
        int adc_value0 = read_mcp3008_channel(spi_fd, 0);
        int adc_value1 = read_mcp3008_channel(spi_fd, 1);
        int adc_value2 = read_mcp3008_channel(spi_fd, 2);

        // Convert ADC values to moisture percentages
        float moisture0 = convert_to_moisture(adc_value0);
        float moisture1 = convert_to_moisture(adc_value1);
        float moisture2 = convert_to_moisture(adc_value2);

        // Log data to CSV file
        if (log_data(csv_file, moisture0, moisture1, moisture2) < 0) {
            program_running = 0; // Stop on logging error
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI device and CSV file
    close(spi_fd);
    fclose(csv_file);

    return EXIT_SUCCESS;
}

