    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read ADC values from channels 0, 1, and 2
        int adc_value0 = read_mcp3008_channel(spi_fd, 0);
        int adc_value1 = read_mcp3008_channel(spi_fd, 1);
        int adc_value2 = read_mcp3008_channel(spi_fd, 2);

        // Convert ADC values to moisture percentages
        float moisture0 = convert_to_moisture(adc_value0);
        float moisture1 = convert_to_moisture(adc_value1);
        float moisture2 = convert_to_moisture(adc_value2);

        // Log data to CSV file
        if (log_data(csv_file, moisture0, moisture1, moisture2) < 0) {
