#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define LED_GPIO 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int reconnect_delay = 1; // Initial reconnection delay in seconds

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

// Function to parse JSON payload and extract led_state
int parse_led_state(const char *payload) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        log_error("Failed to parse JSON payload");
        return -1; // Indicate parsing error
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(led_state)) {
        log_error("Invalid JSON format: led_state is not a boolean");
        cJSON_Delete(json);
        return -1; // Indicate invalid format
    }

    int state = led_state->valueint;
    cJSON_Delete(json);
    return state;
}

// Function to set the LED state using pigpio
void set_led_state(int state) {
    gpioWrite(LED_GPIO, state);
}

// Callback function for MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state = parse_led_state((char *)message->payload);
        if (led_state != -1) {
            set_led_state(led_state);
        }
    } else {
        log_error("Empty message received");
    }
}

// Callback function for MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("MQTT connection error");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Received signal %d, cleaning up...\n", signum);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Turn off the LED on startup
    gpioWrite(LED_GPIO, 0);

    // Initialize mosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("mosquitto initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker with exponential backoff
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Start the mosquitto loop
    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up resources
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0); // Turn off LED before exiting
    gpioTerminate();

    return 0;
}

