#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *sound_sensor_line = NULL;
static struct gpiod_line *alarm_led_line = NULL;

// Signal handler for graceful exit
static void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main()
{
    int sound_level;
    int ret;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for sound sensor
    sound_sensor_line = gpiod_chip_get_line(gpio_chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Get GPIO line for alarm LED
    alarm_led_line = gpiod_chip_get_line(gpio_chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED GPIO line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO line for input (sound sensor)
    ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Error requesting sound sensor GPIO line for input");
        gpiod_line_release(alarm_led_line);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO line for output (alarm LED)
    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0);
    if (ret < 0) {
        perror("Error requesting alarm LED GPIO line for output");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sound sensor value
        sound_level = gpiod_line_get_value(sound_sensor_line);
        if (sound_level < 0) {
            perror("Error reading sound sensor value");
            break; // Exit loop on error
        }

        // Print sound level to console
        printf("Sound level: %d\n", sound_level);

        // Check for sound and blink LED
        if (sound_level == 0) {
            // Turn LED on
            ret = gpiod_line_set_value(alarm_led_line, 1);
            if (ret < 0) {
                perror("Error setting alarm LED value");
                break; // Exit loop on error
            }
            sleep(1); // Wait for 1 second

            // Turn LED off
            ret = gpiod_line_set_value(alarm_led_line, 0);
            if (ret < 0) {
                perror("Error setting alarm LED value");
                break; // Exit loop on error
            }
        }

        // Delay for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Clean up GPIO lines and chip
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

