#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main() {
    struct gpiod_line_event event;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    char log_message[100];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request falling-edge event detection
    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor") < 0) {
        perror("Error requesting falling-edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Monitoring vibration on GPIO %d... Press Ctrl+C to exit.\n", GPIO_LINE);

    // Main loop
    while (!terminate) {
        // Wait for event
        if (gpiod_line_event_wait(line, NULL) < 0) {
            perror("Error waiting for event");
            break;
        }

        // Read event
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Error reading event");
            break;
        }

        // Get current time
        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Format log message
        snprintf(log_message, sizeof(log_message), "%s: Vibration detected!\n", timestamp);

        // Write to log file
        if (fprintf(log_fp, "%s", log_message) < 0) {
            perror("Error writing to log file");
            break;
        }
        fflush(log_fp);

        // Print to stdout
        printf("%s", log_message);

        // Shutdown the system
        system("sudo shutdown -h now");
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    return 0;
}

