#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define LM35_SCALE 0.01 // 10mV/°C
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void update_buffer(float temperature);
void log_to_file();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode + channel number
    tx[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx, rx, 3);

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float temperature = voltage / LM35_SCALE;
    return temperature;
}

// Function to update the circular buffer
void update_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to log the buffer to a file
void log_to_file() {
    if (log_file != NULL) {
        fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, log_file);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temp_log.dat", "wb+");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float temperature = convert_to_celsius(adc_value);
            printf("Temperature: %.2f °C\n", temperature);
            update_buffer(temperature);
            if (log_file != NULL) {
                log_to_file();
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    return 0;
}

