#include <linux/spi/spidev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

// Global variables for cleanup
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int read_bh1750(int fd);
int read_mcp3008(int fd, int channel);
void log_data(FILE *fp, int light, int sound);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) close(i2c_fd);
    if (spi_fd != -1) close(spi_fd);
    if (log_file != NULL) fclose(log_file);
    exit(0);
}

// Function to read light level from BH1750 sensor
int read_bh1750(int fd) {
    unsigned char buf[2];
    int lux = -1; // Initialize to an error value

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // 0x10 for continuous high resolution mode
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read two bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert the data
    lux = (buf[0] << 8 | buf[1]) / 1.2; // BH1750 datasheet conversion

    return lux;
}

// Function to read sound level from MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to file
void log_data(FILE *fp, int light, int sound) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
    fflush(fp); // Ensure data is written to disk immediately
}

