    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        close(i2c_fd);
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int light = read_bh1750(i2c_fd);
        int sound = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        if (light != -1 && sound != -1) {
            log_data(log_file, light, sound);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log entry.\n");
        }

        sleep(1);
    }

    return 0;
}

