#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO
int init_gpio()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with pull-down\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value\n");
        return -1;
    }
    return value;
}

// Function to log the event to a file
int log_event(int state)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, GPIO_LINE, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle flame detection
void handle_flame_detection()
{
    printf("Flame detected!\n");
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (log_event(sensor_value) < 0) {
            fprintf(stderr, "Error logging event, continuing...\n");
        }

        if (sensor_value == 1) {
            handle_flame_detection();
        }

        sleep(1);
    }

    // Cleanup resources
    printf("Cleaning up resources...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

