#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define I2C_ADDRESS 0x62
#define DAC_VREF 3300.0 // mV
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int write_mcp4725(int dac_value);
void log_data(int adc_value, float temperature, int dac_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * DAC_VREF) / 1024.0;
    float temperature = (voltage - 500.0) / 10.0;
    return temperature;
}

// Function to write to MCP4725 DAC
int write_mcp4725(int dac_value) {
    if (dac_value < 0 || dac_value > 4095) {
        fprintf(stderr, "Error: DAC value out of range: %d\n", dac_value);
        return -1;
    }

    char buffer[3];
    buffer[0] = 0x40; // Write DAC value command
    buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    buffer[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    int result = i2cWriteDevice(i2c_handle, buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed with code %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to file and stdout
void log_data(int adc_value, float temperature, int dac_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %d\n", timestamp, adc_value, temperature, dac_value);
    fflush(log_file);

    printf("%s, ADC: %d, Temperature: %.2f C, DAC: %d\n", timestamp, adc_value, temperature, dac_value);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, I2C_ADDRESS, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Map temperature to DAC value (0V to 3.3V)
        int dac_value = (int)((temperature / 50.0) * 4095.0);

        // Write to DAC
        if (write_mcp4725(dac_value) != 0) {
            fprintf(stderr, "Error: Failed to write to DAC\n");
        }

        // Log data
        log_data(adc_value, temperature, dac_value);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

