#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define the GPIO chip number (usually 0 for Raspberry Pi)
#define GPIOCHIP 0

// Global variables for GPIO lines and chip
static struct gpiod_chip *chip;
static struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    if (relay1_line) gpiod_line_set_value(relay1_line, 0);
    if (relay2_line) gpiod_line_set_value(relay2_line, 0);
    if (relay3_line) gpiod_line_set_value(relay3_line, 0);
    if (relay4_line) gpiod_line_set_value(relay4_line, 0);

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "relay2", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "relay3", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        perror("Error requesting GPIO line for output");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Activate relays sequentially
        if (gpiod_line_set_value(relay1_line, 1) < 0) perror("Error setting relay 1 value");
        if (gpiod_line_set_value(relay2_line, 1) < 0) perror("Error setting relay 2 value");
        if (gpiod_line_set_value(relay3_line, 1) < 0) perror("Error setting relay 3 value");
        if (gpiod_line_set_value(relay4_line, 1) < 0) perror("Error setting relay 4 value");
        sleep(1);

        // Deactivate relays sequentially
        if (gpiod_line_set_value(relay1_line, 0) < 0) perror("Error setting relay 1 value");
        if (gpiod_line_set_value(relay2_line, 0) < 0) perror("Error setting relay 2 value");
        if (gpiod_line_set_value(relay3_line, 0) < 0) perror("Error setting relay 3 value");
        if (gpiod_line_set_value(relay4_line, 0) < 0) perror("Error setting relay 4 value");
        sleep(1);
    }

cleanup:
    // Cleanup resources before exiting
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);
    if (chip) gpiod_chip_close(chip);

    return 1;
}

