#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define MICROPHONE_PIN 26 // GPIO pin connected to the microphone output
#define LED_PIN 16        // GPIO pin connected to the LED

// Define ADC parameters
#define ADC_RESOLUTION 10 // 10-bit ADC
#define ADC_MAX_VALUE (1 << ADC_RESOLUTION) - 1 // Maximum ADC value (1023 for 10-bit)

// Define clap detection threshold
#define CLAP_THRESHOLD (0.7 * 3.3) // 70% of 3.3V

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1; // Flag to control the main loop
static volatile unsigned long last_clap_time = 0; // Timestamp of the last clap

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int state);
void print_clap_message();
void debounce();
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        running = 0; // Stop the main loop
        gpioWrite(LED_PIN, 0); // Turn off the LED
        gpioTerminate(); // Terminate pigpio
        exit(0); // Exit the program
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Read ADC value from the microphone pin
int read_adc() {
    int adc_value = 0;
    int i;

    // Sample the ADC multiple times and average the results
    for (i = 0; i < 10; i++) {
        // Read the GPIO pin level (0 or 1) and scale it to the ADC range
        int gpio_level = gpioRead(MICROPHONE_PIN);
        adc_value += (gpio_level == 1) ? ADC_MAX_VALUE : 0; // Treat HIGH as ADC_MAX_VALUE
        gpioDelay(1); // Small delay between samples
    }

    return adc_value / 10; // Return the average ADC value
}

// Detect a clap based on the ADC value
int detect_clap(int adc_value) {
    float voltage = (float)adc_value / ADC_MAX_VALUE * 3.3; // Convert ADC value to voltage
    return (voltage > CLAP_THRESHOLD) ? 1 : 0; // Return 1 if clap detected, 0 otherwise
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state); // Set the LED pin to the specified state
}

// Print a timestamped clap detection message
void print_clap_message() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Clap detected!\n", timestamp);
}

// Debounce the clap detection
void debounce() {
    last_clap_time = gpioTick(); // Update the last clap time
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_adc(); // Read the ADC value
        int clap_detected = detect_clap(adc_value); // Detect a clap

        if (clap_detected) {
            unsigned long current_time = gpioTick();
            if (current_time - last_clap_time > DEBOUNCE_TIME * 1000) { // Check debounce time
                control_led(1); // Turn on the LED
                print_clap_message(); // Print the clap message
                debounce(); // Debounce the clap
                gpioDelay(500); // Keep the LED on for 500ms
                control_led(0); // Turn off the LED
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

