        int pump_status = (moisture_percentage < MOISTURE_THRESHOLD) ? 1 : 0;
        if (control_pump(pump_status) < 0) {
            fprintf(log_file, "Error controlling pump. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }

        // Log data
        if (log_data(moisture_percentage, pump_status) < 0) {
            fprintf(log_file, "Error logging data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }

        printf("Moisture: %.2f%%, Pump: %s\n", moisture_percentage, pump_status ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("Shutting down...\n");
    control_pump(0); // Turn off pump
    gpiod_line_release(pump_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

