#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define ADC_CHANNEL 0
#define VREF 5.0
#define SENSITIVITY 0.1
#define LOG_FILE "current_log.txt"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
float calculate_current(int adc_value);
int log_current(float current);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize GPIO
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "current_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed Hz
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate current
float calculate_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float current = voltage / SENSITIVITY;
    return current;
}

// Log current to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.4f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Current sensor application started.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate current
        float current = calculate_current(adc_value);

        // Log current
        if (log_current(current) < 0) {
            fprintf(stderr, "Error logging current. Retrying.\n");
        }

        printf("Current: %.4f A\n", current);

        sleep(1); // Read every 1 second
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Current sensor application terminated.\n");
    return 0;
}

