#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define ZERO_CURRENT_VOLTAGE 2.5
#define FULL_SCALE_CURRENT_VOLTAGE 5.0
#define FULL_SCALE_CURRENT 50.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_current(float voltage);
void log_current(float current);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx, rx, 3);

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    if (voltage < ZERO_CURRENT_VOLTAGE || voltage > FULL_SCALE_CURRENT_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage out of range (%fV). Skipping sample.\n", voltage);
        return -1.0; // Indicate an error
    }
    return (voltage - ZERO_CURRENT_VOLTAGE) * (FULL_SCALE_CURRENT / (FULL_SCALE_CURRENT_VOLTAGE - ZERO_CURRENT_VOLTAGE));
}

// Function to log current to file
void log_current(float current) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("current_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fflush(fp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping sample.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value / 1023.0 * VREF;

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        if (current >= 0) {
            // Log current
            log_current(current);
        }

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Current monitoring stopped.\n");
    return 0;
}

