#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define LOG_INTERVAL_SEC 1

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_sensor(struct gpiod_line *line) {
    int i, low_count = 0;
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", gpiod_line_name(line));
            return -1; // Indicate error
        }
        if (value == 0) {
            low_count++;
        }
        usleep(DEBOUNCE_DELAY_MS * 1000); // 2ms delay
    }
    return (low_count > DEBOUNCE_SAMPLES / 2) ? 0 : 1; // 0 if majority LOW, 1 if majority HIGH
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = LOG_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error(NULL));
        return 1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting sensor 1 line: %s\n", gpiod_error(NULL));
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting sensor 2 line: %s\n", gpiod_error(NULL));
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting sensor 1 line: %s\n", gpiod_error(NULL));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting sensor 2 line: %s\n", gpiod_error(NULL));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (!terminate) {
        int sensor1_state = read_sensor(sensor1_line);
        int sensor2_state = read_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return 0;
}

