#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 200 // milliseconds
#define POLL_INTERVAL 50  // milliseconds
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_DIR "/home/pi/security_cam/"
#define MAX_FILENAME_LENGTH 256

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting motion detector...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(GPIO_PIN);
    struct timespec last_change_time;
    clock_gettime(CLOCK_MONOTONIC, &last_change_time);

    while (!terminate) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long time_diff_ms = (now.tv_sec - last_change_time.tv_sec) * 1000 + (now.tv_nsec - last_change_time.tv_nsec) / 1000000;

            if (time_diff_ms >= DEBOUNCE_TIME) {
                last_state = current_state;
                clock_gettime(CLOCK_MONOTONIC, &last_change_time);

                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected!");

                    // Generate ISO 8601 timestamp
                    time_t rawtime;
                    struct tm *timeinfo;
                    char filename[MAX_FILENAME_LENGTH];
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(filename, sizeof(filename), IMAGE_DIR "%Y%m%dT%H%M%S%z.jpg", timeinfo);

                    // Check if the directory exists, create if not
                    char dir[MAX_FILENAME_LENGTH];
                    strncpy(dir, IMAGE_DIR, sizeof(dir) - 1);
                    dir[sizeof(dir) - 1] = '\0'; // Ensure null termination
                    if (access(dir, F_OK) == -1) {
                        if (mkdir(dir, 0777) == -1) {
                            syslog(LOG_ERR, "Failed to create directory: %s", dir);
                            continue; // Skip capture if directory creation fails
                        }
                    }

                    // Construct the libcamera-still command
                    char command[512];
                    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --encoding jpeg --timeout 1000", filename, IMAGE_WIDTH, IMAGE_HEIGHT);

                    syslog(LOG_INFO, "Capturing image: %s", filename);

                    // Execute the command
                    int status = system(command);

                    if (status == 0) {
                        syslog(LOG_INFO, "Image captured successfully.");
                    } else {
                        syslog(LOG_ERR, "Image capture failed with status: %d", status);
                    }
                }
            }
        }
        gpioDelay(POLL_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    gpioTerminate();
    syslog(LOG_INFO, "Exiting...");
    closelog();
    return 0;
}

