#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAME_SIZE (WIDTH * HEIGHT * 2) // Assuming YUYV format
#define LOG_FILE "frame_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int video_fd = -1;
FILE *log_file = NULL;

// Structure to hold V4L2 buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the V4L2 device
int init_v4l2(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(*fd);
        return -1;
    }

    struct buffer *buffers = calloc(req.count, sizeof(struct buffer));
    if (!buffers) {
        perror("Error allocating buffers");
        close(*fd);
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(*fd);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(*fd);
            free(buffers);
            return -1;
        }
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(*fd);
            for (int j = 0; j < i; j++) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(*fd);
        for (int i = 0; i < req.count; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        return -1;
    }

    return 0;
}

// Function to capture a frame and log the timestamp
int capture_frame(int fd, FILE *log_file) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    fprintf(log_file, "%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
    fflush(log_file);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to release resources
void release_resources(int fd, FILE *log_file, struct buffer *buffers, int buffer_count) {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    if (fd != -1) {
        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        for (int i = 0; i < buffer_count; i++) {
            if (buffers[i].start != MAP_FAILED && buffers[i].start != NULL) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }

        close(fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (buffers != NULL) {
        free(buffers);
    }
}

int main() {
    int fd = -1;
    FILE *log_file = NULL;
    struct buffer *buffers = NULL;
    int buffer_count = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize V4L2 device
    if (init_v4l2(&fd) < 0) {
        fprintf(stderr, "Failed to initialize V4L2 device\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        release_resources(fd, NULL, NULL, 0);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        if (capture_frame(fd, log_file) < 0) {
            fprintf(stderr, "Failed to capture frame\n");
            break;
        }
    }

    // Release resources before exiting
    release_resources(fd, log_file, buffers, buffer_count);

    return EXIT_SUCCESS;
}

