#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define MAX_FRAME_SIZE (640 * 480 * 2) // YUYV, 640x480
#define MAX_UDP_DATAGRAM_SIZE 65000
#define MAX_FRAGMENTS (MAX_FRAME_SIZE / MAX_UDP_DATAGRAM_SIZE + 1)

struct frame_header {
    int frame_index;
    int fragment_index;
    int total_fragments;
    size_t payload_size;
};

struct udp_packet {
    struct frame_header header;
    unsigned char payload[MAX_UDP_DATAGRAM_SIZE - sizeof(struct frame_header)];
};

static int fd = -1;
static void *buffers[4];
static size_t buffer_sizes[4];
static int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", "/dev/video0");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", "/dev/video0");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
        buffer_sizes[i] = buf.length;
    }

    return 0;
}

int start_capturing(int fd) {
    for (int i = 0; i < 4; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting capture");
        return -1;
    }

    return 0;
}

int capture_frame(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.bytesused > buffer_size) {
        fprintf(stderr, "Warning: Frame size (%zu bytes) exceeds buffer size (%zu bytes)\n", buf.bytesused, buffer_size);
    }

    memcpy(buffer, buffers[buf.index], buf.bytesused);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return buf.bytesused;
}

int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping capture");
        return -1;
    }
    return 0;
}

int uninit_device(int fd) {
    for (int i = 0; i < 4; i++) {
        if (munmap(buffers[i], buffer_sizes[i]) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

int close_device(int fd) {
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int send_frame_udp(const char *server_ip, int server_port, int frame_index, const void *frame_data, size_t frame_size) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        perror("Error converting IP address");
        close(sockfd);
        return -1;
    }

    size_t total_fragments = (frame_size + MAX_UDP_DATAGRAM_SIZE - 1) / MAX_UDP_DATAGRAM_SIZE;
    for (size_t i = 0; i < total_fragments; i++) {
        size_t payload_size = (i == total_fragments - 1) ? (frame_size - i * MAX_UDP_DATAGRAM_SIZE) : MAX_UDP_DATAGRAM_SIZE;
        struct udp_packet packet;
        packet.header.frame_index = frame_index;
        packet.header.fragment_index = i;
        packet.header.total_fragments = total_fragments;
        packet.header.payload_size = payload_size;
        memcpy(packet.payload, (const char *)frame_data + i * MAX_UDP_DATAGRAM_SIZE, payload_size);

        if (sendto(sockfd, &packet, sizeof(packet.header) + payload_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) == -1) {
            perror("Error sending UDP packet");
            close(sockfd);
            return -1;
        }
    }

    close(sockfd);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open_device("/dev/video0");
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (start_capturing(fd) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Streaming video to %s:%d...\n", server_ip, server_port);

    int frame_index = 0;
    while (running) {
        unsigned char frame_data[MAX_FRAME_SIZE];
        int bytes_read = capture_frame(fd, frame_data, sizeof(frame_data));
        if (bytes_read == -1) {
            break;
        }

        if (send_frame_udp(server_ip, server_port, frame_index++, frame_data, bytes_read) == -1) {
            fprintf(stderr, "Error sending frame %d, exiting...\n", frame_index - 1);
            break;
        }
    }

    if (stop_capturing(fd) == -1) {
        fprintf(stderr, "Error stopping capture, continuing...\n");
    }

    if (uninit_device(fd) == -1) {
        fprintf(stderr, "Error uninitializing device, continuing...\n");
    }

    if (close_device(fd) == -1) {
        fprintf(stderr, "Error closing device, continuing...\n");
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

