#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

// Define servo parameters
#define SERVO_PERIOD_NS 20000000 // 20ms in nanoseconds
#define SERVO_MIN_DUTY_NS 1000000 // 1ms in nanoseconds
#define SERVO_MAX_DUTY_NS 2000000 // 2ms in nanoseconds
#define SERVO_RANGE 1000 // 1000 steps from 1ms to 2ms

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pan_servo_line;
static struct gpiod_line *tilt_servo_line;
static struct gpiod_line *tilt_up_button_line;
static struct gpiod_line *tilt_down_button_line;
static struct gpiod_line *pan_left_button_line;
static struct gpiod_line *pan_right_button_line;
static int pan_position = 75; // Initial pan position
static int tilt_position = 75; // Initial tilt position
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void set_servo_position(int pin, int position);
int get_button_state(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get pan servo line
    pan_servo_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    if (!pan_servo_line) {
        perror("Error getting pan servo line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get tilt servo line
    tilt_servo_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    if (!tilt_servo_line) {
        perror("Error getting tilt servo line");
        gpiod_line_release(pan_servo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get tilt up button line
    tilt_up_button_line = gpiod_chip_get_line(chip, TILT_UP_BUTTON_PIN);
    if (!tilt_up_button_line) {
        perror("Error getting tilt up button line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get tilt down button line
    tilt_down_button_line = gpiod_chip_get_line(chip, TILT_DOWN_BUTTON_PIN);
    if (!tilt_down_button_line) {
        perror("Error getting tilt down button line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get pan left button line
    pan_left_button_line = gpiod_chip_get_line(chip, PAN_LEFT_BUTTON_PIN);
    if (!pan_left_button_line) {
        perror("Error getting pan left button line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get pan right button line
    pan_right_button_line = gpiod_chip_get_line(chip, PAN_RIGHT_BUTTON_PIN);
    if (!pan_right_button_line) {
        perror("Error getting pan right button line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_line_release(pan_left_button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request lines for output
    if (gpiod_line_request_output(pan_servo_line, "pan_servo", 0) < 0) {
        perror("Error requesting pan servo line for output");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_line_release(pan_left_button_line);
        gpiod_line_release(pan_right_button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(tilt_servo_line, "tilt_servo", 0) < 0) {
        perror("Error requesting tilt servo line for output");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_button_line);
        gpiod_line_release(tilt_down_button_line);
        gpiod_line_release(pan_left_button_line);
        gpiod_line_release(pan_right_button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    return 0;
}

// Set servo position using software PWM
void set_servo_position(int pin, int position) {
    struct timespec start, now;
    long elapsed_ns;
    int duty_ns;

    if (position < 25) position = 25;
    if (position > 125) position = 125;

    duty_ns = SERVO_MIN_DUTY_NS + (position - 25) * (SERVO_MAX_DUTY_NS - SERVO_MIN_DUTY_NS) / 100;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000 + (now.tv_nsec - start.tv_nsec);

        if (elapsed_ns >= SERVO_PERIOD_NS) {
            break;
        }

        if (elapsed_ns < duty_ns) {
            if (pin == PAN_SERVO_PIN) {
                gpiod_line_set_value(pan_servo_line, 1);
            } else {
                gpiod_line_set_value(tilt_servo_line, 1);
            }
        } else {
            if (pin == PAN_SERVO_PIN) {
                gpiod_line_set_value(pan_servo_line, 0);
            } else {
                gpiod_line_set_value(tilt_servo_line, 0);
            }
        }
    }
}

// Get button state
int get_button_state(int pin) {
    int value;
    struct gpiod_line *line;

    switch (pin) {
        case TILT_UP_BUTTON_PIN:
            line = tilt_up_button_line;
            break;
        case TILT_DOWN_BUTTON_PIN:
            line = tilt_down_button_line;
            break;
        case PAN_LEFT_BUTTON_PIN:
            line = pan_left_button_line;
            break;
        case PAN_RIGHT_BUTTON_PIN:
            line = pan_right_button_line;
            break;
        default:
            fprintf(stderr, "Invalid button pin: %d\n", pin);
            return 0; // Return 0 for invalid pin
    }

    value = gpiod_line_get_value(line);
    return (value == 0); // Active-low
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    printf("Cleaning up GPIO resources...\n");

    if (pan_servo_line) {
        gpiod_line_release(pan_servo_line);
    }
