    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    return 0;
}

// Set servo position using software PWM
void set_servo_position(int pin, int position) {
    struct timespec start, now;
    long elapsed_ns;
    int duty_ns;

    if (position < 25) position = 25;
    if (position > 125) position = 125;

    duty_ns = SERVO_MIN_DUTY_NS + (position - 25) * (SERVO_MAX_DUTY_NS - SERVO_MIN_DUTY_NS) / 100;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000 + (now.tv_nsec - start.tv_nsec);

        if (elapsed_ns >= SERVO_PERIOD_NS) {
            break;
        }

        if (elapsed_ns < duty_ns) {
            if (pin == PAN_SERVO_PIN) {
                gpiod_line_set_value(pan_servo_line, 1);
            } else {
                gpiod_line_set_value(tilt_servo_line, 1);
            }
        } else {
            if (pin == PAN_SERVO_PIN) {
                gpiod_line_set_value(pan_servo_line, 0);
            } else {
                gpiod_line_set_value(tilt_servo_line, 0);
            }
        }
    }
}

// Get button state
int get_button_state(int pin) {
    int value;
    struct gpiod_line *line;

    switch (pin) {
        case TILT_UP_BUTTON_PIN:
            line = tilt_up_button_line;
            break;
        case TILT_DOWN_BUTTON_PIN:
            line = tilt_down_button_line;
            break;
        case PAN_LEFT_BUTTON_PIN:
            line = pan_left_button_line;
            break;
        case PAN_RIGHT_BUTTON_PIN:
            line = pan_right_button_line;
            break;
        default:
            fprintf(stderr, "Invalid button pin: %d\n", pin);
            return 0; // Return 0 for invalid pin
    }

    value = gpiod_line_get_value(line);
    return (value == 0); // Active-low
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    printf("Cleaning up GPIO resources...\n");

    if (pan_servo_line) {
        gpiod_line_release(pan_servo_line);
    }
    if (tilt_servo_line) {
        gpiod_line_release(tilt_servo_line);
    }
    if (tilt_up_button_line) {
        gpiod_line_release(tilt_up_button_line);
    }
    if (tilt_down_button_line) {
        gpiod_line_release(tilt_down_button_line);
    }
    if (pan_left_button_line) {
