#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define JPEG_QUALITY 75

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int camera_fd = -1;
struct buffer {
    void   *start;
    size_t  length;
};

struct buffer *buffers = NULL;
unsigned int   n_buffers = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// Function to initialize the camera
int init_camera(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    n_buffers = req.count;

    // Map the buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    // Queue the buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(int fd, void *buffer) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    memcpy(buffer, buffers[buf.index].start, WIDTH * HEIGHT * 2); // Copy YUYV data

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    unsigned char *yp, *up, *vp;
    unsigned char y1, u, y2, v;
    unsigned char r, g, b;

    for (i = 0; i < height; i += 2) {
        for (j = 0; j < width; j += 2) {
            yp = yuyv + (i * width + j) * 2;
            up = yuyv + (i * width + j) * 2 + 1;
            vp = yuyv + (i * width + j) * 2 + 3;

            y1 = yp[0];
            u = up[0];
            y2 = yp[2];
            v = vp[0];

            // YUV to RGB conversion (simplified)
            r = y1 + 1.13983 * (v - 128);
            g = y1 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            b = y1 + 2.03211 * (u - 128);

            rgb[(i * width + j) * 3] = r;
            rgb[(i * width + j) * 3 + 1] = g;
            rgb[(i * width + j) * 3 + 2] = b;

            r = y2 + 1.13983 * (v - 128);
            g = y2 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            b = y2 + 2.03211 * (u - 128);

            rgb[(i * width + j + 1) * 3] = r;
            rgb[(i * width + j + 1) * 3 + 1] = g;
            rgb[(i * width + j + 1) * 3 + 2] = b;

            r = y2 + 1.13983 * (v - 128);
            g = y2 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            b = y2 + 2.03211 * (u - 128);

            rgb[(i * width + j + width) * 3] = r;
            rgb[(i * width + j + width) * 3 + 1] = g;
            rgb[(i * width + j + width) * 3 + 2] = b;

            r = y1 + 1.13983 * (v - 128);
            g = y1 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            b = y1 + 2.03211 * (u - 128);

            rgb[(i * width + j + width + 1) * 3] = r;
            rgb[(i * width + j + width + 1) * 3 + 1] = g;
            rgb[(i * width + j + width + 1) * 3 + 2] = b;
        }
    }
}

// Function to apply a 5x5 box blur filter
void box_blur(unsigned char *src, unsigned char *dst, int width, int height) {
    int i, j, k, l;
    int sum_r, sum_g, sum_b;
    int radius = 2;

    for (i = 0; i < height; ++i) {
        for (j = 0; j < width; ++j) {
            sum_r = sum_g = sum_b = 0;
            for (k = -radius; k <= radius; ++k) {
                for (l = -radius; l <= radius; ++l) {
                    int x = j + l;
                    int y = i + k;

                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        sum_r += src[(y * width + x) * 3];
                        sum_g += src[(y * width + x) * 3 + 1];
                        sum_b += src[(y * width + x) * 3 + 2];
                    }
                }
            }
            dst[(i * width + j) * 3] = sum_r / (radius * 2 + 1);
            dst[(i * width + j) * 3 + 1] = sum_g / (radius * 2 + 1);
            dst[(i * width + j) * 3 + 2] = sum_b / (radius * 2 + 1);
        }
    }
}

// Function to save the image as a JPEG file
int save_jpeg(unsigned char *rgb, int width, int height, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    outfile = fopen("capture.jpg", "wb");
    if (!outfile) {
        perror("Error opening output JPEG file");
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to uninitialize the camera
void uninit_camera(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
        }
    }

    free(buffers);
}

int main() {
    int fd;
    unsigned char *yuyv_frame, *rgb_frame;
    struct tm *tm_info;
    time_t timer;
    char timestamp[26];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the camera device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Cannot open " DEVICE_NAME);
        return EXIT_FAILURE;
    }
    camera_fd = fd; // Store the fd for cleanup

    // Initialize the camera
    if (init_camera(fd) == -1) {
        fprintf(stderr, "Camera initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the frames
    yuyv_frame = malloc(WIDTH * HEIGHT * 2);
    rgb_frame = malloc(WIDTH * HEIGHT * 3);

    if (!yuyv_frame || !rgb_frame) {
        perror("Failed to allocate memory for frames");
        uninit_camera(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture a single frame
    if (capture_frame(fd, yuyv_frame) == -1) {
        fprintf(stderr, "Failed to capture frame\n");
        free(yuyv_frame);
        free(rgb_frame);
        uninit_camera(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    // Convert YUYV to RGB24
    yuyv_to_rgb24(yuyv_frame, rgb_frame, WIDTH, HEIGHT);

    // Apply box blur filter
    unsigned char *blurred_frame = malloc(WIDTH * HEIGHT * 3);
    if (!blurred_frame) {
        perror("Failed to allocate memory for blurred frame");
        free(yuyv_frame);
        free(rgb_frame);
        uninit_camera(fd);
        close(fd);
        return EXIT_FAILURE;
    }
    box_blur(rgb_frame, blurred_frame, WIDTH, HEIGHT);

    // Save the blurred image as a JPEG
    if (save_jpeg(blurred_frame, WIDTH, HEIGHT, JPEG_QUALITY) == -1) {
        fprintf(stderr, "Failed to save JPEG image\n");
    }

    // Get timestamp for filename
    time(&timer);
    tm_info = localtime(&timer);
    strftime(timestamp, 26, "%Y%m%d_%H%M%S", tm_info);
    printf("Image saved as capture_%s.jpg\n", timestamp);

    // Clean up
    free(yuyv_frame);
    free(rgb_frame);
    free(blurred_frame);
    uninit_camera(fd);
    close(fd);

    return EXIT_SUCCESS;
}

