    printf("\nSupported Formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        printf("  %s (FourCC: %c%c%c%c)\n", fmtdesc.description,
               fmtdesc.pixelformat & 0xFF, (fmtdesc.pixelformat >> 8) & 0xFF,
               (fmtdesc.pixelformat >> 16) & 0xFF, (fmtdesc.pixelformat >> 24) & 0xFF);
        fmtdesc.index++;
    }

    // Enumerate frame sizes
    frmsizeenum.index = 0;
    frmsizeenum.pixel_format = fmtdesc.pixelformat; // Use the first format
    printf("\nSupported Frame Sizes for %s:\n", fmtdesc.description);
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsizeenum) == 0) {
        printf("  %dx%d\n", frmsizeenum.discrete.width, frmsizeenum.discrete.height);
        frmsizeenum.index++;
    }

    // Enumerate frame intervals
    frmivalenum.index = 0;
    frmivalenum.pixel_format = fmtdesc.pixelformat; // Use the first format
    frmivalenum.width = 640; // Example width
    frmivalenum.height = 480; // Example height
    printf("\nSupported Frame Intervals for %s (640x480):\n", fmtdesc.description);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmivalenum) == 0) {
        printf("  %d/%d fps\n", frmivalenum.discrete.numerator, frmivalenum.discrete.denominator);
        frmivalenum.index++;
    }

    // Query autofocus control
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("\nAutofocus Support: Supported\n");
    } else {
        printf("\nAutofocus Support: Not Supported\n");
    }

    close(fd);
    return 0;
}

