#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define servo center position
#define CENTER_PULSE_WIDTH 1500

// Define button press duration
#define BUTTON_PRESS_DURATION 50 // milliseconds

// Global variables
volatile int pan_position = CENTER_PULSE_WIDTH;
volatile int tilt_position = CENTER_PULSE_WIDTH;
volatile int up_pressed = 0;
volatile int down_pressed = 0;
volatile int left_pressed = 0;
volatile int right_pressed = 0;

// Function prototypes
void signal_handler(int signal);
void button_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active-low)
        if (gpio == UP_BUTTON_PIN) {
            up_pressed = 1;
        } else if (gpio == DOWN_BUTTON_PIN) {
            down_pressed = 1;
        } else if (gpio == LEFT_BUTTON_PIN) {
            left_pressed = 1;
        } else if (gpio == RIGHT_BUTTON_PIN) {
            right_pressed = 1;
        }
    } else { // Button released
        if (gpio == UP_BUTTON_PIN) {
            up_pressed = 0;
        } else if (gpio == DOWN_BUTTON_PIN) {
            down_pressed = 0;
        } else if (gpio == LEFT_BUTTON_PIN) {
            left_pressed = 0;
        } else if (gpio == RIGHT_BUTTON_PIN) {
            right_pressed = 0;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable internal pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(PAN_SERVO_PIN, 20000); // 20ms period
    gpioSetPWMrange(TILT_SERVO_PIN, 20000);

    // Set PWM frequency (optional, but recommended)
    gpioSetPWMfrequency(PAN_SERVO_PIN, 50); // 50Hz
    gpioSetPWMfrequency(TILT_SERVO_PIN, 50);

    // Set initial servo positions
    gpioServo(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    gpioServo(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Print startup message
    printf("Pan-Tilt System Control\n");
    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Center Position: Pan = %d us, Tilt = %d us\n", CENTER_PULSE_WIDTH, CENTER_PULSE_WIDTH);

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback functions for button presses
    gpioSetAlertFunc(UP_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(DOWN_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(LEFT_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(RIGHT_BUTTON_PIN, button_callback);

