#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define SERVER_PORT 8080
#define SERVER_PATH "/upload"

volatile sig_atomic_t program_running = 1;
int last_motion_state = 0; // 0: no motion, 1: motion detected
time_t last_motion_time = 0;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

// Function to get current timestamp in ISO 8601 format
char* get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char* timestamp = malloc(30 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    sprintf(timestamp + strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000); // Add microseconds
    return timestamp;
}

// Function to capture a JPEG image using libcamera-still
int capture_image(const char* filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n --width 640 --height 480 --quality 85 --encoding jpeg", filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute libcamera-still");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to send data to the server using libcurl
int send_data(const char* filename, const char* timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json_payload[512];

    // Construct JSON payload
    snprintf(json_payload, sizeof(json_payload), 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        char url[256];
        snprintf(url, sizeof(url), "http://127.0.0.1:%d%s", SERVER_PORT, SERVER_PATH);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char* server_ip = argv[1];
    const char* server_port_str = argv[2];
    int server_port = atoi(server_port_str);

    if (server_port <= 0) {
        fprintf(stderr, "Invalid server port number.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char filename[64];
    time_t current_time;
    struct tm time_info;
    char timestamp[30];

    while (program_running) {
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected && !last_motion_state) {
            // Motion detected
            current_time = time(NULL);
            localtime_r(&current_time, &time_info);
            strftime(filename, sizeof(filename), "motion_%Y%m%d_%H%M%S.jpg", &time_info);
            snprintf(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &time_info);

            if (capture_image(filename) == 0) {
                if (send_data(filename, timestamp, 1, GPIO_PIN) != 0) {
                    fprintf(stderr, "Failed to send data to server.\n");
                }
            } else {
                fprintf(stderr, "Failed to capture image.\n");
            }

            last_motion_state = 1;
            last_motion_time = current_time;
        } else if (!motion_detected && last_motion_state) {
            // Motion stopped
            current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                if (send_data(filename, timestamp, 0, GPIO_PIN) != 0) {
                    fprintf(stderr, "Failed to send data to server.\n");
                }
                last_motion_state = 0;
            }
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    return 0;
}

