#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define LIBCAMERA_STILL_PATH "/usr/bin/libcamera-still"
#define CAPTURE_TIMEOUT_MS 2000

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int log_event(const char *message);
int capture_image(const char *filename);
char *generate_filename(char *filename_buffer, size_t buffer_size);
int debounce();
void signal_handler(int sig);

// Logging function
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Image capture function
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "%s -o %s --width 640 --height 480 -q 85 --timeout %d --nopreview",
             LIBCAMERA_STILL_PATH, filename, CAPTURE_TIMEOUT_MS);

    int status = system(command);
    if (status == -1) {
        log_event("Error: Failed to execute libcamera-still.");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        char error_message[64];
        snprintf(error_message, sizeof(error_message), "Error: libcamera-still exited with status %d.", WEXITSTATUS(status));
        log_event(error_message);
        return -1;
    }

    return 0;
}

// Filename generation function
char *generate_filename(char *filename_buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(filename_buffer, buffer_size, "%Y%m%d_%H%M%S", t);
    snprintf(filename_buffer + strlen(filename_buffer), buffer_size - strlen(filename_buffer), "_%03d.jpg", (int)(now % 1000));
    return filename_buffer;
}

// Debounce function
int debounce() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
    return nanosleep(&ts, NULL);
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    log_event("Signal received, exiting...");
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    log_event("Starting motion capture...");

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Error: Could not open GPIO chip.");
        fclose(log_file);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_event("Error: Could not get GPIO line.");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Request GPIO line for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        log_event("Error: Could not request GPIO line.");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            log_event("Error: Could not read GPIO value.");
            break;
        }

        if (value == 0) { // Motion detected (LOW signal)
            log_event("Motion detected!");

            // Debounce
            if (debounce() == -1) {
                log_event("Error: Debounce failed.");
                break;
            }

            // Generate filename
            char filename[128];
            generate_filename(filename, sizeof(filename));

            // Capture image
            if (capture_image(filename) == 0) {
                char message[128];
                snprintf(message, sizeof(message), "Image captured: %s", filename);
                log_event(message);
            } else {
                log_event("Error: Image capture failed.");
            }
        }

        // Small delay to avoid busy-waiting
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    log_event("Exiting.");
    return 0;
}

