#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define CROPPED_WIDTH 200
#define CROPPED_HEIGHT 150
#define CROP_X 100
#define CROP_Y 50

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;

static void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    if (buffer) {
        if (munmap(buffer, buffer_size) == -1) {
            perror("munmap");
        }
    }
    if (fd != -1) {
        close(fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    // Query buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for frame
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue the buffer
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify format
    if (fmt.fmt.pix.width != 640 || fmt.fmt.pix.height != 480 || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV || fmt.fmt.pix.field != V4L2_FIELD_NONE) {
        fprintf(stderr, "Format mismatch: expected 640x480 YUYV, got %dx%d %d %d\n", fmt.fmt.pix.width, fmt.fmt.pix.height, fmt.fmt.pix.pixelformat, fmt.fmt.pix.field);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Crop the frame
    FILE *out = fopen("cropped.yuv", "wb");
    if (!out) {
        perror("fopen");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t offset = (CROP_Y * 640 + CROP_X) * 2; // YUYV: Y0 U Y1 V
    size_t cropped_size = CROPPED_WIDTH * CROPPED_HEIGHT * 2;
    size_t row_size = 640 * 2; // YUYV: Y0 U Y1 V

    for (size_t i = 0; i < CROPPED_HEIGHT; ++i) {
        if (fwrite(((char*)buffer) + offset + (i * 640 * 2), 1, row_size, out) != row_size) {
            perror("fwrite");
            fclose(out);
            ioctl(fd, VIDIOC_STREAMOFF, &type);
            munmap(buffer, buffer_size);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    fclose(out);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Clean up
    munmap(buffer, buffer_size);
    close(fd);

    printf("Frame captured and cropped successfully. Cropped image saved to cropped.yuv\n");
    return EXIT_SUCCESS;
}

