#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define neutral position (90 degrees)
#define NEUTRAL_PAN 90
#define NEUTRAL_TILT 90

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM range (microseconds)
#define PWM_RANGE 20000 // 20ms period (50Hz) * 1000 (microseconds)

// Define angle increment (5 degrees)
#define ANGLE_INCREMENT 5

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_PAN;
int tilt_angle = NEUTRAL_TILT;

// Function prototypes
int map_angle_to_pulsewidth(int angle);
int set_servo_angle(int gpio, int angle);
void handle_input(char input);
void signal_handler(int signal);

// Function to map angle (0-180) to pulsewidth (500-2500)
int map_angle_to_pulsewidth(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180).\n");
        return -1; // Indicate error
    }
    return 500 + (int)((float)angle / 180.0 * (2500 - 500));
}

// Function to set servo angle using pigpio
int set_servo_angle(int gpio, int angle) {
    int pulsewidth = map_angle_to_pulsewidth(angle);
    if (pulsewidth == -1) {
        return -1; // Propagate error from mapping function
    }

    if (gpioServo(gpio, pulsewidth) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulsewidth for GPIO %d.\n", gpio);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to handle user input
void handle_input(char input) {
    int new_pan_angle = pan_angle;
    int new_tilt_angle = tilt_angle;

    switch (input) {
        case 'w':
            new_tilt_angle += ANGLE_INCREMENT;
            break;
        case 's':
            new_tilt_angle -= ANGLE_INCREMENT;
            break;
        case 'a':
            new_pan_angle -= ANGLE_INCREMENT;
            break;
        case 'd':
            new_pan_angle += ANGLE_INCREMENT;
            break;
        case 'q':
            // Quit program
            set_servo_angle(PAN_GPIO, NEUTRAL_PAN);
            set_servo_angle(TILT_GPIO, NEUTRAL_TILT);
            gpioTerminate();
            exit(0);
        default:
            return; // Ignore other inputs
    }

    // Validate angles
    if (new_pan_angle < 0 || new_pan_angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180).\n");
        return;
    }
    if (new_tilt_angle < 0 || new_tilt_angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180).\n");
        return;
    }

    // Set new angles
    if (set_servo_angle(PAN_GPIO, new_pan_angle) == 0) {
        pan_angle = new_pan_angle;
    }
    if (set_servo_angle(TILT_GPIO, new_tilt_angle) == 0) {
        tilt_angle = new_tilt_angle;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_servo_angle(PAN_GPIO, NEUTRAL_PAN);
    set_servo_angle(TILT_GPIO, NEUTRAL_TILT);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Set initial angles
    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    char input;
    while (1) {
        if (scanf(" %c", &input) == 1) {
            handle_input(input);
        } else {
            // Handle potential error during scanf
            fprintf(stderr, "Error reading input.\n");
            break; // Exit loop on error
        }
        usleep(100000); // 100ms delay
    }

    // Clean up and exit
    set_servo_angle(PAN_GPIO, NEUTRAL_PAN);
    set_servo_angle(TILT_GPIO, NEUTRAL_TILT);
    gpioTerminate();

    return 0;
}

