        gpioTerminate();
        return 1;
    }

    // Initialize SSD1306
    if (ssd1306_init() != 0) {
        fprintf(stderr, "SSD1306 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

