int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SSD1306_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SSD1306
    if (ssd1306_init() != 0) {
        fprintf(stderr, "SSD1306 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();

        // Format temperature and usage strings
        char temp_str[10];
        char usage_str[10];

        if (temp == -1) {
            strcpy(temp_str, "ERR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "%dC", temp);
        }

        if (usage == -1) {
            strcpy(usage_str, "ERR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "%d%%", usage);
        }

        // Clear the display
        ssd1306_clear();

        // Draw temperature and usage strings
        ssd1306_draw_string(0, 0, "Temp:", 1);
        ssd1306_draw_string(0, 8, temp_str, 1);
        ssd1306_draw_string(0, 16, "Usage:", 1);
        ssd1306_draw_string(0, 24, usage_str, 1);

        // Display the buffer
        ssd1306_display();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

// Initialize SSD1306
int ssd1306_init() {
    // Initialization sequence
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 fps)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) < 0) {
            fprintf(stderr, "I2C write error during initialization\n");
            return -1;
        }
    }

    return 0;
}

// Clear the display buffer
void ssd1306_clear() {
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        ssd1306_send_data(0x00);
    }
}

// Display the buffer contents
void ssd1306_display() {
    // Set column and page address
    ssd1306_send_command(0x21); // Column start/end address
    ssd1306_send_command(0x00); // Start at column 0
    ssd1306_send_command(0x7F); // End at column 127

    ssd1306_send_command(0x22); // Page start/end address
    ssd1306_send_command(0x00); // Start at page 0
    ssd1306_send_command(0x07); // End at page 7

    // Send the data
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        ssd1306_send_data(0x00); // Dummy data, will be overwritten
    }
}

// Send a command to the SSD1306
void ssd1306_send_command(unsigned char command) {
    if (i2cWriteByteData(i2c_handle, 0x00, command) < 0) {
        fprintf(stderr, "I2C write error (command): %d\n", i2c_handle);
        terminate = 1; // Exit on I2C error
    }
}

// Send data to the SSD1306
void ssd1306_send_data(unsigned char data) {
    if (i2cWriteByteData(i2c_handle, 0x40, data) < 0) {
        fprintf(stderr, "I2C write error (data): %d\n", i2c_handle);
        terminate = 1; // Exit on I2C error
    }
}

// Set a pixel on the display
void ssd1306_set_pixel(int x, int y, int color) {
    if (x < 0 || x >= SSD1306_WIDTH || y < 0 || y >= SSD1306_HEIGHT) {
        return; // Ignore out-of-bounds pixels
    }

    int page = y / 8;
    int bit = y % 8;

    unsigned char data = 0x00;
    if (color) {
        data = 1 << bit;
    }

    // Read the current page data
    char buffer[2];
    buffer[0] = 0x00; // Command byte
    buffer[1] = 0x40; // Data byte
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, buffer, 2) < 0) {
        fprintf(stderr, "I2C write error (set pixel - read): %d\n", i2c_handle);
        terminate = 1; // Exit on I2C error
        return;
    }

    char page_data[128];
    if (i2cReadI2CBlockData(i2c_handle, 0x40, page_data, 128) < 0) {
        fprintf(stderr, "I2C read error (set pixel - read): %d\n", i2c_handle);
        terminate = 1; // Exit on I2C error
        return;
    }

    // Modify the pixel data
    page_data[x] |= data;

    // Write the modified page data back
    buffer[0] = 0x40; // Data byte
    if (i2cWriteI2CBlockData(i2c_handle, 0x40, page_data, 128) < 0) {
        fprintf(stderr, "I2C write error (set pixel - write): %d\n", i2c_handle);
        terminate = 1; // Exit on I2C error
    }
}

// Draw a character at a specific position
void ssd1306_draw_char(int x, int y, char c, int color) {
    if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
    c -= 32; // Adjust index to font array

    for (int i = 0; i < FONT_WIDTH; i++) {
        for (int j = 0; j < FONT_HEIGHT; j++) {
            if ((font[c][j] >> i) & 0x01) {
                ssd1306_set_pixel(x + i, y + j, color);
            }
        }
    }
}

// Draw a string at a specific position
void ssd1306_draw_string(int x, int y, const char *str, int color) {
    while (*str) {
        ssd1306_draw_char(x, y, *str, color);
        x += FONT_WIDTH;
        str++;
    }
}

// Read CPU temperature from /sys/class/thermal/thermal_zone0/temp
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(buffer) / 1000; // Convert to degrees Celsius
}

// Read CPU usage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0, prev_idle_total = 0;
    unsigned long long total, idle_total;
    int usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CPU stats file\n");
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading CPU stats file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle_total - prev_idle_total;

    usage = (int)(((double)(total_diff - idle_diff) / total_diff) * 100);

    prev_total = total;
    prev_idle_total = idle_total;

    return usage;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

