#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Define calibration factor (pulses per liter)
#define PULSES_PER_LITER 450.0

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);

// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to update the LCD display
void update_lcd(double flow_rate, double total_volume) {
    char buffer[32];
    int chars_written;

    // Clear the LCD
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(5000); // Delay for clear command to complete

    // Display flow rate
    chars_written = snprintf(buffer, sizeof(buffer), "Flow: %.2f LPM", flow_rate);
    if (chars_written > 0 && chars_written < sizeof(buffer)) {
        i2cWriteByteData(i2c_handle, 0x00, 0x80); // Set cursor to beginning of first line
        for (int i = 0; i < chars_written; i++) {
            i2cWriteByteData(i2c_handle, 0x40, buffer[i]);
        }
    }

    // Display total volume
    chars_written = snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    if (chars_written > 0 && chars_written < sizeof(buffer)) {
        i2cWriteByteData(i2c_handle, 0x00, 0xC0); // Set cursor to beginning of second line
        for (int i = 0; i < chars_written; i++) {
            i2cWriteByteData(i2c_handle, 0x40, buffer[i]);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on GPIO17 (rising edge)
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate flow rate
        double flow_rate = (double)pulse_count / PULSES_PER_LITER * 60.0; // LPM
        pulse_count = 0; // Reset pulse count

        // Calculate total volume
        total_volume += flow_rate / 60.0; // Add flow rate for 1 second

        // Update LCD
        update_lcd(flow_rate, total_volume);

        // Print to console
        printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", flow_rate, total_volume);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

