// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI handle is invalid.\n");
        return -1;
    }

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to read from LCD (PCF8574)
int read_lcd() {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle is invalid.\n");
        return -1;
    }

    char buffer[1];
    int result = i2cReadDevice(i2c_handle, buffer, 1);
    if (result != 1) {
        fprintf(stderr, "Error: I2C read failed: %d\n", result);
        return -1;
    }

    return buffer[0];
}

