#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// Define GPIO pins
#define FLOW_SENSOR_GPIO 17
#define LCD_RS 25
#define LCD_EN 24
#define LCD_D4 23
#define LCD_D5 22
#define LCD_D6 21
#define LCD_D7 14

// Define LCD parameters
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_LINE_1 0x80 // 1st line
#define LCD_LINE_2 0xC0 // 2nd line

#define LCD_BACKLIGHT 0x08  // On
#define LCD_NOBACKLIGHT 0x00 // Off

#define ENABLE_PULSE 1000 // Enable pulse duration in microseconds

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
int i2c_fd;
double flow_rate = 0.0;
double calibration_factor = 7.5;
double flow_rate_sum = 0.0;
int flow_rate_count = 0;
int zero_pulse_count = 0;
int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_set_cursor(int col, int row);
void display_flow_rate(double flow_rate);
void signal_handler(int signal);
void cleanup();

// Function to handle pulses from the flow sensor
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to initialize the LCD
void lcd_init() {
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor blinking
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    delay(500);
}

// Function to send a byte to the LCD in 4-bit mode
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_high);
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_high | ENABLE_PULSE);
    delayMicroseconds(ENABLE_PULSE);
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_high & ~ENABLE_PULSE);
    delayMicroseconds(ENABLE_PULSE);

    // Low bits
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_low);
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_low | ENABLE_PULSE);
    delayMicroseconds(ENABLE_PULSE);
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_low & ~ENABLE_PULSE);
    delayMicroseconds(ENABLE_PULSE);
}

// Function to send a string to the LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    delay(500);
}

// Function to set the cursor position on the LCD
void lcd_set_cursor(int col, int row) {
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(LCD_LINE_1 + row_offsets[row], LCD_CMD);
    lcd_byte(col, LCD_CMD);
}

// Function to display the flow rate on the LCD
void display_flow_rate(double flow_rate) {
    char buffer[17];
    sprintf(buffer, "Flow Rate: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable interrupt
    gpioTerminate(); // Terminate pigpio
    close(i2c_fd); // Close I2C connection
    lcd_clear(); // Clear LCD
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C for LCD
    i2c_fd = wiringPiI2CSetup(0x27);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    lcd_init();

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for the flow sensor
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        cleanup();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Calculate flow rate
        flow_rate = (double)pulse_count / calibration_factor * 60.0; // L/min
        flow_rate_sum += flow_rate;
        flow_rate_count++;

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Reset pulse count
        pulse_count = 0;

        // Check for zero flow rate
        if (flow_rate == 0.0) {
            zero_pulse_count++;
            if (zero_pulse_count > 10) { // Consider sensor absent after 10 seconds of zero flow
                printf("Sensor absent or disconnected.\n");
                lcd_clear();
                lcd_set_cursor(0, 0);
                lcd_string("Sensor Absent");
                running = 0; // Exit the loop
            }
        } else {
            zero_pulse_count = 0; // Reset the counter if flow is detected
        }

        // Wait for 1 second
        sleep(1);

        // Calculate average flow rate over 5 seconds
        if (flow_rate_count >= 5) {
            double average_flow_rate = flow_rate_sum / 5.0;
            printf("Average flow rate: %.2f L/min\n", average_flow_rate);
            flow_rate_sum = 0.0;
            flow_rate_count = 0;
        }
    }

    cleanup();
    return 0;
}

