    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get row lines
    int row_pins[] = ROW_PINS;
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            perror("Error getting row line");
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "wave_led", 0) < 0) {
            perror("Error requesting row line as output");
            return -1;
        }
    }

    // Get column lines
    int col_pins[] = COL_PINS;
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            perror("Error getting column line");
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "wave_led", 1) < 0) {
            perror("Error requesting column line as output");
            return -1;
        }
    }

    return 0;
}

