    int spad_nb = i2cReadWordData(i2c_handle, VL53L3CX_REG_RESULT_SPAD_NB);
    if (spad_nb < 0) {
        fprintf(stderr, "Error reading SPAD number from sensor.\n");
        return -1;
    }
    data->spad_nb = (uint16_t)spad_nb;

    int peak_signal_rate = i2cReadWordData(i2c_handle, VL53L3CX_REG_RESULT_PEAK_SIGNAL_RATE);
    if (peak_signal_rate < 0) {
        fprintf(stderr, "Error reading peak signal rate from sensor.\n");
        return -1;
    }
    data->peak_signal_rate = (uint32_t)peak_signal_rate;

    int distance = i2cReadWordData(i2c_handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance from sensor.\n");
        return -1;
    }
    data->distance_mm = (uint16_t)distance;

    return 0;
}

// Function to log sensor data with ISO-8601 timestamp
void log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s, Model ID: 0x%02X, Revision ID: 0x%02X, Range Status: 0x%02X, SPAD Number: %u, Peak Signal Rate: %u, Distance: %u mm\n",
           timestamp, data.model_id, data.revision_id, data.range_status, data.spad_nb, data.peak_signal_rate, data.distance_mm);
}

