    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor model ID
    int model_id = i2cReadByteData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID from sensor.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0xEACC)\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log sensor data
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

