// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define DISTANCE_REGISTER 0x0D
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_distance(int *distance);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char reg_addr = DISTANCE_REGISTER;
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg_addr, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write register address: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1]; // Big-endian
    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Distance\n"); // Write header
    }

    fprintf(log_file, "%s,%d\n", timestamp_str, data.distance);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    int distance;
    sensor_data_t data;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Get timestamp
            data.distance = distance;
            data.timestamp = time(NULL);

            // Log data
            if (log_data(data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance, attempting to re-open I2C...\n");
            i2cClose(i2c_handle);
            if (open_i2c_connection() != 0) {
                fprintf(stderr, "Failed to re-open I2C, exiting...\n");
                terminate = 1; // Exit loop if re-open fails
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

