int read_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to initialize the Si1145 sensor
int initialize_sensor(int handle) {
    // Verify PART ID
    int part_id = read_register(handle, PART_ID_REG);
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID (0x%02X, expected 0x45)\n", part_id);
        return -1;
    }

    // Set measurement rate (e.g., every 500ms)
    if (write_register(handle, MEAS_RATE_REG, 0x07) != 0) { // Example value, adjust as needed
        fprintf(stderr, "Error setting measurement rate\n");
        return -1;
    }

    // Clear any stale IRQ
    if (write_register(handle, 0x17, 0x00) != 0) {
        fprintf(stderr, "Error clearing IRQ\n");
        return -1;
    }

    return 0;
}

