    vis_data_high = read_register(handle, ALS_VIS_DATA0 + 1);
    ps1_data_low = read_register(handle, PS1_DATA0);
    ps1_data_high = read_register(handle, PS1_DATA0 + 1);

    if (vis_data_low < 0 || vis_data_high < 0 || ps1_data_low < 0 || ps1_data_high < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *ambient_light = (vis_data_high << 8) | vis_data_low;
    *proximity = (ps1_data_high << 8) | ps1_data_low;

    return 0;
}

