#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"

static volatile int running = 1;
static int led_state = 0; // 0: off, 1: on
static int last_sensor_state = 1; // Assume sensor is initially HIGH

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Function to log an event to the log file
int log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

