#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor I2C address and registers
#define SI1145_ADDR 0x60
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x07
#define SI1145_CH_LIST 0x4F
#define SI1145_PS1_DATA0 0x18
#define SI1145_ALS_VIS_DATA0 0x22
#define SI1145_COMMAND 0x30
#define SI1145_ALS_FORCE 0x06
#define SI1145_PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_sensor_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize the Si1145 sensor
int si1145_init() {
    int status;
    unsigned char part_id;

    // Verify PART_ID
    status = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    part_id = (unsigned char)status;
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Set CH_LIST
    status = i2cWriteByteData(i2c_handle, SI1145_CH_LIST, 0x77); // Enable PS1, ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CH_LIST: %d\n", status);
        return -1;
    }

    // Configure measurement rates (example values)
    status = i2cWriteByteData(i2c_handle, 0x08, 0x0A); // PS1 rate
    if (status < 0) {
        fprintf(stderr, "Error writing PS1 rate: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x09, 0x0A); // ALS rate
    if (status < 0) {
        fprintf(stderr, "Error writing ALS rate: %d\n", status);
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int status;
    unsigned char data[4];

    // Trigger measurement
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_ALS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error triggering ALS measurement: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_PS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error triggering PS measurement: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    // Read PS1 data
    status = i2cReadI2CBlockData(i2c_handle, SI1145_PS1_DATA0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];

    // Read ALS_VIS data
    status = i2cReadI2CBlockData(i2c_handle, SI1145_ALS_VIS_DATA0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    *ambient_light = (data[1] << 8) | data[0];

    return 0;
}

// Log data to CSV file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main() {
    int proximity, ambient_light;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(&proximity, &ambient_light);
        if (status == 0) {
            // Log data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

