#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define WATERING_THRESHOLD 15.0 // cm

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_sensor(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void log_data(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trigger_line, "plant_watering", 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "plant_watering");
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 1);
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width(void) {
    struct gpiod_line_event event;
    int ret;
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for echo to go high
    ret = gpiod_line_event_wait(echo_line, &event, TIMEOUT_US);
    if (ret < 0) {
        perror("Error waiting for echo high");
        return -1;
    }

    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        fprintf(stderr, "Error: Echo did not go high\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo to go low
    ret = gpiod_line_event_wait(echo_line, &event, TIMEOUT_US);
    if (ret < 0) {
        perror("Error waiting for echo low");
        return -1;
    }

    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        fprintf(stderr, "Error: Echo did not go low\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate distance from pulse width
double calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 20000.0; // Divide by 2 for one-way distance
}

// Log data to file
void log_data(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;
    long pulse_width;
    double distance;
    char log_message[256];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger sensor
        trigger_sensor();

        // Measure pulse width
        pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            snprintf(log_message, sizeof(log_message), "Error measuring pulse width");
            log_data(log_message);
            sleep(60);
            continue;
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);

        // Validate distance
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            snprintf(log_message, sizeof(log_message), "Invalid distance: %.2f cm", distance);
            log_data(log_message);
            sleep(60);
            continue;
        }

        // Log distance
        snprintf(log_message, sizeof(log_message), "Distance: %.2f cm", distance);
        log_data(log_message);

        // Check watering threshold
        if (distance < WATERING_THRESHOLD) {
            log_data("Time to water the plant!");
        }

        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

