#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    int status;

    // Enable power and ALS
    status = i2cWriteByteData(i2c_handle, 0x80, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Set ALS integration time
    status = i2cWriteByteData(i2c_handle, 0x81, 0xDB);
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    // Set wait time
    status = i2cWriteByteData(i2c_handle, 0x83, 0xF6);
    if (status < 0) {
        fprintf(stderr, "Error writing to WTIME register: %d\n", status);
        return -1;
    }

    // Set proximity pulse count and length
    status = i2cWriteByteData(i2c_handle, 0x8E, 0x87);
    if (status < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %d\n", status);
        return -1;
    }

    // Set control register
    status = i2cWriteByteData(i2c_handle, 0xF1, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", status);
        return -1;
    }

    // Set config2 register
    status = i2cWriteByteData(i2c_handle, 0x90, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    char buffer[8];
    int status;

    // Read RGB data (0x96-0x9B)
    status = i2cReadI2CBlockData(i2c_handle, 0x96, buffer, 8);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Combine the bytes to form 16-bit values
    *red   = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];
    *green = (uint16_t)buffer[3] << 8 | (uint16_t)buffer[2];
    *blue  = (uint16_t)buffer[5] << 8 | (uint16_t)buffer[4];

    // Read proximity data (0x9C)
    status = i2cReadByteData(i2c_handle, 0x9C);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", status);
        return -1;
    }
    *proximity = (uint8_t)status;

    return 0;
}

// Function to log data to a CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    uint16_t red, green, blue;
    uint8_t proximity;
    int status;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&red, &green, &blue, &proximity) == 0) {
            // Check proximity threshold
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip to the next iteration
            }
            if (initialize_sensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

