#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_PART_ID 0x82
#define SI1182_MEAS_RATE0 0x08
#define SI1182_COMMAND 0x47
#define SI1182_PS_DATA0 0x24
#define SI1182_PS_DATA1 0x25
#define CSV_FILE "heartrate.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *proximity);
float calculate_bpm(uint16_t proximity);
int log_data(FILE *fp, float bpm);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    int result;
    uint8_t buf[1];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading register: %s\n", strerror(errno));
        return -1;
    }

    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *proximity) {
    int result;
    uint8_t data[2];

    // Read PS_DATA0 and PS_DATA1 registers
    data[0] = i2c_read_reg(fd, SI1182_PS_DATA0);
    data[1] = i2c_read_reg(fd, SI1182_PS_DATA1);

    if (data[0] == -1 || data[1] == -1) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    *proximity = (uint16_t)data[1] << 8 | data[0];

    return 0;
}

// Calculate BPM function (placeholder)
float calculate_bpm(uint16_t proximity) {
    // Simple linear mapping for demonstration purposes
    return (float)proximity / 100.0f; // Adjust divisor as needed
}

// Log data function
int log_data(FILE *fp, float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x5A) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    int part_id = i2c_read_reg(i2c_fd, 0x00);
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Error: Incorrect sensor ID. Expected 0x%02X, got 0x%02X\n", SI1182_PART_ID, part_id);
        close(i2c_fd);
        return 1;
    }
    printf("Si1182 sensor found with ID 0x%02X\n", part_id);

    // Configure sensor for proximity measurement
    if (i2c_write_reg(i2c_fd, SI1182_MEAS_RATE0, 0x0A) < 0) { // Example rate
        fprintf(stderr, "Error configuring sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Start measurement
    if (i2c_write_reg(i2c_fd, SI1182_COMMAND, 0x01) < 0) { // Example command
        fprintf(stderr, "Error starting measurement\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t proximity;
    float bpm;
    while (running) {
        if (read_sensor_data(i2c_fd, &proximity) == 0) {
            bpm = calculate_bpm(proximity);
            if (log_data(csv_file, bpm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

