#define GPIO_PIN 17
#define RESULT_RANGE_STATUS 0x14
#define RESULT_INTERRUPT_STATUS 0x13
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define SYSRANGE_START 0x00
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l0x();
int read_distance(int *distance);
void log_distance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L0X sensor
int init_vl53l0x() {
    // Check sensor presence
    int data = i2cReadByteData(i2c_handle, 0x00);
    if (data < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", data);
        return -1;
    }
    if (data != 0xEE) {
        fprintf(stderr, "VL53L0X not found at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L0X sensor
int read_distance(int *distance) {
    int status;
    int timeout_count = 0;

    // Wait for interrupt status to set
    do {
        status = i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            return -1;
        }
        if (status & 0x01) break; // Check bit 0
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
        if (timeout_count > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for interrupt\n");
            return -1;
        }
    } while (1);

    // Read distance data
    char data[14];
    if (i2cReadI2CBlockData(i2c_handle, RESULT_RANGE_STATUS, data, 14) < 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    // Extract distance (bytes 10-11)
    *distance = (data[10] << 8) | data[11];

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

