    if (init_vl53l0x() < 0) {
        fprintf(stderr, "VL53L0X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;
    // Main loop
    while (!terminate) {
        // Wait for falling edge on GPIO pin
        if (gpioRead(GPIO_PIN) == 0) {
            // Read distance
            if (read_distance(&distance) == 0) {
                // Log distance
                log_distance(distance);
                printf("Distance: %d mm\n", distance);
            } else {
                fprintf(stderr, "Error reading distance\n");
            }
            // Debounce: Wait for the pin to go high before continuing
            while (gpioRead(GPIO_PIN) == 0 && !terminate) {
                gpioDelay(1); // Small delay to avoid busy-waiting
            }
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

