#define DISTANCE_REG 0x01
#define SAMPLE_INTERVAL_MS 200
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int trigger_measurement();
int read_distance(int *distance);
void log_data(int distance);
void print_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a distance measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the distance from the sensor
int read_distance(int *distance) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Log the data to a file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Log file is not open!\n");
    }
}

// Print the data to stdout
void print_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, %d\n", timestamp, distance);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    while (!terminate) {
        int distance;

        // Trigger measurement
        if (trigger_measurement() == 0) {
            // Wait for measurement to complete (adjust as needed)
            gpioDelay(50); // 50 ms

            // Read distance
            if (read_distance(&distance) == 0) {
                // Log data
                log_data(distance);

                // Print data
                print_data(distance);
            } else {
                fprintf(stderr, "Failed to read distance, retrying...\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
        }

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

