// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int handle, unsigned char reg, unsigned char *data, int len);
int log_data(FILE *fp, int proximity, int ambient);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read data from the sensor with retries
int read_sensor_data(int handle, unsigned char reg, unsigned char *data, int len) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %d, retry %d\n", reg, len, result, retries + 1);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to a file
int log_data(FILE *fp, int proximity, int ambient) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Proximity: %d, Ambient: %d\n", timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned char proximity_data[2];
    unsigned char ambient_data[2];
    int proximity, ambient;

    // Main loop
    while (!terminate) {
        // Read proximity data
        if (read_sensor_data(i2c_handle, PROXIMITY_REG, proximity_data, 2) == 0) {
            proximity = (proximity_data[1] << 8) | proximity_data[0];
        } else {
            proximity = -1; // Indicate error
        }

        // Read ambient light data
        if (read_sensor_data(i2c_handle, AMBIENT_REG, ambient_data, 2) == 0) {
            ambient = (ambient_data[1] << 8) | ambient_data[0];
        } else {
            ambient = -1; // Indicate error
        }

        // Log the data
        if (log_data(log_file, proximity, ambient) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

