#define DISTANCE_REG_MSB 0x00
#define DISTANCE_REG_LSB 0x01
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm

// Global variables
int i2c_handle;
FILE *log_file;
int threshold = DEFAULT_THRESHOLD;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(int distance);
void control_led(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set back to input
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initializes the ICU-20201 sensor
int initialize_sensor() {
    int who_am_i;
    int retries = 3;

    // Verify WHO_AM_I register
    while (retries > 0) {
        who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (who_am_i >= 0) {
            if (who_am_i == 0x47) {
                printf("ICU-20201 sensor found.\n");
                return 0; // Success
            } else {
                fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
                return -1; // Failure
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure after retries
}

// Reads the distance from the sensor
int read_distance(int *distance) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_MSB, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1; // Failure
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0; // Success
}

// Logs the distance data to a file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Controls the LED based on the distance
void control_led(int distance) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

int main(int argc, char *argv[]) {
    int distance;

    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        printf("Using threshold: %d mm\n", threshold);
    } else {
        printf("Using default threshold: %d mm\n", DEFAULT_THRESHOLD);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tof_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping logging and LED control.\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

