#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_FRAME_LENGTH 15
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_INTERVAL_MS 100 // ms

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_write(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, data, len) != len) {
        perror("Failed to write to the i2c bus.");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read from the i2c bus.");
        return -1;
    }
    return 0;
}

int request_distance_measurement(int fd) {
    uint8_t command_frame[] = COMMAND_FRAME;
    if (i2c_write(fd, SENSOR_ADDRESS, command_frame, sizeof(command_frame)) != 0) {
        fprintf(stderr, "Error requesting distance measurement.\n");
        return -1;
    }
    return 0;
}

int read_distance_data(int fd, uint8_t *data) {
    if (i2c_read(fd, SENSOR_ADDRESS, data, RESPONSE_FRAME_LENGTH) != 0) {
        fprintf(stderr, "Error reading distance data.\n");
        return -1;
    }
    return 0;
}

uint16_t parse_distance(uint8_t *data) {
    return (uint16_t)((data[11] << 8) | data[12]);
}

float calculate_average_distance(uint16_t *distances, int num_samples) {
    if (num_samples == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (float)(sum / num_samples);
}

int log_intrusion(FILE *fp, float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance) < 0) {
        perror("Error writing to log file.");
        return -1;
    }
    fflush(fp); // Ensure immediate write to disk
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus.");
        return 1;
    }

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open intrusion_log.txt");
        close(i2c_fd);
        return 1;
    }

    uint8_t response_data[RESPONSE_FRAME_LENGTH];
    uint16_t distances[10]; // Store 10 samples
    int num_samples = 0;

    while (program_running) {
        if (request_distance_measurement(i2c_fd) == 0) {
            usleep(10000); // 10 ms delay
            if (read_distance_data(i2c_fd, response_data) == 0) {
                if (response_data[0] == 0x50) {
                    uint16_t distance = parse_distance(response_data);
                    distances[num_samples] = distance;
                    num_samples++;

                    if (num_samples == 10) {
                        float average_distance = calculate_average_distance(distances, num_samples);
                        if (average_distance < INTRUSION_THRESHOLD) {
                            if (log_intrusion(log_file, average_distance) != 0) {
                                fprintf(stderr, "Error logging intrusion.\n");
                            }
                        }
                        num_samples = 0; // Reset for next cycle
                    }
                } else {
                    fprintf(stderr, "Invalid header byte: 0x%02X\n", response_data[0]);
                }
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // 100 ms delay
    }

    close(i2c_fd);
    fclose(log_file);
    return 0;
}

