#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define MM_PER_COUNT 0.125

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void sigint_handler(int sig) {
    keep_running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500 * 1000 * 1000; // 500ms

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device responds by reading a register (e.g., status)
    uint8_t status_reg = 0x01; // Example status register
    uint8_t status_data[2];
    if (write(i2c_fd, &status_reg, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }
    if (read(i2c_fd, status_data, 2) != 2) {
        perror("Error reading from I2C device");
        close(i2c_fd);
        return 1;
    }

    // Read distance data
    uint8_t distance_data[2];
    uint16_t raw_distance;
    float distance_mm;

    while (keep_running) {
        if (write(i2c_fd, &DISTANCE_REG, 1) != 1) {
            perror("Error writing to I2C device");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        if (read(i2c_fd, distance_data, 2) != 2) {
            perror("Error reading from I2C device");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        raw_distance = (distance_data[1] << 8) | distance_data[0];
        distance_mm = raw_distance * MM_PER_COUNT;

        printf("Distance: %.2f mm\n", distance_mm);
        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    return 0;
}

