#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MAX_DISTANCE 38.0    // cm
#define TIMEOUT_US 200000     // 200 ms timeout in microseconds

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long startTime, endTime, pulseWidth;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    pulseWidth = endTime - startTime;
    if (pulseWidth < 0) {
        pulseWidth += 0xFFFFFFFF; // Handle timer wrap-around
    }

    return pulseWidth;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth <= 0) {
        return -1.0; // Indicate invalid pulse width
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2.0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Log the distance with timestamp
        if (distance > 0 && distance <= MAX_DISTANCE) {
            printf("Distance: %.2f cm\n", distance);
        } else if (distance > MAX_DISTANCE) {
            fprintf(stderr, "Error: Distance exceeds maximum range (%.2f cm)\n", MAX_DISTANCE);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

