// Constants
#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 1.0
#define LED_ON_TIME 2 // seconds
#define RANGE_RESOLUTION 0.0486 // meters/bin
#define RANGE_PROFILE_SIZE 64

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Function prototypes
int uart_init(uart_config_t *config);
int read_radar_data(uart_config_t *config, int16_t *range_profile);
float calculate_distance(int16_t range_bin);
int detect_intrusion(float distance);
int log_intrusion(float distance);
void signal_handler(int signal);
int gpio_init();
int gpio_control(int state);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// UART initialization function
int uart_init(uart_config_t *config) {
    config->fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd < 0) {
        perror("Error opening UART port");
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        perror("Error getting UART attributes");
        close(config->fd);
        return -1;
    }

    config->tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 115200 baud, 8 data bits, no parity, 1 stop bit
    config->tty.c_iflag = IGNPAR;                           // Ignore parity errors
    config->tty.c_oflag = 0;
    config->tty.c_lflag = 0; // Non-canonical mode
    config->tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    config->tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds

    if (tcsetattr(config->fd, TCSANOW, &config->tty) != 0) {
        perror("Error setting UART attributes");
        close(config->fd);
        return -1;
    }

    return 0;
}

// Read radar data function
int read_radar_data(uart_config_t *config, int16_t *range_profile) {
    unsigned char buffer[128];
    ssize_t bytes_read = read(config->fd, buffer, sizeof(buffer));

    if (bytes_read < 0) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != sizeof(buffer)) {
        fprintf(stderr, "Warning: Incomplete data read (%zd bytes, expected %zu)\n", bytes_read, sizeof(buffer));
        return -1; // Indicate incomplete read
    }

    // Convert buffer to int16_t range profile
    for (int i = 0; i < RANGE_PROFILE_SIZE; i++) {
        range_profile[i] = (int16_t)((buffer[2 * i] << 8) | buffer[2 * i + 1]);
    }

    return 0;
}

