    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (uart_init(&uart_config) != 0) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(uart_config.fd);
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_config.fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_meters\n");
    }
    rewind(log_file);

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read radar data
        if (read_radar_data(&uart_config, range_profile) == 0) {
            // Calculate distance of the first range bin
            distance = calculate_distance(range_profile[0]);

            // Detect intrusion
            intrusion_detected = detect_intrusion(distance);

            // Log intrusion
            if (intrusion_detected) {
                printf("Intrusion detected at %.4f meters!\n", distance);
                log_intrusion(distance);

                // Activate LED
                gpio_control(1); // Turn LED on
                gpioDelay(LED_ON_TIME * 1000000); // Wait for 2 seconds
                gpio_control(0); // Turn LED off
