#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor_line;
struct gpiod_line *buzzer_line;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int control_buzzer(struct gpiod_line *line, int state);
int log_event(const char *event);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor data
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to control the buzzer
int control_buzzer(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(-ret));
        return -1; // Indicate error
    }
    return 0;
}

// Function to log events with ISO 8601 timestamp
int log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen("obstacle_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request sensor line for input
    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Error requesting sensor line for input: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request buzzer line for output
    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line for output: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    int last_state = -1; // Initialize to an invalid state
    int current_state;

    // Main loop
    while (1) {
        current_state = read_sensor(sensor_line);
        if (current_state < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (current_state != last_state) {
            // State has changed, log the event
            if (current_state == 0) {
                if (control_buzzer(buzzer_line, 1) == 0) {
                    log_event("Obstacle detected");
                }
            } else {
                if (control_buzzer(buzzer_line, 0) == 0) {
                    log_event("Obstacle removed");
                }
            }
            last_state = current_state;
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup (in case of error)
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 1;
}

