#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// Thresholds for parking guidance
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void vl53l1x_stop();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Check if the sensor is present
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "VL53L1X not found. Model ID: 0x%02X\n", model_id);
        return -1;
    }
    printf("VL53L1X sensor found with model ID 0x%02X\n", model_id);

    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x000, 0x00) < 0) {
        fprintf(stderr, "Error writing to reset register\n");
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous back-to-back ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to start register\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance() {
    int distance = -1;
    int status = 0;

    // Start a new measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting range measurement\n");
        return -1;
    }

    // Wait for measurement to complete with timeout
    int timeout_count = 0;
    while (1) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START);
        if (status < 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        if ((status & 0x01) == 0) break; // Check bit 0 for completion
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Timeout waiting for range measurement\n");
            return -1;
        }
    }

    // Read distance
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return distance;
}

