void vl53l1x_stop() {
    // Stop ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error stopping ranging\n");
    }
}

