    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        vl53l1x_stop();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            // Get timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data to file
            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);

            // Print parking guidance message
            if (distance < STOP_THRESHOLD) {
                printf("STOP\n");
            } else if (distance < APPROACH_THRESHOLD) {
                printf("APPROACH\n");
            } else if (distance < SLOW_THRESHOLD) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait 100 ms
