#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define SAMPLE_INTERVAL_MS 100
#define MIN_DISTANCE_MM 50
#define MAX_DISTANCE_MM 500
#define MIN_BLINK_FREQUENCY_HZ 10
#define MAX_BLINK_FREQUENCY_HZ 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle);
float convert_to_mm(int raw_distance);
float map_distance_to_frequency(float distance_mm);
void set_led_frequency(float frequency_hz);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read distance from CH201 sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result, retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            return (buf[0] << 8) | buf[1];
        } else {
            fprintf(stderr, "I2C read failed, retrying... (%d retries left)\n", retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert raw distance to millimeters
float convert_to_mm(int raw_distance) {
    // Assuming raw distance is in units of 0.1 mm
    return (float)raw_distance / 10.0f;
}

// Function to map distance to blink frequency
float map_distance_to_frequency(float distance_mm) {
    if (distance_mm < MIN_DISTANCE_MM) {
        return MAX_BLINK_FREQUENCY_HZ;
    } else if (distance_mm > MAX_DISTANCE_MM) {
        return MIN_BLINK_FREQUENCY_HZ;
    } else {
        return MIN_BLINK_FREQUENCY_HZ + (distance_mm - MIN_DISTANCE_MM) * (MAX_BLINK_FREQUENCY_HZ - MIN_BLINK_FREQUENCY_HZ) / (MAX_DISTANCE_MM - MIN_DISTANCE_MM);
    }
}

// Function to set LED frequency using PWM
void set_led_frequency(float frequency_hz) {
    if (frequency_hz > 0) {
        // Calculate period in microseconds
        int period_us = (int)(1000000.0 / frequency_hz);

        // Set PWM frequency and range
        gpioSetPWMfrequency(LED_GPIO, frequency_hz);
        gpioSetPWMrange(LED_GPIO, 1000); // Range of 0-1000 for smoother transitions

        // Toggle LED every half cycle
        gpioPWM(LED_GPIO, 500); // 50% duty cycle
    } else {
        gpioPWM(LED_GPIO, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        int raw_distance = read_distance(i2c_handle);
        if (raw_distance >= 0) {
            // Convert to millimeters
            float distance_mm = convert_to_mm(raw_distance);

            // Map distance to blink frequency
            float frequency_hz = map_distance_to_frequency(distance_mm);

            // Set LED frequency
            set_led_frequency(frequency_hz);

            // Get current timestamp
            time_t now = time(NULL);
