        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", config.retry_count);
        }

        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

