#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 10

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the sensor event to a file
int log_sensor_event(int sensor_id, const char* event_type) {
    FILE *fp = fopen("proximity_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening proximity_log.txt");
        return -1;
    }

    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    free(timestamp); // Free the allocated memory
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = gpioRead(SENSOR_1_GPIO);
    int sensor2_state = gpioRead(SENSOR_2_GPIO);

    int sensor1_last_state = sensor1_state;
    int sensor2_last_state = sensor2_state;

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor states
        sensor1_state = gpioRead(SENSOR_1_GPIO);
        sensor2_state = gpioRead(SENSOR_2_GPIO);

        // Debounce and log events for sensor 1
        if (sensor1_state != sensor1_last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce
            int debounced_state = gpioRead(SENSOR_1_GPIO);
            if (debounced_state != sensor1_state) {
                // State changed during debounce, ignore
            } else {
                if (sensor1_state == 0) {
                    if (log_sensor_event(1, "DETECTED") != 0) {
                        fprintf(stderr, "Failed to log event for sensor 1\n");
                    }
                } else {
                    if (log_sensor_event(1, "CLEARED") != 0) {
                        fprintf(stderr, "Failed to log event for sensor 1\n");
                    }
                }
                sensor1_last_state = sensor1_state;
            }
        }

        // Debounce and log events for sensor 2
        if (sensor2_state != sensor2_last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce
            int debounced_state = gpioRead(SENSOR_2_GPIO);
            if (debounced_state != sensor2_state) {
                // State changed during debounce, ignore
            } else {
                if (sensor2_state == 0) {
                    if (log_sensor_event(2, "DETECTED") != 0) {
                        fprintf(stderr, "Failed to log event for sensor 2\n");
                    }
                } else {
                    if (log_sensor_event(2, "CLEARED") != 0) {
                        fprintf(stderr, "Failed to log event for sensor 2\n");
                    }
                }
                sensor2_last_state = sensor2_state;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll every 10 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

