#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define DATA_READY_BIT 0x01
#define TIMEOUT_MS 50

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers
int i2c_read_word(int fd, unsigned char high_reg, unsigned char low_reg, unsigned short *value) {
    unsigned char high_val, low_val;
    if (i2c_read_byte(fd, high_reg, &high_val) != 0) return -1;
    if (i2c_read_byte(fd, low_reg, &low_val) != 0) return -1;
    *value = (high_val << 8) | low_val;
    return 0;
}

// Function to trigger a range measurement
int trigger_measurement(int fd) {
    if (i2c_write_byte(fd, MEAS_TRIGGER_REG, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Function to poll the measurement status
int poll_measurement_status(int fd) {
    unsigned char status;
    int timeout_start = time(NULL);
    while (1) {
        if (i2c_read_byte(fd, MEAS_STATUS_REG, &status) != 0) {
            fprintf(stderr, "Error reading measurement status\n");
            return -1;
        }
        if (status & DATA_READY_BIT) {
            return 0;
        }
        if (time(NULL) - timeout_start > TIMEOUT_MS / 1000.0) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
        usleep(1000); // Check every 1 ms
    }
}

// Function to read the distance in millimeters
int read_distance(int fd, unsigned short *distance) {
    if (i2c_read_word(fd, DIST_HIGH_REG, DIST_LOW_REG, distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    return 0;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, unsigned short distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    unsigned short distance;
    struct timespec sleep_time = {0, 500000000}; // 500 ms

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s (errno: %d)\n", strerror(errno), errno);
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (trigger_measurement(i2c_fd) == 0) {
            if (poll_measurement_status(i2c_fd) == 0) {
                if (read_distance(i2c_fd, &distance) == 0) {
                    if (log_data(log_file, distance) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "Error reading distance, skipping sample\n");
                }
            } else {
                fprintf(stderr, "Error polling measurement status, skipping sample\n");
            }
        } else {
            fprintf(stderr, "Error triggering measurement, skipping sample\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

