#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDR 0x4C

// Define the register address for the distance measurement (replace with actual value from datasheet)
#define DISTANCE_REG 0x00

// Define the number of retries for I2C transactions
#define MAX_RETRIES 3

// Define the delay between retries in milliseconds
#define RETRY_DELAY 10

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C handle if it's open
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the distance measurement from the sensor
        int distance = i2cReadWordData(i2c_handle, DISTANCE_REG);

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "I2C read failed: %d\n", distance);

            // Retry the read operation up to MAX_RETRIES times
            for (int i = 0; i < MAX_RETRIES; i++) {
                distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
                if (distance >= 0) {
                    break; // Success, exit retry loop
                }
                fprintf(stderr, "Retrying I2C read (%d/%d): %d\n", i + 1, MAX_RETRIES, distance);
                gpioDelay(RETRY_DELAY * 1000); // Delay in microseconds
            }

            // If all retries failed, log an error message
            if (distance < 0) {
                fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
            }
        } else {
            // Get the current timestamp in milliseconds
            long long timestamp = gpioTick();

            // Log the distance measurement and timestamp to the console
            printf("Timestamp: %lld, Distance: %d mm\n", timestamp, distance);
        }

        // Delay for 100 milliseconds
        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop condition changes.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

