#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// I2C bus
#define I2C_BUS 1

// Register addresses
#define REG_IDENTIFICATION_MODEL_ID 0x00C0
#define REG_IDENTIFICATION_REVISION_ID 0x00C2
#define REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD 0x001E
#define REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE 0x001F
#define REG_START_STOP_CONTROL 0x0400
#define REG_INTERMEASUREMENT_PERIOD 0x04D9
#define REG_RESULT_INTERRUPT_STATUS 0x0046
#define REG_RESULT_RANGE_STATUS 0x004D
#define REG_RESULT_SPAD_NB_DETECTED 0x0050
#define REG_RESULT_DISTANCE 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to write a byte to a VL53L4CX register
int vl53l4cx_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;              // Data to write

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L4CX register
int vl53l4cx_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char buf[1];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *data = buf[0];
    return 0;
}

// Function to read a 16-bit word from a VL53L4CX register
int vl53l4cx_read_word(int handle, uint16_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to initialize the VL53L4CX sensor
int vl53l4cx_init(int handle) {
    // Reset the sensor
    if (vl53l4cx_write_byte(handle, 0x7FFF, 0x00) != 0) return -1;
    gpioDelay(10000); // 10 ms

    // Configure the sensor for continuous ranging
    if (vl53l4cx_write_byte(handle, REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD, 0x00) != 0) return -1;
    if (vl53l4cx_write_byte(handle, REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE, 0x00) != 0) return -1;
    if (vl53l4cx_write_byte(handle, REG_INTERMEASUREMENT_PERIOD, 0x00) != 0) return -1; // Continuous mode
    if (vl53l4cx_write_byte(handle, REG_START_STOP_CONTROL, 0x01) != 0) return -1; // Start ranging

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L4CX sensor
    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t interrupt_status;
        if (vl53l4cx_read_word(i2c_handle, REG_RESULT_INTERRUPT_STATUS, &interrupt_status) == 0) {
            if (interrupt_status & 0x01) { // Check bit 0 for new measurement
                uint16_t distance;
                if (vl53l4cx_read_word(i2c_handle, REG_RESULT_DISTANCE, &distance) == 0) {
                    // Get current timestamp
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);

                    // Log the distance data
                    printf("Timestamp: %ld.%09ld, Distance: %d mm\n", ts.tv_sec, ts.tv_nsec, distance);
                } else {
                    fprintf(stderr, "Error reading distance data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading interrupt status\n");
        }

        gpioDelay(500000); // 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

