#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE -90.0       // degrees
#define MAX_ANGLE 90.0        // degrees
#define LOG_INTERVAL_MS 200

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
void set_servo_angle(float distance);
void log_data(float distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;
    float distance;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high with timeout
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // Check every 1 ms
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Echo signal not received (low).\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // Check every 1 ms
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Echo signal not received (high).\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion and 2 for one-way distance

    return distance;
}

// Function to set servo angle
void set_servo_angle(float distance) {
    float angle;

    // Map distance to angle
    if (distance < MIN_DISTANCE) {
        angle = MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        angle = MAX_ANGLE;
    } else {
        angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    }

    // Set servo pulse width based on angle
    int pulse_width = (int)(500 + (angle * 2000 / 180)); // 500 us for 0 degrees, 2500 us for 180 degrees
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to file
void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();          // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = 0;

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance > 0) {
            set_servo_angle(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Log data every LOG_INTERVAL_MS
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= (LOG_INTERVAL_MS / 1000.0)) {
            log_data(distance);
            last_log_time = current_time;
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

