        return -1;
    }
    printf("VL53L1X model ID: 0x%02X\n", model_id);

    // Software reset
    if (i2cWriteByteData(i2c_handle, REG_SYSTEM_START, 0x00) < 0) {
        fprintf(stderr, "Error writing to reset register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to reset register\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure timing budget
    if (i2cWriteByteData(i2c_handle, REG_TIMING_BUDGET, TIMING_BUDGET) < 0) {
        fprintf(stderr, "Error writing to timing budget register\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    int range_status;
    int distance_msb, distance_lsb;

