        return -1;
    }

    // Wait for data ready
    while (1) {
        range_status = i2cReadByteData(i2c_handle, REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        if (range_status & 0x01) {
