    if (distance_msb < 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    distance_lsb = i2cReadByteData(i2c_handle, REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
    if (distance_lsb < 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
