#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000        // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_THRESHOLD 30.0  // cm

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
double calculateDistance(uint32_t pulse_width);
void activateBuzzer();
void deactivateBuzzer();
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
  gpioWrite(TRIGGER_PIN, 1);
  gpioDelay(10); // 10 us trigger pulse
  gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick) {
  if (level == 1) {
    start_tick = tick;
    echo_received = 1;
  } else if (level == 0) {
    end_tick = tick;
    echo_received = 2;
  }
}

// Function to calculate distance from pulse width
double calculateDistance(uint32_t pulse_width) {
  double distance = (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for round trip
  return distance;
}

// Function to activate the buzzer
void activateBuzzer() {
  gpioWrite(BUZZER_PIN, 1);
}

// Function to deactivate the buzzer
void deactivateBuzzer() {
  gpioWrite(BUZZER_PIN, 0);
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
  printf("\nCaught signal %d, cleaning up...\n", signal);
  running = 0;
  deactivateBuzzer();
  gpioTerminate();
  exit(0);
}

int main() {
  // Initialize pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO modes
  if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
    fprintf(stderr, "Failed to set TRIGGER_PIN to output\n");
    gpioTerminate();
    return 1;
  }
  if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
    fprintf(stderr, "Failed to set ECHO_PIN to input\n");
    gpioTerminate();
    return 1;
  }
  if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
    fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
    gpioTerminate();
    return 1;
  }

  // Register signal handler for Ctrl+C
  signal(SIGINT, signalHandler);

  // Register callback function for echo pin
  if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
    fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
    gpioTerminate();
    return 1;
  }

  // Main loop
  while (running) {
    triggerSensor();
    echo_received = 0; // Reset flag

    // Wait for echo or timeout
    int timeout_count = 0;
    while (!echo_received && timeout_count < TIMEOUT_US) {
      gpioDelay(1); // Check every 1 us
      timeout_count++;
    }

    if (!echo_received) {
      fprintf(stderr, "Timeout: No echo received\n");
      continue; // Skip to next iteration
    }

    // Calculate pulse width
    uint32_t pulse_width = end_tick - start_tick;
    if (pulse_width > 0x80000000) {
      // Handle tick wraparound
      pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
    }

    // Validate pulse width
    if (pulse_width < 1000) { // Minimum pulse width
      fprintf(stderr, "Invalid reading: Pulse width too short (%u us)\n", pulse_width);
      continue; // Skip to next iteration
    }

    // Calculate distance
    double distance = calculateDistance(pulse_width);

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
      fprintf(stderr, "Invalid reading: Distance out of range (%.2f cm)\n", distance);
      continue; // Skip to next iteration
    }

    // Display distance
    printf("Distance: %.2f cm\n", distance);

    // Activate/deactivate buzzer based on distance
    if (distance < BUZZER_THRESHOLD) {
      activateBuzzer();
    } else {
      deactivateBuzzer();
    }

    gpioDelay(100); // Delay 100 ms
  }

  // Clean up and exit
  deactivateBuzzer();
  gpioTerminate();
  return 0;
}

