#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define MQTT_BROKER "localhost" // Replace with your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define MQTT_CLIENT_ID "gate_controller"

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_open();
void servo_close();
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);
int mqtt_publish_status(int distance);

// VL53L1X Initialization
int vl53l1x_init() {
    int status = 0;
    int retries = 3;

    while (retries > 0) {
        // Software reset
        char buf[2];
        buf[0] = 0x00; // Reset register
        buf[1] = 0x01; // Reset value
        if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
            fprintf(stderr, "Error: VL53L1X reset failed.\n");
            log_event("VL53L1X reset failed");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }
        gpioDelay(100); // Wait for reset to complete

        // Check sensor ID
        char reg = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
        if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
            fprintf(stderr, "Error: VL53L1X ID read failed.\n");
            log_event("VL53L1X ID read failed");
            retries--;
            gpioDelay(100);
            continue;
        }
        char id;
        if (i2cReadDevice(i2c_handle, &id, 1) != 0) {
            fprintf(stderr, "Error: VL53L1X ID read failed.\n");
            log_event("VL53L1X ID read failed");
            retries--;
            gpioDelay(100);
            continue;
        }
        if (id != 0xEA) {
            fprintf(stderr, "Error: VL53L1X ID mismatch: 0x%02X\n", id);
            log_event("VL53L1X ID mismatch");
            retries--;
            gpioDelay(100);
            continue;
        }

        // Start ranging
        reg = VL53L1X_REG_SYSRANGE_START;
        buf[0] = reg;
        buf[1] = 0x01; // Start ranging
        if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
