// VL53L1X Read Distance
int vl53l1x_read_distance() {
    int distance = -1;
    int retries = 3;
    char reg;

    while (retries > 0) {
        reg = VL53L1X_REG_RESULT_RANGE_STATUS;
        if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
            fprintf(stderr, "Error: VL53L1X range status write failed.\n");
            log_event("VL53L1X range status write failed");
            retries--;
            gpioDelay(100);
            continue;
        }

        char status;
        if (i2cReadDevice(i2c_handle, &status, 1) != 0) {
            fprintf(stderr, "Error: VL53L1X range status read failed.\n");
            log_event("VL53L1X range status read failed");
            retries--;
            gpioDelay(100);
            continue;
        }

