#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 30000
#define MIN_PULSE_WIDTH 100
#define MEASURE_INTERVAL_US 200000 // 200ms
#define TIMEOUT_WARNING_US 60000 // 60ms

static volatile int running = 1;
static FILE *log_file = NULL;
static int rising_tick = 0;
static int falling_tick = 0;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            rising_tick = tick;
        } else if (level == 0) {
            falling_tick = tick;
            int pulse_width = falling_tick - rising_tick;

            if (pulse_width > TIMEOUT_US) {
                fprintf(stderr, "Timeout: Pulse width %d us exceeds maximum (%d us)\n", pulse_width, TIMEOUT_US);
                fprintf(log_file, "Timeout: Pulse width %d us exceeds maximum (%d us)\n", pulse_width, TIMEOUT_US);
                fflush(log_file);
            } else if (pulse_width < MIN_PULSE_WIDTH) {
                fprintf(stderr, "Noise: Pulse width %d us below minimum (%d us)\n", pulse_width, MIN_PULSE_WIDTH);
                fprintf(log_file, "Noise: Pulse width %d us below minimum (%d us)\n", pulse_width, MIN_PULSE_WIDTH);
                fflush(log_file);
            } else {
                double distance = (double)pulse_width * SPEED_OF_SOUND / 2.0;
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                printf("%s Distance: %.2f cm\n", timestamp, distance);
                fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
                fflush(log_file);
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down resistor\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    while (running) {
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIG_PIN, 0);

        gpioDelay(MEASURE_INTERVAL_US);

        if (falling_tick == 0 && rising_tick == 0) {
            fprintf(stderr, "Timeout warning: No valid echo received within %d us\n", TIMEOUT_WARNING_US);
            fprintf(log_file, "Timeout warning: No valid echo received within %d us\n", TIMEOUT_WARNING_US);
            fflush(log_file);
        }
        falling_tick = 0;
        rising_tick = 0;
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    return 0;
}

