#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD 200 // mm
#define POLLING_INTERVAL_MS 500
#define LOG_FILE "gate_events.log"

// VL53L1X Register Addresses (Example - Refer to Datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X Initialization Sequence (Simplified - Refer to Datasheet for full sequence)
int vl53l1x_init(int i2c_handle) {
    // Soft Reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) return -1;
    gpioDelay(10000); // 10 ms delay

    // Set I2C standard mode
    if (i2cWriteByteData(i2c_handle, 0x002d, 0x04) < 0) return -1;

    // Set timing budget (e.g., 50ms)
    if (i2cWriteByteData(i2c_handle, 0x008E, 0x32) < 0) return -1; // MSB
    if (i2cWriteByteData(i2c_handle, 0x008F, 0x00) < 0) return -1; // LSB

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) return -1;

    return 0;
}

// Read distance from VL53L1X
int vl53l1x_read_distance(int i2c_handle) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Control the gate actuator
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
        log_event("Gate Open");
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
        log_event("Gate Closed");
    }
}

// Log events to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            log_event("Error reading distance");
        } else {
            control_gate(distance);
        }
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    printf("Gate control system stopped.\n");
    return 0;
}

