    while (running) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    uint8_t model_id, revision_id;

    // Check sensor ID
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Failed to read revision ID\n");
        return -1;
    }

    // Reset the sensor
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(1); // Wait for reset to complete

    // Configure sensor (example configuration, adjust as needed)
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x01) != 0) {
        fprintf(stderr, "Failed to configure pre-range timeout\n");
        return -1;
    }
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x01) != 0) {
        fprintf(stderr, "Failed to configure final range timeout\n");
        return -1;
    }

    // Start continuous ranging
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int *distance) {
    uint16_t range_status;
    uint16_t distance_mm;

    // Read range status
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Failed to read range status\n");
        return -1;
    }

    // Check for data ready
    if (!(range_status & 0x01)) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read distance
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_mm) != 0) {
        fprintf(stderr, "Failed to read distance\n");
        return -1;
    }

    *distance = (int)distance_mm;
    return 0;
}

// Motor control function
void motor_control(int state) {
    switch (state) {
        case MOTOR_FORWARD:
            gpioWrite(FORWARD_PIN, 1);
            gpioWrite(BACKWARD_PIN, 0);
            printf("Motor: Forward\n");
            break;
        case MOTOR_BACKWARD:
            gpioWrite(FORWARD_PIN, 0);
            gpioWrite(BACKWARD_PIN, 1);
            printf("Motor: Backward\n");
            break;
        case MOTOR_STOP:
        default:
            gpioWrite(FORWARD_PIN, 0);
            gpioWrite(BACKWARD_PIN, 0);
            printf("Motor: Stop\n");
            break;
    }
}

// ISR for trigger pin
void trigger_isr(int gpio, int level, uint32_t tick, void *user) {
    int distance;
    if (vl53l1x_read_distance(&distance) == 0) {
        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_control(MOTOR_FORWARD);
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_control(MOTOR_BACKWARD);
        } else {
            motor_control(MOTOR_STOP);
        }
    } else {
        fprintf(stderr, "Failed to read distance in ISR\n");
        motor_control(MOTOR_STOP);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    motor_control(MOTOR_STOP);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

