#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELECTRODE_TOUCH_THRESHOLD 0x0A
#define ELECTRODE_RELEASE_THRESHOLD 0x05
#define LED_GPIO 27
#define DEBOUNCE_DELAY_MS 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status();
void proximity_detected();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure MPR121 registers
    if (i2cWriteByteData(i2c_handle, 0x5E, 0xC0) < 0) { // Set Electrode Configuration to enable all 12 electrodes
        fprintf(stderr, "Error: Failed to set Electrode Configuration\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Set Debounce Configuration
        fprintf(stderr, "Error: Failed to set Debounce Configuration\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) { // Set Baseline Filtering Configuration
        fprintf(stderr, "Error: Failed to set Baseline Filtering Configuration\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { // Set AFE Configuration
        fprintf(stderr, "Error: Failed to set AFE Configuration\n");
        return -1;
    }

    // Set touch and release thresholds for electrode 0
    if (i2cWriteByteData(i2c_handle, 0x41, ELECTRODE_TOUCH_THRESHOLD) < 0) {
        fprintf(stderr, "Error: Failed to set touch threshold for electrode 0\n");
