#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

// Function prototypes
void signal_handler(int sig);
int setup_gpio(void);
void trigger_sensor(void);
long measure_pulse_width(void);
double calculate_distance(long pulse_width);
void log_distance(double distance);
void cleanup_gpio(void);

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Setup GPIO pins
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trigger_line, "ultrasonic_trigger", 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "ultrasonic_echo");
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor(void) {
    gpiod_line_set_value(trigger_line, 0); // Ensure trigger is low
    usleep(5);                             // Wait 5 microseconds
    gpiod_line_set_value(trigger_line, 1); // Pulse high
    usleep(10);                            // Wait 10 microseconds
    gpiod_line_set_value(trigger_line, 0); // Pulse low
}

// Measure the echo pulse width
long measure_pulse_width(void) {
    struct gpiod_line_event event;
    int ret;
    long start_time, end_time;

    // Wait for rising edge
    ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
    if (ret < 0) {
        perror("Error waiting for rising edge");
        return -1;
    }

    ret = gpiod_line_event_read(echo_line, &event);
    if (ret < 0) {
        perror("Error reading rising edge event");
        return -1;
    }
    start_time = event.ts.tv_sec * 1000000 + event.ts.tv_nsec / 1000;

    // Wait for falling edge
    ret = gpiod_line_event_wait(echo_line, TIMEOUT_US);
    if (ret < 0) {
        perror("Error waiting for falling edge");
        return -1;
    }

    ret = gpiod_line_event_read(echo_line, &event);
    if (ret < 0) {
        perror("Error reading falling edge event");
        return -1;
    }
    end_time = event.ts.tv_sec * 1000000 + event.ts.tv_nsec / 1000;

    return end_time - start_time;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 20000.0; // Divide by 1000000.0 to convert us to s, then divide by 2
}

// Log the distance to a file
void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    double distance;
    long pulse_width;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width, retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        distance = calculate_distance(pulse_width);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            fprintf(log_file, "ERROR: Distance out of range: %.2f cm\n", distance);
            fflush(log_file);
        } else {
            log_distance(distance);
        }

        sleep(1); // Measure every second
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

