static volatile int pulse_width = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;

        // Handle tick-wraparound
        if (pulse_width < 0) {
            pulse_width += 0xFFFFFFFF; // Add 32-bit max value
        }

        // Validate pulse width
        if (pulse_width > 0 && pulse_width < MAX_PULSE_WIDTH) {
            double distance = calculate_distance(pulse_width);
            log_distance(distance);
        } else {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        }
    }
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f m\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt-driven ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(1000000); // Wait 1 second
    }

    return 0;
}

