#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define CONTINUOUS_MODE 0x00
#define NO_TIMEOUT 0x00
#define START_RANGING 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance, int *status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Set XSHUT high to enable the sensor
    gpioWrite(XSHUT_PIN, 1);
    gpioDelay(100); // Wait for sensor to power up

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure sensor for continuous mode
    if (i2cWriteByteData(i2c_handle, 0x0018, CONTINUOUS_MODE) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0019, NO_TIMEOUT) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0020, START_RANGING) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        i2cClose(i2c_handle);
        return -1;
    }

    syslog(LOG_INFO, "Sensor initialized successfully");
    return 0;
}

// Read distance and status from the VL53L1X sensor
int read_distance(int *distance, int *status) {
    char buffer[3];
    int result;

    // Read distance (2 bytes) and status (1 byte)
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 3);
    if (result < 0) {
        syslog(LOG_ERR, "Failed to read distance and status: %d", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    *status = buffer[2];

    return 0;
}

