    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (init_sensor() != 0) {
        syslog(LOG_ERR, "Sensor initialization failed, exiting");
        closelog();
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance, status;

