#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define GATE_OPEN_DURATION 5.0  // seconds
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(float *distance);
void control_gate(float distance);
void log_message(const char *message);
void signal_handler(int signal);

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_STOP 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;              // Data to write

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 3) {
        return -1; // Error
    }
    return 0; // Success
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *data) {
    char buf[1];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        return -1; // Error writing register address
    }

    result = i2cReadDevice(handle, buf, 1);
    if (result != 1) {
        return -1; // Error reading data
    }

    *data = buf[0];
    return 0; // Success
}

// Function to read a 16-bit value from two VL53L1X registers
int read_register_16(int handle, uint16_t reg, uint16_t *data) {
    char buf[1];
    char read_buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        return -1; // Error writing register address
    }

    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        return -1; // Error reading data
    }

    *data = (read_buf[0] << 8) | read_buf[1];
    return 0; // Success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize gate to closed state

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Control gate based on distance
            control_gate(distance);

            // Log distance and gate state
            char log_message_buffer[256];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Distance: %.2f cm, Gate: %s", distance, gate_open ? "OPEN" : "CLOSED");
            log_message(log_message_buffer);
        } else {
            log_message("Failed to read distance");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;
    int retry = 0;

    // Check model ID
    while (retry < I2C_RETRY_COUNT) {
        if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) == 0) {
            if (model_id == 0xEA) {
                break; // Success
            } else {
                char log_message_buffer[256];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Incorrect model ID: 0x%02X", model_id);
                log_message(log_message_buffer);
            }
        } else {
            log_message("Failed to read model ID");
        }
        retry++;
        gpioDelay(10); // Small delay before retry
    }

    if (retry == I2C_RETRY_COUNT) {
        log_message("Failed to verify model ID after multiple retries");
        return -1;
    }

    // Set ranging mode to short
    if (write_register(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x00) != 0) {
        log_message("Failed to set ranging mode");
        return -1;
    }

    // Start ranging
    if (write_register(i2c_handle, VL53L1X_REG_START_STOP, 0x01) != 0) {
        log_message("Failed to start ranging");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(float *distance) {
    uint16_t raw_distance;
    int retry = 0;

    while (retry < I2C_RETRY_COUNT) {
        if (read_register_16(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &raw_distance) == 0) {
            *distance = (float)raw_distance / 10.0; // Convert mm to cm
            return 0; // Success
        } else {
            log_message("Failed to read distance data");
        }
        retry++;
        gpioDelay(10); // Small delay before retry
    }

    return -1; // Failure
}

// Control gate actuator based on distance
void control_gate(float distance) {
    static time_t gate_open_time = 0;

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        // Open gate
        gpioWrite(GATE_GPIO, 1);
        gate_open = 1;
        gate_open_time = time(NULL);
        log_message("Gate opened");
    } else if (gate_open && (time(NULL) - gate_open_time >= GATE_OPEN_DURATION)) {
        // Close gate
        gpioWrite(GATE_GPIO, 0);
        gate_open = 0;
        log_message("Gate closed");
    }
}

// Log messages to file with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

