#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0.0         // degrees
#define MAX_ANGLE 180.0       // degrees
#define MIN_PULSE_WIDTH 500.0  // us
#define MAX_PULSE_WIDTH 2500.0 // us
#define MOVING_AVG_SIZE 5
#define TRIGGER_INTERVAL 100   // ms
#define TIMEOUT 30             // ms

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
double distance_history[MOVING_AVG_SIZE] = {0.0};
int history_index = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
double measure_pulse_width();
double calculate_distance(double pulse_width);
double moving_average(double new_value);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Trigger pulse generation
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo pulse width measurement with timeout
double measure_pulse_width() {
    uint32_t start_tick = 0, end_tick = 0;
    double pulse_width = -1.0; // Default to error value

    // Wait for echo to go high with timeout
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT) {
        gpioDelay(1);
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0;
    }

    end_tick = gpioTick();

    pulse_width = (double)(end_tick - start_tick);
    return pulse_width;
}

// Distance calculation
double calculate_distance(double pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Moving average filter
double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;

    double sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_history[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Distance to angle mapping (logarithmic)
double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;

    // Logarithmic mapping
    double angle = (log10(distance) / log10(MAX_DISTANCE / MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    return angle;
}

// Servo angle setting
int set_servo_angle(double angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Angle out of range: %f\n", angle);
        return -1; // Indicate error
    }

    // Map angle to pulse width (500-2500 us)
    double pulse_width = (angle / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH;

    int result = gpioServo(SERVO_PIN, (int)pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo angle: %d\n", result);
        return -1; // Indicate error
    }
    return 0;
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    // This function is not used directly, but is required by gpioSetAlertFuncEx.
    // The actual pulse width measurement is done in measure_pulse_width().
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        double pulse_width = measure_pulse_width();

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Apply moving average filter
        double filtered_distance = moving_average(distance);

        // Map distance to angle
        double angle = map_distance_to_angle(filtered_distance);

        // Set servo angle
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Failed to set servo angle, setting to default.\n");
            set_servo_angle(90.0); // Set to default position
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to file
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, filtered_distance, angle);
        fflush(log_file);

        // Wait for the next trigger
        gpioDelay(TRIGGER_INTERVAL);
    }

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

