#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_proximity(int i2c_handle);
int check_threshold(int proximity_value, int threshold);
void log_data(int proximity_value, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to read proximity value from Si1102
int read_proximity(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1; // Indicate error
    }

    return (buf[0] << 8) | buf[1]; // Combine high and low bytes
}

// Function to check if proximity value exceeds threshold
int check_threshold(int proximity_value, int threshold) {
    return proximity_value > threshold;
}

// Function to log data to file
void log_data(int proximity_value, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Proximity: %d, Status: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            proximity_value, status);

    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity_value = read_proximity(i2c_handle);
    if (proximity_value != -1) {
        const char *status = check_threshold(proximity_value, threshold) ? "ALERT" : "SAFE";
        log_data(proximity_value, status);
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

