#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MAX_DISTANCE 50.0  // cm
#define MIN_DISTANCE 5.0   // cm
#define TIMEOUT_US 100000   // 100 ms timeout

// Global variables
static volatile int running = 1;
static volatile float last_valid_distance = 25.0; // Initial distance

// Function prototypes
void signal_handler(int signal);
float read_distance();
void set_frequency(float distance);
void trigger_pulse();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to read distance from the ultrasonic sensor
float read_distance() {
    long long start_tick, end_tick, diff_tick;
    float distance;

    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);

    trigger_pulse();

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout\n");
        return last_valid_distance; // Return last valid distance
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout\n");
        return last_valid_distance; // Return last valid distance
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    distance = (float)diff_tick * 343.0 / 20000.0; // cm

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return last_valid_distance; // Return last valid distance
    }

    last_valid_distance = distance;
    return distance;
}

// Function to set the PWM frequency based on distance
void set_frequency(float distance) {
    float frequency;

    // Map distance to frequency linearly
    frequency = MAX_FREQ + (MIN_FREQ - MAX_FREQ) * (distance - MAX_DISTANCE) / (MIN_DISTANCE - MAX_DISTANCE);

    // Clamp frequency to valid range
    if (frequency < MIN_FREQ) {
        frequency = MIN_FREQ;
    } else if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (optional, but good practice)
    gpioSetPWMrange(PWM_PIN, 1000); // Range of 0-1000
    gpioSetPWMrange(PWM_PIN, 1000);

    // Set PWM duty cycle (optional, but good practice)
    gpioPWM(PWM_PIN, 500); // 50% duty cycle

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = read_distance();
        set_frequency(distance);

        // Print distance and frequency
        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, gpioGetPWMfrequency(PWM_PIN));

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

