#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1ms

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        uint32_t end_tick = start_tick;

        while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start_tick) < 50000) {
            start_tick = gpioTick();
        }

        if (gpioRead(ECHO_PIN) == 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue;
        }

        while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - end_tick) < 50000) {
            end_tick = gpioTick();
        }

        if (gpioRead(ECHO_PIN) == 1) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;

        float distance = (float)pulse_width / 2.0 / 29.1;

        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf(" Too close!");
            }
            printf("\n");
        }

        gpioDelay(500); // 500ms delay
    }

    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

