#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8 // GPIO8 for Chip Select
#define DISTANCE_REG 0x0C
#define CONFIG_REG 0x01
#define RANGE_REG 0x02
#define TRIGGER_REG 0x00

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(int distance);
void signal_handler(int signal);

// Structure for SPI transaction
typedef struct {
    unsigned char tx[2];
    unsigned char rx[2];
} spi_transaction_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the sensor
int initialize_sensor() {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];

    // Set continuous measurement mode
    tx_buf[0] = CONFIG_REG;
    tx_buf[1] = 0x01; // Continuous mode
    spi_transaction_t tx = {tx_buf, rx_buf};
    if (spiXfer(spi_handle, tx.tx, tx.rx, 2) != 0) {
        fprintf(stderr, "Error setting continuous mode\n");
        return -1;
    }

    // Set range to 5 meters
    tx_buf[0] = RANGE_REG;
    tx_buf[1] = 0x00; // 5 meters
    tx = (spi_transaction_t){tx_buf, rx_buf};
    if (spiXfer(spi_handle, tx.tx, tx.rx, 2) != 0) {
        fprintf(stderr, "Error setting range\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance(int *distance) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];

    // Trigger measurement
    tx_buf[0] = TRIGGER_REG;
    tx_buf[1] = 0x01;
    spi_transaction_t tx = {tx_buf, rx_buf};
    if (spiXfer(spi_handle, tx.tx, tx.rx, 2) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Read distance data
    tx_buf[0] = DISTANCE_REG;
    tx_buf[1] = 0x00;
    tx = (spi_transaction_t){tx_buf, rx_buf};
    if (spiXfer(spi_handle, tx.tx, tx.rx, 2) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    *distance = (rx_buf[1] << 8) | rx_buf[0];

    return 0;
}

// Function to log data to a file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

