#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define SI1175_ADDR 0x60      // Default I2C address of Si1175
#define ALS_REG_LOW 0x22       // Register address for ALS low byte
#define ALS_REG_HIGH 0x23      // Register address for ALS high byte
#define LOG_FILE "proximity_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_fp = NULL; // Log file pointer
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_als_visible(int fd);
int log_data(FILE *fp, int als_visible);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read ALS visible function
int read_als_visible(int fd) {
    int low_byte, high_byte;

    low_byte = i2c_read_reg(fd, ALS_REG_LOW);
    if (low_byte < 0) return -1;

    high_byte = i2c_read_reg(fd, ALS_REG_HIGH);
    if (high_byte < 0) return -1;

    return (high_byte << 8) | low_byte;
}

// Log data function
int log_data(FILE *fp, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, als_visible) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "timestamp,als_visible\n");
    }
    rewind(log_fp);

    // Main loop
    while (!terminate) {
        int als_visible = read_als_visible(i2c_fd);
        if (als_visible >= 0) {
            if (log_data(log_fp, als_visible) != 0) {
                fprintf(stderr, "Failed to log data. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ALS visible. Continuing.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    printf("Program terminated successfully.\n");
    return 0;
}

