#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_RESET_REG 0x30
#define SI1120_PART_ID_REG 0x00
#define SI1120_ALS_DATA_LOW 0x22
#define SI1120_ALS_DATA_HIGH 0x23
#define SI1120_PS1_DATA_LOW 0x18
#define SI1120_PS1_DATA_HIGH 0x19
#define SI1120_RESET_VALUE 0x01
#define SI1120_PART_ID_VALUE 0x41
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(unsigned int *als, unsigned int *proximity);
void log_data(unsigned int als, unsigned int proximity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the Si1120 sensor
int initialize_sensor() {
    int result, i;
    unsigned char data[2];

    // Reset the sensor
    data[0] = SI1120_RESET_REG;
    data[1] = SI1120_RESET_VALUE;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 2);
        if (result == 0) break; // Success
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error resetting sensor after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Verify part ID
    data[0] = SI1120_PART_ID_REG;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to part ID register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading part ID after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    if (data[0] != SI1120_PART_ID_VALUE) {
        fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x%02X).\n", data[0], SI1120_PART_ID_VALUE);
        return -1;
    }

    printf("Si1120 sensor initialized successfully.\n");
    return 0;
}

// Read ALS and proximity data from the sensor
int read_sensor_data(unsigned int *als, unsigned int *proximity) {
    int result, i;
    unsigned char data[2];

    // Read ALS data
    data[0] = SI1120_ALS_DATA_LOW;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to ALS low byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading ALS low byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int als_low = data[0];

    data[0] = SI1120_ALS_DATA_HIGH;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to ALS high byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading ALS high byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int als_high = data[0];

    // Read proximity data
    data[0] = SI1120_PS1_DATA_LOW;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to proximity low byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading proximity low byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int proximity_low = data[0];

    data[0] = SI1120_PS1_DATA_HIGH;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to proximity high byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading proximity high byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int proximity_high = data[0];

    // Combine bytes into 16-bit values (little-endian)
    *als = (als_high << 8) | als_low;
    *proximity = (proximity_high << 8) | proximity_low;

    return 0;
}

// Log data to file
void log_data(unsigned int als, unsigned int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned int als, proximity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&als, &proximity) == 0) {
            log_data(als, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(500000); // 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

