    printf("Si1120 sensor initialized successfully.\n");
    return 0;
}

// Read ALS and proximity data from the sensor
int read_sensor_data(unsigned int *als, unsigned int *proximity) {
    int result, i;
    unsigned char data[2];

    // Read ALS data
    data[0] = SI1120_ALS_DATA_LOW;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to ALS low byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading ALS low byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int als_low = data[0];

    data[0] = SI1120_ALS_DATA_HIGH;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to ALS high byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading ALS high byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int als_high = data[0];

    // Read proximity data
    data[0] = SI1120_PS1_DATA_LOW;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to proximity low byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading proximity low byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int proximity_low = data[0];

    data[0] = SI1120_PS1_DATA_HIGH;
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result == 0) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 0) {
        fprintf(stderr, "Error writing to proximity high byte register after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 1);
        if (result == 1) break;
        gpioDelay(RETRY_DELAY_US);
    }
    if (result != 1) {
        fprintf(stderr, "Error reading proximity high byte after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int proximity_high = data[0];

    // Combine bytes into 16-bit values (little-endian)
    *als = (als_high << 8) | als_low;
    *proximity = (proximity_high << 8) | proximity_low;

    return 0;
}

// Log data to file
void log_data(unsigned int als, unsigned int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

