        if (lux >= 0 && proximity >= 0) {
            log_data(log_file, lux, proximity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        usleep(SLEEP_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

