#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_ADDR 0x60
#define I2C_BUS 1

int i2c_handle;
FILE *log_file;

// Function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log messages to file
void log_message(const char *message)
{
    char timestamp[20];
    get_timestamp(timestamp);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Function to initialize the Si1145 sensor
int initialize_sensor()
{
    int retries = 3;
    int status;

    while (retries > 0) {
        // Hardware Key
        status = i2cWriteByteData(i2c_handle, 0x07, 0x03);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (HW Key): %d", status);
            log_message(error_message);
            gpioDelay(1000); // Wait 1 second before retrying
            retries--;
            continue;
        }

        // MEAS_RATE
        status = i2cWriteByteData(i2c_handle, 0x06, 0x02);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (MEAS_RATE): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // No Interrupt
        status = i2cWriteByteData(i2c_handle, 0x1A, 0x00);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (No Interrupt): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // ALS_VIS_IR_ADC_COUNTER
        status = i2cWriteByteData(i2c_handle, 0x21, 0x00);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (ALS_VIS_IR_ADC_COUNTER): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // ALS_VIS_ADC_GAIN
        status = i2cWriteByteData(i2c_handle, 0x24, 0x00);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (ALS_VIS_ADC_GAIN): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // PS_ADC_COUNTER
        status = i2cWriteByteData(i2c_handle, 0x22, 0x49);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (PS_ADC_COUNTER): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // PS_LED21
        status = i2cWriteByteData(i2c_handle, 0x0C, 0x03);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (PS_LED21): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // PS_LED3
        status = i2cWriteByteData(i2c_handle, 0x0F, 0x0F);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (PS_LED3): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // PS_ADC_MISC
        status = i2cWriteByteData(i2c_handle, 0x11, 0x03);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (PS_ADC_MISC): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // PS_ADC_GAIN
        status = i2cWriteByteData(i2c_handle, 0x0D, 0x07);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (PS_ADC_GAIN): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        // PS_FORCE
        status = i2cWriteByteData(i2c_handle, 0x80, 0x03);
        if (status < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Write Error (PS_FORCE): %d", status);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        log_message("Sensor initialized successfully.");
        return 0; // Initialization successful
    }

    log_message("Sensor initialization failed after multiple retries.");
    return -1; // Initialization failed
}

// Function to read proximity data from the sensor
int read_proximity()
{
    int low_byte, high_byte, proximity_value;
    int retries = 3;
    int status;

    while (retries > 0) {
        low_byte = i2cReadByteData(i2c_handle, 0x16);
        if (low_byte < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Read Error (Low Byte): %d", low_byte);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        high_byte = i2cReadByteData(i2c_handle, 0x17);
        if (high_byte < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C Read Error (High Byte): %d", high_byte);
            log_message(error_message);
            gpioDelay(1000);
            retries--;
            continue;
        }

        proximity_value = (high_byte << 8) | low_byte;
        return proximity_value;
    }

    log_message("Failed to read proximity data after multiple retries.");
    return -1; // Indicate read failure
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    log_message("Received signal, shutting down...");
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Proximity: %d", proximity);
            log_message(log_message_buffer);
        } else {
            log_message("Failed to read proximity data.");
        }

