#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define distance limits for servo mapping
#define MIN_DISTANCE 20.0  // cm
#define MAX_DISTANCE 200.0 // cm

// Define timeout for echo pulse (microseconds)
#define ECHO_TIMEOUT 50000 // 50ms

// Global variables
volatile int running = 1;
int servo_angle = 90; // Initial servo angle

// Function prototypes
void signal_handler(int signal);
float measure_distance();
int set_servo_angle(int angle);
int map_distance_to_angle(float distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    set_servo_angle(90); // Set servo to a safe position
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ECHO_TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse not received (timeout).\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ECHO_TIMEOUT) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse not received (timeout).\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff / 1000000.0 * 34300.0 / 2.0; // cm

    return distance;
}

// Function to set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle (%d). Angle must be between 0 and 180.\n", angle);
        return -1;
    }

    // Map angle to pulse width (us)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)(angle) / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return 180;
    } else if (distance > MAX_DISTANCE) {
        return 0;
    } else {
        // Linear mapping
        return (int)((MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE) * 180.0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error setting servo angle.\n");
            }
            servo_angle = angle; // Update global servo angle
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        gpioDelay(100); // Update every 100 ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();         // Terminate pigpio

    return 0;
}

