#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();         // Terminate pigpio
        program_running = 0;      // Set flag to exit main loop
        exit(0);                  // Exit the program
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger HIGH
    gpioDelay(10);             // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger LOW
}

// Function to measure the echo pulse width with timeout
double measurePulseWidth() {
    uint32_t start_tick, end_tick, diff_tick;

    // Wait for echo to go HIGH with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout occurred
    }

    start_tick = gpioTick();

    // Wait for echo to go LOW with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1.0; // Timeout occurred
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    return (double)diff_tick;
}

// Function to calculate distance from pulse width
double calculateDistance(double pulse_width) {
    if (pulse_width < 0) return -1.0; // Handle timeout
