#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define TEMP_SCALE 175.72
#define TEMP_OFFSET -46.85
#define HUMID_SCALE 125.0
#define HUMID_OFFSET -6.0
#define CONFIG_VALUE 0x00
#define READ_DELAY_MS 10
#define LOG_INTERVAL_SEC 2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the Si7005 sensor
int init_si7005() {
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (result != 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }
    gpioDelay(READ_DELAY_MS * 1000); // Delay in microseconds
    return 0;
}

// Function to read temperature from the Si7005
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }
    return (TEMP_SCALE * raw_temp) / 65536.0 + TEMP_OFFSET;
}

// Function to read humidity from the Si7005
float read_humidity() {
    int raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity: %d\n", raw_humidity);
        return -1.0; // Indicate error with a negative value
    }
    return (HUMID_SCALE * raw_humidity) / 65536.0 + HUMID_OFFSET;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si7005() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        float humidity = read_humidity();

        if (temperature > -999.0 && humidity > -0.5) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

