#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC8_POLY 0x31

// Global variable for I2C handle
int i2c_handle = -1;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
uint8_t calculate_crc(const uint8_t *data, int len);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temp_crc = calculate_crc(data, 2);
    if (temp_crc != data[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Validate CRC for humidity
    uint8_t humidity_crc = calculate_crc(data + 3, 2);
    if (humidity_crc != data[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 0.0;
    if (raw_humidity > 0) {
        *humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;
    }
    if (*humidity > 100.0) *humidity = 100.0;
    if (*humidity < 0.0) *humidity = 0.0;

    return 0;
