#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_to_celsius(uint16_t raw_temp);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw temperature data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[4];
    int result;

    // Read ambient temperature
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", result);
        return -1;
    }
    uint16_t raw_ambient = (buffer[1] << 8) | buffer[0];
    data->ambient_temp = convert_to_celsius(raw_ambient);

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        return -1;
    }
    uint16_t raw_object = (buffer[1] << 8) | buffer[0];
    data->object_temp = convert_to_celsius(raw_object);

    return 0;
}

// Convert raw temperature data to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

