char* get_iso8601_timestamp();
int log_data(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Checksum validation function
int validate_checksum(const uint8_t *data, int count) {
    uint8_t calculated_crc = calculate_crc(data, count - 1);
    return (calculated_crc == data[count - 1]);
}

// Data processing function
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t result;
    // Extract scale factors (not used in this example, but kept for potential future use)
    // float scale_factor_pressure = (float)((int16_t)((data[SCALE_FACTOR_OFFSET] << 8) | data[SCALE_FACTOR_OFFSET + 1]));
    // float scale_factor_temperature = (float)((int16_t)((data[SCALE_FACTOR_OFFSET + 2] << 8) | data[SCALE_FACTOR_OFFSET + 3]));

    // Extract raw pressure and temperature values
    int16_t raw_pressure = (int16_t)((data[PRESSURE_OFFSET] << 8) | data[PRESSURE_OFFSET + 1]);
    int16_t raw_temperature = (int16_t)((data[TEMPERATURE_OFFSET] << 8) | data[TEMPERATURE_OFFSET + 1]);

    // Convert raw values to physical units (Pa and °C) - Example values, adjust as needed
    result.pressure = (float)raw_pressure / 10.0; // Example scaling factor
    result.temperature = (float)raw_temperature / 10.0; // Example scaling factor

    return result;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

