    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[DATA_FRAME_LENGTH];
        sensor_data_t sensor_data;

        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND, MEASUREMENT_COMMAND_ARG) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(1); // Wait for measurement to complete

        // Read data from sensor
        if (read_data(i2c_handle, data, DATA_FRAME_LENGTH) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate checksum
        if (!validate_checksum(data, DATA_FRAME_LENGTH)) {
            fprintf(stderr, "Checksum validation failed\n");
            continue;
        }

        // Process data
        sensor_data = process_data(data);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue;
        }

        // Log data
        if (log_data(timestamp, sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        free(timestamp); // Free the allocated memory

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

