#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "sht40_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry
int read_sensor_data(uint8_t *data) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing to I2C device.\n");
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }
        gpioDelay(10000); // Wait 10ms for measurement

        int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (bytes_read == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
        }
    }
    return -1; // Failure after retries
}

// Process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t result;
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    // CRC validation
    if (calculate_crc(data, 2) != data[2] || calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        result.temperature = -999.0; // Indicate error
        result.humidity = -999.0;    // Indicate error
        return result;
    }

    // Convert raw data to temperature and humidity
    result.temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    result.humidity = 100.0 * (float)raw_humidity / 65535.0;

    return result;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            processed_data = process_sensor_data(sensor_data);
            if (processed_data.temperature != -999.0 && processed_data.humidity != -999.0) {
                if (log_data(processed_data) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error processing sensor data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

