#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUM_CMD 0xF5
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_si7015(int i2c_handle, float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the program
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(gpioInitialise()));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read temperature and humidity from Si7015
int read_si7015(int i2c_handle, float *temperature, float *humidity) {
    int raw_temp, raw_humidity;
    int retries = 0;

    // Read temperature
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, TEMP_CMD) != 0) {
            fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(20); // Wait for measurement (datasheet specifies 20ms)

        raw_temp = i2cReadWordData(i2c_handle, 0); // Dummy register address
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        return 1;
    }

    // Read humidity
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, HUM_CMD) != 0) {
            fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(20); // Wait for measurement (datasheet specifies 20ms)

        raw_humidity = i2cReadWordData(i2c_handle, 0); // Dummy register address
        if (raw_humidity < 0) {
            fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read humidity after %d retries.\n", MAX_RETRIES);
        return 1;
    }

    // Convert raw values to temperature and humidity
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float temperature, humidity;

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("Starting sensor data logging...\n");

    while (!terminate) {
        if (read_si7015(i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

