        float temperature;

        // Send measurement command
        if (send_measurement_command() != 0) {
            log_error("Failed to send measurement command, retrying...");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            log_error("Failed to read sensor data, retrying...");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // CRC validation
        unsigned char crc = calculate_crc(data, 2);
        if (crc != data[2]) {
            log_error("CRC mismatch");
            log_error("Raw data: ");
            char temp_str[10];
            sprintf(temp_str, "%02X%02X%02X", data[0], data[1], data[2]);
            log_error(temp_str);
            log_error("Calculated CRC: ");
            sprintf(temp_str, "%02X", crc);
            log_error(temp_str);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert to Celsius
        raw_value = (data[0] << 8) | data[1];
        temperature = convert_to_celsius(raw_value);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature");
        }

        printf("Temperature: %.2f °C\n", temperature);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait 5 seconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

