#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define CONT_MEASURE_CMD 0x362F
#define PRESSURE_SCALE 240.0
#define TEMPERATURE_SCALE 200.0
#define TEMPERATURE_OFFSET -45.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF
#define LOG_FILE "airflow_data.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int i2c_write(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len, uint8_t crc);
sensor_data_t read_sdp800(int fd);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    if (write(fd, buffer, len + 1) != len + 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len, uint8_t crc) {
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read data from SDP800
sensor_data_t read_sdp800(int fd) {
    sensor_data_t data = {0, 0};
    uint8_t raw_data[6];
    uint8_t cmd[2] = {(CONT_MEASURE_CMD >> 8) & 0xFF, CONT_MEASURE_CMD & 0xFF};

    if (i2c_write(fd, 0, cmd, 2) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command.\n");
        return data; // Return default values on error
    }

    usleep(1000); // Wait 1 ms

    if (i2c_read(fd, 0, raw_data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return data; // Return default values on error
    }

    // CRC validation
    if (crc8(raw_data, 2, CRC_INIT_VALUE) != raw_data[2]) {
        fprintf(stderr, "Pressure CRC check failed.\n");
        return data; // Return default values on error
    }
    if (crc8(raw_data + 3, 2, CRC_INIT_VALUE) != raw_data[5]) {
        fprintf(stderr, "Temperature CRC check failed.\n");
        return data; // Return default values on error
    }

    // Extract data
    data.pressure = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    data.temperature = (int16_t)((raw_data[3] << 8) | raw_data[4]);

    return data;
}

// Convert raw pressure to Pa
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE;
}

// Convert raw temperature to °C
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE + TEMPERATURE_OFFSET;
}

// Log data to file
void log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function
int setup() {
    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return -1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    if (setup() != 0) {
        return 1;
    }

    while (!terminate) {
        sensor_data_t sensor_data = read_sdp800(i2c_fd);
        float pressure = convert_pressure(sensor_data.pressure);
        float temperature = convert_temperature(sensor_data.temperature);

        log_data(pressure, temperature);

        usleep(100000); // 100 ms delay
    }

    cleanup();
    return 0;
}

