#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_HOLD_CMD 0xE3
#define HUMID_HOLD_CMD 0xE5
#define TEMP_MIN 27.0
#define TEMP_MAX 28.0
#define HUMID_MIN 0.0
#define HUMID_MAX 100.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for storing sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void log_data(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;
    int retries = 0;

    // Read temperature
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TEMP_HOLD_CMD);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing temperature command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write temperature command after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }
    gpioDelay(10000); // Wait 10 ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading temperature data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read temperature data after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = 175.72 * raw_temp / 65536.0 - 46.85;

    // Read humidity
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, HUMID_HOLD_CMD);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing humidity command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write humidity command after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }
    gpioDelay(10000); // Wait 10 ms

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading humidity data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read humidity data after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0; // Indicate success
}

// Function to control the fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_MAX && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_MIN && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to log data to the circular buffer
void log_data(float temperature, float humidity) {
    time(&sensor_buffer[buffer_index].timestamp);
    sensor_buffer[buffer_index].temperature = temperature;
    sensor_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&sensor_buffer[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
