#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// Start Periodic Measurement command
#define START_PERIODIC_MEASUREMENT 0x21B1

// Read Measurement command
#define READ_MEASUREMENT 0xEC05

// Stop Periodic Measurement command
#define STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// CRC-8 initialization value
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len);
int read_scd40_data(int handle, float *co2, float *temperature, float *humidity);
int log_data(float co2, float temperature, float humidity);
void signal_handler(int signal);
int stop_periodic_measurement(int handle);

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 verification function
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Read SCD40 data with retries and CRC verification
int read_scd40_data(int handle, float *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        // Send Read Measurement command
        if (send_command(handle, READ_MEASUREMENT) != 0) {
            fprintf(stderr, "Error sending read measurement command, retrying...\n");
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
            continue;
        }

        // Wait for data ready flag (0xE4B8)
        uint8_t data_ready[2];
        if (read_data(handle, data_ready, 2) != 0) {
            fprintf(stderr, "Error reading data ready flag, retrying...\n");
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
        }

        if ((data_ready[0] != 0xE4) || (data_ready[1] != 0xB8)) {
            fprintf(stderr, "Data not ready, retrying...\n");
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
        }

        // Read 9 bytes of data
        if (read_data(handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
        }

        // Verify CRC for each 2-byte word
        if (!verify_crc(data, 3) || !verify_crc(data + 3, 3) || !verify_crc(data + 6, 3)) {
            fprintf(stderr, "CRC verification failed, retrying...\n");
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
        }

        // Extract CO2, temperature, and humidity values
        uint16_t co2_raw = (data[0] << 8) | data[1];
        uint16_t temperature_raw = (data[3] << 8) | data[4];
        uint16_t humidity_raw = (data[6] << 8) | data[7];

        // Convert to float values
        *co2 = (float)co2_raw;
        *temperature = -45 + 175 * (float)temperature_raw / (65535.0 - 1);
        *humidity = 100 * (float)humidity_raw / (65535.0 - 1);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SCD40 data after multiple retries\n");
    return -1; // Failure
}

// Log data to file
int log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement(int handle) {
    if (send_command(handle, STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command\n");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float co2, temperature, humidity;
    time_t last_log_time = 0;

    // Main loop
    while (!terminate) {
        // Read SCD40 data
        if (read_scd40_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            // Log data every 5 seconds
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 5) {
                log_data(co2, temperature, humidity);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Failed to read SCD40 data\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Stop periodic measurement
    if (stop_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

