#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000
#define MEASUREMENT_INTERVAL 5 // seconds

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_reading_t;

// Circular buffer
sensor_reading_t reading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
int stop_periodic_measurement();
int validate_checksum(uint16_t data, uint8_t checksum);
void add_reading_to_buffer(uint16_t co2, float temperature, float humidity);
void print_reading_from_buffer(int index);
void control_led(int co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per SCD40 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get data ready status
        if (get_data_ready_status() != 0) {
            fprintf(stderr, "Failed to get data ready status. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read measurement
        uint16_t co2;
        float temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) != 0) {
            fprintf(stderr, "Failed to read measurement. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Add reading to buffer
        add_reading_to_buffer(co2, temperature, humidity);

        // Print reading from buffer
        print_reading_from_buffer(buffer_index);

        // Control LED
        control_led(co2);

        // Wait for the next measurement interval
        sleep(MEASUREMENT_INTERVAL);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement.\n");
    }

    // Cleanup
    cleanup();

    return 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int start_periodic_measurement() {
    char cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

int get_data_ready_status() {
    char cmd[2] = {0xE4, 0xB8};
    char buf[3];
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write get data ready status command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }

    // Check if data is ready (bit 0 of byte 0)
    if ((buf[0] & 0x01) == 0) {
        return -1; // Data not ready
    }

    return 0;
}

int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    char cmd[2] = {0xEC, 0x05};
    char buf[9];
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC validation
    if (!validate_checksum((uint16_t)((buf[0] << 8) | buf[1]), buf[2]) ||
        !validate_checksum((uint16_t)((buf[3] << 8) | buf[4]), buf[5]) ||
        !validate_checksum((uint16_t)((buf[6] << 8) | buf[7]), buf[8])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract data
    *co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = -45 + 175 * ((float)((uint16_t)((buf[3] << 8) | buf[4])) / 65535.0);
    *humidity = 100 * ((float)((uint16_t)((buf[6] << 8) | buf[7])) / 65535.0);

    return 0;
}

int stop_periodic_measurement() {
    char cmd[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write stop periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

int validate_checksum(uint16_t data, uint8_t checksum) {
    uint8_t calculated_checksum = crc8((uint8_t *)&data, 2);
    return (calculated_checksum == checksum);
}

void add_reading_to_buffer(uint16_t co2, float temperature, float humidity) {
    reading_buffer[buffer_index].timestamp = time(NULL);
    reading_buffer[buffer_index].co2 = co2;
    reading_buffer[buffer_index].temperature = temperature;
    reading_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_reading_from_buffer(int index) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&reading_buffer[index].timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
           timestamp_str, reading_buffer[index].co2, reading_buffer[index].temperature, reading_buffer[index].humidity);
}

void control_led(int co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    // Stop periodic measurement
    stop_periodic_measurement();

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO to input mode

    // Terminate pigpio
    gpioTerminate();
}

