#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define TIMEOUT_US 50000   // 50ms timeout
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int sensor_failures = 0;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

int read_temperature(float *temperature) {
    uint32_t start_tick, end_tick, high_time, total_time;
    int timeout;

    // Wait for rising edge
    timeout = TIMEOUT_US;
    while (gpioRead(GPIO_PIN) == 0 && timeout > 0) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout--;
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }
    start_tick = gpioTick();

    // Wait for falling edge
    timeout = TIMEOUT_US;
    while (gpioRead(GPIO_PIN) == 1 && timeout > 0) {
        gpioDelay(1);
        timeout--;
    }
    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }
    end_tick = gpioTick();

    high_time = end_tick - start_tick;
    total_time = end_tick - start_tick;

    // Check for division by zero
    if (total_time == 0) {
        fprintf(stderr, "Error: Total time is zero\n");
        return -1;
    }

    *temperature = (4215.0 - (2143.0 * (float)high_time / (float)total_time));

    return 0;
}

int validate_temperature(float temperature) {
    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        return -1;
    }
    return 0;
}

int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

int main() {
    float temperature;
    int result;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    while (program_running) {
        result = read_temperature(&temperature);
        if (result == 0) {
            if (validate_temperature(temperature) == 0) {
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature\n");
                }
                sensor_failures = 0; // Reset failure count
            } else {
                fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
                fprintf(log_file, "ERROR: Temperature out of range: %.2f\n", temperature);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
            fprintf(log_file, "ERROR: Failed to read temperature\n");
            fflush(log_file);
            sensor_failures++;
            if (sensor_failures >= 3) {
                fprintf(stderr, "SENSOR MALFUNCTION\n");
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                fflush(log_file);
                sensor_failures = 0; // Reset after logging
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

