#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define DATA_FILE "environmental_data.txt"
#define LOG_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_pigpio();
int open_i2c_connection();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
SensorData process_sensor_data(const uint8_t *data);
SensorData simulate_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint8_t *data) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, (MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF);
        if (result != 0) {
            fprintf(stderr, "I2C write failed: %d, retries left: %d\n", result, retries);
            gpioDelay(1000); // Wait 1 second
            retries--;
            continue;
        }

        gpioDelay(15); // Wait for measurement (at least 15ms)

        result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed: %d, retries left: %d\n", result, retries);
            gpioDelay(1000); // Wait 1 second
            retries--;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries\n");
    return -1; // Failure
}

// Process sensor data (CRC validation and conversion)
SensorData process_sensor_data(const uint8_t *data) {
    SensorData result = {NAN, NAN};
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    // CRC validation
    if (calculate_crc(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return result; // Return NaN values
    }
    if (calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return result; // Return NaN values
    }

    // Conversion formulas (from SHT35 datasheet)
    result.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    result.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return result;
}

// Simulate offset (sinusoidal)
SensorData simulate_offset(SensorData data) {
    SensorData offset_data = data;
    double time = time(NULL) / 3600.0; // Time in hours
    offset_data.temperature += 2.0 * sin(time * M_PI);
    offset_data.humidity += 5.0 * sin(time * M_PI);
    return offset_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    SensorData processed_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Simulate offset
            processed_data = simulate_offset(processed_data);

            // Log data
            if (!isnan(processed_data.temperature) && !isnan(processed_data.humidity)) {
                if (log_data(processed_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor data, skipping logging\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000); // Wait for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

