#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_US 45000 // 45 ms
#define CSV_FILENAME "airflow.csv"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int count);
SensorData process_data(const uint8_t *raw_data);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t calculate_crc(const uint8_t *data, int count) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Process raw data to get pressure and temperature
SensorData process_data(const uint8_t *raw_data) {
    SensorData data;
    // Extract raw values
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
    int16_t raw_scale_factor = (raw_data[6] << 8) | raw_data[7];

    // CRC validation
    if (calculate_crc(raw_data, 2) != raw_data[2]) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        data.pressure = 0.0; // Indicate error
    } else if (calculate_crc(raw_data + 3, 2) != raw_data[5]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        data.temperature = 0.0; // Indicate error
    } else if (calculate_crc(raw_data + 6, 2) != raw_data[8]) {
        fprintf(stderr, "Scale Factor CRC check failed!\n");
        data.pressure = 0.0; // Indicate error
    } else {
        // Convert to physical units (refer to SDP810 datasheet)
        data.pressure = (float)raw_pressure / 240.0; // Pa
        data.temperature = (float)raw_temperature / 200.0; // °C
    }

    return data;
}

// Log data to CSV file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(csv_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        cleanup();
        return 1;
    }

    uint8_t raw_data[9];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_US);

        // Read data from sensor
        if (read_data(i2c_handle, raw_data, 9) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Process data
        sensor_data = process_data(raw_data);

        // Log data
        if (sensor_data.pressure != 0.0 && sensor_data.temperature != 0.0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error: Invalid sensor data, skipping logging.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

