#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUM_CMD 0xF5
#define READ_TEMP_CMD 0xE0
#define RESET_CMD 0xFE
#define LOG_FILE "environment.log"
#define SAMPLE_INTERVAL_SEC 5

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_fp = NULL;

void signal_handler(int sig) {
    keep_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read a single byte from the I2C device
int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading byte: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing byte: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from the I2C device
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading bytes: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from the Si7021
float read_temperature(int fd) {
    uint8_t data[3];
    int retry_count = 0;
    const int max_retries = 5;
    const int delay_ms = 10;

    while (retry_count < max_retries) {
        if (i2c_write_byte(fd, 0, TEMP_CMD) != 0) {
            fprintf(stderr, "Error writing temperature command.\n");
            return -1000.0; // Indicate error
        }
        usleep(10000); // Wait for measurement (at least 11ms)

        if (i2c_read_bytes(fd, 0, data, 3) == 0) {
            uint16_t raw_temp = (data[0] << 8) | data[1];
            uint8_t crc = data[2];

            uint8_t calculated_crc = crc8(data, 2);
            if (crc != calculated_crc) {
                fprintf(stderr, "Temperature CRC check failed!\n");
                return -1000.0; // Indicate error
            }

            return 175.72 * raw_temp / 65536.0 - 46.85;
        } else {
            fprintf(stderr, "Error reading temperature data, retrying (%d/%d).\n", retry_count + 1, max_retries);
            retry_count++;
            usleep(delay_ms * 1000); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1000.0; // Indicate error
}

// Function to read humidity from the Si7021
float read_humidity(int fd) {
    uint8_t data[3];
    int retry_count = 0;
    const int max_retries = 5;
    const int delay_ms = 10;

    while (retry_count < max_retries) {
        if (i2c_write_byte(fd, 0, HUM_CMD) != 0) {
            fprintf(stderr, "Error writing humidity command.\n");
            return -1.0; // Indicate error
        }
        usleep(10000); // Wait for measurement (at least 11ms)

        if (i2c_read_bytes(fd, 0, data, 3) == 0) {
            uint16_t raw_humidity = (data[0] << 8) | data[1];
            uint8_t crc = data[2];

            uint8_t calculated_crc = crc8(data, 2);
            if (crc != calculated_crc) {
                fprintf(stderr, "Humidity CRC check failed!\n");
                return -1.0; // Indicate error
            }

            return 125.0 * raw_humidity / 65536.0 - 6.0;
        } else {
            fprintf(stderr, "Error reading humidity data, retrying (%d/%d).\n", retry_count + 1, max_retries);
            retry_count++;
            usleep(delay_ms * 1000); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to read humidity after multiple retries.\n");
    return -1.0; // Indicate error
}

// Function to log data to a CSV file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(fp); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "timestamp,temperature_C,humidity_percent\n");
    }

    // Main loop
    while (keep_running) {
        float temperature = read_temperature(i2c_fd);
        float humidity = read_humidity(i2c_fd);

        if (temperature > -999.0 && humidity > -1.0) {
            if (log_data(log_fp, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Logging error.\n");
            if (log_data(log_fp, -999.0, -1.0) != 0) {
                fprintf(stderr, "Error logging error data.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    return 0;
}

