#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3603
#define CONVERSION_TIME_MS 45
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int16_t convert_pressure(int16_t raw_pressure);
int log_pressure_data(int16_t pressure);
void signal_handler(int signal);

// CRC-8 calculation (from SDP800 datasheet)
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 3);
    return (crc == data[len - 3]);
}

// Pressure conversion
int16_t convert_pressure(int16_t raw_pressure) {
    return (int16_t)(raw_pressure / SCALE_FACTOR);
}

// Logging function
int log_pressure_data(int16_t pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %d Pa\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, pressure);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Failed to send measurement command.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t raw_data[9];
    sensor_data_t sensor_data;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            // Read sensor data
            if (read_sensor_data(i2c_handle, raw_data, 9) == 0) {
                // Validate CRC
                if (validate_crc(raw_data, 9)) {
                    // Extract data
                    sensor_data.pressure = (int16_t)((raw_data[0] << 8) | raw_data[1]);
                    sensor_data.temperature = (int16_t)((raw_data[3] << 8) | raw_data[4]);
                    sensor_data.status = (uint16_t)((raw_data[6] << 8) | raw_data[7]);

                    // Convert pressure
                    int16_t pressure_pa = convert_pressure(sensor_data.pressure);

                    // Log data
                    if (log_pressure_data(pressure_pa) != 0) {
                        fprintf(stderr, "Error logging pressure data.\n");
                    }

                    // Wait for conversion time
                    gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to us

                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "CRC validation failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
            }
            retry++;
            gpioDelay(1000); // Wait 1ms before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

