#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Sensor calibration parameters
#define MIN_FLOW 0.0  // SLPM
#define MAX_FLOW 10.0 // SLPM
#define MIN_RAW 1638
#define MAX_RAW 14745

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle);
float convert_to_slpm(int raw_flow);
void set_fan_speed(float flow_rate);
void log_data(float pressure_Pa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to read the sensor data
int read_sensor(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit word
    int16_t raw_flow = (buf[0] << 8) | buf[1];

    // Mask off the status bits (2 MSBs)
    raw_flow = raw_flow >> 2;

    return raw_flow;
}

// Function to convert raw flow to SLPM
float convert_to_slpm(int raw_flow) {
    float flow_rate = MIN_FLOW + (float)(raw_flow - MIN_RAW) * (MAX_FLOW - MIN_FLOW) / (MAX_RAW - MIN_RAW);
    return flow_rate;
}

// Function to set the fan speed based on flow rate
void set_fan_speed(float flow_rate) {
    // Scale the flow rate to a PWM duty cycle (0-100)
    int duty_cycle = (int)(flow_rate * 100.0);

    // Ensure the duty cycle is within the valid range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 100) {
        duty_cycle = 100;
    }

    // Set the PWM duty cycle
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log the data to a file
void log_data(float pressure_Pa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_Pa);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int raw_flow = read_sensor(i2c_handle);
        if (raw_flow < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to SLPM
        float flow_rate = convert_to_slpm(raw_flow);

        // Set fan speed
        set_fan_speed(flow_rate);

        // Log the data
        log_data(flow_rate);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);   // Close the I2C bus
    fclose(log_file);       // Close the log file
    gpioTerminate();        // Terminate pigpio

    printf("Shutdown complete.\n");
    return 0;
}

