// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
void log_data(int32_t pressure, int16_t temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize LPS33HW sensor
int init_lps33hw() {
    int status;
    uint8_t who_am_i;

    // Read WHO_AM_I register
    status = i2cReadI2CBlockData(i2c_handle, WHO_AM_I, (char *)&who_am_i, 1);
    if (status != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }

    // Check WHO_AM_I value
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 register
    uint8_t ctrl_reg1 = 0xB0; // Block data update, 10 Hz, active mode
    status = i2cWriteI2CBlockData(i2c_handle, CTRL_REG1, (char *)&ctrl_reg1, 1);
    if (status != 1) {
        fprintf(stderr, "Error writing CTRL_REG1 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read pressure from LPS33HW sensor
int read_pressure(int32_t *pressure) {
    int status;
    uint8_t buffer[3];

    // Read pressure data (3 bytes)
    status = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, (char *)buffer, 3);
    if (status != 3) {
        fprintf(stderr, "Error reading pressure data: %d\n", status);
        return -1;
    }

    // Combine bytes to form 24-bit pressure value
    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | ((uint32_t)buffer[0]));

    return 0;
}

// Read temperature from LPS33HW sensor
int read_temperature(int16_t *temperature) {
    int status;
    uint8_t buffer[2];

    // Read temperature data (2 bytes)
    status = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, (char *)buffer, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", status);
        return -1;
    }

    // Combine bytes to form 16-bit temperature value
    *temperature = (int16_t)((((uint16_t)buffer[1]) << 8) | ((uint16_t)buffer[0]));

    return 0;
}

// Log data to file
void log_data(int32_t pressure, int16_t temperature) {
    time_t now;
    struct tm timeinfo;
    char timestamp[20];

    // Get current time
    time(&now);
    localtime_r(&now, &timeinfo);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    // Write data to file
    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, (float)pressure / 4096.0, 42.5 + (float)temperature / 480.0);
    fflush(log_file);
}

int main() {
    int status;
    int32_t pressure;
    int16_t temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            // Log data
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

