#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define SCD30_ADDR 0x61
#define MEASUREMENT_INTERVAL 2.0 // seconds
#define LOG_FILE "air_quality.log"

// Global variables for signal handling
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_command(int handle, unsigned char command[], int command_len);
int read_data(int handle, unsigned char data[], int data_len);
int verify_crc(unsigned char data[], int len);
int start_periodic_measurement(int handle);
int stop_periodic_measurement(int handle);
int read_measurement(int handle, float *co2, float *temperature, float *humidity);
void log_data(float co2, float temperature, float humidity);
void ventilation_control(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start periodic measurement. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    float co2, temperature, humidity;
    while (running) {
        // Read measurement
        if (read_measurement(i2c_handle, &co2, &temperature, &humidity) == 0) {
            // Log data
            log_data(co2, temperature, humidity);

            // Ventilation control
            ventilation_control(co2);
        } else {
            fprintf(stderr, "Failed to read measurement.\n");
        }

        // Wait for the next measurement interval
        gpioDelay(MEASUREMENT_INTERVAL * 1000000); // microseconds
    }

    // Stop periodic measurement
    stop_periodic_measurement(i2c_handle);

    // Cleanup
    cleanup();

    return 0;
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int write_command(int handle, unsigned char command[], int command_len) {
    int result = i2cWriteDevice(handle, (char *)command, command_len);
    if (result != command_len) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

int read_data(int handle, unsigned char data[], int data_len) {
    int result = i2cReadDevice(handle, (char *)data, data_len);
    if (result != data_len) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

int verify_crc(unsigned char data[], int len) {
    unsigned char crc = crc8(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", data[len], crc);
        return -1;
    }
    return 0;
}

int start_periodic_measurement(int handle) {
    unsigned char command[] = {0x21, 0xB1, 0x01};
    if (write_command(handle, command, sizeof(command)) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        return -1;
    }
    return 0;
}

int stop_periodic_measurement(int handle) {
    unsigned char command[] = {0x3F, 0x86, 0x00};
    if (write_command(handle, command, sizeof(command)) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
        return -1;
    }
    return 0;
}

int read_measurement(int handle, float *co2, float *temperature, float *humidity) {
    unsigned char command[] = {0x00, 0x00, 0x00};
    unsigned char data[18];
    unsigned char data_ready[3];

    // Check data ready
    if (write_command(handle, command, sizeof(command)) != 0) {
        fprintf(stderr, "Failed to write data ready command\n");
        return -1;
    }
    if (read_data(handle, data_ready, sizeof(data_ready)) != 0) {
        fprintf(stderr, "Failed to read data ready status\n");
        return -1;
    }

    if (data_ready[0] != 0x00 || data_ready[1] != 0x00 || data_ready[2] != 0x00) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read measurement
    if (write_command(handle, command, sizeof(command)) != 0) {
        fprintf(stderr, "Failed to write read measurement command\n");
        return -1;
    }
    if (read_data(handle, data, sizeof(data)) != 0) {
        fprintf(stderr, "Failed to read measurement data\n");
        return -1;
    }

    // Verify CRC
    if (verify_crc(data, 2) != 0) return -1;
    if (verify_crc(data + 3, 2) != 0) return -1;
    if (verify_crc(data + 6, 2) != 0) return -1;
    if (verify_crc(data + 9, 2) != 0) return -1;
    if (verify_crc(data + 12, 2) != 0) return -1;

    // Convert data
    *co2 = *((float *)data);
    *temperature = *((float *)(data + 6));
    *humidity = *((float *)(data + 12));

    return 0;
}

void log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

void ventilation_control(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

