#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define CONTINUOUS_MEASUREMENT_CMD_1 0x36
#define CONTINUOUS_MEASUREMENT_CMD_2 0x2F
#define SAMPLE_INTERVAL_MS 1000
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint8_t cmd1, uint8_t cmd2);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *raw_data);
void log_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (SDP32 specific)
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the SDP32
int send_command(int handle, uint8_t cmd1, uint8_t cmd2) {
    char buf[2];
    buf[0] = cmd1;
    buf[1] = cmd2;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP32
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Process raw sensor data
sensor_data_t process_sensor_data(const uint8_t *raw_data) {
    sensor_data_t data;
    // Extract raw values
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
    int16_t raw_scale_factor = (raw_data[6] << 8) | raw_data[7];

    // CRC Check
    if (calculate_crc(raw_data, 2) != raw_data[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        data.pressure_pa = 0.0; // Indicate error
    } else {
        data.pressure_pa = (float)raw_pressure / raw_scale_factor;
    }

    if (calculate_crc(raw_data + 3, 2) != raw_data[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        data.temperature_c = 0.0; // Indicate error
    } else {
        data.temperature_c = (float)raw_temperature / 200.0; // Temperature in Celsius
    }

    if (calculate_crc(raw_data + 6, 2) != raw_data[8]) {
        fprintf(stderr, "Scale Factor CRC check failed\n");
        data.scale_factor = 1.0; // Indicate error
    } else {
        data.scale_factor = (float)raw_scale_factor;
    }

    return data;
}

// Log sensor data with timestamp
void log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f C, Scale Factor: %.2f\n", timestamp, data.pressure_pa, data.temperature_c, data.scale_factor);
}

