#define CONTINUOUS_MEASUREMENT_CMD_2 0x2F
#define SAMPLE_INTERVAL_MS 1000
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint8_t cmd1, uint8_t cmd2);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
