#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to a specific register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a specific number of bytes from a register
int read_register(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1000
int read_hdc1000(int fd, float *temperature, float *humidity) {
    uint8_t buf[4];
    int16_t raw_temp, raw_humidity;

    // Trigger temperature and humidity measurement
    if (write_register(fd, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for conversion to complete (at least 20ms)
    usleep(20000); // 20ms

    // Read temperature and humidity registers
    if (read_register(fd, TEMP_REG, buf, 4) < 0) {
        fprintf(stderr, "Error reading temperature and humidity\n");
        return -1;
    }

    // Combine the bytes to form 16-bit raw values
    raw_temp = (buf[0] << 8) | buf[1];
    raw_humidity = (buf[2] << 8) | buf[3];

    // Convert raw values to temperature and humidity
    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    return 0;
}

