    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from Si7051 sensor
int read_temperature(float *temperature) {
    int result, retries = 0;
    unsigned char buf[2];
    unsigned short raw_temp;

    // Send temperature measurement command
    while (retries < RETRY_COUNT) {
        result = i2cWriteByteData(i2c_handle, TEMP_MEASURE_CMD, 0); // No data to write, just command
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing to I2C: %d, retrying...\n", result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write to I2C after multiple retries.\n");
        return -1; // Indicate failure
    }

    // Wait for measurement (typical conversion time is 25ms, but we wait longer for safety)
    gpioDelay(50000); // 50ms

    // Read two bytes of temperature data
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) break; // Success
        fprintf(stderr, "Error reading from I2C: %d, retrying...\n", result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
