float read_pressure() {
    char buf[2];
    int result;
    int raw_pressure;

    // Read two bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0; // Indicate an error
    }

    // Combine the two bytes into a 16-bit integer
    raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw pressure to a floating-point pressure value (example conversion)
    // Replace with the actual conversion formula from the MLX90833 datasheet
    float pressure = (float)raw_pressure * 0.1; // Example scaling

    return pressure;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float pressure = read_pressure();

        if (pressure >= 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the pressure value with timestamp
            printf("[%s] Pressure: %.2f kPa\n", timestamp, pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
