        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpioDelay takes microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

