#define I2C_ADDR 0x63

// I2C bus
#define I2C_BUS 1

// Calibration data register
#define CALIB_DATA_REG 0x50

// Measurement command
#define MEASURE_CMD 0x40

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
double scale_factor_lut, scale_factor_h, scale_factor_p;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read calibration data from the sensor
int read_calibration_data() {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_DATA_REG, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    // Extract calibration coefficients from the buffer
    // These are placeholder values, replace with actual extraction logic from the datasheet
    scale_factor_lut = (double)((unsigned char)buf[0] << 8 | (unsigned char)buf[1]) / 100.0;
    scale_factor_h = (double)((unsigned char)buf[2] << 8 | (unsigned char)buf[3]) / 100.0;
    scale_factor_p = (double)((unsigned char)buf[4] << 8 | (unsigned char)buf[5]) / 100.0;

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int *raw_temperature, int *raw_pressure) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *raw_temperature = (int16_t)((unsigned char)buf[0] << 8 | (unsigned char)buf[1]);
    *raw_pressure = (int32_t)((unsigned char)buf[2] << 16 | (unsigned char)buf[3] << 8 | (unsigned char)buf[4]);

    return 0;
}

// Function to convert raw data to temperature and pressure
void convert_data(int raw_temperature, int raw_pressure, double *temperature, double *pressure) {
    // Placeholder conversion formulas, replace with actual formulas from the datasheet
    *temperature = (double)raw_temperature / scale_factor_lut;
    *pressure = (double)raw_pressure / scale_factor_p;
}

// Function to log data with ISO-8601 timestamp
void log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_temperature, raw_pressure;
        double temperature, pressure;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(7000); // 7 ms

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Convert data
        convert_data(raw_temperature, raw_pressure, &temperature, &pressure);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

