#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CSV_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_SEC 1

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int read_sdp800(int i2c_handle, float *pressure) {
    char cmd[2] = {0x36, 0x2F};
    char buf[3];
    int raw_pressure;
    unsigned char crc;
    unsigned char crc_table[256];

    // Send continuous measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at least 8 ms)
    gpioDelay(8);

    // Read 3 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Extract raw pressure value
    raw_pressure = (buf[0] << 8) | buf[1];

    // Extract CRC byte
    crc = buf[2];

    // CRC-8 checksum calculation
    for (int i = 0; i < 256; i++) {
        unsigned char crc = i;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
        crc_table[i] = crc;
    }

    // Verify CRC checksum
    unsigned char crc_calculated = crc_table[buf[0] ^ 0xFF] ^ crc_table[buf[1] ^ 0xFF];

    if (crc_calculated != crc) {
        fprintf(stderr, "CRC checksum mismatch\n");
        return -1;
    }

    // Convert raw value to pressure in Pa
    *pressure = (float)raw_pressure / 60.0;

    return 0;
}

int log_data(const char *filename, float pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open file in append mode
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return -1;
    }

    // Write header if file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    // Write data to file
    fprintf(fp, "%s,%.2f\n", timestamp, pressure);

    // Close file
    fclose(fp);

    return 0;
}

int main() {
    float pressure;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure data
        result = read_sdp800(i2c_handle, &pressure);
        if (result == 0) {
            // Log data to file
            if (log_data(CSV_FILE, pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

