#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_FILE_SIZE 1048576 // 1 MB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t validate_checksum(uint8_t data1, uint8_t data2, uint8_t data3, uint8_t data4);
SensorData convert_data(uint8_t *data);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from HIH6130
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate checksum
uint8_t validate_checksum(uint8_t data1, uint8_t data2, uint8_t data3, uint8_t data4) {
    uint8_t checksum = (data1 >> 8) ^ (data2 >> 8) ^ (data3 >> 8) ^ (data4 >> 8);
    return checksum;
}

// Convert raw data to temperature and humidity
SensorData convert_data(uint8_t *data) {
    SensorData sensor_data;
    uint16_t raw_humidity = ((data[0] & 0x3F) << 8) | data[1];
    uint16_t raw_temperature = (data[2] << 6) | (data[3] >> 2);

    sensor_data.humidity = raw_humidity * 100.0 / 16383.0;
    sensor_data.temperature = raw_temperature * 165.0 / 16383.0 - 40.0;

    return sensor_data;
}

// Log data to file
void log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fclose(fp);

    // Truncate file if it exceeds the maximum size
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && st.st_size > MAX_FILE_SIZE) {
        fp = fopen(LOG_FILE, "w");
        if (fp != NULL) {
            fclose(fp);
        } else {
            fprintf(stderr, "Error truncating log file!\n");
        }
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t data[4];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (i2cWriteByte(i2c_handle, 0x00) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
            cleanup();
            return 1;
        }

        // Wait for measurement to complete
        gpioDelay(50000); // 50 ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            cleanup();
            return 1;
        }

        // Validate checksum
        if (validate_checksum(data[0], data[1], data[2], data[3]) != 0) {
            fprintf(stderr, "Checksum validation failed\n");
            cleanup();
            return 1;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        log_data(sensor_data);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

