#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define DEVICE_ID_VALUE 0x0117
#define TEMP_CONVERSION_FACTOR 0.0078125f
#define SAMPLE_INTERVAL_SEC 60
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_device_id(int i2c_handle);
float read_temperature(int i2c_handle);
int write_float_to_file(FILE *fp, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the device ID register
int read_device_id(int i2c_handle) {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    return device_id;
}

// Function to read the temperature register
float read_temperature(int i2c_handle) {
    int16_t raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0f; // Indicate error with a very low temperature
    }
    return (float)raw_temp * TEMP_CONVERSION_FACTOR;
}

// Function to write a float to the file
int write_float_to_file(FILE *fp, float temperature) {
    uint32_t float_data = *((uint32_t *)&temperature);
    size_t bytes_written = fwrite(&float_data, sizeof(uint32_t), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    int device_id = read_device_id(i2c_handle);
    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect device ID. Expected 0x%X, got 0x%X\n", DEVICE_ID_VALUE, device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for appending
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature(i2c_handle);

        // Write temperature to file
        if (temperature > -999.0f) { // Only write if read was successful
            if (write_float_to_file(fp, temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, but continuing...\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

