#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF
#define LOG_FILE "environmental_data.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_command(int handle, unsigned char command);
int read_data(int handle, unsigned char *data, int count);
unsigned char calculate_crc8(const unsigned char *data, int len);
int validate_checksum(const unsigned char *data, int len);
SensorData convert_data(const unsigned char *data);
int log_data(SensorData data);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char calculate_crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Checksum validation function
int validate_checksum(const unsigned char *data, int len) {
    unsigned char crc = calculate_crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Data conversion function
SensorData convert_data(const unsigned char *data) {
    SensorData result;
    unsigned int raw_temp = (data[0] << 8) | data[1];
    unsigned int raw_hum = (data[3] << 8) | data[4];

    result.temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    result.humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return result;
}

// Data logging function
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to SHT40
int write_command(int handle, unsigned char command) {
    int result = i2cWriteByteData(handle, command, 0); // No data to write, just the command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT40
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return result;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[6];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Wait for conversion (at least 8.5 ms)
        gpioDelay(8500); // 8500 microseconds = 8.5 milliseconds

        // Read data
        if (read_data(i2c_handle, data, 6) != 6) {
            fprintf(stderr, "Error reading data. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Validate checksums
        if (!validate_checksum(data, 2) || !validate_checksum(data + 3, 2)) {
            fprintf(stderr, "Checksum validation failed. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data. Retrying in %d seconds.\n", SLEEP_SECONDS);
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

