#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define SAMPLE_INTERVAL_SEC 5
#define BUFFER_SIZE 60
#define LOG_FILE "temperature_log.dat"

// Structure to hold temperature data
typedef struct {
    float temperature;
    uint32_t timestamp;
} TemperatureReading;

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Circular buffer
TemperatureReading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
float read_temperature();
void add_to_buffer(float temperature);
void flush_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert big-endian 2-byte data to temperature in degrees Celsius
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;

    return temperature;
}

// Add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Flush the buffer to the log file
void flush_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(TemperatureReading), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write all elements to log file.\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    flush_buffer_to_file();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

