#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASUREMENT_COMMAND 0x7866
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, int len);
SensorData process_sensor_data(const uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char buf[2];
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Process sensor data
SensorData process_sensor_data(const uint8_t *data) {
    SensorData result;
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    // CRC validation
    if (calculate_crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC failure\n");
        result.temperature = -999.0; // Indicate error
    } else if (calculate_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC failure\n");
        result.humidity = -999.0; // Indicate error
    } else {
        // Data validation
        if (raw_temperature < 0x0000 || raw_temperature > 0xFFFF) {
            fprintf(stderr, "Temperature out of range: 0x%X\n", raw_temperature);
            result.temperature = -999.0; // Indicate error
        } else if (raw_humidity < 0x0000 || raw_humidity > 0xFFFF) {
            fprintf(stderr, "Humidity out of range: 0x%X\n", raw_humidity);
            result.humidity = -999.0; // Indicate error
        } else {
            // Conversion
            result.temperature = 175.0 * raw_temperature / 65535.0 - 45.0;
            result.humidity = 100.0 * raw_humidity / 65535.0;
        }
    }

    return result;
}

// Log data to file
int log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    SensorData processed_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Failed to send measurement command. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Wait for conversion (at least 12.4 ms)
        gpioDelay(12400); // microseconds

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Process sensor data
        processed_data = process_sensor_data(sensor_data);

        // Log data if valid
        if (processed_data.temperature != -999.0 && processed_data.humidity != -999.0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", processed_data.temperature, processed_data.humidity);
            if (log_data(processed_data) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor data. Skipping logging.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

