    float magnetic_field;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_magnetic_field(uint16_t raw_value);
float convert_temperature(uint16_t raw_value);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int write_header(FILE *fp);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from Si7202
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[4]; // Assuming 2 bytes for magnetic field and 2 for temperature
    int result;

    // Read magnetic field
    result = i2cReadI2CBlockData(i2c_handle, MAG_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field: %d\n", result);
        data->magnetic_field = NAN;
    } else {
        uint16_t raw_magnetic_field = (buffer[0] << 8) | buffer[1];
        data->magnetic_field = convert_magnetic_field(raw_magnetic_field);
    }

    // Read temperature
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)buffer + 2, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        data->temperature = NAN;
    } else {
        uint16_t raw_temperature = (buffer[2] << 8) | buffer[3];
        data->temperature = convert_temperature(raw_temperature);
    }

    return 0;
}

