#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from TMP117
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit signed integer
            int16_t raw_temp = (buf[0] << 8) | buf[1];

            // Convert to temperature in Celsius
            *temperature = raw_temp * TEMP_SCALE;

            // Handle negative temperatures
            if (*temperature > 127.0) {
                *temperature -= 256.0;
            }

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading temperature (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

