#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_celsius;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(unsigned char *data);
SensorData convert_data(unsigned char *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the I2C bus
int read_sensor_data(unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C bus: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert raw data to flow and temperature values
SensorData convert_data(unsigned char *data) {
    SensorData sensor_data;
    // Combine the two bytes for flow and temperature
    unsigned int raw_flow = ((data[0] & 0x3F) << 8) | data[1];
    unsigned int raw_temp = (data[2] << 4) | (data[3] >> 4);

    // Apply the conversion formulas
    sensor_data.flow_slpm = ((float)raw_flow / 16384.0 - 0.1) / 0.8 * 25.0;
    sensor_data.temperature_celsius = ((float)raw_temp / 4096.0 - 0.1) / 0.8 * 80.0 - 40.0;

    return sensor_data;
}

// Function to log the data to a file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, data.flow_slpm, data.temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    unsigned char raw_data[4];
    SensorData sensor_data;
    int retries = 3; // Number of retries for I2C read

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data with retries
        int read_result = -1;
        for (int i = 0; i < retries; ++i) {
            if (read_sensor_data(raw_data) == 0) {
                read_result = 0;
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i + 1, retries);
                gpioDelay(100); // Wait before retrying
            }
        }

        if (read_result != 0) {
            fprintf(stderr, "Failed to read sensor data after multiple retries. Logging error.\n");
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, ERROR: Failed to read sensor data after multiple retries.\n", timestamp);
            fflush(log_file);
            cleanup();
            return 1; // Exit the program if read fails repeatedly
        }

        // Convert the raw data
        sensor_data = convert_data(raw_data);

        // Log the data
        log_data(sensor_data);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // pigpioDelay takes milliseconds
    }

    // Clean up resources before exiting
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

