// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_fp = NULL;
FILE *error_fp = NULL;

// Structure to hold sensor data
typedef struct {
    int humidity;
    int temperature;
    int checksum;
    int error_code;
} DHT11Data;

// Function prototypes
int initialize_gpio();
int send_start_signal();
int read_data(DHT11Data *data);
int validate_checksum(DHT11Data *data);
void log_data(DHT11Data *data);
void log_error(int error_code, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

// Function to send the start signal
int send_start_signal() {
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18 ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20 us
    return 0;
}

// Function to read data from the sensor
int read_data(DHT11Data *data) {
    int data_bits[40];
    int i, j;

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the start of the data bit (50 us low)
        int count = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            count++;
            gpioDelay(1); // 1 us delay
            if (count > 50) { // Timeout
                log_error(2, "Timeout waiting for data bit start");
                return 1;
            }
        }

        // Measure the length of the high pulse
        count = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            count++;
            gpioDelay(1); // 1 us delay
            if (count > 80) { // Timeout
                log_error(3, "Timeout waiting for data bit end");
                return 1;
            }
        }

        data_bits[i] = count;
    }

    // Convert the data bits to bytes
    data->humidity = 0;
    data->temperature = 0;
    data->checksum = 0;

    for (i = 0; i < 8; i++) {
        data->humidity <<= 1;
        if (data_bits[i] > 26) data->humidity |= 1; // '1' if pulse > 28 us
    }

    for (i = 8; i < 16; i++) {
        data->temperature <<= 1;
        if (data_bits[i] > 26) data->temperature |= 1; // '1' if pulse > 28 us
    }

    for (i = 16; i < 24; i++) {
        data->checksum <<= 1;
        if (data_bits[i] > 26) data->checksum |= 1; // '1' if pulse > 28 us
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(DHT11Data *data) {
    int checksum = (data->humidity & 0xFF) + ((data->humidity >> 8) & 0xFF) +
                   (data->temperature & 0xFF) + ((data->temperature >> 8) & 0xFF);

    if ((checksum & 0xFF) != data->checksum) {
        log_error(4, "Checksum validation failed");
        return 1;
    }

    return 0;
}

