    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_fp, "%s, Humidity: %d, Temperature: %d\n", timestamp, data->humidity, data->temperature);
    fflush(log_fp);
}

