    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(error_fp, "%s, Error Code: %d, Message: %s\n", timestamp, error_code, message);
    fflush(error_fp);
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(DHT11_GPIO, 0); // Set GPIO low
    gpioTerminate(); // Terminate pigpio

    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (error_fp != NULL) {
        fclose(error_fp);
    }
}

int main() {
    DHT11Data data;
    int retries = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log files
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_fp == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        cleanup();
        return 1;
    }

    printf("DHT11 reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Retry mechanism
        for (int i = 0; i < retries; i++) {
            // Send start signal
            if (send_start_signal() != 0) {
                log_error(1, "Failed to send start signal");
                continue; // Retry
            }

            // Read data
            if (read_data(&data) != 0) {
                log_error(5, "Failed to read data");
                continue; // Retry
            }

            // Validate checksum
            if (validate_checksum(&data) != 0) {
