            }

            // Log data
            log_data(&data);
            break; // Exit retry loop on success
        }

        if (terminate) break; // Exit main loop if terminated

        gpioDelay(SAMPLE_INTERVAL * 1000); // Sample every 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
