#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define DATA_LENGTH 6
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define SLEEP_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
unsigned char crc8(const unsigned char *data, int len);
SensorData process_data(unsigned char *raw_data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per SHT31-D datasheet)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to SHT31-D
int write_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT31-D
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Process raw data to get temperature and humidity
SensorData process_data(unsigned char *raw_data) {
    SensorData data;
    unsigned short temperature_raw = (raw_data[0] << 8) | raw_data[1];
    unsigned short humidity_raw = (raw_data[3] << 8) | raw_data[4];

    data.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char raw_data[DATA_LENGTH];
        int retry = 0;
        int read_result = -1;

        // Retry reading data up to 3 times
        while (retry < RETRY_COUNT && read_result != 0) {
            // Send measurement command
            if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
                fprintf(stderr, "Error writing measurement command, retry %d\n", retry + 1);
                gpioDelay(100); // Wait before retrying
                retry++;
                continue;
            }

            // Wait for measurement (at least 15 ms)
            gpioDelay(15);

            // Read data
            read_result = read_data(i2c_handle, raw_data, DATA_LENGTH);
            if (read_result != 0) {
                fprintf(stderr, "Error reading data, retry %d\n", retry + 1);
                gpioDelay(100); // Wait before retrying
                retry++;
            } else {
                break; // Exit retry loop if read is successful
            }
        }

        if (read_result != 0) {
            fprintf(stderr, "Persistent sensor failure, skipping data logging\n");
            gpioDelay(SLEEP_INTERVAL * 1000); // Wait before next attempt
            continue;
        }

        // CRC validation
        if (crc8(raw_data, 2) != raw_data[2] || crc8(raw_data + 3, 2) != raw_data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            gpioDelay(SLEEP_INTERVAL * 1000); // Wait before next attempt
            continue;
        }

        // Process data
        SensorData data = process_data(raw_data);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_INTERVAL * 1000);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

