    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char raw_data[DATA_LENGTH];
        int retry = 0;
        int read_result = -1;

        // Retry reading data up to 3 times
        while (retry < RETRY_COUNT && read_result != 0) {
            // Send measurement command
            if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
                fprintf(stderr, "Error writing measurement command, retry %d\n", retry + 1);
                gpioDelay(100); // Wait before retrying
                retry++;
                continue;
            }

            // Wait for measurement (at least 15 ms)
            gpioDelay(15);

            // Read data
            read_result = read_data(i2c_handle, raw_data, DATA_LENGTH);
            if (read_result != 0) {
                fprintf(stderr, "Error reading data, retry %d\n", retry + 1);
                gpioDelay(100); // Wait before retrying
                retry++;
            } else {
                break; // Exit retry loop if read is successful
            }
        }

        if (read_result != 0) {
            fprintf(stderr, "Persistent sensor failure, skipping data logging\n");
            gpioDelay(SLEEP_INTERVAL * 1000); // Wait before next attempt
            continue;
        }

        // CRC validation
        if (crc8(raw_data, 2) != raw_data[2] || crc8(raw_data + 3, 2) != raw_data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            gpioDelay(SLEEP_INTERVAL * 1000); // Wait before next attempt
            continue;
        }

        // Process data
        SensorData data = process_data(raw_data);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_INTERVAL * 1000);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

