    result = i2cReadI2CBlockData(i2c_handle, REG_RED_DATA, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read green data
    result = i2cReadI2CBlockData(i2c_handle, REG_GREEN_DATA, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading green data: %d\n", result);
        return -1;
