#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 800.0
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 125.0
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_raw_pressure(int i2c_handle);
int read_raw_temperature(int i2c_handle);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
void log_data(float pressure_kPa, float temperature_C);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read raw pressure data from the sensor
int read_raw_pressure(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure register: %d\n", result);
        return -1; // Indicate error
    }
    return (buf[0] << 8) | buf[1]; // Combine bytes into 16-bit value
}

// Function to read raw temperature data from the sensor
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1; // Indicate error
    }
    return (buf[0] << 8) | buf[1]; // Combine bytes into 16-bit value
}

// Function to convert raw pressure to kPa
float convert_pressure(int raw_pressure) {
    return (float)(raw_pressure - OUTPUT_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature * 0.01 - 40.0;
}

// Function to log data to a file
void log_data(float pressure_kPa, float temperature_C) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f kPa, %.2f C\n", timestamp, pressure_kPa, temperature_C);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tire pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_pressure = read_raw_pressure(i2c_handle);
        int raw_temperature = read_raw_temperature(i2c_handle);

        if (raw_pressure != -1 && raw_temperature != -1) {
            float pressure_kPa = convert_pressure(raw_pressure);
            float temperature_C = convert_temperature(raw_temperature);

            log_data(pressure_kPa, temperature_C);

            printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure_kPa, temperature_C);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        gpioDelay(READ_INTERVAL_SEC * 1000); // Delay for 2 seconds
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

