#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define TEMP_CONVERSION_FACTOR 0.5
#define TEMP_OFFSET 0.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temp_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature();
float convert_to_celsius(int raw_temp);
void update_circular_buffer(float temperature);
float calculate_running_average();
void control_fan(float average_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read temperature from LM75B
int read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1; // Indicate error
    }
    return raw_temp;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    // The LM75B returns a 9-bit temperature value, with the upper bit (D0) always 0.
    // The remaining 8 bits (D1-D9) represent the temperature in 0.5 degree increments.
    // The sign bit (D9) is ignored for simplicity.
    int temp = raw_temp & 0x3FF; // Mask out the sign bit and unused bits
    return (float)temp * TEMP_CONVERSION_FACTOR + TEMP_OFFSET;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temp_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
float calculate_running_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temp_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(float average_temp) {
    static int fan_on = 0; // Track fan state

    if (average_temp > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Average Temp: %.2f)\n", average_temp);
    } else if (average_temp < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Average Temp: %.2f)\n", average_temp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Initialize circular buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temp_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        int raw_temp = read_temperature();
        if (raw_temp >= 0) {
            // Convert to Celsius
            float temperature = convert_to_celsius(raw_temp);

            // Update circular buffer
            update_circular_buffer(temperature);

            // Calculate running average
            float average_temp = calculate_running_average();

            // Control fan
            control_fan(average_temp);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying in 1 second...\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

