#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define LOG_FILE "airflow.log"
#define PRESSURE_THRESHOLD 5.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *buffer, int count);
uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc8(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *buffer);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *buffer, int count) {
    int result = i2cReadDevice(handle, (char *)buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC8 checksum
int validate_crc8(const uint8_t *data, int len) {
    uint8_t calculated_crc = calculate_crc8(data, len - 1);
    return (calculated_crc == data[len - 1]);
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *buffer) {
    sensor_data_t data;
    data.pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data.status = (uint16_t)((buffer[6] << 8) | buffer[7]);
    return data;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure / PRESSURE_SCALE_FACTOR, data.temperature / TEMPERATURE_SCALE_FACTOR);
    fflush(log_file);

    if (data.pressure / PRESSURE_SCALE_FACTOR > PRESSURE_THRESHOLD) {
        fprintf(stderr, "WARNING: Differential pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", data.pressure / PRESSURE_SCALE_FACTOR, PRESSURE_THRESHOLD);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    uint8_t buffer[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(45000); // 45 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC8 checksums
        if (!validate_crc8(buffer, 2) || !validate_crc8(buffer + 3, 2) || !validate_crc8(buffer + 6, 2)) {
            fprintf(stderr, "CRC8 checksum mismatch, discarding data\n");
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(buffer);

        // Log data
        log_data(sensor_data);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

