#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// Constants
#define I2C_SLAVE_ADDR 0x4A
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMPERATURE_REG 0x00
#define TEMPERATURE_SCALE 0.0625
#define HYSTERESIS_HIGH 28.0
#define HYSTERESIS_LOW 27.0
#define I2C_RETRY_COUNT 3

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_temperature(int fd, float *temperature);
int gpio_set_output(int value);
void signal_handler(int sig);
int setup_gpio();
int setup_i2c();
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// I2C read temperature function
int i2c_read_temperature(int fd, float *temperature) {
    uint8_t data[2];
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = read(fd, data, 2);
        if (result == 2) {
            // Combine MSB and LSB, right-shift by 4 bits
