#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_MASK 0xFFFF
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define PRESSURE_SCALE_FACTOR 500.0 //Pa
#define TEMPERATURE_SCALE_FACTOR 200.0 //degC
#define MEASUREMENT_DELAY_MS 45

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int command);
int read_sensor_data(uint8_t *data, int count);
uint8_t calculate_crc8(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *raw_data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(int command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Process raw sensor data
sensor_data_t process_sensor_data(const uint8_t *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
    int16_t scale_factor = (raw_data[6] << 8) | raw_data[7];

    // CRC validation
    uint8_t pressure_crc = calculate_crc8(&raw_data[0], 2);
    uint8_t temperature_crc = calculate_crc8(&raw_data[3], 2);

    if (pressure_crc != raw_data[2]) {
        fprintf(stderr, "Pressure CRC validation failed!\n");
        data.differential_pressure = 0.0; // Indicate error
    } else if (temperature_crc != raw_data[5]) {
        fprintf(stderr, "Temperature CRC validation failed!\n");
        data.temperature = 0.0; // Indicate error
    } else {
        // Data conversion
        data.differential_pressure = (float)raw_pressure / scale_factor * PRESSURE_SCALE_FACTOR;
        data.temperature = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;
    }

    return data;
}

// Log data to file
void log_data(sensor_data_t data) {
    FILE *fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f Pa, %.2f degC\n", timestamp, data.differential_pressure, data.temperature);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Send continuous measurement command
    if (send_command(CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        cleanup();
        return 1;
    }

    uint8_t raw_data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(raw_data, 9) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(raw_data);

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

