#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_RH_NOHOLD 0xF5
#define MEASURE_TEMP_NOHOLD 0xF3
#define READ_TEMP_LAST_RH 0xE0
#define TEMP_SCALE 175.72
#define TEMP_OFFSET -46.85
#define HUMID_SCALE 125.0
#define HUMID_OFFSET -6.0
#define SAMPLE_INTERVAL 60 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char command, unsigned char *data, int len);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(unsigned char command, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, &command, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (command == MEASURE_TEMP_NOHOLD || command == MEASURE_RH_NOHOLD) {
            gpioDelay(20000); // Wait 20 ms
        }

        result = i2cReadDevice(i2c_handle, (char *)data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return TEMP_SCALE * raw_temp / 65536.0 + TEMP_OFFSET;
}

// Convert raw humidity to percentage
float convert_humidity(unsigned int raw_humidity) {
    float humidity = HUMID_SCALE * raw_humidity / 65536.0 + HUMID_OFFSET;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Log data to file and stdout
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    // Log to file
    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(fp);
