int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure HDC1080 sensor
int configure_hdc1080(int handle) {
    // Configure for 14-bit temperature and humidity resolution
    if (i2cWriteByteData(handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to config register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1080
int read_hdc1080(int handle, float *temperature, float *humidity) {
    unsigned char buffer[4];

    // Write pointer to measurement register
    if (i2cWriteByte(handle, MEASUREMENT_REG) < 0) {
        fprintf(stderr, "Failed to write to measurement register\n");
        return -1;
    }

    // Wait for conversion (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read 4 bytes of data
    if (i2cReadDevice(handle, buffer, 4) != 4) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned int raw_temp = (buffer[0] << 8) | buffer[1];
    unsigned int raw_humidity = (buffer[2] << 8) | buffer[3];

