void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, HDC1080_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Configure HDC1080
    if (configure_hdc1080(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            // Log data
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

