#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD 0x2C
#define HIGH_REPEATABILITY 0xE0
#define DATA_BYTES 3
#define CRC_POLYNOMIAL 0x31

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    keep_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

float convert_to_celsius(uint16_t raw_ticks) {
    return -45.0 + 175.0 * raw_ticks / 65535.0;
}

int main() {
    struct timespec sleep_time = {5, 0}; // 5 seconds
    uint8_t write_buffer[2] = {MEASURE_CMD, HIGH_REPEATABILITY};
    uint8_t read_buffer[DATA_BYTES];
    uint16_t raw_ticks;
    uint8_t crc;
    float temperature;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char log_message[100];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        // Send measurement command
        if (write(i2c_fd, write_buffer, sizeof(write_buffer)) != sizeof(write_buffer)) {
            perror("Error writing to I2C device");
            continue; // Continue to the next iteration
        }

        // Wait for conversion (10 ms)
        struct timespec delay = {0, 10000000}; // 10 ms
        nanosleep(&delay, NULL);

        // Read data
        if (read(i2c_fd, read_buffer, DATA_BYTES) != DATA_BYTES) {
            perror("Error reading from I2C device");
            continue; // Continue to the next iteration
        }

        // Extract raw temperature data
        raw_ticks = (read_buffer[0] << 8) | read_buffer[1];

        // Extract CRC8
        crc = read_buffer[2];

        // CRC validation
        if (crc8(read_buffer, DATA_BYTES - 1) != crc) {
            fprintf(stderr, "CRC mismatch!\n");
            continue; // Continue to the next iteration
        }

        // Convert to Celsius
        temperature = convert_to_celsius(raw_ticks);

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        snprintf(log_message, sizeof(log_message), "%s Temperature: %.2f °C\n", timestamp, temperature);
        fprintf(log_file, "%s", log_message);
        fflush(log_file); // Ensure data is written to file immediately

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

