#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <pthread.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define READ_MEASUREMENT 0xE000
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define BUFFER_SIZE 100
#define LOGGING_INTERVAL 60 // seconds
#define CSV_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
circular_buffer_t data_buffer;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_i2c(int handle, unsigned char *data, int count);
int read_i2c(int handle, unsigned char *data, int count);
int crc8(const unsigned char *data, int len);
int start_periodic_measurement(int handle);
int read_measurement(int handle, int *co2, float *temperature, float *humidity);
int stop_periodic_measurement(int handle);
int init_circular_buffer(circular_buffer_t *cb);
int add_to_circular_buffer(circular_buffer_t *cb, sensor_data_t data);
int get_from_circular_buffer(circular_buffer_t *cb, sensor_data_t *data);
void *logging_thread(void *arg);
void signal_handler(int signal);
void log_error(const char *message);
void cleanup();

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return i2c_handle;
}

// Function to write data to the I2C bus
int write_i2c(int handle, unsigned char *data, int count) {
    int result = i2cWriteDevice(handle, (char *)data, count);
    if (result != count) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C bus
int read_i2c(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to start periodic measurement
int start_periodic_measurement(int handle) {
    unsigned char data[2];
    data[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    data[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    if (write_i2c(handle, data, 2) != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    return 0;
}

// Function to read measurement data
int read_measurement(int handle, int *co2, float *temperature, float *humidity) {
    unsigned char data[9];
    unsigned char command[2];
    command[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    command[1] = READ_MEASUREMENT & 0xFF;

    if (write_i2c(handle, command, 2) != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Wait 1 ms

    if (read_i2c(handle, data, 9) != 0) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        log_error("CRC validation failed");
        return -1;
    }

    // Data conversion
    *co2 = (data[0] << 8) | data[1];
    *temperature = -45 + 175 * ((float)((data[3] << 8) | data[4])) / 65535.0;
    *humidity = 100 * ((float)((data[6] << 8) | data[7])) / 65535.0;

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement(int handle) {
    unsigned char data[2];
    data[0] = (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    data[1] = STOP_PERIODIC_MEASUREMENT & 0xFF;

    if (write_i2c(handle, data, 2) != 0) {
        log_error("Failed to send stop periodic measurement command");
        return -1;
    }
    return 0;
}

// Function to initialize the circular buffer
int init_circular_buffer(circular_buffer_t *cb) {
    if (pthread_mutex_init(&cb->mutex, NULL) != 0) {
        log_error("Mutex initialization failed");
        return -1;
    }
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    return 0;
}

// Function to add data to the circular buffer
int add_to_circular_buffer(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

// Function to get data from the circular buffer
int get_from_circular_buffer(circular_buffer_t *cb, sensor_data_t *data) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return -1; // Buffer is empty
    }
    *data = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    cb->count--;
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

// Logging thread function
void *logging_thread(void *arg) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    char filename[100];
    FILE *fp;
    sensor_data_t data;

    while (running) {
        sleep(LOGGING_INTERVAL);

        // Create directory if it doesn't exist
        struct stat st = {0};
        if (stat(CSV_DIR, &st) == -1) {
            mkdir(CSV_DIR, 0777);
        }

        // Create filename with timestamp
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
        snprintf(filename, sizeof(filename), "%s/scd40_data_%s.csv", CSV_DIR, timestamp);

        // Open file for writing
        fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Failed to open CSV file for writing");
            continue; // Try again next interval
        }

        // Write header row
        fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");

        // Write data from circular buffer to file
        while (get_from_circular_buffer(&data_buffer, &data) == 0) {
            timeinfo = localtime(&data.timestamp);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(fp, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
        }

        // Close file
        fclose(fp);
    }
    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Shutting down...\n");
        running = 0;
    }
}

// Error logging function
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    // Stop periodic measurement
    if (i2c_handle >= 0) {
        stop_periodic_measurement(i2c_handle);
    }

    // Close I2C bus
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Destroy mutex
    pthread_mutex_destroy(&data_buffer.mutex);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    int co2, ret;
    float temperature, humidity;
    sensor_data_t data;
    pthread_t logging_thread_id;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() < 0) {
        cleanup();
        return 1;
    }
    i2c_handle = i2c_handle; // Store the handle for later use

    // Initialize circular buffer
    if (init_circular_buffer(&data_buffer) != 0) {
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Create logging thread
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        ret = read_measurement(i2c_handle, &co2, &temperature, &humidity);
        if (ret == 0) {
            // Data validation
            if (co2 >= 400 && co2 <= 5000 && temperature >= -40 && temperature <= 125 && humidity >= 0 && humidity <= 100) {
                data.timestamp = time(NULL);
                data.co2 = co2;
                data.temperature = temperature;
                data.humidity = humidity;
                add_to_circular_buffer(&data_buffer, data);
            } else {
                log_error("Invalid sensor data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(5);
    }

    // Wait for logging thread to finish
    pthread_join(logging_thread_id, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

