#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_DATA_START 0x05
#define MEASURE_REG 0x00
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
double c0, c1, c2, c3;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int verify_sensor_identity();
int read_calibration_data();
int trigger_measurement();
int read_sensor_data(unsigned char *data);
double convert_pressure(unsigned char *data);
double convert_temperature(unsigned char *data);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, double pressure, double temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor_identity() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02x\n", who_am_i);
        return -1;
    }
    printf("Sensor identity verified successfully\n");
    return 0;
}

// Read calibration data
int read_calibration_data() {
    char buf[4];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_DATA_START, buf, 4) != 4) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }
    c0 = (double)((unsigned char)buf[0] << 8 | (unsigned char)buf[1]) / 100.0;
    c1 = (double)((unsigned char)buf[2] << 8 | (unsigned char)buf[3]) / 100.0;

    if (i2cReadI2CBlockData(i2c_handle, CALIB_DATA_START + 4, buf, 4) != 4) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }
    c2 = (double)((unsigned char)buf[0] << 8 | (unsigned char)buf[1]) / 100.0;
    c3 = (double)((unsigned char)buf[2] << 8 | (unsigned char)buf[3]) / 100.0;

    printf("Calibration data read successfully\n");
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    if (i2cWriteByteData(i2c_handle, MEASURE_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    if (i2cReadI2CBlockData(i2c_handle, MEASURE_REG, (char *)data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    return 0;
}

// Convert pressure to hPa
double convert_pressure(unsigned char *data) {
