    if (i2c_write_byte(fd, 0xF9, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0xFA, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0xFB, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0xFC, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0xFD, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0xFE, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, 0xFF, 0x00) != 0) return -1;

    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert pressure to Pascals
float convert_pressure(uint32_t raw_pressure) {
    return c0 + c1 * raw_pressure + c2 * raw_pressure * raw_pressure + c3 * raw_pressure * raw_pressure * raw_pressure;
}

// Convert temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return 25.0f + raw_temperature / 100.0f;
}

// Blink LED function
void blink_led(int gpio_fd, int gpio_line_num, float blink_rate, int duration_ms) {
    struct gpiod_line_request_config config;
    struct timespec on_time, off_time;
    int on_ns, off_ns;

    // Calculate on/off times
    on_ns = (int)(1000000000.0f / blink_rate);
    off_ns = (int)(1000000000.0f / blink_rate);

    on_time.tv_sec = on_ns / 1000000000;
    on_time.tv_nsec = on_ns % 1000000000;
    off_time.tv_sec = off_ns / 1000000000;
    off_time.tv_nsec = off_ns % 1000000000;

    // Request the GPIO line
    memset(&config, 0, sizeof(config));
    config.consumer = GPIO_CONSUMER;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        return;
    }

    // Blink the LED
    for (int i = 0; i < duration_ms / (on_time.tv_nsec / 1000000 + off_time.tv_nsec / 1000000); i++) {
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Failed to set GPIO line value (on)");
        }
        nanosleep(&on_time, NULL);

        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Failed to set GPIO line value (off)");
        }
        nanosleep(&off_time, NULL);
    }

    // Release the GPIO line
    if (gpiod_line_release(gpio_line) < 0) {
        perror("Failed to release GPIO line");
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint8_t sensor_data[6];
    uint32_t raw_pressure;
    uint16_t raw_temperature;
    float pressure, temperature;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request the GPIO line
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = GPIO_CONSUMER;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        // Wait for measurement to complete
        usleep(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Verify CRC
        if (calculate_crc(sensor_data, 2) != sensor_data[2]) {
            fprintf(stderr, "CRC check failed for pressure\n");
            break;
        }
        if (calculate_crc(sensor_data + 3, 2) != sensor_data[5]) {
            fprintf(stderr, "CRC check failed for temperature\n");
            break;
        }

        // Extract raw data
        raw_pressure = ((uint32_t)sensor_data[0] << 16) | ((uint32_t)sensor_data[1] << 8) | sensor_data[2];
        raw_pressure = raw_pressure >> 4;
        raw_temperature = ((uint16_t)sensor_data[3] << 8) | sensor_data[4];

        // Convert data
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Check pressure threshold
        if (pressure < PRESSURE_THRESHOLD) {
            blink_led(gpio_fd, GPIO_LINE, WARNING_BLINK_RATE, WARNING_BLINK_DURATION);
        } else {
            blink_led(gpio_fd, GPIO_LINE, NORMAL_BLINK_RATE, NORMAL_BLINK_DURATION);
        }

        // Print data
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

