            perror("Failed to set GPIO line value (off)");
        }
        nanosleep(&off_time, NULL);
    }

    // Release the GPIO line
    if (gpiod_line_release(gpio_line) < 0) {
        perror("Failed to release GPIO line");
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint8_t sensor_data[6];
    uint32_t raw_pressure;
    uint16_t raw_temperature;
    float pressure, temperature;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request the GPIO line
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = GPIO_CONSUMER;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        // Wait for measurement to complete
        usleep(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Verify CRC
        if (calculate_crc(sensor_data, 2) != sensor_data[2]) {
            fprintf(stderr, "CRC check failed for pressure\n");
            break;
        }
        if (calculate_crc(sensor_data + 3, 2) != sensor_data[5]) {
            fprintf(stderr, "CRC check failed for temperature\n");
            break;
        }

        // Extract raw data
        raw_pressure = ((uint32_t)sensor_data[0] << 16) | ((uint32_t)sensor_data[1] << 8) | sensor_data[2];
        raw_pressure = raw_pressure >> 4;
        raw_temperature = ((uint16_t)sensor_data[3] << 8) | sensor_data[4];

        // Convert data
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Check pressure threshold
        if (pressure < PRESSURE_THRESHOLD) {
            blink_led(gpio_fd, GPIO_LINE, WARNING_BLINK_RATE, WARNING_BLINK_DURATION);
        } else {
            blink_led(gpio_fd, GPIO_LINE, NORMAL_BLINK_RATE, NORMAL_BLINK_DURATION);
        }

        // Print data
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

