// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 30.0
#define TEMP_THRESHOLD_OFF 28.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mlx90614(int handle, float *ambient_temp, float *object_temp);
float convert_to_celsius(unsigned int raw_temp);
void control_fan(int gpio, int state);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read temperature data from MLX90614
int read_mlx90614(int handle, float *ambient_temp, float *object_temp) {
    int retries = 3;
    int result;
    unsigned int raw_ambient, raw_object;

    while (retries > 0) {
        result = i2cReadWordData(handle, AMBIENT_TEMP_REG);
        if (result >= 0) {
            raw_ambient = (unsigned int)result;
            break;
        } else {
            fprintf(stderr, "Error reading ambient temperature: %d. Retrying...\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ambient temperature after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        result = i2cReadWordData(handle, OBJECT_TEMP_REG);
        if (result >= 0) {
            raw_object = (unsigned int)result;
            break;
        } else {
            fprintf(stderr, "Error reading object temperature: %d. Retrying...\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read object temperature after multiple retries.\n");
        return -1;
    }

    *ambient_temp = convert_to_celsius(raw_ambient);
    *object_temp = convert_to_celsius(raw_object);

    return 0;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(unsigned int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Function to control the cooling fan
void control_fan(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *fp = fopen(LOG_FILE, "a");

    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f °C, Object: %.2f °C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_temp, object_temp);

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float ambient_temp, object_temp;
    int fan_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_mlx90614(i2c_handle, &ambient_temp, &object_temp) == 0) {
            printf("Ambient: %.2f °C, Object: %.2f °C\n", ambient_temp, object_temp);

            // Hysteresis control for fan
            if (object_temp > TEMP_THRESHOLD_ON && fan_state == 0) {
                control_fan(FAN_GPIO, 1);
                fan_state = 1;
                printf("Fan turned ON\n");
            } else if (object_temp < TEMP_THRESHOLD_OFF && fan_state == 1) {
                control_fan(FAN_GPIO, 0);
                fan_state = 0;
                printf("Fan turned OFF\n");
            }

            log_temperature(ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature data.\n");
        }

        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_fan(FAN_GPIO, 0); // Turn off fan on exit
    gpioTerminate();

    return 0;
}

