#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SERVER_PORT 8080

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    char buf[6];
    int raw_temperature, raw_humidity;
    int result;

    result = i2cWriteByteData(i2c_handle, MEASURE_CMD, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    raw_humidity = (buf[3] << 8) | buf[4];

    *temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    float temperature, humidity;
    int opt = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    while (!terminate) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening even if accept fails
        }

        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            snprintf(buffer, sizeof(buffer), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>Temperature: %.2f &deg;C</h1><h1>Humidity: %.2f %%</h1></body></html>", temperature, humidity);
        } else {
            snprintf(buffer, sizeof(buffer), "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>Error</title></head><body><h1>Failed to read sensor data</h1></body></html>");
        }

        send(new_socket, buffer, strlen(buffer), 0);
        close(new_socket);
    }

    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Server terminated.\n");
    return 0;
}

