#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read temperature and humidity from HDC2010
int read_hdc2010(float *temperature, float *humidity)
{
    int retries = 3;
    int status;
    unsigned short raw_temperature, raw_humidity;

    // Trigger one-shot measurement
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, 0x01);
        if (status >= 0) break; // Success
        gpioDelay(1000); // Wait 1ms before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to trigger measurement after multiple retries.\n");
        return -1;
    }

    // Wait for measurement to complete (bit 0 of MEASUREMENT_CONFIG_REG is cleared)
    retries = 50; // Timeout after 50 attempts (500ms)
    while (retries > 0) {
        int config_value = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG_REG);
        if (config_value < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG_REG during wait.\n");
            return -1;
        }
        if ((config_value & 0x01) == 0) break; // Measurement complete
        gpioDelay(10000); // Wait 10ms before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Measurement timeout.\n");
        return -1;
    }

    // Read temperature and humidity registers
    retries = 3;
    while (retries > 0) {
        raw_temperature = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temperature >= 0) break; // Success
        gpioDelay(1000); // Wait 1ms before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read temperature after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
        if (raw_humidity >= 0) break; // Success
        gpioDelay(1000); // Wait 1ms before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read humidity after multiple retries.\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

int main()
{
    float temperature, humidity;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        if (read_hdc2010(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

