#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define PRESSURE_DATA_LENGTH 2
#define TEMPERATURE_DATA_LENGTH 2
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 45

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_command(int handle, unsigned short command);
int read_data(int handle, char *buffer, int count);
unsigned char calculate_crc8(const char *data, int length);
void log_data(int pressure, int temperature);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char calculate_crc8(const char *data, int length) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to the console
void log_data(int pressure, int temperature) {
    printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[6];
        // Read data from the sensor
        if (read_data(i2c_handle, buffer, 6) == 0) {
            // CRC validation
            if (calculate_crc8(buffer, PRESSURE_DATA_LENGTH) == buffer[PRESSURE_DATA_LENGTH]) {
                if (calculate_crc8(buffer + 3, TEMPERATURE_DATA_LENGTH) == buffer[3 + TEMPERATURE_DATA_LENGTH]) {
                    // Extract pressure and temperature values
                    int pressure = (buffer[0] << 8) | buffer[1];
                    int temperature = (buffer[3] << 8) | buffer[4];

                    // Log the data
                    log_data(pressure, temperature);
                } else {
                    fprintf(stderr, "Temperature CRC check failed\n");
                }
            } else {
                fprintf(stderr, "Pressure CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

