int initialize_gpio(int gpio_chip_num, int gpio_line_num);
int initialize_spi(int spi_channel, int spi_speed);
void cleanup();

// Function to read temperature from MAX6675
int read_thermocouple(int spi_handle, double *temperature) {
    unsigned char data[2];
    int result;

    result = spiXfer(spi_handle, data, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Check for fault conditions
    if (data[0] & 0x04) {
        fprintf(stderr, "Error: Thermocouple open circuit\n");
        return -1;
    }
    if (data[0] & 0x02) {
        fprintf(stderr, "Error: Thermocouple shorted to GND\n");
        return -1;
    }
    if (data[0] & 0x01) {
        fprintf(stderr, "Error: Thermocouple shorted to VCC\n");
        return -1;
    }

    // Extract temperature data (bits 3-14)
    int raw_temp = ((data[0] << 8) | data[1]) >> 4;
    *temperature = (double)raw_temp * 0.25;

    return 0;
}

// Function to read target temperature profile from file
int read_profile(const char time_filename, double profile[], int *num_points) {
    FILE *fp = fopen(time_filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open profile file %s\n", time_filename);
        return -1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL && i < MAX_PROFILE_LENGTH) {
        if (sscanf(line, "%lf,%lf", &profile[i], &profile[i + MAX_PROFILE_LENGTH]) == 2) {
            i++;
        } else {
            fprintf(stderr, "Warning: Invalid line in profile file, skipping\n");
        }
    }

    fclose(fp);
    *num_points = i;
    return 0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, PIDState *pid_state) {
    double error = setpoint - actual_temperature;
    pid_state->integral += error;
    double derivative = error - pid_state->previous_error;
    double output = KP * error + KI * pid_state->integral + KD * derivative;
    pid_state->previous_error = error;

    // Clamp output to 0.0 - 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to control the solid-state relay
int control_relay(int gpio_chip_num, int gpio_line_num, double duty_cycle) {
    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, gpio_line_num);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_line_num);
        return -1;
    }

    int ret = gpiod_line_request_output(line, "reflow", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line as output: %s\n", strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    // Set the duty cycle
    if (duty_cycle > 0.0) {
        ret = gpiod_line_set_value(line, 1); // HIGH
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line value: %s\n", strerror(-ret));
            gpiod_line_release(line);
            return -1;
        }
    } else {
        ret = gpiod_line_set_value(line, 0); // LOW
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line value: %s\n", strerror(-ret));
            gpiod_line_release(line);
            return -1;
        }
    }

    gpiod_line_release(line);
    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, double temperature, double target_temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, target_temperature, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to initialize GPIO
int initialize_gpio(int gpio_chip_num, int gpio_line_num) {
    gpio_chip = gpiod_chip_open_by_number(gpio_chip_num);
    if (!gpio_chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %d\n", gpio_chip_num);
