        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_line_num);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize SPI
int initialize_spi(int spi_channel, int spi_speed) {
    spi_handle = spiOpen(spi_channel, spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d: %d\n", spi_channel, spi_handle);
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (gpio_chip) {
        if (relay_line) {
            gpiod_line_release(relay_line);
        }
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    double profile[MAX_PROFILE_LENGTH * 2]; // Time (s), Temperature (C)
    int num_profile_points = 0;
    double current_temperature, target_temperature, duty_cycle;
    PIDState pid_state = {0.0, 0.0};
    time_t start_time, current_time;
    double elapsed_time;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(0, RELAY_GPIO) != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(SPI_CHANNEL, SPI_SPEED) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Temperature,Target Temperature,Duty Cycle\n");

    // Read target temperature profile
    if (read_profile(TARGET_PROFILE, profile, &num_profile_points) != 0) {
        cleanup();
        return 1;
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time(&start_time);
    i = 0;

    printf("Reflow oven started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature
        if (read_thermocouple(spi_handle, &current_temperature) != 0) {
            fprintf(stderr, "Error: Failed to read temperature\n");
            break; // Exit loop on error
        }

        // Check for sensor failure
        if (current_temperature < -50.0 || current_temperature > 150.0) {
            fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", current_temperature);
            break; // Exit loop on invalid reading
        }

        // Calculate elapsed time
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        // Check if we've reached the end of the profile
        if (i >= num_profile_points) {
            fprintf(stderr, "Profile complete. Exiting.\n");
            break;
        }

        // Get target temperature from profile
        target_temperature = profile[i * 2 + 1];

        // Calculate PID output
        duty_cycle = calculate_pid(target_temperature, current_temperature, &pid_state);

        // Control relay
        if (control_relay(0, RELAY_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to control relay\n");
            break; // Exit loop on error
        }

        // Log data
        log_data(log_file, current_temperature, target_temperature, duty_cycle);

        // Update profile index based on elapsed time
        while (i < num_profile_points && profile[i * 2] <= elapsed_time) {
            i++;
        }

        // Check for maximum temperature
        if (current_temperature > MAX_TEMPERATURE) {
            fprintf(stderr, "Error: Maximum temperature exceeded (%.2f > %.2f)\n", current_temperature, MAX_TEMPERATURE);
            break; // Exit loop on temperature limit
        }

        // Check for maximum simulation time
        if (elapsed_time > MAX_TIME) {
            fprintf(stderr, "Error: Maximum simulation time exceeded (%.2f > %d)\n", elapsed_time, MAX_TIME);
            break; // Exit loop on time limit
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

