#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define W1_DEVICES_PATH "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_CHIP "gpiochip0"
#define HEATER_GPIO 18
#define PWM_GPIO 18
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000 // 1ms
#define LOG_FILE "greenhouse.log"
#define SENSOR_READ_INTERVAL_SEC 5

// Global variables
static volatile sig_atomic_t keep_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static struct gpiod_line_request_config pwm_config;
static int pwm_fd = -1;
static double setpoint_temperature = 25.0; // Default setpoint
static double Kp = 1.0; // Default Kp
static double Ki = 0.1; // Default Ki
static double Kd = 0.01; // Default Kd

// Function prototypes
double read_temperature(const char *sensor_id);
int validate_crc(const char *data);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
int control_heater(double pid_output);
int log_data(double average_temperature, double setpoint, double pid_output, double pwm_duty_cycle);
void signal_handler(int sig);
int setup_gpio();
int cleanup_gpio();
int setup_logging();
int cleanup_logging();

// Function to read temperature from a DS18B20 sensor
double read_temperature(const char *sensor_id) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_PATH, sensor_id, W1_SLAVE_FILE);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Failed to open w1_slave file");
        return NAN; // Not a Number
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error reading from w1_slave file\n");
        return NAN;
    }

    fclose(fp);

    if (validate_crc(line1)) {
        char *temp_str = strstr(line1, "t=");
        if (temp_str != NULL) {
            long temperature_raw = strtol(temp_str + 2, NULL, 10);
            return (double)temperature_raw / 1000.0;
        } else {
            fprintf(stderr, "Temperature data not found in w1_slave output\n");
            return NAN;
        }
    } else {
        fprintf(stderr, "CRC check failed\n");
        return NAN;
    }
}

// Function to validate CRC checksum
int validate_crc(const char *data) {
    int crc = 0;
    int byte;
    int i;

    for (i = 0; i < 15; i++) {
        byte = (int)data[i];
        crc = (crc ^ byte) & 0xFF;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc = (crc << 1);
            }
        }
    }
    byte = (int)data[15];
    crc = (crc ^ byte) & 0xFF;
    if (crc != 0) {
        return 0; // CRC check failed
    }
    return 1; // CRC check passed
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to control the heater using PWM
int control_heater(double pid_output) {
    // Clamp PID output to 0-100 range
    if (pid_output < 0) pid_output = 0;
    if (pid_output > 100) pid_output = 100;

    // Calculate PWM duty cycle (0-100%)
    double duty_cycle = pid_output;

    // Calculate PWM value (0-255)
    int pwm_value = (int)(duty_cycle * 255.0 / 100.0);

    // Set PWM value
    if (pwm_fd != -1) {
        if (ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, pwm_value) < 0) {
            perror("Failed to set PWM duty cycle");
            return -1;
        }
    } else {
        fprintf(stderr, "PWM file descriptor is invalid\n");
        return -1;
    }

    return 0;
}

