            return NAN;
        }
    } else {
        fprintf(stderr, "CRC check failed\n");
        return NAN;
    }
}

// Function to validate CRC checksum
int validate_crc(const char *data) {
    int crc = 0;
    int byte;
    int i;

    for (i = 0; i < 15; i++) {
        byte = (int)data[i];
        crc = (crc ^ byte) & 0xFF;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc = (crc << 1);
            }
        }
    }
    byte = (int)data[15];
    crc = (crc ^ byte) & 0xFF;
    if (crc != 0) {
        return 0; // CRC check failed
    }
    return 1; // CRC check passed
}

