#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define POLL_INTERVAL_S 5
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_aht20();
int read_aht20_data(float *humidity, float *temperature);
void control_dehumidifier(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// AHT20 initialization function
int initialize_aht20() {
    char init_cmd[] = {0xBE, 0x08, 0x00};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, init_cmd, 3);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (init), retry %d: %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "I2C write failed (init) after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 data reading function
int read_aht20_data(float *humidity, float *temperature) {
    char trigger_cmd[] = {0xAC, 0x33, 0x00};
    char data[6];
    int retries = 0;
    int result;

    // Trigger measurement
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "I2C write failed (trigger), retry %d: %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_US);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "I2C write failed (trigger) after %d retries\n", MAX_RETRIES);
        return -1; // Failure
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result == 6) {
            break; // Success
        } else {
            fprintf(stderr, "I2C read failed, retry %d: %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_US);
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
        return -1; // Failure
    }

    // Check status bit (bit 7 of byte 0)
    if ((data[0] & 0x80) != 0) {
        fprintf(stderr, "Sensor busy or not calibrated\n");
        return -1; // Sensor busy or not calibrated
    }

    // Convert data
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    uint32_t temperature_raw = ((uint32_t)data[3] & 0x0F) << 16 | ((uint32_t)data[4] << 8) | data[5];

    *humidity = ((float)humidity_raw / 0x100000) * 100;
    *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

    return 0; // Success
}

// Dehumidifier control function
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    }
}

// Data logging function
void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Humidity: %.2f%%, Temperature: %.2f°C\n", timestamp, humidity, temperature);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off initially

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (initialize_aht20() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity, temperature;

    // Main loop
    while (!terminate) {
        if (read_aht20_data(&humidity, &temperature) == 0) {
            log_data(humidity, temperature);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read AHT20 data\n");
        }

        gpioDelay(POLL_INTERVAL_S * 1000000); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

