#define API_ENDPOINT "http://api.example.com/humidity"
#define LOG_FILE "/var/log/humidity_monitor.log"
#define RETRY_COUNT 3
#define RETRY_DELAY 5 // seconds

// HTU21D Commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMD_MEASURE 0xE5

// Global variables
int i2c_fd = -1;
int socket_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char *data, int len);
int i2c_write_byte(int fd, unsigned char data);
int htu21d_read_temperature(int fd, float *temperature);
int htu21d_read_humidity(int fd, float *humidity);
int post_data(const char *url, const char *data);
void signal_handler(int sig);
int log_message(int priority, const char *message);
int create_socket();
int connect_to_server(int socket_fd, const char *url);
int send_data(int socket_fd, const char *data);
int receive_data(int socket_fd, char *buffer, size_t buffer_size);
int close_socket(int socket_fd);
int cleanup();

// I2C read function
int i2c_read_bytes(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        log_message(LOG_ERR, "I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        log_message(LOG_ERR, "I2C write failed");
        return -1;
    }
    return 0;
}

// HTU21D read temperature function
int htu21d_read_temperature(int fd, float *temperature) {
    unsigned char data[3];
    int raw_temperature;

    if (i2c_write_byte(fd, TRIGGER_TEMP_MEASURE) < 0) {
        log_message(LOG_ERR, "Failed to trigger temperature measurement");
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    if (i2c_read_bytes(fd, data, 3) < 0) {
        log_message(LOG_ERR, "Failed to read temperature data");
        return -1;
    }

    raw_temperature = (data[0] << 8) | data[1];
    *temperature = -46.85 + 175.72 * ((float)raw_temperature / 65536.0);

    return 0;
}

// HTU21D read humidity function
int htu21d_read_humidity(int fd, float *humidity) {
    unsigned char data[3];
    int raw_humidity;

    if (i2c_write_byte(fd, TRIGGER_HUMD_MEASURE) < 0) {
        log_message(LOG_ERR, "Failed to trigger humidity measurement");
        return -1;
    }
    usleep(100000); // Wait for measurement (at least 50ms)

    if (i2c_read_bytes(fd, data, 3) < 0) {
        log_message(LOG_ERR, "Failed to read humidity data");
        return -1;
    }

    raw_humidity = (data[0] << 8) | data[1];
    *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    return 0;
}

// HTTP POST function
int post_data(const char *url, const char *data) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (create_socket() < 0) {
            log_message(LOG_ERR, "Failed to create socket");
            retries--;
            sleep(RETRY_DELAY);
            continue;
        }

        if (connect_to_server(socket_fd, url) < 0) {
            log_message(LOG_ERR, "Failed to connect to server");
            close_socket(socket_fd);
            socket_fd = -1;
            retries--;
            sleep(RETRY_DELAY);
            continue;
        }

        if (send_data(socket_fd, data) < 0) {
            log_message(LOG_ERR, "Failed to send data");
            close_socket(socket_fd);
            socket_fd = -1;
            retries--;
            sleep(RETRY_DELAY);
            continue;
        }

        char buffer[1024];
        if (receive_data(socket_fd, buffer, sizeof(buffer)) < 0) {
            log_message(LOG_ERR, "Failed to receive data");
            close_socket(socket_fd);
            socket_fd = -1;
            retries--;
            sleep(RETRY_DELAY);
            continue;
        }

        close_socket(socket_fd);
        socket_fd = -1;
        log_message(LOG_INFO, "Data posted successfully");
        return 0;
    }

    log_message(LOG_ERR, "Failed to post data after multiple retries");
    return -1;
}

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Logging function
int log_message(int priority, const char *message) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
    return 0;
}

// Create socket function
int create_socket() {
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message(LOG_ERR, "Failed to create socket");
        return -1;
    }
    return 0;
}

// Connect to server function
int connect_to_server(int socket_fd, const char *url) {
    struct sockaddr_in server_addr;
    char hostname[256];
    char *port_str;
    int port;

    // Parse hostname and port from URL
    if (strncmp(url, "http://", 7) == 0) {
        url += 7; // Remove "http://"
    }
    strncpy(hostname, url, sizeof(hostname) - 1);
    hostname[sizeof(hostname) - 1] = '\0'; // Ensure null termination
    port_str = strchr(hostname, ':');
    if (port_str == NULL) {
        port = 80; // Default port
    } else {
        *port_str = '\0'; // Null-terminate hostname
        port_str++;       // Point to port number
        port = atoi(port_str);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, hostname, &server_addr.sin_addr) <= 0) {
        log_message(LOG_ERR, "Invalid address/ Address not supported");
        return -1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message(LOG_ERR, "Failed to connect to server");
        return -1;
    }

    return 0;
}

// Send data function
int send_data(int socket_fd, const char *data) {
    char request[2048];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             API_ENDPOINT, API_ENDPOINT, strlen(data), data);

    if (send(socket_fd, request, strlen(request), 0) < 0) {
        log_message(LOG_ERR, "Failed to send data");
        return -1;
    }

    return 0;
}

// Receive data function
int receive_data(int socket_fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_received = recv(socket_fd, buffer, buffer_size - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "Failed to receive data");
        return -1;
    }
    buffer[bytes_received] = '\0';
    return 0;
}

// Close socket function
int close_socket(int socket_fd) {
    if (socket_fd != -1) {
        close(socket_fd);
    }
    return 0;
}

// Cleanup function
int cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (socket_fd != -1) {
        close_socket(socket_fd);
    }
    closelog();
    return 0;
}

int main() {
    // Initialize syslog
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus");
        cleanup();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        log_message(LOG_ERR, "Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        char json_data[256];

        // Read temperature and humidity
        if (htu21d_read_temperature(i2c_fd, &data.temperature) < 0) {
            log_message(LOG_ERR, "Failed to read temperature");
            data.temperature = -999.0; // Indicate error
        }
        if (htu21d_read_humidity(i2c_fd, &data.humidity) < 0) {
            log_message(LOG_ERR, "Failed to read humidity");
            data.humidity = -999.0; // Indicate error
        }

        // Format data as JSON
        snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"humidity\": %.2f}", data.temperature, data.humidity);

        // Post data to API endpoint
        if (post_data(API_ENDPOINT, json_data) < 0) {
            log_message(LOG_ERR, "Failed to post data");
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

