            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        if (read(fd, buf, len) == len) {
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retries and backoff
int i2c_write_bytes(int fd, uint8_t addr, uint8_t *buf, int len) {
    int retries = 0;
    int delay_ms = BACKOFF_DELAY_MS;

    while (retries < MAX_RETRIES) {
        if (write(fd, buf, len) == len) {
            return 0; // Success
        } else {
