            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 read data function
int aht20_read_data(int fd, uint8_t addr, uint8_t *data) {
    uint8_t cmd[3] = {AHT20_MEASURE_CMD1, AHT20_MEASURE_CMD2, AHT20_MEASURE_CMD3};
    if (i2c_write_bytes(fd, addr, cmd, 3) != 0) {
        fprintf(stderr, "Failed to trigger AHT20 measurement.\n");
        return -1;
    }
    usleep(80 * 1000); // Wait for measurement (80ms)

    if (i2c_read_bytes(fd, addr, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read AHT20 data.\n");
        return -1;
    }

    return 0;
}

