float tmp117_read_temperature(int fd) {
    uint8_t buf[2];
    int16_t raw_temp;

    if (i2c_read_bytes(fd, TMP117_ADDR, TMP117_TEMP_REG, buf, 2) != 0) {
        fprintf(stderr, "Failed to read TMP117 temperature.\n");
        return -1000.0; // Indicate error
    }

    raw_temp = (buf[0] << 8) | buf[1];
    return (float)raw_temp * 0.0078125;
}

// AHT20 read humidity function
float aht20_read_humidity(int fd) {
    uint8_t data[6];
