    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy.\n");
        return -1.0;
    }

    humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
