#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_FORWARD_PIN 23
#define MOTOR_REVERSE_PIN 24

// Define motor run time
#define MOTOR_RUN_TIME 5 // seconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *rain_sensor_line;
struct gpiod_line *motor_enable_line;
struct gpiod_line *motor_forward_line;
struct gpiod_line *motor_reverse_line;

// Function prototypes
int read_rain_sensor(struct gpiod_line *line);
int control_motor(struct gpiod_line *enable_line, struct gpiod_line *forward_line, struct gpiod_line *reverse_line, int run_time);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nCaught signal %d, cleaning up...\n", sig);

        // Stop the motor
        if (motor_enable_line) {
            gpiod_line_set_value(motor_enable_line, 0);
        }

        // Release GPIO lines
        if (rain_sensor_line) {
            gpiod_line_release(rain_sensor_line);
        }
        if (motor_enable_line) {
            gpiod_line_release(motor_enable_line);
        }
        if (motor_forward_line) {
            gpiod_line_release(motor_forward_line);
        }
        if (motor_reverse_line) {
            gpiod_line_release(motor_reverse_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading rain sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the motor
int control_motor(struct gpiod_line *enable_line, struct gpiod_line *forward_line, struct gpiod_line *reverse_line, int run_time) {
    // Enable the motor
    if (gpiod_line_set_value(enable_line, 1) < 0) {
        fprintf(stderr, "Error enabling motor\n");
        return -1;
    }

    // Set motor direction (forward)
    if (gpiod_line_set_value(forward_line, 1) < 0) {
        fprintf(stderr, "Error setting motor forward direction\n");
        return -1;
    }
    if (gpiod_line_set_value(reverse_line, 0) < 0) {
        fprintf(stderr, "Error setting motor reverse direction\n");
        return -1;
    }

    // Run the motor for the specified time
    sleep(run_time);

    // Stop the motor
    if (gpiod_line_set_value(enable_line, 0) < 0) {
        fprintf(stderr, "Error disabling motor\n");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    motor_enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    motor_forward_line = gpiod_chip_get_line(chip, MOTOR_FORWARD_PIN);
    motor_reverse_line = gpiod_chip_get_line(chip, MOTOR_REVERSE_PIN);

    if (!rain_sensor_line || !motor_enable_line || !motor_forward_line || !motor_reverse_line) {
        fprintf(stderr, "Error getting GPIO lines\n");
        if (rain_sensor_line) gpiod_line_release(rain_sensor_line);
        if (motor_enable_line) gpiod_line_release(motor_enable_line);
        if (motor_forward_line) gpiod_line_release(motor_forward_line);
        if (motor_reverse_line) gpiod_line_release(motor_reverse_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        fprintf(stderr, "Error requesting rain sensor line as input\n");
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_forward_line);
        gpiod_line_release(motor_reverse_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(motor_enable_line, "motor_enable", 0) < 0) {
        fprintf(stderr, "Error requesting motor enable line as output\n");
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_forward_line);
        gpiod_line_release(motor_reverse_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(motor_forward_line, "motor_forward", 0) < 0) {
        fprintf(stderr, "Error requesting motor forward line as output\n");
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_forward_line);
        gpiod_line_release(motor_reverse_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(motor_reverse_line, "motor_reverse", 0) < 0) {
        fprintf(stderr, "Error requesting motor reverse line as output\n");
        gpiod_line_release(rain_sensor_line);
        gpiod_line_release(motor_enable_line);
        gpiod_line_release(motor_forward_line);
        gpiod_line_release(motor_reverse_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read rain sensor
        int rain_detected = read_rain_sensor(rain_sensor_line);
        if (rain_detected < 0) {
            fprintf(stderr, "Error reading rain sensor, exiting\n");
            break;
        }

        // If rain is detected, close the window
        if (rain_detected == 0) {
            printf("Rain detected! Closing window...\n");
            if (control_motor(motor_enable_line, motor_forward_line, motor_reverse_line, MOTOR_RUN_TIME) < 0) {
                fprintf(stderr, "Error controlling motor, exiting\n");
                break;
            }
            printf("Window closed.\n");
        }

        // Wait 2 seconds
        sleep(2);
    }

    // Cleanup (in case the loop breaks)
    gpiod_line_release(rain_sensor_line);
    gpiod_line_release(motor_enable_line);
    gpiod_line_release(motor_forward_line);
    gpiod_line_release(motor_reverse_line);
    gpiod_chip_close(chip);

    return 0;
}

