// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU load from /proc/stat
float read_cpu_load()
{
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0, prev_idle_total = 0;
    float load;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat\n");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle_total - prev_idle_total;

    load = (float)(total_diff - idle_diff) / total_diff;

    prev_total = total;
    prev_idle_total = idle_total;

    return load;
}

// Function to map CPU load to RGB values
void map_load_to_rgb(float load, int *red, int *green, int *blue)
{
    if (load <= 0.5) {
        // Green to Yellow gradient
        *red = 0;
        *green = (int)(255 * (load / 0.5));
        *blue = 0;
    } else {
        // Yellow to Red gradient
        *red = (int)(255 * ((load - 0.5) / 0.5));
        *green = 255;
        *blue = 0;
    }
}

// Function to set RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, green, blue;
    float load;

    // Main loop
    while (!terminate) {
        // Read CPU load
        load = read_cpu_load();
        if (load < 0) {
            fprintf(stderr, "Error reading CPU load, using previous value.\n");
            // Consider a default value or previous value here
            load = 0.0; // Or some other sensible default
        }

        // Map load to RGB values
        map_load_to_rgb(load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

