// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_START 0x88
#define BMP280_REG_CALIB_END 0xA1
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA_START 0xF7

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
int udp_socket;
struct sockaddr_in server_addr;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int handle, bmp280_calib_data *calib) {
    uint8_t buffer[26];
    int result = i2cReadI2CBlockData(handle, BMP280_REG_CALIB_START, (char *)buffer, 26);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calib->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int read_raw_data(int handle, int32_t *raw_temperature, int32_t *raw_pressure) {
    uint8_t buffer[6];
    int result = i2cReadI2CBlockData(handle, BMP280_REG_DATA_START, (char *)buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *raw_pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *raw_temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, p;
    double t_fine = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2) + ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// Function to format data as a JSON string
char* format_json(double temperature, double pressure) {
    char *json_string = malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Function to send data over UDP
int send_udp_data(int socket, const char *data, const char *ip_address, int port) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        return -1;
    }

    if (sendto(socket, data, strlen(data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP data: %d\n", socket);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    int chip_id = read_register(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id < 0 || chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP280 chip ID: 0x%02X\n", chip_id);

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set forced mode
    if (write_register(i2c_handle, BMP280_REG_CTRL_MEAS, 0b00100011) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read raw data
        int32_t raw_temperature, raw_pressure;
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Compensate temperature and pressure
        double temperature = compensate_temperature(raw_temperature, calib);
        double pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

        // Format data as JSON
        char *json_string = format_json(temperature, pressure);
        if (json_string == NULL) {
            fprintf(stderr, "Error formatting JSON data\n");
            sleep(1);
            continue;
