        fprintf(stderr, "Error: Invalid chip ID: 0x%02X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP280 chip ID: 0x%02X\n", chip_id);

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

