            sleep(1);
            continue;
        }

        // Send data over UDP
        if (send_udp_data(udp_socket, json_string, "192.168.1.100", 5000) < 0) {
            fprintf(stderr, "Error sending UDP data, retrying...\n");
        }

        // Free allocated memory
        free(json_string);

        // Wait 5 seconds
        sleep(5);
    }

