#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// Temperature thresholds for PWM mapping
#define TEMP_LOW 25.0
#define TEMP_MED_LOW 40.0
#define TEMP_MED_HIGH 60.0
#define TEMP_HIGH 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, uint32_t *raw_data);
float process_temperature(uint32_t raw_data);
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read data from MAX31855 via SPI
int read_max31855(int spi_handle, uint32_t *raw_data) {
    char tx_buf[4] = {0, 0, 0, 0}; // Dummy data for reading
    char rx_buf[4];

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate failure
    }

    *raw_data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];
    return 0; // Indicate success
}

// Function to process raw temperature data
float process_temperature(uint32_t raw_data) {
    // Check for fault bits
    if (raw_data & 0x00000007) {
        fprintf(stderr, "Error: MAX31855 fault detected (0x%08X)\n", raw_data);
        if (raw_data & 0x00000001) fprintf(stderr, "  Open circuit fault\n");
        if (raw_data & 0x00000002) fprintf(stderr, "  Short to GND fault\n");
        if (raw_data & 0x00000004) fprintf(stderr, "  Short to VCC fault\n");
        return -273.15; // Indicate error
    }

    // Extract thermocouple temperature (14-bit, signed)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask relevant bits
    float temperature = thermocouple_data * 0.25; // Convert to degrees Celsius

    return temperature;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_LOW) {
        return 0;
    } else if (temperature < TEMP_MED_LOW) {
        return (int)((temperature - TEMP_LOW) / (TEMP_MED_LOW - TEMP_LOW) * 50.0);
    } else if (temperature < TEMP_MED_HIGH) {
        return (int)(50.0 + (temperature - TEMP_MED_HIGH) / (TEMP_MED_HIGH - TEMP_MED_LOW) * 150.0);
    } else {
        return 255;
    }
}

// Function to update the fan speed using hardware PWM
void update_fan(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint32_t raw_data;
    float temperature;
    int duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &raw_data) == 0) {
            // Process temperature data
            temperature = process_temperature(raw_data);

            if (temperature > -273.0) { // Check for valid temperature
                // Calculate duty cycle
                duty_cycle = calculate_duty_cycle(temperature);

                // Update fan speed
                update_fan(duty_cycle);

                // Log data
                log_data(temperature, duty_cycle);
            } else {
                fprintf(stderr, "Error: Invalid temperature reading\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read temperature\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Print buffer contents
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

