#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8       // CE0
#define LOG_FILE "rtd_log.csv"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// RTD Constants
#define RREF 430.0       // Reference resistor value (ohms)
#define A 0.0039083
#define B -0.0000005775
#define C 0.0

// Global variables
static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int device, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_init(const char *chip_name, int line);
int gpio_set_value(int fd, int value);
int log_init(const char *filename);
int log_write(int fd, const char *timestamp, float temperature);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(int bus, int device, int speed) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip_name, int line) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ptr = gpiod_chip_get_line(chip, line);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line_ptr, "rtd_logger", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line_ptr);
        return -1;
    }

    return (int)line_ptr; // Return the line pointer as an integer
}

// GPIO Set Value
int gpio_set_value(int fd, int value) {
    if (gpiod_line_set_value((struct gpiod_line *)fd, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log Initialization
int log_init(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }

    // Write header if the file is newly created
    off_t file_size = lseek(fd, 0, SEEK_END);
    if (file_size == 0) {
        dprintf(fd, "Timestamp,Temperature (C)\n");
    }
    lseek(fd, 0, SEEK_END); // Reset file pointer to the end

    return fd;
}

// Log Write
int log_write(int fd, const char *timestamp, float temperature) {
    dprintf(fd, "%s,%.2f\n", timestamp, temperature);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line != NULL) {
