#include <math.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA_PRESS_MSB 0xF7
#define BME280_REG_DATA_PRESS_LSB 0xF8
#define BME280_REG_DATA_PRESS_XLSB 0xF9
#define BME280_REG_DATA_TEMP_MSB 0xFA
#define BME280_REG_DATA_TEMP_LSB 0xFB
#define BME280_REG_DATA_TEMP_XLSB 0xFC
#define BME280_REG_DATA_HUM_MSB 0xFD
#define BME280_REG_DATA_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Oversampling settings
#define BME280_OVERSAMPLING_TEMP 2 // x2
#define BME280_OVERSAMPLING_HUM 1  // x1
#define BME280_OVERSAMPLING_PRESS 5 // x16
#define BME280_MODE_NORMAL 3       // Normal mode

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t data);
int bme280_init(int fd);
int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure);
