void signal_handler(int sig);
int read_calibration_data(int fd, struct bme280_calib_data *calib);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// BME280 initialization function
int bme280_init(int fd) {
    uint8_t chip_id;

    // Check chip ID
    if (i2c_read_reg(fd, BME280_REG_CHIPID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set oversampling and mode
    uint8_t ctrl_meas = (BME280_OVERSAMPLING_TEMP << 5) | (BME280_OVERSAMPLING_PRESS << 2) | BME280_MODE_NORMAL;
    uint8_t ctrl_hum = BME280_OVERSAMPLING_HUM;

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, ctrl_hum) != 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, ctrl_meas) != 0) return -1;

    return 0;
}

// Read calibration data from BME280
int read_calibration_data(int fd, struct bme280_calib_data *calib) {
    uint8_t data[26];
    uint8_t data_h[7];

    if (i2c_read_reg(fd, BME280_REG_CALIB_00, data, 26) != 0) return -1;
    if (i2c_read_reg(fd, BME280_REG_CALIB_26, data_h, 7) != 0) return -1;

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];
    calib->dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib->dig_H3 = data_h[2];
    calib->dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib->dig_H5 = (int16_t)((data_h[5] << 4) | (data_h[4] >> 4));
    calib->dig_H6 = (int8_t)data_h[6];

    return 0;
}

// BME280 data reading function
int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    int32_t raw_temp, raw_press, raw_hum;

    // Read raw data
    if (i2c_read_reg(fd, BME280_REG_DATA_PRESS_MSB, data, 8) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    raw_press = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temp = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    raw_hum = (int32_t)data[6] << 8 | (int32_t)data[7];

    // Temperature compensation
    double var1, var2, T;
    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;

    // Pressure compensation
    double var3, var4, p;
    var3 = ((double)t_fine / 2.0) - 64000.0;
    var4 = var3 * var3 * ((double)calib.dig_P6) / 32768.0;
    var4 = var4 + var3 * ((double)calib.dig_P5) * 2.0;
    var4 = (var4 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var3 = (((double)calib.dig_P3) * var3 * var3 / 524288.0 + ((double)calib.dig_P2) * var3) / 524288.0;
    var3 = (1.0 + var3 / 32768.0) * ((double)calib.dig_P1);
