#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 readings/second)
#define BUFFER_SIZE 1200

// Pressure deviation threshold (hPa)
#define PRESSURE_DEVIATION_THRESHOLD 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular buffer
float pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
float calculate_pressure(int raw_temp, int raw_pressure);
float calculate_rolling_average();
void trigger_alert();
void log_error(const char *message);
void signal_handler(int signal);
void timer_callback(int timer_id, void *user_data);

// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        log_error("Failed to read I2C word");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the I2C bus
uint16_t read_i2c_uword(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        log_error("Failed to read I2C unsigned word");
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        log_error("Failed to read calibration data");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        log_error("Failed to write temperature read command");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        log_error("Failed to read raw temperature data");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        log_error("Failed to write pressure read command");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        log_error("Failed to read raw pressure data");
        return -1;
    }

    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temp, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = ((long)raw_temp - (long)ac6) * (long)ac5 / pow(2, 15);
    x1 = ((long)mc * pow(2, 11)) / (b5 + md);
    b6 = b5 + x1 - pow(2, 11);
    x2 = ((long)ac1 * b6) / pow(2, 11);
    x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    b3 = (((x2 + x3) + pow(2, 2)) + 32768) / pow(2, 15);
    x1 = ((long)ac3 * b6) / pow(2, 13);
    x2 = ((long)b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    x3 = ((x1 + x2) + pow(2, 2)) / pow(2, 2);
    b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) / pow(2, 15);
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return (float)p / 100.0; // Convert to hPa
}

// Function to calculate the rolling average of the last 60 seconds
float calculate_rolling_average()
{
    float sum = 0.0;
    int count = 0;
    int start_index = buffer_index - BUFFER_SIZE;
    if (start_index < 0) {
        start_index += BUFFER_SIZE; // Wrap around
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        if (pressure_buffer[index] != 0.0) { // Only include valid readings
            sum += pressure_buffer[index];
            count++;
        }
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // No valid readings
    }
}

// Function to trigger an alert on GPIO24
void trigger_alert()
{
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
}

// Function to log errors to stderr
void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    if (signal == SIGINT) {
        printf("Received SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data)
{
    int raw_temp, raw_pressure;
    float pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        log_error("Failed to read raw temperature");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        log_error("Failed to read raw pressure");
        return;
    }

    pressure = calculate_pressure(raw_temp, raw_pressure);

    // Store pressure reading in circular buffer
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Calculate rolling average
    float rolling_average = calculate_rolling_average();

    // Check for pressure deviation
    if (fabs(pressure - rolling_average) > PRESSURE_DEVIATION_THRESHOLD) {
        printf("Pressure deviation detected: Current = %.2f hPa, Average = %.2f hPa\n", pressure, rolling_average);
        trigger_alert();
    }

    printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, rolling_average);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer function
    if (gpioSetTimerFuncEx(0, 50, timer_callback, NULL) != 0) {
        log_error("Failed to set up timer function");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Clean up
    gpioSetTimerFuncEx(0, 50, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Reset GPIO
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

