    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature command to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (read_i2c_word(i2c_handle, BMP180_REG_MSB, (int16_t*)raw_temp) != 0) {
        return -1;
    }

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure command to I2C device.\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    char data[3];
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure read command to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data from I2C device.\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)data[0] << 16 | (uint32_t)data[1] << 8 | (uint32_t)data[2]) >> (8 - BMP180_OSS);

    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)calibration_data.ac6) * (int32_t)calibration_data.ac5) >> 15;
    int32_t X2 = ((int32_t)calibration_data.mc << 11) / (X1 + calibration_data.md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, double temperature) {
    int32_t B6 = (int32_t)temperature * 10 - 400;
    int32_t X1 = ((int32_t)calibration_data.b2 * (B6 * B6) >> 12) >> 11;
    int32_t X2 = ((int32_t)calibration_data.ac2 * B6) >> 11;
