#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define TEMP_MIN 40000
#define TEMP_MAX 70000
#define DUTY_MIN 0
#define DUTY_MAX 255

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping fan and cleaning up...\n", signal);
}

int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

int map_temperature_to_duty(int temperature) {
    int duty;

    if (temperature <= TEMP_MIN) {
        duty = DUTY_MIN;
    } else if (temperature >= TEMP_MAX) {
        duty = DUTY_MAX;
    } else {
        duty = (int)(((float)(temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN));
    }

    return duty;
}

int set_fan_speed(int duty) {
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Error setting fan speed\n");
        return -1;
    }
    return 0;
}

int log_data(int temperature, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %d, Duty: %d\n", timestamp, temperature, duty);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    return 0;
}

int main() {
    int temperature, duty;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, 255);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature, using previous value or default.\n");
            // Consider using a default temperature or previous value here
        } else {
            duty = map_temperature_to_duty(temperature);
            if (set_fan_speed(duty) != 0) {
                fprintf(stderr, "Failed to set fan speed.\n");
            }
            if (log_data(temperature, duty) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }
        sleep(5);
    }

    set_fan_speed(0); // Stop the fan
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

