#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BMP280_ADDR_76 0x76
#define BMP280_ADDR_77 0x77
#define BMP280_CHIP_ID 0xD0
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LENGTH 24
#define BMP280_DATA_START 0xF7
#define BMP280_DATA_LENGTH 6
#define BMP280_CTRL_MEAS 0xF4
#define BMP280_STATUS 0xF3
#define BMP280_STATUS_MEAS_MASK 0x08
#define BMP280_STATUS_MEAS_CLEAR 0x07 // Clear all but measuring bit

#define BMP280_TEMP_PRESS_OSR_X1 0x27 // Temperature x1, Pressure x1, Forced mode

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int fd, bmp280_calib_data *calib) {
    uint8_t buffer[BMP280_CALIB_LENGTH];
    for (int i = 0; i < BMP280_CALIB_LENGTH; i++) {
        int result = i2c_read_reg(fd, BMP280_CALIB_START + i);
        if (result < 0) {
            fprintf(stderr, "Error reading calibration data at offset %d\n", i);
            return -1;
        }
        buffer[i] = (uint8_t)result;
    }

    calib->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int read_raw_data(int fd, int32_t *raw_temperature, int32_t *raw_pressure) {
    uint8_t buffer[BMP280_DATA_LENGTH];
    for (int i = 0; i < BMP280_DATA_LENGTH; i++) {
        int result = i2c_read_reg(fd, BMP280_DATA_START + i);
        if (result < 0) {
            fprintf(stderr, "Error reading raw data at offset %d\n", i);
            return -1;
        }
        buffer[i] = (uint8_t)result;
    }

    *raw_pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *raw_temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib, int32_t *t_fine) {
    double var1 = (raw_temperature / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temperature / 131072.0 - calib.dig_T1 / 8192.0) * (raw_temperature / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    double T = (*t_fine) / 5120.0;
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, int32_t t_fine) {
    double var1 = (t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (calib.dig_P4 * 65536.0);
    var1 = (calib.dig_P3 * var1 * var1 / 524288.0 + calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * calib.dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    double p = 1048576.0 - raw_pressure;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + calib.dig_P7) / 16.0;

    return p / 100.0; // hPa
}

// Function to log data to a file
int log_data(FILE *file, double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(file, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address (default 0x76)
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR_76) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x76: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify chip ID
    int chip_id = i2c_read_reg(i2c_fd, BMP280_CHIP_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID\n");
        close(i2c_fd);
        return 1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02x. Expected 0x58\n", chip_id);

        // Try 0x77
        if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR_77) < 0) {
            fprintf(stderr, "Error setting I2C slave address 0x77: %s\n", strerror(errno));
            close(i2c_fd);
            return 1;
        }

        chip_id = i2c_read_reg(i2c_fd, BMP280_CHIP_ID);
        if (chip_id < 0) {
            fprintf(stderr, "Error reading chip ID\n");
            close(i2c_fd);
            return 1;
        }

        if (chip_id != 0x58) {
            fprintf(stderr, "Error: Invalid chip ID 0x%02x. Expected 0x58\n", chip_id);
            close(i2c_fd);
            return 1;
        }
    }

    // Read calibration data
    bmp280_calib_data calib;
    if (read_calibration_data(i2c_fd, &calib) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

