        // Try 0x77
        if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDR_77) < 0) {
            fprintf(stderr, "Error setting I2C slave address 0x77: %s\n", strerror(errno));
            close(i2c_fd);
