            timeout--;
        } while ((status & BMP280_STATUS_MEAS_MASK) && timeout > 0);

        if (timeout == 0) {
            fprintf(stderr, "Error: Timeout waiting for measurement to complete\n");
            break;
        }

        // Read raw data
        int32_t raw_temperature, raw_pressure;
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data\n");
            break;
        }

        // Compensate temperature and pressure
        int32_t t_fine;
        double temperature = compensate_temperature(raw_temperature, calib, &t_fine);
        double pressure = compensate_pressure(raw_pressure, calib, t_fine);

        // Log data
        if (log_data(log_file, temperature, pressure) < 0) {
