#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
void signal_handler(int sig);
int init_i2c(int bus, int addr);
int read_temperature(int fd, float *temperature);
void *data_acquisition_thread(void *arg);
void update_led(struct gpiod_line *line, float temperature);
void add_to_buffer(float temperature);
float calculate_average();
void cleanup();

// Signal handler
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// I2C initialization function
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Temperature reading function
int read_temperature(int fd, float *temperature) {
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading temperature data");
        return -1;
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits

    *temperature = (float)raw_temp / 256.0f;
    return 0;
}

// Data acquisition thread function
void *data_acquisition_thread(void *arg) {
    float temperature;
    while (running) {
        if (read_temperature(i2c_fd, &temperature) == 0) {
            pthread_mutex_lock(&buffer_mutex);
            add_to_buffer(temperature);
            pthread_mutex_unlock(&buffer_mutex);
        } else {
            fprintf(stderr, "Error reading temperature, retrying I2C init...\n");
            if (i2c_fd != -1) close(i2c_fd);
            i2c_fd = init_i2c(I2C_BUS, LM75_ADDR);
            if (i2c_fd == -1) {
                fprintf(stderr, "Fatal error: Failed to re-initialize I2C. Exiting thread.\n");
                running = 0; // Exit the thread if re-init fails
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    return NULL;
}

// LED control function
void update_led(struct gpiod_line *line, float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpiod_line_set_value(line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(line, 0); // Turn LED off
    }
}

// Circular buffer functions
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

float calculate_average() {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    return sum / buffer_count;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    pthread_mutex_destroy(&buffer_mutex);
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LM75_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Fatal error: Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "temp_monitor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        cleanup();
        return 1;
    }

    // Create data acquisition thread
    pthread_t data_thread;
    if (pthread_create(&data_thread, NULL, data_acquisition_thread, NULL) != 0) {
        perror("Error creating data acquisition thread");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        float avg_temp = calculate_average();
        pthread_mutex_unlock(&buffer_mutex);
        printf("Average Temperature: %.2f °C\n", avg_temp);
        update_led(gpio_line, avg_temp);
        sleep(5);
    }

    // Clean up resources
    pthread_join(data_thread, NULL);
    cleanup();

    return 0;
}

