// Constants
#define GPIO_PWM 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_FAULT_REG 0x07
#define MAX31865_VBIAS_BIT 0x04
#define MAX31865_AUTOCONVERT_BIT 0x02
#define MAX31865_CLEAR_FAULT_BIT 0x01
#define MAX_RTD_RESISTANCE 430.0 // 430 ohms
#define R0 100.0 // Reference resistance (100 ohms)
#define TARGET_TEMP_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define MAX_DUTY 900 // 90% of PWM_RANGE

// Global variables
int spi_handle;
double target_temperature = TARGET_TEMP_DEFAULT;
double Kp = KP_DEFAULT;
double Ki = KI_DEFAULT;
double Kd = KD_DEFAULT;
double integral = 0.0;
double previous_error = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename);
int init_spi();
int init_gpio();
int init_pigpio();
int read_max31865(double *temperature);
double rtd_to_resistance(unsigned int rtd_code);
double resistance_to_temperature(double resistance);
double pid_control(double setpoint, double actual_temperature);
void set_pwm_duty(int duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from JSON file
int read_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    if (target_temp_json) {
        target_temperature = json_real_value(target_temp_json);
    } else {
        fprintf(stderr, "Warning: target_temperature not found in config file, using default: %.2f\n", TARGET_TEMP_DEFAULT);
        target_temperature = TARGET_TEMP_DEFAULT;
    }

    json_t *kp_json = json_object_get(root, "Kp");
    if (kp_json) {
        Kp = json_real_value(kp_json);
    } else {
        fprintf(stderr, "Warning: Kp not found in config file, using default: %.2f\n", KP_DEFAULT);
        Kp = KP_DEFAULT;
    }

    json_t *ki_json = json_object_get(root, "Ki");
    if (ki_json) {
        Ki = json_real_value(ki_json);
    } else {
        fprintf(stderr, "Warning: Ki not found in config file, using default: %.2f\n", KI_DEFAULT);
        Ki = KI_DEFAULT;
    }

    json_t *kd_json = json_object_get(root, "Kd");
    if (kd_json) {
        Kd = json_real_value(kd_json);
    } else {
        fprintf(stderr, "Warning: Kd not found in config file, using default: %.2f\n", KD_DEFAULT);
        Kd = KD_DEFAULT;
    }

    json_decref(root);
    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI_MODE_0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    gpioSetMode(GPIO_PWM, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);
    return 0;
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31865
int read_max31865(double *temperature) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int rtd_code;
    unsigned char fault_status;

    // Read RTD MSB and LSB
    tx_buffer[0] = MAX31865_RTD_MSB_REG | 0x80; // Read command
    tx_buffer[1] = 0x00; // Dummy data
    tx_buffer[2] = 0x00; // Dummy data

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1;
    }

    rtd_code = ((rx_buffer[1] << 8) | rx_buffer[2]) >> 1; // Combine MSB and LSB, remove fault bit

    // Read fault register
    tx_buffer[0] = MAX31865_FAULT_REG | 0x80; // Read command
    tx_buffer[1] = 0x00; // Dummy data
    tx_buffer[2] = 0x00; // Dummy data

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1;
    }

    fault_status = rx_buffer[1];

    // Check for faults
    if (fault_status) {
        fprintf(stderr, "Error: MAX31865 fault detected (0x%02X)\n", fault_status);
        if (fault_status & 0x01) fprintf(stderr, "  Open circuit fault\n");
        if (fault_status & 0x02) fprintf(stderr, "  Short to VCC fault\n");
        if (fault_status & 0x04) fprintf(stderr, "  Short to GND fault\n");
        if (fault_status & 0x08) fprintf(stderr, "  RTD high fault\n");
        if (fault_status & 0x10) fprintf(stderr, "  RTD low fault\n");
        return -1;
    }

    *temperature = resistance_to_temperature(rtd_to_resistance(rtd_code));
    return 0;
}

// Function to convert RTD code to resistance
double rtd_to_resistance(unsigned int rtd_code) {
    return ((double)rtd_code / 32768.0) * MAX_RTD_RESISTANCE;
}

// Function to convert resistance to temperature (Callendar-Van Dusen)
double resistance_to_temperature(double resistance) {
    double A = -0.000266;
    double B = 0.00000044;
    return (resistance - R0) / (R0 * (1 + A + B));
}

// Function to implement PID control
double pid_control(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the PWM range
    if (output < 0) output = 0;
    if (output > MAX_DUTY) output = MAX_DUTY;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty(int duty_cycle) {
    gpioPWM(GPIO_PWM, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    set_pwm_duty(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    double temperature;
    double pid_output;
    int duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Read configuration from file
    if (read_config("config.json") != 0) {
        fprintf(stderr, "Warning: Using default configuration\n");
    }

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31865
        if (read_max31865(&temperature) == 0) {
            // Calculate PID output
            pid_output = pid_control(target_temperature, temperature);

            // Convert PID output to duty cycle
            duty_cycle = (int)pid_output;

            // Set PWM duty cycle
            set_pwm_duty(duty_cycle);

            // Failsafe shutoff
            if (temperature > MAX_TEMP) {
                fprintf(stderr, "Error: Temperature exceeded maximum limit (%.2f > %.2f)\n", temperature, MAX_TEMP);
                set_pwm_duty(0);
                cleanup();
                return 1;
            }
        } else {
            fprintf(stderr, "Error: Failed to read temperature, shutting down\n");
            set_pwm_duty(0);
            cleanup();
            return 1;
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

