#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int bmp180_read_raw_temperature(int fd, int32_t *raw_temp);
int bmp180_read_raw_pressure(int fd, int32_t *raw_pressure);
float bmp180_calculate_temperature(int32_t raw_temp);
float bmp180_calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
bool check_thresholds(float temperature, float pressure);
void log_breach(float temperature, float pressure);
void signal_handler(int sig);
int bmp180_init(int fd);

// I2C read function with retry and error handling
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("Failed to read data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// I2C write function with retry and error handling
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int retries = 3;
    int result;
    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Failed to write data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// BMP180 initialization function
int bmp180_init(int fd) {
    uint8_t data[22];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, data, 22) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// BMP180 read raw temperature function
int bmp180_read_raw_temperature(int fd, int32_t *raw_temp) {
    uint8_t data[2];
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms

    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 2) != 0) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// BMP180 read raw pressure function
int bmp180_read_raw_pressure(int fd, int32_t *raw_pressure) {
    uint8_t data[3];
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
    usleep((2 + (3 << BMP180_OSS)) * 1000); // Wait for conversion

    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 3) != 0) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// BMP180 calculate temperature function
float bmp180_calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0f;
    return temperature;
}

// BMP180 calculate pressure function
float bmp180_calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
