#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
sensor_data_t data_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle);
float calculate_true_temperature(int raw_temperature, bmp180_calibration_data_t calibration);
float calculate_true_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration);
void control_fan(float temperature);
void signal_handler(int signal);
void timer_callback(int timer_id, void *user_data);

// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int i2c_handle, uint8_t reg)
{
    char buf[2];
    if (i2cWriteByte(i2c_handle, reg) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration)
{
    calibration->ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    calibration->ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    calibration->ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    calibration->ac4 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC4);
    calibration->ac5 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC5);
    calibration->ac6 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC6);
    calibration->b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    calibration->b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    calibration->mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    calibration->mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    calibration->md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (calibration->ac1 == -1 || calibration->ac2 == -1 || calibration->ac3 == -1 ||
        calibration->ac4 == -1 || calibration->ac5 == -1 || calibration->ac6 == -1 ||
        calibration->b1 == -1 || calibration->b2 == -1 || calibration->mb == -1 ||
        calibration->mc == -1 || calibration->md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    gpioDelay(5); // Wait 4.5ms
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle)
{
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) return -1;
    gpioDelay(2 + (3 << OSS)); // Wait for conversion
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) return -1;
    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
}

// Function to calculate true temperature in degrees Celsius
float calculate_true_temperature(int raw_temperature, bmp180_calibration_data_t calibration)
{
    long X1 = ((long)raw_temperature - (long)calibration.ac6) * ((long)calibration.ac5) / pow(2, 15);
    long X2 = ((long)calibration.mc * pow(2, 11)) / (X1 + calibration.md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4);
    return temperature / 10.0;
}

// Function to calculate true pressure in Pascals
float calculate_true_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration)
{
    long X1 = ((long)raw_temperature - (long)calibration.ac6) * ((long)calibration.ac5) / pow(2, 15);
    long X2 = ((long)calibration.mc * pow(2, 11)) / (X1 + calibration.md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)calibration.b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)calibration.ac2 * B6) / pow(2, 11);
    long B3 = (((long)calibration.ac1 * 4 + X3 + X4) + 2) / 4;

    unsigned long X1_pressure = ((unsigned long)calibration.ac3 * B6) / pow(2, 13);
    unsigned long X2_pressure = ((unsigned long)calibration.b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = ((unsigned long)calibration.ac4 * (X1_pressure + X2_pressure + 32768)) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);

    float true_pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);
    return true_pressure;
}

// Function to control the cooling fan based on temperature
void control_fan(float temperature)
{
    if (temperature > 30.0) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Timer callback function
void timer_callback(int timer_id, void *user_data)
{
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    // Read raw temperature and pressure
    raw_temperature = read_raw_temperature(i2c_handle);
    raw_pressure = read_raw_pressure(i2c_handle);

    if (raw_temperature == -1 || raw_pressure == -1) {
        fprintf(stderr, "Error reading sensor data, skipping sample\n");
        return;
    }

    // Calculate true temperature and pressure
    temperature = calculate_true_temperature(raw_temperature, calibration_data);
    pressure = calculate_true_pressure(raw_pressure, raw_temperature, calibration_data);

    // Store data in circular buffer
    data_buffer[buffer_index].timestamp = time(NULL);
    data_buffer[buffer_index].temperature = temperature;
    data_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Control the fan
    control_fan(temperature);

    // Print the data
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n", data_buffer[buffer_index].timestamp, temperature, pressure);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 500 ms)
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer callback\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Keep the program running until a signal is received
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Clean up
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(FAN_PIN, 0); // Turn fan off
    gpioTerminate();

    return 0;
}

