// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for toggle
#define TOGGLE_GPIO 27

// Debounce time (ms)
#define DEBOUNCE_TIME 200

// Logging interval (s)
#define LOGGING_INTERVAL 2

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile int logging_enabled = 0;
static volatile int toggle_state = 0; // 0 = off, 1 = on
static int ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned int ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
long calculate_true_temperature(int raw_temp);
long calculate_true_pressure(int raw_pressure, long true_temperature);
void log_data(long pressure);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int read_i2c_word(int handle, char reg, int *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *value = (*value << 8) | (value[1] & 0xFF);
    return 0;
}

// Function to read a signed 16-bit value from the BMP180
int read_i2c_signed_word(int handle, char reg, int *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *value = (*value << 8) | (value[1] & 0xFF);
    if (*value & 0x8000) {
        *value = -*value;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(TOGGLE_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOGGLE_GPIO, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_toggle_state = toggle_state;
    time_t last_toggle_time = 0;

    // Main loop
    while (1) {
        // Debounce the toggle switch
        if (gpioRead(TOGGLE_GPIO) == 0) {
            time_t now = time(NULL);
            if (last_toggle_time == 0 || (now - last_toggle_time) * 1000 > DEBOUNCE_TIME) {
                toggle_state = !toggle_state;
                last_toggle_time = now;
            }
        }

        // Toggle logging state
        if (toggle_state != last_toggle_state) {
            logging_enabled = toggle_state;
            last_toggle_state = toggle_state;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        }

        // Log data if logging is enabled
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            long true_temperature, true_pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw data\n");
                continue; // Skip to the next iteration
            }

            // Calculate true temperature and pressure
            true_temperature = calculate_true_temperature(raw_temp);
            true_pressure = calculate_true_pressure(raw_pressure, true_temperature);

            // Log the data
            log_data(true_pressure);
        }

        // Wait for the next logging interval
        sleep(LOGGING_INTERVAL);
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC4, (int*)&ac4) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC5, (int*)&ac5) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC6, (int*)&ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

