        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(TOGGLE_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOGGLE_GPIO, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_toggle_state = toggle_state;
    time_t last_toggle_time = 0;

    // Main loop
    while (1) {
        // Debounce the toggle switch
        if (gpioRead(TOGGLE_GPIO) == 0) {
            time_t now = time(NULL);
            if (last_toggle_time == 0 || (now - last_toggle_time) * 1000 > DEBOUNCE_TIME) {
                toggle_state = !toggle_state;
                last_toggle_time = now;
            }
        }

        // Toggle logging state
        if (toggle_state != last_toggle_state) {
            logging_enabled = toggle_state;
            last_toggle_state = toggle_state;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        }

        // Log data if logging is enabled
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            long true_temperature, true_pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
                fprintf(stderr, "Error reading raw data\n");
                continue; // Skip to the next iteration
            }

            // Calculate true temperature and pressure
            true_temperature = calculate_true_temperature(raw_temp);
            true_pressure = calculate_true_pressure(raw_pressure, true_temperature);

            // Log the data
            log_data(true_pressure);
        }

        // Wait for the next logging interval
        sleep(LOGGING_INTERVAL);
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC4, (int*)&ac4) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC5, (int*)&ac5) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC6, (int*)&ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temp)
{
    char buf[1];
    buf[0] = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (read_i2c_word(i2c_handle, BMP180_REG_MSB, raw_temp) != 0) {
        return -1;
    }

    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    if (read_i2c_word(i2c_handle, BMP180_REG_MSB, raw_pressure) != 0) {
        return -1;
    }

    return 0;
}

// Function to calculate the true temperature in degrees Celsius
long calculate_true_temperature(int raw_temp)
{
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    long temperature = (B5 + 8) / pow(2, 4);
    return temperature;
}

// Function to calculate the true pressure in Pascals
long calculate_true_pressure(int raw_pressure, long true_temperature)
{
    long B6 = true_temperature - 4000;
    long X1 = (b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    long X2 = ac2 * B6 / pow(2, 11);
    long X3 = X1 + X2;
    long B3 = (((long)ac1 * 4 + X3) << BMP180_OSS + 2) / 4;
    unsigned long B4 = ac4 * (unsigned long)(X3 + 32768) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> BMP180_OSS);
    long p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    p = p + (X1 + X2 + 3791) / pow(2, 4);
    return p;
}

// Function to log the pressure data to a file
void log_data(long pressure)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %ld Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %ld Pa\n", timestamp, pressure);
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C device
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

