#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"

// PI Controller Parameters
#define KP 1.0
#define KI 0.1
#define MAX_INTEGRAL 10.0

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double integral = 0.0;

// Function Prototypes
double read_temperature();
double calculate_duty_cycle(double temperature, double target_temperature);
void set_heater_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for MAX31855 fault bits
    if (data[3] & 0x07) {
        fprintf(stderr, "MAX31855 Fault: %02X\n", data[3]);
        if (data[3] & 0x01) fprintf(stderr, "  Open circuit\n");
        if (data[3] & 0x02) fprintf(stderr, "  Short to GND\n");
        if (data[3] & 0x04) fprintf(stderr, "  Short to VCC\n");
        return -1000.0; // Indicate error
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = ((data[0] << 8) | data[1]) >> 2;
    double temperature = thermocouple_data * 0.25;

    return temperature;
}

// Function to calculate duty cycle using PI controller
double calculate_duty_cycle(double temperature, double target_temperature) {
    double error = target_temperature - temperature;
    integral += error;

    // Anti-windup
    if (integral > MAX_INTEGRAL) integral = MAX_INTEGRAL;
    if (integral < -MAX_INTEGRAL) integral = -MAX_INTEGRAL;

    double output = KP * error + KI * integral;

    // Limit output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(double duty_cycle) {
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * 2.55)); // pigpio PWM range is 0-255
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Heater control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            // Calculate duty cycle
            double duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE);

            // Set heater duty cycle
            set_heater_duty_cycle(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);

            printf("Temperature: %.2f C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);
        } else {
            // Log error and turn off heater
            fprintf(stderr, "Error reading temperature, turning off heater.\n");
            set_heater_duty_cycle(0.0);
            log_data(-999.0, 0.0); // Log error
        }

        // Wait 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    printf("Heater control stopped.\n");
    return 0;
}

