#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (millidegrees Celsius)
#define TEMP_LOW   40000
#define TEMP_MED   60000
#define TEMP_HIGH  70000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    int temp = -1; // Default to error value

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file!\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading temperature file!\n");
        } else {
            fprintf(stderr, "Error parsing temperature value!\n");
        }
        temp = -1; // Set to error value
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common anode
}

int main()
{
    int temp_milli;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp_milli = read_cpu_temp();

        if (temp_milli == -1) {
            // Error reading temperature, skip update
            sleep(1); // Wait before next attempt
            continue;
        }

        // Determine RGB values based on temperature
        if (temp_milli < TEMP_LOW) {
            red = 0; green = 0; blue = 255;
        } else if (temp_milli < TEMP_MED) {
            red = 0; green = 255; blue = 0;
        } else {
            red = 255; green = 0; blue = 0;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp_milli, red, green, blue);

        // Wait for 0.5 seconds
        sleep(1);
    }

    // Cleanup before exiting
    set_led_color(255, 255, 255); // Turn off LED
    gpioTerminate();              // Terminate pigpio

    return 0;
}

