#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30 to match DHT22 datasheet

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1ms
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22: Timeout waiting for start signal.\n");
            return -1; // Timeout error
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22: Timeout waiting for bit start.\n");
                return -1; // Timeout error
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22: Timeout waiting for bit end.\n");
                return -1; // Timeout error
            }
        }
        long end = gpioTick();

        if ((end - start) > 40) { // Changed from 50 to 40 to match DHT22 datasheet
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum error.\n");
        return -2; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Failed to allocate memory for JSON string.\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to send data to the server using libcurl
int send_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    float temperature, humidity;
    char *json_data;
    int retries = 0;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        retries = 0;
        result = -1; // Initialize result to an error state

        while (retries < MAX_RETRIES && result != 0) {
            result = read_dht22(DHT22_GPIO, &temperature, &humidity);
            if (result != 0) {
                fprintf(stderr, "DHT22 read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(1000); // Wait 1 second before retrying
            }
        }

        if (result == 0) {
            // Format data as JSON
            json_data = format_json(temperature, humidity);
            if (json_data != NULL) {
                // Send data to the server
                if (send_data(json_data) == 0) {
                    printf("Data sent successfully: Temperature = %.1f, Humidity = %.1f\n", temperature, humidity);
                } else {
                    fprintf(stderr, "Failed to send data.\n");
                }
                free(json_data);
            } else {
                fprintf(stderr, "Failed to format JSON data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(5000); // Wait 5 seconds before next reading
    }

    // Clean up resources
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

