    if (i2cWriteByte(i2c_handle, reg) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_MD, &md) != 0) return -1;

    // Basic validation (check for reasonable values)
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0) {
        fprintf(stderr, "Error: Invalid calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteByte(i2c_handle, BMP180_REG_CONTROL) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cWriteByte(i2c_handle, buf[0]) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (read_i2c_word(BMP180_REG_MSB, raw_temp) != 0) return -1;

    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteByte(i2c_handle, BMP180_REG_CONTROL) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cWriteByte(i2c_handle, buf[0]) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (OSS=3)

    char data[3];
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    *raw_pressure = (data[0] << 16 | data[1] << 8 | data[2]) >> (8 - BMP180_OSS);

    return 0;
}

// Function to calculate true temperature in degrees Celsius
long calculate_true_temperature(int raw_temp)
{
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    long temperature = (B5 + 8) / pow(2, 4);
    return temperature;
}

// Function to calculate true pressure in hPa
long calculate_true_pressure(int raw_pressure, long true_temperature)
{
    long B6 = true_temperature - 4000;
    long X1 = (b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    long X2 = ac2 * B6 / pow(2, 11);
    long X3 = X1 + X2;
    long B3 = (((long)ac1 * 4 + X3) << BMP180_OSS + 2) / 4;
    unsigned long B4 = ac4 * (unsigned long)(X3 + 32768) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> BMP180_OSS);
    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }
    X1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (X1 + X2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to log data to a file
void log_data(long pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure / 100.0);

    fclose(fp);
}

// Interrupt service routine for the push-button
void button_isr(int gpio, int level, uint32_t tick, void *user)
{
    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME)
    {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt service routine for falling edge on GPIO4
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL);

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            long true_temperature, true_pressure;

            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                true_temperature = calculate_true_temperature(raw_temp);
                true_pressure = calculate_true_pressure(raw_pressure, true_temperature);
                log_data(true_pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        } else {
            printf("Logging disabled.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

