#define DHT22_GPIO 4
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds

static volatile int running = 1;
static char *server_url = DEFAULT_SERVER_URL;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Function to read DHT22 data using pigpio
int read_dht22_data(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(20); // 20us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Wait for the DHT22 to pull the line high (response signal)
    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Wait for the DHT22 to pull the line low again (response signal)
    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go high
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }
        long end = gpioTick();

        long pulse_length = end - start;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        if (pulse_length > 40) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }

        bit_count++;
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum failure");
        return -1;
    }

    // Convert data to humidity
    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;

    return 0;
}

// Function to format humidity data as JSON
char *format_json(float humidity) {
    char *json_string = malloc(50 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 50, "{\"humidity\": %.2f}", humidity);
    return json_string;
}

// Function to POST data to the server using libcurl
int post_data(const char *url, const char *data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                syslog(LOG_ERR, "HTTP request failed with code: %ld", response_code);
                res = CURLE_HTTP_RETURNED_ERROR;
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;
    int retries;
    int post_retries;

    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_dht22_data(&humidity) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
                break;
            } else {
                syslog(LOG_ERR, "DHT22 read failed, retrying (%d/%d)", retries + 1, MAX_RETRIES);
                retries++;
                sleep(BACKOFF_DELAY);
            }
        }

        if (retries == MAX_RETRIES) {
            syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
            continue; // Skip posting if DHT22 read failed
        }

        char *json_data = format_json(humidity);
        if (json_data == NULL) {
            syslog(LOG_ERR, "Failed to format JSON data");
            continue; // Skip posting if JSON formatting failed
        }

        post_retries = 0;
        while (post_retries < MAX_RETRIES) {
            if (post_data(server_url, json_data) == 0) {
                syslog(LOG_INFO, "Data posted successfully");
                break;
            } else {
                syslog(LOG_ERR, "Data post failed, retrying (%d/%d)", post_retries + 1, MAX_RETRIES);
                post_retries++;
                sleep(BACKOFF_DELAY);
            }
        }

        if (post_retries == MAX_RETRIES) {
            syslog(LOG_ERR, "Data post failed after %d retries", MAX_RETRIES);
        }

        free(json_data);
        sleep(10);
    }

    gpioTerminate();
    closelog();
    return 0;
}

