#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_FAN_STATE 3
#define LOG_FILE "/var/log/fan_control.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, stopping fan and exiting...\n", signum);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    int retries = 3;

    while (retries > 0) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            perror("Error opening temperature file");
            retries--;
            sleep(1); // Wait before retrying
            continue;
        }

        if (fscanf(fp, "%d", &temp) != 1) {
            fprintf(stderr, "Error reading temperature from file\n");
            temp = -1; // Indicate error
        }

        fclose(fp);
        break; // Exit retry loop on success
    }

    if (temp == -1) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    }

    return temp;
}

// Function to set fan speed
int set_fan_speed(int speed) {
    FILE *fp;
    int max_state = -1;
    int retries = 3;

    while (retries > 0) {
        fp = fopen(FAN_FILE, "r");
        if (fp == NULL) {
            perror("Error opening fan file for reading max state");
            retries--;
            sleep(1);
            continue;
        }
        if (fscanf(fp, "%d", &max_state) != 1) {
            fprintf(stderr, "Error reading max state from file\n");
            max_state = -1;
        }
        fclose(fp);
        break;
    }

    if (max_state == -1) {
        fprintf(stderr, "Failed to read max fan state after multiple retries.\n");
        return -1; // Indicate failure
    }

    if (speed > max_state) {
        fprintf(stderr, "Requested fan speed (%d) exceeds maximum allowed (%d).\n", speed, max_state);
        speed = max_state; // Clamp to max
    }

    retries = 3;
    while (retries > 0) {
        fp = fopen(FAN_FILE, "w");
        if (fp == NULL) {
            perror("Error opening fan file for writing");
            retries--;
            sleep(1);
            continue;
        }

