#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK_PIN 11
#define SPI_CS_PIN 8
#define SPI_DO_PIN 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz

// Define PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define TARGET_TEMP 50.0

// Define temperature limits
#define MIN_TEMP -50.0
#define MAX_TEMP 150.0

// Define heater limits
#define MIN_DUTY 0
#define MAX_DUTY 100

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
int read_max31855(uint8_t *data);
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_pwm(int duty_cycle);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    uint8_t data[4];
    int result = read_max31855(data);

    if (result != 0) {
        fprintf(stderr, "Error reading temperature from MAX31855\n");
        return -1000.0; // Indicate error
    }

    // Extract temperature data (bits 31:18, signed 14-bit integer)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(temperature, 0, 0);
        set_heater_pwm(0);
        integral = 0.0;
        previous_error = 0.0;
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        log_data(temperature, 0, 0);
        set_heater_pwm(0);
        integral = 0.0;
        previous_error = 0.0;
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(temperature, 0, 0);
        set_heater_pwm(0);
        integral = 0.0;
        previous_error = 0.0;
        return -1000.0;
    }

    return temperature;
}

// Function to read data from MAX31855 via SPI
int read_max31855(uint8_t *data) {
    char tx_buf[4] = {0, 0, 0, 0}; // Dummy data for reading
    char rx_buf[4];

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        data[i] = rx_buf[i];
    }

    return 0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;

    integral += error;
    if (integral > 100.0) integral = 100.0;
    if (integral < -100.0) integral = -100.0;

    double derivative = error - previous_error;

    double output = (Kp * error) + (Ki * integral) + (Kd * derivative);

    previous_error = error;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < MIN_DUTY) {
        duty_cycle = MIN_DUTY;
    } else if (duty_cycle > MAX_DUTY) {
        duty_cycle = MAX_DUTY;
    }

    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    set_heater_pwm(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK_PIN, PI_INPUT); // SPI CLK is input
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    gpioSetMode(SPI_DO_PIN, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heater control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature > MIN_TEMP && temperature < MAX_TEMP) {
            double pid_output = calculate_pid(TARGET_TEMP, temperature);
            int duty_cycle = (int)pid_output;

            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        } else {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            set_heater_pwm(0);
            log_data(temperature, 0, 0);
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

