#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
float read_cpu_temp();
int calculate_duty_cycle(float temperature);
void set_fan_speed(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down...\n", signal);
    set_fan_speed(0); // Turn off the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)((temperature - 40.0) / (70.0 - 40.0) * 100.0);
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
void set_fan_speed(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle * 2.55) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", duty_cycle);
    }
}

// Function to log data to CSV file
void log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency to 25 kHz
    gpioSetPWMfrequency(GPIO_PIN, 25000);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider a default temperature or previous value here
        } else {
            duty_cycle = calculate_duty_cycle(temperature);
            set_fan_speed(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

