#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// I2C bus
#define I2C_BUS 1

// Continuous measurement command
#define CONT_MEAS_CMD 0x3608

// CRC-8 polynomial
#define CRC8_POLY 0x31

// File to log flow rates
#define LOG_FILE "flow_log.txt"

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int send_command(int handle, int command);
int read_sensor_data(int handle, unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
float convert_to_flow_rate(const unsigned char *data);
int log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Send a command to the sensor
int send_command(int handle, int command) {
    int result = i2cWriteWordData(handle, command >> 8, command & 0xFF);
    if (result < 0) {
        fprintf(stderr, "Error writing command 0x%04x: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, unsigned char *data) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = calculate_crc(data, len - 1);
    return (crc == data[2]);
}

// Convert raw data to flow rate (ml/min)
float convert_to_flow_rate(const unsigned char *data) {
    int raw_value = (data[0] << 8) | data[1];
    return raw_value * 0.01;
}

// Log flow rates to a file
int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C communication for both sensors
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command to both sensors
    if (send_command(i2c_handle1, CONT_MEAS_CMD) < 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (send_command(i2c_handle2, CONT_MEAS_CMD) < 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char data1[3], data2[3];
    float flow1, flow2;

    // Main loop
    while (program_running) {
        // Read sensor data from both sensors
        if (read_sensor_data(i2c_handle1, data1) == 0 && read_sensor_data(i2c_handle2, data2) == 0) {
            // Validate CRC checksums
            if (validate_crc(data1, 3) && validate_crc(data2, 3)) {
                // Convert raw data to flow rates
                flow1 = convert_to_flow_rate(data1);
                flow2 = convert_to_flow_rate(data2);

                // Log flow rates
                if (log_flow_rates(flow1, flow2) != 0) {
                    fprintf(stderr, "Error logging flow rates\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed for one or more sensors\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close I2C handles
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

