#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for Sensor A and Sensor B
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int pulse_count = 0;
static volatile int current_state = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void handle_sensor_a(int gpio, int level, uint32_t tick);
void handle_sensor_b(int gpio, int level, uint32_t tick);
void log_state_change(int state, double angular_position);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int a_pin;
    int b_pin;
    int current_state;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);

    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to handle sensor A state changes
void handle_sensor_a(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        int b_level = gpioRead(SENSOR_B_PIN);
        if (b_level == PI_HIGH) {
            if (current_state == 0) current_state = 1;
            else if (current_state == 3) current_state = 2;
        } else {
            if (current_state == 1) current_state = 0;
            else if (current_state == 2) current_state = 3;
        }
        pulse_count++;
        log_state_change(current_state, (double)pulse_count * 360.0 / PULSES_PER_REVOLUTION);
    }
}

// Function to handle sensor B state changes
void handle_sensor_b(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        int a_level = gpioRead(SENSOR_A_PIN);
        if (a_level == PI_HIGH) {
            if (current_state == 0) current_state = 3;
            else if (current_state == 1) current_state = 2;
        } else {
            if (current_state == 2) current_state = 0;
            else if (current_state == 3) current_state = 1;
        }
        pulse_count++;
        log_state_change(current_state, (double)pulse_count * 360.0 / PULSES_PER_REVOLUTION);
    }
}

// Function to log state changes to a file
void log_state_change(int state, double angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, State: %d, Angular Position: %.2f degrees\n", timestamp, state, angular_position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up interrupt handlers for sensor A and sensor B
    gpioSetAlertFuncEx(SENSOR_A_PIN, handle_sensor_a, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, handle_sensor_b, NULL);

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Do other tasks here if needed
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

