#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1;

// Structure to pass data to the ISR
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} isr_data_t;

// Function prototypes
void isr_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count);
void log_rpm(double rpm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine (ISR)
void isr_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    return (double)pulse_count * 60.0;
}

// Function to log RPM with timestamp
void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, rpm);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    // Register ISR
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return 1;
    }

    time_t start_time = time(NULL);
    while (running) {
        sleep(1);

        int current_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(current_pulse_count);
        log_rpm(rpm);

        printf("RPM: %.2f\n", rpm);
    }

    cleanup();
    return 0;
}

