#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x08
#define RED_CHANNEL_REG 0x0A
#define IR_CHANNEL_REG 0x0C
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_fifo_data(int handle, uint16_t *red, uint16_t *ir);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read red and IR data from the FIFO
int read_fifo_data(int handle, uint16_t *red, uint16_t *ir) {
    char buffer[4];
    int result = i2cReadI2CBlockData(handle, FIFO_DATA_REG, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }

    *red = (uint16_t)((buffer[1] << 8) | buffer[0]);
    *ir = (uint16_t)((buffer[3] << 8) | buffer[2]);

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence by reading PART_ID register
    int part_id = read_register(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x144) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02X, expected 0x144)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADPD144RI sensor found with PART_ID 0x%02X\n", part_id);

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t red, ir;
    while (!terminate) {
        // Read red and IR data
        if (read_fifo_data(i2c_handle, &red, &ir) == 0) {
            // Log data
            log_data(log_file, red, ir);

            // Control LED based on IR threshold
            if (ir > IR_THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn LED on
            } else {
                gpioWrite(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

