#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint8_t *data);
int parse_sensor_data(const uint8_t *data, int *tvoc, int *eco2);
float calculate_iaq(int tvoc, int eco2);
int log_data(FILE *log_file, float iaq, int tvoc, int eco2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to parse sensor data
int parse_sensor_data(const uint8_t *data, int *tvoc, int *eco2) {
    if (data == NULL || tvoc == NULL || eco2 == NULL) {
        fprintf(stderr, "Invalid input to parse_sensor_data\n");
        return -1;
    }

    *tvoc = (data[1] << 8) | data[0];
    *eco2 = (data[6] << 8) | data[5];

    return 0;
}

// Function to calculate IAQ index
float calculate_iaq(int tvoc, int eco2) {
    float iaq = 100.0 - (tvoc / 10.0) - ((eco2 - 400) / 50.0);
    if (iaq < 0.0) {
        iaq = 0.0;
    } else if (iaq > 100.0) {
        iaq = 100.0;
    }
    return iaq;
}

// Function to log data to file
int log_data(FILE *log_file, float iaq, int tvoc, int eco2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,eCO2\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[7];
    int tvoc, eco2;
    float iaq;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            // Parse sensor data
            if (parse_sensor_data(sensor_data, &tvoc, &eco2) == 0) {
                // Calculate IAQ
                iaq = calculate_iaq(tvoc, eco2);

                // Log data
                if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error parsing sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

