#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_PIN 17
#define TOUCH_DURATION 5 // seconds
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int is_tamper_detected(void)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

static void print_intrusion_alert(void)
{
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("INTRUSION ALERT: Tamper detected at %s\n", buf);
}

int main(void)
{
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000L}; // 100ms
    struct timespec touch_start_time = {0, 0};
    int touch_detected = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Tamper detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = is_tamper_detected();
        if (sensor_value < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) {
            if (!touch_detected) {
                clock_gettime(CLOCK_MONOTONIC, &touch_start_time);
                touch_detected = 1;
            } else {
                struct timespec current_time;
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                double elapsed_time = (current_time.tv_sec - touch_start_time.tv_sec) +
                                      (current_time.tv_nsec - touch_start_time.tv_nsec) / 1e9;

                if (elapsed_time >= TOUCH_DURATION) {
                    print_intrusion_alert();
                    touch_detected = 0; // Reset for next event
                }
            }
        } else {
            touch_detected = 0; // Reset on release
        }

        nanosleep(&sleep_time, NULL);
    }

    printf("Exiting gracefully.\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

