#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define ALSA_DEVICE "default" // Or "hw:0,0" if needed
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 24 // Bits
#define NUM_SAMPLES 1024
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_VALUE 0 // Low for left channel

// Global variables
snd_pcm_t *pcm_handle;
FILE *audio_file;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int init_gpio(struct gpiod_chip **gpio_chip, struct gpiod_line **gpio_line);
int set_gpio_output(struct gpiod_line *gpio_line, int value);
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file);
int write_to_file(FILE *audio_file, short *buffer, int num_samples);
void signal_handler(int sig);
void cleanup();

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "Error initializing ALSA. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(&gpio_chip, &gpio_line) != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin to output mode
    if (set_gpio_output(gpio_line, GPIO_VALUE) != 0) {
        fprintf(stderr, "Error setting GPIO output. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen("audio_capture.pcm", "wb");
    if (audio_file == NULL) {
        perror("Error opening audio file");
        cleanup();
        return 1;
    }

    // Capture audio data
    if (capture_audio(pcm_handle, audio_file) != 0) {
        fprintf(stderr, "Error capturing audio. Exiting.\n");
        cleanup();
        return 1;
    }

    // Clean up resources
    cleanup();

    printf("Audio capture complete. File saved as audio_capture.pcm\n");
    return 0;
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        return -1;
    }

    // Set format to 24-bit signed little-endian
    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S24_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting number of channels: %s\n", snd_strerror(err));
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio(struct gpiod_chip **gpio_chip, struct gpiod_line **gpio_line) {
    // Open GPIO chip
    *gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (*gpio_chip == NULL) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line
    *gpio_line = gpiod_chip_get_line(*gpio_chip, GPIO_PIN);
    if (*gpio_line == NULL) {
        perror("Error getting GPIO line");
        gpiod_chip_close(*gpio_chip);
        return -1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(*gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(*gpio_chip);
        return -1;
    }

    return 0;
}

// Set GPIO output value
int set_gpio_output(struct gpiod_line *gpio_line, int value) {
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Capture audio data
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file) {
    short buffer[NUM_SAMPLES];
    int err;
    int i;

    // Capture loop
    while (1) {
        // Read audio data
        if ((err = snd_pcm_readi(pcm_handle, buffer, NUM_SAMPLES)) != NUM_SAMPLES) {
            fprintf(stderr, "Error reading audio data: %s\n", snd_strerror(err));
            return -1;
        }

        // Extract 24-bit data and right-shift to 16-bit
        for (i = 0; i < NUM_SAMPLES; i++) {
            buffer[i] = (short)((buffer[i] >> 8) & 0xFFFF); // Right-shift by 8 bits and mask to 16 bits
        }

        // Write to file
        if (write_to_file(audio_file, buffer, NUM_SAMPLES) != 0) {
            fprintf(stderr, "Error writing to file.\n");
            return -1;
        }
    }

    return 0;
}

// Write audio data to file
int write_to_file(FILE *audio_file, short *buffer, int num_samples) {
    size_t bytes_written = fwrite(buffer, sizeof(short), num_samples, audio_file);
    if (bytes_written != num_samples) {
        perror("Error writing to file");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Clean up resources
void cleanup() {
    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }
    if (audio_file != NULL) {
        fclose(audio_file);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

