#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define data parameters
#define NUM_CHIRPS 64
#define NUM_SAMPLES 256
#define FRAME_SIZE (NUM_CHIRPS * NUM_SAMPLES * 2) // 2 bytes per complex sample (real + imag)

// Define file parameters
#define LOG_FILE_NAME "radar_data.bin"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    uint64_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to configure GPIO pins
int configure_gpio() {
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN); // Pull-down resistor
    return 0;
}

// Function to write the log file header
int write_log_file_header() {
    uint32_t magic_number = 0x52444144; // "RAD4"
    config_t config = {
        .timestamp = (uint64_t)time(NULL),
        .start_frequency = 7700000000, // 77 GHz
        .end_frequency = 7900000000,   // 79 GHz
        .num_chirps = NUM_CHIRPS,
        .num_samples = NUM_SAMPLES,
        .frame_period_ms = 100
    };

    if (fwrite(&magic_number, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing magic number to log file\n");
        return -1;
    }

    if (fwrite(&config.timestamp, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }

    if (fwrite(&config, sizeof(config_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing config struct to log file\n");
        return -1;
    }

    return 0;
}

// Function to read data from SPI
int read_spi_data(uint8_t *buffer, int count) {
    int result = spiXfer(spi_handle, buffer, buffer, count);
    if (result != count) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to write data to log file
int write_to_log_file(uint8_t *data, int data_len) {
    uint64_t timestamp = (uint64_t)time(NULL);
    uint32_t frame_number = 0; // Increment this for each frame

    if (fwrite(&timestamp, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }

    if (fwrite(&frame_number, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Error writing frame number to log file\n");
        return -1;
    }

    if (fwrite(data, sizeof(uint8_t), data_len, log_file) != data_len) {
        fprintf(stderr, "Error writing data to log file\n");
        return -1;
    }

    frame_number++; // Increment frame number for next frame
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pins
    if (configure_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write log file header
    if (write_log_file_header() != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t *data_buffer = malloc(FRAME_SIZE);
    if (data_buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Wait for data ready interrupt
        while (gpioRead(DATA_READY_PIN) == 0 && !terminate) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (terminate) break;

        // Read data from SPI
        if (read_spi_data(data_buffer, FRAME_SIZE) == 0) {
            // Write data to log file
            if (write_to_log_file(data_buffer, FRAME_SIZE) != 0) {
                fprintf(stderr, "Error writing data to log file\n");
                break;
            }
        } else {
            fprintf(stderr, "Error reading SPI data\n");
            break;
        }

        // Wait for the next frame
        gpioDelay(100); // 100 ms frame period
    }

    // Cleanup
    free(data_buffer);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated successfully\n");
    return 0;
}

