#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int bus;
    int address;
    int config_value;
} opt3001_config_t;

// Function prototypes
int configure_opt3001(int i2c_handle, int config_value);
int read_opt3001_result(int i2c_handle, unsigned int *raw_result);
float calculate_lux(unsigned int raw_result);
int log_data(float lux_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to configure the OPT3001
int configure_opt3001(int i2c_handle, int config_value) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error configuring OPT3001 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "Failed to configure OPT3001 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to read the result from the OPT3001
int read_opt3001_result(int i2c_handle, unsigned int *raw_result) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, RESULT_REG);
        if (result >= 0) {
            *raw_result = (unsigned int)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading OPT3001 result (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "Failed to read OPT3001 result after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to calculate lux value
float calculate_lux(unsigned int raw_result) {
    int exponent = (raw_result >> 12) & 0x0F;
    int mantissa = raw_result & 0x0FFF;
    return 0.01 * (1 << exponent) * mantissa;
}

// Function to log data to file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001(i2c_handle, 0xCB10) != 0) { // Continuous mode, 100ms conversion time, auto-range
        fprintf(stderr, "OPT3001 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    unsigned int raw_result;
    float lux_value;
    while (!terminate) {
        // Read result from OPT3001
        if (read_opt3001_result(i2c_handle, &raw_result) == 0) {
            // Calculate lux value
            lux_value = calculate_lux(raw_result);

            // Log data
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read OPT3001 result.\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

