#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define GPIO_BIAS "pull-up"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    struct gpiod_line_request_config config;
    struct gpiod_line_settings settings;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as input\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&settings, 0, sizeof(settings));
    settings.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_config(line, &settings) < 0) {
        fprintf(stderr, "Error: Could not configure GPIO line %d with pull-up\n", GPIO_LINE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct timespec sleep_time = {1, 0}; // 1 second
    int value;

    signal(SIGINT, signal_handler);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Flame detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read GPIO line value\n");
            break;
        }

        if (value == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("Flame Detected: YES at %s\n", timestamp);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("Flame Detected: NO at %s\n", timestamp);
        }

        nanosleep(&sleep_time, NULL);
    }

    printf("Exiting gracefully.\n");
    cleanup_gpio();

    return EXIT_SUCCESS;
}

