#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 18
#define RIGHT_SENSOR 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LEFT_SENSOR as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set CENTER_SENSOR as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set RIGHT_SENSOR as input\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read sensor values
    while (!terminate) {
        // Read sensor values
        int left_value = gpioRead(LEFT_SENSOR);
        int center_value = gpioRead(CENTER_SENSOR);
        int right_value = gpioRead(RIGHT_SENSOR);

        // Print sensor values to console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

