#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the touch sensor channels
const int touch_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    int i, state;
    long long start_time, current_time;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure GPIO pins as inputs with pull-down resistors
    for (i = 0; i < num_channels; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (1) {
        start_time = gpioTick();
        printf("[%+lld ms] ", start_time / 1000);

        for (i = 0; i < num_channels; i++) {
            state = gpioRead(touch_pins[i]);
            printf("CH%d=%d ", i + 1, state);
        }
        printf("\n");

        gpioDelay(100000); // 100 ms delay
    }

    // This point should not be reached due to the signal handler
    gpioTerminate();
    return 0;
}

