// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop to read sensor states and log data
    while (program_running) {
        // Read the state of each sensor
        int sensor1_state = gpioRead(SENSOR_1_GPIO);
        int sensor2_state = gpioRead(SENSOR_2_GPIO);

        // Log the sensor states to the console
        printf("Sensor 1: %s, Sensor 2: %s\n",
               sensor1_state == 0 ? "LOW" : "HIGH",
               sensor2_state == 0 ? "LOW" : "HIGH");

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

