#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_CHIP "gpiochip0"
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS] = {NULL};
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
static void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO-8601 format
static char *get_iso8601_timestamp(char *buf, size_t buf_size)
{
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return buf;
}

// Function to read the state of all channels
static int read_channels(int *channel_states)
{
    int i, ret;
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_get_value(lines[i]);
        if (ret < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", i, strerror(-ret));
            return -1;
        }
        channel_states[i] = ret;
    }
    return 0;
}

int main()
{
    int i, ret;
    char timestamp[32];
    int channel_states[NUM_CHANNELS];

    // Install signal handler for SIGINT
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Request lines for each channel
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 2); // GPIO lines 2-9
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", i + 2, strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226_monitor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", i + 2, strerror(-ret));
            goto cleanup;
        }
    }

    // Main loop
    while (!terminate) {
        // Read channel states
        if (read_channels(channel_states) != 0) {
            fprintf(stderr, "Error reading channels, exiting.\n");
            goto cleanup;
        }

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Print CSV line
        printf("%s", timestamp);
        for (i = 0; i < NUM_CHANNELS; i++) {
            printf(",%d", channel_states[i]);
        }
        printf("\n");

        // Wait for the next poll interval
        usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

cleanup:
    // Release lines and chip resources
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

