#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define POLL_INTERVAL_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int gpio_read_result;
    int previous_state = -1; // Initialize to an invalid state
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main polling loop
    while (program_running) {
        // Read GPIO pin state
        gpio_read_result = gpioRead(GPIO_PIN);

        if (gpio_read_result < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, gpio_read_result);
            // Attempt to recover by re-initializing pigpio
            gpioTerminate();
            pigpio_init_result = gpioInitialise();
            if (pigpio_init_result < 0) {
                fprintf(stderr, "pigpio re-initialisation failed: %d\n", pigpio_init_result);
                break; // Exit loop if re-initialization fails
            }
            gpioSetMode(GPIO_PIN, PI_INPUT);
            gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
            gpio_read_result = gpioRead(GPIO_PIN); // Retry reading
            if (gpio_read_result < 0) {
                fprintf(stderr, "Failed to read GPIO after re-initialization: %d\n", gpio_read_result);
                break; // Exit loop if retry fails
            }
        }

        // Check for state change
        if (gpio_read_result != previous_state) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log message to console
            if (gpio_read_result == 0) {
                printf("%s: Tilted\n", timestamp);
            } else {
                printf("%s: Not Tilted\n", timestamp);
            }

            fflush(stdout); // Flush output to ensure immediate display

            // Update previous state
            previous_state = gpio_read_result;
        }

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

