                printf("%s: Not Tilted\n", timestamp);
            }

            fflush(stdout); // Flush output to ensure immediate display

            // Update previous state
            previous_state = gpio_read_result;
        }

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

