#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define ALARM_GPIO 17
#define FLOW_SCALE_FACTOR 0.036
#define FLOW_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, float *flow_rate);
float convert_flow_rate(uint16_t raw_flow);
uint8_t calculate_crc(const uint8_t *data, size_t len);
void log_data(float flow1, float flow2, float avg_flow);
void control_alarm(float avg_flow);
void signal_handler(int signal);

// CRC calculation function (from Sensirion datasheet)
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize sensor function
int initialize_sensor(int i2c_handle) {
    char cmd[2] = {0x08, 0x36};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(100); // Wait 100ms
    return 0;
}

// Read sensor data function
int read_sensor_data(int i2c_handle, float *flow_rate) {
    char buffer[9];
    if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Extract flow data (bytes 0-1 and 3-4, combined into a 16-bit value)
    uint16_t raw_flow = (buffer[0] << 8) | buffer[1];

    // CRC validation
    uint8_t crc_flow = calculate_crc((uint8_t *)buffer, 2);
    if (crc_flow != buffer[2]) {
        fprintf(stderr, "CRC check failed for flow data.\n");
        return -1;
    }

    *flow_rate = convert_flow_rate(raw_flow);
    return 0;
}

// Convert flow rate function
float convert_flow_rate(uint16_t raw_flow) {
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Log data function
void log_data(float flow1, float flow2, float avg_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min, Average: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2, avg_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control alarm function
void control_alarm(float avg_flow) {
    if (avg_flow < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1) != 0 || initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2, avg_flow;
    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &flow1) != 0) {
            flow1 = 0.0; // Set to 0 if read fails
        }
        if (read_sensor_data(i2c_handle2, &flow2) != 0) {
            flow2 = 0.0; // Set to 0 if read fails
        }

        // Calculate average flow rate
        avg_flow = (flow1 + flow2) / 2.0;

        // Log data
        log_data(flow1, flow2, avg_flow);

        // Control alarm
        control_alarm(avg_flow);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

