#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and reading
typedef struct {
    time_t timestamp;
    int reading;
} Reading;

// Circular buffer
Reading readingBuffer[BUFFER_SIZE];
int bufferIndex = 0;
int bufferFull = 0;

// Function prototypes
int initializeGPIO();
int readSensor();
void addToBuffer(time_t timestamp, int reading);
void printBuffer();
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        printBuffer();
        gpioTerminate();
        exit(0);
    }
}

// Initializes the pigpio library and configures the GPIO pin
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0; // Indicate success
}

// Reads the sensor value from the specified GPIO pin
int readSensor() {
    return gpioRead(GPIO_PIN);
}

// Adds a reading to the circular buffer
void addToBuffer(time_t timestamp, int reading) {
    readingBuffer[bufferIndex].timestamp = timestamp;
    readingBuffer[bufferIndex].reading = reading;
