#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define MODE_CONTROL_REG 0x1D
#define ACTIVE_MODE 0x10
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_MSB_REG 0x2A
#define ACCEL_Y_MSB_REG 0x2C
#define ACCEL_Z_MSB_REG 0x2E
#define ACCEL_SCALE 0.0009765625 // g/LSB
#define SAMPLE_INTERVAL_MS 500
#define TIMEOUT_SEC 1

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int initialize_sensor(int fd);
int read_sensor_data(int fd, sensor_data_t *data);
void convert_to_g(sensor_data_t *data);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(const char *timestamp, sensor_data_t data);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        }
        perror("I2C write failed");
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, value, 1) == 1) {
                return 0; // Success
            }
        }
        perror("I2C read failed");
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read block function with retry
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, data, len) == len) {
                return 0; // Success
            }
        }
        perror("I2C read block failed");
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C read block failed after multiple retries.\n");
    return -1; // Failure
}

// Initialize the sensor
int initialize_sensor(int fd) {
    if (i2c_write(fd, MODE_CONTROL_REG, ACTIVE_MODE) != 0) {
        fprintf(stderr, "Failed to set active mode.\n");
        return -1;
    }

    // Wait for the sensor to become active
    uint8_t status;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        if (i2c_read(fd, OPERATING_STATUS_REG, &status) != 0) {
            fprintf(stderr, "Failed to read operating status.\n");
            return -1;
        }

        if ((status & 0x01) == 0x01) {
            break; // Active mode
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        if (elapsed_time >= TIMEOUT_SEC) {
            fprintf(stderr, "Sensor did not become active within timeout period.\n");
            return -1;
        }

        usleep(10000); // 10ms delay
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t raw_data[6];

    if (i2c_read_block(fd, ACCEL_X_MSB_REG, raw_data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    data->x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    data->y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    data->z = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    return 0;
}

// Convert raw data to g
void convert_to_g(sensor_data_t *data) {
    data->x *= ACCEL_SCALE;
    data->y *= ACCEL_SCALE;
    data->z *= ACCEL_SCALE;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_str;
}

// Log data to CSV file
int log_data(const char *timestamp, sensor_data_t data) {
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file is not open.\n");
        return -1;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }

    sensor_data_t sensor_data;
    char timestamp_str[32];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Convert to g
            convert_to_g(&sensor_data);

            // Get timestamp
            get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

            // Log data
            if (log_data(timestamp_str, sensor_data) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data in main loop.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500ms
    }

    // Close I2C bus and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

