#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int init_result;
    int sensor1_value, sensor2_value;
    int led_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio library
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Set GPIO modes
    int mode_result1 = gpioSetMode(SENSOR1_PIN, PI_INPUT);
    int mode_result2 = gpioSetMode(SENSOR2_PIN, PI_INPUT);
    int mode_result3 = gpioSetMode(LED_PIN, PI_OUTPUT);

    if (mode_result1 != 0 || mode_result2 != 0 || mode_result3 != 0) {
        fprintf(stderr, "Failed to set GPIO mode. gpioSetMode returned: %d, %d, %d\n", mode_result1, mode_result2, mode_result3);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1_value = gpioRead(SENSOR1_PIN);
        sensor2_value = gpioRead(SENSOR2_PIN);

        // Check for errors during gpioRead
        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor value. gpioRead returned: %d, %d\n", sensor1_value, sensor2_value);
            break; // Exit loop on error
        }

        // Check if either sensor detects an obstacle
        if (sensor1_value == 0 || sensor2_value == 0) {
            // Obstacle detected, turn LED ON
            if (led_state == 0) {
                int write_result = gpioWrite(LED_PIN, 1);
                if (write_result != 0) {
                    fprintf(stderr, "Error writing to LED. gpioWrite returned: %d\n", write_result);
                    break; // Exit loop on error
                }
                led_state = 1;
            }
        } else {
            // No obstacle detected, turn LED OFF
            if (led_state == 1) {
                int write_result = gpioWrite(LED_PIN, 0);
                if (write_result != 0) {
                    fprintf(stderr, "Error writing to LED. gpioWrite returned: %d\n", write_result);
                    break; // Exit loop on error
                }
                led_state = 0;
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

