#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x0E
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x8D
#define CONFIG_REG 0x01
#define X_AXIS_DATA_REG 0x02
#define Y_AXIS_DATA_REG 0x04
#define Z_AXIS_DATA_REG 0x06
#define SCALE_FACTOR 0.00025 // 50 mT range, 2^15 counts
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "magnetic_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mT(int16_t raw_value);
int log_data(float x_mT, float y_mT, float z_mT);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x%02X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }
    printf("Device ID verified successfully.\n");
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Enable continuous conversion mode and all axes
    int status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x07); // Example configuration
    if (status < 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", status);
        return -1;
    }
    printf("Sensor configured successfully.\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, X_AXIS_DATA_REG, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw data to mT
float convert_to_mT(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Log data to CSV file
int log_data(float x_mT, float y_mT, float z_mT) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_mT, y_mT, z_mT);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    int16_t x_raw, y_raw, z_raw;
    float x_mT, y_mT, z_mT;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to mT
            x_mT = convert_to_mT(x_raw);
            y_mT = convert_to_mT(y_raw);
            z_mT = convert_to_mT(z_raw);

            // Log data
            log_data(x_mT, y_mT, z_mT);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

