#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL 2 // seconds

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor
    return 0;
}

int read_sensor() {
    return gpioRead(GPIO_PIN);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("%s %s\n", timestamp, message);
}

void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("Daemon started");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            log_event("ALERT: Water detected");
        } else if (sensor_value < 0) {
            log_event("ERROR: Failed to read sensor, retrying...");
            gpioTerminate();
            sleep(60); // Wait 60 seconds before retrying
            if (initialize_gpio() != 0) {
                log_event("ERROR: Failed to re-initialize GPIO, exiting.");
                running = 0; // Exit loop if re-initialization fails
            }
        }

        sleep(POLL_INTERVAL);
    }

    log_event("Daemon stopped");
    cleanup();
    return 0;
}

