    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("Daemon started");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            log_event("ALERT: Water detected");
        } else if (sensor_value < 0) {
            log_event("ERROR: Failed to read sensor, retrying...");
