#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define rotation direction enum
enum RotationDirection {
    CW,
    CCW,
    NO_ROTATION
};

// Define sensor state enum
enum SensorState {
    SENSOR_A,
    SENSOR_B,
    SENSOR_A_AND_B,
    SENSOR_NONE
};

// Define mutex and condition variable
pthread_mutex_t mutex;
pthread_cond_t condition;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    enum SensorState state;
    long long timestamp;
} SensorData;

SensorData sensor_data = {SENSOR_NONE, 0};

// Function prototypes
void signal_handler(int signal);
void log_rotation(enum RotationDirection direction);
void sensor_a_callback(int gpio, int level, uint32_t tick);
void sensor_b_callback(int gpio, int level, uint32_t tick);
void *log_thread(void *arg);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Log rotation function
void log_rotation(enum RotationDirection direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec spec;

    clock_gettime(CLOCK_REALTIME, &spec);
    rawtime = spec.tv_sec;
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", spec.tv_nsec / 1000000);

    fprintf(log_file, "%s: ", timestamp);
    switch (direction) {
        case CW:
            fprintf(log_file, "CW\n");
            break;
        case CCW:
            fprintf(log_file, "CCW\n");
            break;
        case NO_ROTATION:
            fprintf(log_file, "No Rotation\n");
            break;
    }
    fflush(log_file);
}

// Sensor A callback function
void sensor_a_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    long long current_time = gpioTick();
    if (level == PI_HIGH) {
        if (sensor_data.state == SENSOR_NONE) {
            sensor_data.state = SENSOR_A;
            sensor_data.timestamp = current_time;
        } else if (sensor_data.state == SENSOR_B) {
            if (current_time - sensor_data.timestamp > 5000) { // Debounce
                sensor_data.state = SENSOR_A_AND_B;
                sensor_data.timestamp = current_time;
            } else {
                sensor_data.state = SENSOR_A;
                sensor_data.timestamp = current_time;
            }
        } else {
            sensor_data.state = SENSOR_A;
            sensor_data.timestamp = current_time;
        }
    } else {
        sensor_data.state = SENSOR_NONE;
    }
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&condition);
}

// Sensor B callback function
void sensor_b_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    long long current_time = gpioTick();
    if (level == PI_HIGH) {
        if (sensor_data.state == SENSOR_NONE) {
            sensor_data.state = SENSOR_B;
            sensor_data.timestamp = current_time;
        } else if (sensor_data.state == SENSOR_A) {
            if (current_time - sensor_data.timestamp > 5000) { // Debounce
                sensor_data.state = SENSOR_A_AND_B;
                sensor_data.timestamp = current_time;
            } else {
                sensor_data.state = SENSOR_B;
                sensor_data.timestamp = current_time;
            }
        } else {
            sensor_data.state = SENSOR_B;
            sensor_data.timestamp = current_time;
        }
    } else {
        sensor_data.state = SENSOR_NONE;
    }
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&condition);
}

// Log thread function
void *log_thread(void *arg) {
    while (program_running) {
        pthread_mutex_lock(&mutex);
        while (sensor_data.state == SENSOR_NONE && program_running) {
            pthread_cond_wait(&condition, &mutex);
        }
        pthread_mutex_unlock(&mutex);

        if (!program_running) break;

        enum RotationDirection direction = NO_ROTATION;
        pthread_mutex_lock(&mutex);
        if (sensor_data.state == SENSOR_A_AND_B) {
            if (sensor_data.timestamp > 5000) {
                direction = CW;
            } else {
                direction = CCW;
            }
        }
        pthread_mutex_unlock(&mutex);

        if (direction != NO_ROTATION) {
            log_rotation(direction);
        }
    }
    pthread_exit(NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }
    if (pthread_cond_init(&condition, NULL) != 0) {
        fprintf(stderr, "Condition variable initialization failed\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rotation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&mutex);
        pthread_cond_destroy(&condition);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert functions
    gpioSetAlertFuncEx(SENSOR_A_PIN, sensor_a_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, sensor_b_callback, NULL);

    // Create log thread
    pthread_t log_thread_id;
    if (pthread_create(&log_thread_id, NULL, log_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create log thread\n");
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        pthread_cond_destroy(&condition);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up
    pthread_join(log_thread_id, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&condition);
    gpioTerminate();

    return 0;
}

