#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *touch_line;
struct gpiod_line *led_line;

// Function prototypes
int init_gpio(void);
int read_touch_sensor(void);
void control_led(int state);
void signal_handler(int sig);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    control_led(0); // Turn off LED
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        log_message(LOG_ERR, "Failed to get touch sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request touch sensor line for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(touch_line, &config, 0) < 0) {
        log_message(LOG_ERR, "Failed to request touch sensor line for input");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_message(LOG_ERR, "Failed to get LED line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        log_message(LOG_ERR, "Failed to request LED line for output");
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read touch sensor value
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read touch sensor value");
        return -1;
    }
    return value;
}

// Control LED state
void control_led(int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        log_message(LOG_ERR, "Failed to set LED value");
    }
}

// Log message to syslog
void log_message(int priority, const char *message) {
    time_t now;
    time(&now);
