    int led_state;
    struct timespec last_touch_time;
};

struct program_state state = {0, {0, 0}}; // Initialize led_state to 0 and last_touch_time to 0

int main(void) {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
