#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Structure to store log events
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEvent;

// Global variables
volatile sig_atomic_t program_running = 1;
int overflow_count = 0;
LogEvent log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read sensor value from pin %d\n", pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to LED pin %d\n", pin);
    }
}

// Function to log events
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].state = state;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;

    if (log_index == 0) {
        overflow_count++;
    }
}

// Function to print log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (log_index + i) % LOG_BUFFER_SIZE; // Corrected index calculation
        printf("Event %d: Sensor Pin = %d, Timestamp = %ld, State = %d\n",
               i + 1, log_buffer[index].sensor_pin, log_buffer[index].timestamp, log_buffer[index].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
    printf("--- End of Log Buffer ---\n\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    int sensor1_state = 0;
    int sensor2_state = 0;

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Handle error, maybe exit or retry
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (sensor1_value != sensor1_state) {
            log_event(SENSOR_1_PIN, sensor1_value);
            control_led(LED_1_PIN, sensor1_value);
            sensor1_state = sensor1_value;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        if (sensor2_value != sensor2_state) {
            log_event(SENSOR_2_PIN, sensor2_value);
            control_led(LED_2_PIN, sensor2_value);
            sensor2_state = sensor2_value;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    print_log_buffer();
    gpioTerminate();

    return 0;
}

