    int sensor1_state = 0;
    int sensor2_state = 0;

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Handle error, maybe exit or retry
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (sensor1_value != sensor1_state) {
            log_event(SENSOR_1_PIN, sensor1_value);
            control_led(LED_1_PIN, sensor1_value);
            sensor1_state = sensor1_value;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        if (sensor2_value != sensor2_state) {
            log_event(SENSOR_2_PIN, sensor2_value);
            control_led(LED_2_PIN, sensor2_value);
            sensor2_state = sensor2_value;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    print_log_buffer();
    gpioTerminate();

    return 0;
}

