#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// File to log sensor data
#define LOG_FILE "shaft_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} sensor_states_t;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_sensor_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)tick; // Suppress unused parameter warning
    (void)user_data; // Suppress unused parameter warning

    if (gpio == SENSOR1_GPIO) {
        log_sensor_data(level, ((sensor_states_t*)user_data)->sensor2_state);
    } else if (gpio == SENSOR2_GPIO) {
        log_sensor_data(((sensor_states_t*)user_data)->sensor1_state, level);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Initialize sensor states
    sensor_states_t sensor_states = {0, 0};

    // Set up interrupts for both sensors
    if (gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, DEBOUNCE_TIME, sensor_callback, &sensor_states) < 0) {
        fprintf(stderr, "Failed to set ISR for SENSOR1_GPIO: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }
    if (gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, DEBOUNCE_TIME, sensor_callback, &sensor_states) < 0) {
        fprintf(stderr, "Failed to set ISR for SENSOR2_GPIO: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to log sensor data to file
void log_sensor_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    printf("Monitoring RPM... Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Check every second
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

