#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor I2C address and registers
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_DATA_REG 0x02
#define SPO2_DATA_REG 0x04

// Define configuration values
#define CONTINUOUS_MODE 0x01

// Global variables for graceful shutdown
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the Si1182 sensor
int init_si1182(int i2c_handle) {
    int status;

    // Verify sensor presence by reading PART_ID register
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", status);
        return -1;
    }
    if (status != 0x82) { // Expected PART_ID for Si1182
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x82)\n", status);
        return -1;
    }
    printf("Si1182 sensor found with PART_ID: 0x%02X\n", status);

    // Configure the sensor for continuous measurement mode
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, CONTINUOUS_MODE);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", status);
        return -1;
    }
    printf("Sensor configured for continuous mode\n");

    return 0;
}

// Function to read heart rate and SpO2 data from the sensor
int read_sensor_data(int i2c_handle, int *heart_rate, int *spo2) {
    int hr_status, spo2_status;

    hr_status = i2cReadByteData(i2c_handle, HR_DATA_REG);
    if (hr_status < 0) {
        fprintf(stderr, "Error reading HR_DATA register: %d\n", hr_status);
        return -1;
    }
    *heart_rate = hr_status;

    spo2_status = i2cReadByteData(i2c_handle, SPO2_DATA_REG);
    if (spo2_status < 0) {
        fprintf(stderr, "Error reading SPO2_DATA register: %d\n", spo2_status);
        return -1;
    }
    *spo2 = spo2_status;

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int heart_rate, spo2;
    int status;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1182(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(i2c_handle, &heart_rate, &spo2);
        if (status == 0) {
            // Log the data
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

