#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_L 0x28
#define ACCEL_Y_L 0x2A
#define ACCEL_Z_L 0x2C
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500.0f
#define POLLING_INTERVAL_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void control_led(int on);
void log_event(float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    // Clear power-down bit in CTRL1 register
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00); // Example value, check datasheet
        if (status >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL1 register (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10); // Small delay before retry
        }
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Reads acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, ACCEL_X_L, buffer, 6);
        if (status == 6) {
            // Combine high and low bytes for each axis
            int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert to g-force units (adjust scale factor as needed)
            *x = (float)raw_x / 1000.0f; // Example scale factor
            *y = (float)raw_y / 1000.0f;
            *z = (float)raw_z / 1000.0f;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10); // Small delay before retry
        }
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculates the Euclidean magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Controls the LED (on/off)
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Logs the event to a file
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check threshold and control LED
            if (magnitude > VIBRATION_THRESHOLD) {
                control_led(1); // Turn LED on
                log_event(magnitude);
                gpioDelay(1000); // Wait for 1 second
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(POLLING_INTERVAL_MS); // Poll every 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

