#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18

// Define chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor_lines[4];
struct gpiod_line *led_line;

// Function prototypes
int read_sensor(int pin);
int check_any_obstacle(void);
int set_led(int state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 4; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor data
int read_sensor(int pin) {
    int value;
    int ret;

    ret = gpiod_line_get_value(sensor_lines[pin - 4]);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    value = (ret == 0) ? 1 : 0; // Active low
    return value;
}

// Function to check if any obstacle is detected
int check_any_obstacle(void) {
    for (int i = 0; i < 4; i++) {
        if (read_sensor(4 + i) == 1) {
            return 1; // Obstacle detected
        }
    }
    return 0; // No obstacle detected
}

// Function to set LED state
int set_led(int state) {
    int ret;

    ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED state: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines for sensors
    for (int i = 0; i < 4; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, 4 + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", 4 + i, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(sensor_lines[i], "obstacle_sensor") < 0) {
            fprintf(stderr, "Error requesting sensor line %d as input: %s\n", 4 + i, strerror(errno));
            goto cleanup;
        }
    }

    // Request GPIO line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "obstacle_led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    // Main loop
    while (1) {
        int obstacle_detected = check_any_obstacle();
        if (set_led(obstacle_detected) < 0) {
            goto cleanup;
        }

        usleep(50000); // 50 ms delay
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < 4; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

