        usleep(50000); // 50 ms delay
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < 4; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
