#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[5] = {NULL}; // Array to hold line pointers

// Function prototypes
int read_sensor(int gpio);
int log_event(int gpio);
void signal_handler(int sig);
int acquire_lines(int gpios[], int num_gpios);
void release_lines(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read the sensor value
int read_sensor(int gpio) {
    int value;
    int ret;

    ret = gpiod_line_get_value(lines[gpio - 2]); // Index into lines array
    if (ret < 0) {
        syslog(LOG_ERR, "Error reading GPIO %d: %s", gpio, strerror(-ret));
        return -1; // Indicate error
    }
    value = ret; // Direct assignment, gpiod_line_get_value returns 0 or 1

    return value;
}

// Function to log the event
int log_event(int gpio) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;
    char timestamp[30];
    int ret;

    // Get current time
    time(&t);
    tm_info = gmtime(&t);

    // Format timestamp in ISO 8601 UTC format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file: %s", strerror(errno));
        return -1; // Indicate error
    }

    // Acquire an exclusive lock on the file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Error acquiring lock on log file: %s", strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    // Write the event to the log file
    ret = fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, gpio, gpio);
    if (ret < 0) {
        syslog(LOG_ERR, "Error writing to log file: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1; // Indicate error
    }

    // Flush the buffer to ensure immediate write
    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "Error flushing log file: %s", strerror(errno));
    }

    // Release the lock on the file
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Error releasing lock on log file: %s", strerror(errno));
    }

    // Close the log file
    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "Error closing log file: %s", strerror(errno));
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to acquire lines from the GPIO chip
int acquire_lines(int gpios[], int num_gpios) {
    int i, ret;

    for (i = 0; i < num_gpios; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Error getting line for GPIO %d: %s", gpios[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            return -1; // Indicate error
        }

        ret = gpiod_line_request_input(lines[i], "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Error requesting line for GPIO %d: %s", gpios[i], strerror(-ret));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            return -1; // Indicate error
        }
    }
    return 0;
}

// Function to release lines
void release_lines(void) {
    int i;

    for (i = 0; i < 5; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL; // Reset the pointer
        }
    }
}

int main() {
    int gpios[] = {GPIO_2, GPIO_3, GPIO_4, GPIO_17, GPIO_27};
    int i, ret;
    int sensor_values[5];
    int last_values[5] = {1, 1, 1, 1, 1}; // Initialize to 1 (no flame)

    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    // Acquire lines
    if (acquire_lines(gpios, 5) != 0) {
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Flame monitor started");

    // Main loop
    while (!terminate) {
        for (i = 0; i < 5; i++) {
            sensor_values[i] = read_sensor(gpios[i]);
            if (sensor_values[i] < 0) {
                syslog(LOG_ERR, "Error reading sensor %d, skipping", gpios[i]);
                continue; // Skip to the next sensor
            }

            // Check for rising edge (flame detected)
            if (sensor_values[i] == 0 && last_values[i] == 1) {
                // Debounce
                usleep(DEBOUNCE_TIME_MS * 1000); // Convert ms to microseconds
                if (read_sensor(gpios[i]) == 0) { // Re-read to confirm
                    if (log_event(gpios[i]) != 0) {
                        syslog(LOG_ERR, "Error logging event for sensor %d", gpios[i]);
                    }
                }
            }

            last_values[i] = sensor_values[i]; // Update last value
        }

        sleep(1); // Poll every 1 second
    }

    // Release lines
    release_lines();

    // Close the GPIO chip
    if (gpiod_chip_close(chip) != 0) {
        syslog(LOG_ERR, "Error closing GPIO chip: %s", strerror(errno));
    }

    syslog(LOG_INFO, "Flame monitor stopped");

    // Close syslog
    closelog();

    return EXIT_SUCCESS;
}

