#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int touch_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_touch_pins = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Global variables for signal handling and GPIO chip
static volatile int running = 1;
static int gpio_chip = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpio_chip = gpioInitialise();
    if (gpio_chip < 0) {
        fprintf(stderr, "pigpio chip initialisation failed: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    for (int i = 0; i < num_touch_pins; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %s\n", touch_pins[i], strerror(errno));
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of all touch sensor pins
int* read_touch_sensors() {
    int* sensor_states = (int*)malloc(num_touch_pins * sizeof(int));
    if (sensor_states == NULL) {
        fprintf(stderr, "Failed to allocate memory for sensor states: %s\n", strerror(errno));
        return NULL;
    }

    for (int i = 0; i < num_touch_pins; i++) {
        sensor_states[i] = gpioRead(touch_pins[i]);
        if (sensor_states[i] < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", touch_pins[i], strerror(errno));
            free(sensor_states);
            return NULL;
        }
    }

    return sensor_states;
}

// Function to log the state of a touch sensor
void log_touch_state(int sensor_index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s - Sensor %d (BCM %d): %s\n", timestamp, sensor_index, pin, state ? "Touched" : "Released");
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    int* previous_states = (int*)malloc(num_touch_pins * sizeof(int));
    if (previous_states == NULL) {
        fprintf(stderr, "Failed to allocate memory for previous states: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize previous states to 0 (released)
    for (int i = 0; i < num_touch_pins; i++) {
        previous_states[i] = 0;
    }

    // Main loop to continuously monitor the touch sensor states
    while (running) {
        int* current_states = read_touch_sensors();
        if (current_states == NULL) {
            break; // Exit loop if read failed
        }

        for (int i = 0; i < num_touch_pins; i++) {
            if (current_states[i] != previous_states[i]) {
                log_touch_state(i, touch_pins[i], current_states[i]);
                previous_states[i] = current_states[i];
            }
        }

        free(current_states);
        gpioDelay(50000); // Wait 50 milliseconds
    }

    // Clean up and exit
    free(previous_states);
    gpioTerminate();
    return 0;
}

