#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int configure_sensor();
int read_lux();
float calculate_lux(uint16_t raw_als);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the VEML7700 sensor
int configure_sensor() {
    uint16_t config_value = 0x0000; // ALS gain 1/8, ALS integration time 100ms
    char buf[2];
    buf[0] = config_value & 0xFF; // Low byte
    buf[1] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ambient light from the sensor
int read_lux() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read ALS register: %d\n", result);
        return -1;
    }

    uint16_t raw_als = (buf[1] << 8) | buf[0];
    return raw_als;
}

// Calculate lux value
float calculate_lux(uint16_t raw_als) {
    return raw_als * 0.0576;
}

// Set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness = 0;

    if (lux < 100) {
        brightness = PWM_RANGE;
    } else if (lux < 500) {
        brightness = PWM_RANGE * 0.75;
    } else if (lux < 1000) {
        brightness = PWM_RANGE * 0.5;
    } else {
        brightness = PWM_RANGE * 0.25;
    }

    gpioPWM(LED_GPIO, brightness);
    return brightness;
}

