    uint16_t config_value = 0x0000; // ALS gain 1/8, ALS integration time 100ms
    char buf[2];
    buf[0] = config_value & 0xFF; // Low byte
    buf[1] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
