// Define GPIO pins for the touch sensors
#define TOUCH_PIN_1 2
#define TOUCH_PIN_2 3
#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9

// Define GPIO pin for the LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *touch_states);
int debounce(int pin, int *last_state, unsigned long *last_change_time);
int log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(0); // Turn off the LED
    gpioTerminate(); // Release pigpio resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(TOUCH_PIN_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_8, PI_PUD_DOWN);

    // Set GPIO pin for LED as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read the state of the touch sensors
int read_touch_sensors(int *touch_states) {
    touch_states[0] = gpioRead(TOUCH_PIN_1);
    touch_states[1] = gpioRead(TOUCH_PIN_2);
    touch_states[2] = gpioRead(TOUCH_PIN_3);
    touch_states[3] = gpioRead(TOUCH_PIN_4);
    touch_states[4] = gpioRead(TOUCH_PIN_5);
    touch_states[5] = gpioRead(TOUCH_PIN_6);
    touch_states[6] = gpioRead(TOUCH_PIN_7);
    touch_states[7] = gpioRead(TOUCH_PIN_8);
    return 0;
}

// Debounce the touch sensor readings
int debounce(int pin, int *last_state, unsigned long *last_change_time) {
    int current_state = gpioRead(pin);
    unsigned long now = gpioTick();

    if (current_state != *last_state) {
        if ((now - *last_change_time) > (DEBOUNCE_TIME * 1000)) { // Convert ms to us
            *last_change_time = now;
            *last_state = current_state;
            return 1; // State changed and debounced
        }
    }
    return 0; // State changed but not debounced yet
}

// Log a touch event to the file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int touch_states[8] = {0}; // Array to store the state of each touch sensor
    int any_touched = 0;
    unsigned long last_change_time[8] = {0}; // Array to store the last change time for each sensor

    printf("Security Keypad running. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the state of the touch sensors
        read_touch_sensors(touch_states);

        // Debounce and log touch events
        for (int i = 0; i < 8; i++) {
            if (debounce(TOUCH_PIN_1 + i, &touch_states[i], &last_change_time[i])) {
                if (touch_states[i] == 1) {
                    log_touch_event(i + 1);
                    any_touched = 1;
                }
            }
        }

        // Control the LED based on touch events
        if (any_touched) {
            control_led(1);
        } else {
            control_led(0);
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

