#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xC810
#define CONVERSION_DELAY_MS 100
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_result(int *exponent, int *mantissa);
float calculate_lux(int exponent, int mantissa);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    unsigned short config = (CONFIG_VALUE >> 8) | ((CONFIG_VALUE & 0xFF) << 8); // Byte swap
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config);
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the result register and extract exponent and mantissa
int read_result(int *exponent, int *mantissa) {
    int raw_result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", raw_result);
        return -1;
    }

    unsigned short result = (raw_result >> 8) | ((raw_result & 0xFF) << 8); // Byte swap

    *exponent = (result >> 12) & 0x0F;
    *mantissa = result & 0x0FFF;

    return 0;
}

// Calculate lux value from exponent and mantissa
float calculate_lux(int exponent, int mantissa) {
    return mantissa * 0.01 * (1 << exponent);
}

// Log the lux value to a file
int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Wait for the first conversion to complete
    gpioDelay(CONVERSION_DELAY_MS * 1000); // Convert ms to microseconds

    int exponent, mantissa;
    float lux;

    // Main loop
    while (!terminate) {
        // Read the result register
        if (read_result(&exponent, &mantissa) == 0) {
            // Calculate lux value
            lux = calculate_lux(exponent, mantissa);

            // Log the data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Print the lux value
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

