int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Wait for the first conversion to complete
    gpioDelay(CONVERSION_DELAY_MS * 1000); // Convert ms to microseconds

    int exponent, mantissa;
    float lux;

    // Main loop
    while (!terminate) {
        // Read the result register
        if (read_result(&exponent, &mantissa) == 0) {
            // Calculate lux value
            lux = calculate_lux(exponent, mantissa);

            // Log the data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Print the lux value
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

