#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
static char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static buffer to hold the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
static int log_message(const char *message)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", get_timestamp(), message);
    fflush(log_file); // Ensure the message is written immediately
    return 0;
}

// Function to read the touch sensor state
static int read_touch_sensor()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

int main()
{
    // Register signal handlers for graceful shutdown
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for input with pull-down
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    int last_state = 0; // Store the last known state of the touch sensor
    int current_state;

    // Main loop
    while (!terminate) {
        current_state = read_touch_sensor();
        if (current_state < 0) {
            // Error reading sensor, but continue running
            continue;
        }

        if (current_state != last_state) {
            // State changed, log the event
            if (current_state == 1) {
                if (log_message("Touch Detected") != 0) {
                    fprintf(stderr, "Error logging touch detected event.\n");
                }
            } else {
                if (log_message("Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch released event.\n");
                }
            }
            last_state = current_state;
        }

        // Debounce delay
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = DEBOUNCE_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup before exiting
    printf("Cleaning up and exiting...\n");

    // Release the GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

