#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_sensor(int16_t *flow_rate);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int log_data(const char *timestamp, float flow_rate, const char *status);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per Sensirion datasheet)
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    size_t i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = (crc << 1);
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read flow sensor data
int read_flow_sensor(int16_t *flow_rate) {
    uint8_t buffer[3];
    int result;

    // Send start measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, 0x36);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x01, 0x08);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms

    // Read 3 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Extract flow rate and CRC
    *flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);
    uint8_t crc = buffer[2];

    // CRC validation
    uint8_t calculated_crc = calculate_crc(buffer, 2);
    if (crc != calculated_crc) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1; // Indicate CRC failure
    }

    return 0;
}

// Log data to file
int log_data(const char *timestamp, float flow_rate, const char *status) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n"); // Write header
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_flow_rate;
        float flow_rate;
        char timestamp[20];
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

        // Read flow sensor
        if (read_flow_sensor(&raw_flow_rate) == 0) {
            // Convert to ml/min
            flow_rate = (float)raw_flow_rate / 90.0;

            // Validate flow rate
            if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
                log_data(timestamp, flow_rate, "INVALID");
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
            } else {
                log_data(timestamp, flow_rate, "OK");
            }
        } else {
            log_data(timestamp, 0.0, "ERROR");
            fprintf(stderr, "Error reading flow sensor, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C!\n");
                terminate = 1; // Exit if re-initialization fails
            }
        }

