#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the CSV file name
#define CSV_FILE_NAME "path_log.csv"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int open_gpio_chip(const char *chip_name);
struct gpiod_line *request_gpio_line(struct gpiod_chip *chip, int pin, const char *consumer);
int read_sensor(struct gpiod_line *line);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int write_to_csv(FILE *fp, const char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Function to open the GPIO chip
int open_gpio_chip(const char *chip_name) {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", chip_name, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to request a GPIO line
struct gpiod_line *request_gpio_line(struct gpiod_chip *chip, int pin, const char *consumer) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        return NULL;
    }

    int ret = gpiod_line_request_input(line, consumer);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", pin, strerror(errno));
        return NULL;
    }

    return line;
}

// Function to read a sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Function to write data to the CSV file
int write_to_csv(FILE *fp, const char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    if (open_gpio_chip("gpiochip0") < 0) {
        return 1;
    }

    // Request GPIO lines
    left_line = request_gpio_line(chip, LEFT_SENSOR_PIN, "left_sensor");
    middle_line = request_gpio_line(chip, MIDDLE_SENSOR_PIN, "middle_sensor");
    right_line = request_gpio_line(chip, RIGHT_SENSOR_PIN, "right_sensor");

    if (!left_line || !middle_line || !right_line) {
        // Error already reported by request_gpio_line
        if(left_line) gpiod_line_release(left_line);
        if(middle_line) gpiod_line_release(middle_line);
        if(right_line) gpiod_line_release(right_line);
        if(chip) gpiod_chip_close(chip);
        return 1;
    }

    // Open the CSV file in append mode
    log_file = fopen(CSV_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening CSV file '%s': %s\n", CSV_FILE_NAME, strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            // Error already reported by read_sensor
            break; // Exit loop on error
        }

        // Get timestamp
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Write to CSV file
        if (write_to_csv(log_file, timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Error writing to CSV, exiting...\n");
            break; // Exit loop on error
        }

        // Wait 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 1;
}

