#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define GPIO_EDGE "falling"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int sig)
{
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to get the current timestamp as a string
static char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the file
static int log_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: Flame detected\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle the flame detection event
static void handle_flame_detection(struct gpiod_line *line, int event)
{
    (void)event; // Suppress unused parameter warning
    char *timestamp = get_timestamp();
    printf("Flame detected at %s\n", timestamp);

    if (log_event(timestamp) != 0) {
        fprintf(stderr, "Error logging event.\n");
    }
}

int main()
{
    struct gpiod_line_request_config config;
    int ret;

    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("flame_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the GPIO line for falling edge detection
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop to monitor the flame sensor
    printf("Monitoring flame sensor on GPIO%d... (Press Ctrl+C to exit)\n", GPIO_LINE);
    while (!terminate) {
        struct gpiod_line_event event;
        int event_value = gpiod_line_event_wait(line, NULL);

        if (event_value < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_event_read(line, &event) == 0) {
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                handle_flame_detection(line, event.event_type);
            }
        }
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    gpiod_line_release(line);
    fclose(log_file);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

