    ret = gpiod_line_request(led_line, &output_config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request LED line: %s\n", strerror(-ret));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
