#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "alert_log.txt"
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define BUZZER_SLICE_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig);
static int setup_gpio(void);
static int setup_logging(void);
static void cleanup_gpio(void);
static void cleanup_logging(void);
static int read_flame_sensor(void);
static void activate_buzzer(void);
static void log_event(const char *message);

static void signal_handler(int sig) {
    terminate = 1;
}

static int setup_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    ret = gpiod_line_request_input(flame_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        goto cleanup_flame_line;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        goto cleanup_flame_line;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup_buzzer_line;
    }

    return 0;

cleanup_buzzer_line:
    gpiod_line_release(buzzer_line);
cleanup_flame_line:
    gpiod_line_release(flame_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

static int setup_logging(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void cleanup_logging(void) {
    if (log_file) {
        fclose(log_file);
    }
}

static int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

static void activate_buzzer(void) {
    for (int i = 0; i < BUZZER_DURATION_MS / BUZZER_SLICE_MS; ++i) {
        if (terminate) return;
        gpiod_line_set_value(buzzer_line, 1);
        usleep(BUZZER_SLICE_MS * 1000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(BUZZER_SLICE_MS * 1000);
    }
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

int main(void) {
    int flame_detected;
    int prev_flame_state = 1; // Assume HIGH initially (no flame)

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return 1;
    }

    if (setup_logging() < 0) {
        cleanup_gpio();
        return 1;
    }

    log_event("System started");

    while (!terminate) {
        flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            break; // Exit loop on error
        }

        if (flame_detected == 0 && prev_flame_state == 1) {
            log_event("Flame detected!");
            activate_buzzer();
        }

        prev_flame_state = flame_detected;
        usleep(POLL_INTERVAL_MS * 1000); // Poll every 500ms
    }

    log_event("System stopped");
    cleanup_gpio();
    cleanup_logging();

    return 0;
}

