// Define sensor GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

SensorStates current_states = {1, 1, 1}; // Initialize all sensors to magnet-present (LOW)
SensorStates previous_states = {1, 1, 1};

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_event(int sensor_id, int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR1_PIN\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR1_PIN\n");
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_PIN\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR2_PIN\n");
        return 1;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR3_PIN\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR3_PIN\n");
        return 1;
    }

    return 0;
}

// Function to read sensor state
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to log event to file
void log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state ? "Magnet Removed" : "Magnet Present");
    fflush(log_file); // Ensure immediate write to file
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Update current states
        current_states.sensor1_state = sensor1_value;
        current_states.sensor2_state = sensor2_value;
        current_states.sensor3_state = sensor3_value;

        // Log events for each sensor
        if (current_states.sensor1_state != previous_states.sensor1_state) {
            log_event(1, current_states.sensor1_state);
            previous_states.sensor1_state = current_states.sensor1_state;
        }
        if (current_states.sensor2_state != previous_states.sensor2_state) {
            log_event(2, current_states.sensor2_state);
            previous_states.sensor2_state = current_states.sensor2_state;
        }
        if (current_states.sensor3_state != previous_states.sensor3_state) {
            log_event(3, current_states.sensor3_state);
            previous_states.sensor3_state = current_states.sensor3_state;
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

