#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVG_SAMPLES_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    float buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_sensor();
int read_register(int reg);
int write_register(int reg, int value);
float read_heart_rate();
float moving_average(MovingAverageFilter *filter, float new_value);
void log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Initialize moving average filter
void init_moving_average(MovingAverageFilter *filter) {
    memset(filter->buffer, 0, sizeof(filter->buffer));
    filter->index = 0;
    filter->count = 0;
}

// Moving average filter function
float moving_average(MovingAverageFilter *filter, float new_value) {
    filter->buffer[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->buffer[i];
    }

    return sum / filter->count;
}

// Initialize the sensor
int initialize_sensor() {
    int part_id, hw_rev;

    part_id = read_register(PART_ID_REG);
    if (part_id < 0) return -1;
    if (part_id != 0x02) {
        fprintf(stderr, "Error: Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    hw_rev = read_register(HW_REV_REG);
    if (hw_rev < 0) return -1;
    if (hw_rev != 0x01) {
        fprintf(stderr, "Error: Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    if (write_register(LED_CURRENT_REG, 0x3F) < 0) return -1;
    if (write_register(AVG_SAMPLES_REG, 0x04) < 0) return -1;
    if (write_register(ENABLE_REG, 0x01) < 0) return -1;

    return 0;
}

// Read a register
int read_register(int reg) {
    int retries = 3;
    while (retries > 0) {
        int result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retrying...\n", reg, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Fatal I2C read error (reg 0x%02X). Aborting.\n", reg);
    return -1;
}

// Write a register
int write_register(int reg, int value) {
    int retries = 3;
    while (retries > 0) {
        int result = i2cWriteWordData(i2c_handle, reg, value);
        if (result == 0) {
            return 0;
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %d. Retrying...\n", reg, value, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Fatal I2C write error (reg 0x%02X, value 0x%02X). Aborting.\n", reg, value);
    return -1;
}

// Read heart rate data
float read_heart_rate() {
    int raw_value = read_register(HEART_RATE_REG);
    if (raw_value < 0) return -1.0;

    return (float)raw_value * 0.5;
}

// Log data to file
void log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Initialize moving average filter
    MovingAverageFilter filter;
    init_moving_average(&filter);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float raw_bpm = read_heart_rate();
        if (raw_bpm < 0) {
            fprintf(stderr, "Failed to read heart rate\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        float filtered_bpm = moving_average(&filter, raw_bpm);

        if (filtered_bpm >= MIN_BPM && filtered_bpm <= MAX_BPM) {
            log_data(filtered_bpm);
        } else {
            fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
        }

        gpioDelay(1000); // Read every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

