}

// Read heart rate data
float read_heart_rate() {
    int raw_value = read_register(HEART_RATE_REG);
    if (raw_value < 0) return -1.0;

    return (float)raw_value * 0.5;
}

// Log data to file
void log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Initialize moving average filter
    MovingAverageFilter filter;
    init_moving_average(&filter);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float raw_bpm = read_heart_rate();
        if (raw_bpm < 0) {
            fprintf(stderr, "Failed to read heart rate\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        float filtered_bpm = moving_average(&filter, raw_bpm);

        if (filtered_bpm >= MIN_BPM && filtered_bpm <= MAX_BPM) {
            log_data(filtered_bpm);
        } else {
            fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
        }

        gpioDelay(1000); // Read every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

