#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for sensor inputs and counter outputs
#define SENSOR_PIN_1 5
#define SENSOR_PIN_2 6
#define SENSOR_PIN_3 7
#define SENSOR_PIN_4 8
#define SENSOR_PIN_5 9
#define SENSOR_PIN_6 10
#define SENSOR_PIN_7 11
#define SENSOR_PIN_8 12

#define COUNTER_PIN_0 17
#define COUNTER_PIN_1 24
#define COUNTER_PIN_2 25
#define COUNTER_PIN_3 26
#define COUNTER_PIN_4 27
#define COUNTER_PIN_5 22
#define COUNTER_PIN_6 23
#define COUNTER_PIN_7 18

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Define the counter value type
typedef unsigned char counter_value_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[8] = {NULL};
static struct gpiod_line *counter_lines[8] = {NULL};
static counter_value_t counter = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(int channel);
void update_counter(int channel);
void log_touch_event(int channel, counter_value_t counter);
void print_touch_event(int channel, counter_value_t counter);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request sensor lines
    for (i = 0; i < 8; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_PIN_1 + i);
        if (!sensor_lines[i]) {
            perror("Error getting sensor line");
            goto error;
        }
        if (gpiod_line_request_input(sensor_lines[i], "touch_sensor") < 0) {
            perror("Error requesting sensor line");
            goto error;
        }
    }

    // Request counter lines
    for (i = 0; i < 8; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, COUNTER_PIN_0 + i);
        if (!counter_lines[i]) {
            perror("Error getting counter line");
            goto error;
        }
        if (gpiod_line_request_output(counter_lines[i], "touch_counter", 0) < 0) {
            perror("Error requesting counter line");
            goto error;
        }
    }

    return 0;

error:
    cleanup_gpio();
    return -1;
}

// Read sensor value
int read_sensor(int channel) {
    int value;

    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid sensor channel %d\n", channel);
        return -1;
    }

    value = gpiod_line_get_value(sensor_lines[channel]);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }

    return value;
}

// Update counter value
void update_counter(int channel) {
    counter_value_t new_counter;

    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid counter channel %d\n", channel);
        return;
    }

    new_counter = counter + 1;
    if (new_counter > 255) {
        new_counter = 0;
    }

    // Set the corresponding GPIO pin to 1
    if (gpiod_line_set_value(counter_lines[channel], 1) < 0) {
        perror("Error setting counter value");
        return;
    }

    // Set the corresponding GPIO pin to 0 after a short delay
    usleep(1000); // 1 ms delay
    if (gpiod_line_set_value(counter_lines[channel], 0) < 0) {
        perror("Error setting counter value");
        return;
    }

    counter = new_counter;
}

// Log touch event to file
void log_touch_event(int channel, counter_value_t counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Warning: Log file not opened. Logging to stdout instead.\n");
        printf("%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter);
    }
}

// Print touch event to stdout
void print_touch_event(int channel, counter_value_t counter) {
    printf("Touch on channel %d | Counter: %d\n", channel + 1, counter);
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release sensor lines
    for (i = 0; i < 8; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Release counter lines
    for (i = 0; i < 8; i++) {
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int i;
    int sensor_value;
    int prev_sensor_value[8] = {0}; // Track previous sensor state

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        fprintf(stderr, "Logging to stdout instead.\n");
    }

    // Stabilization delay
    usleep(200000); // 200 ms

    // Main loop
    while (!terminate) {
        for (i = 0; i < 8; i++) {
            sensor_value = read_sensor(i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i + 1);
                continue;
            }

            // Detect rising edge (active-high)
            if (sensor_value == 1 && prev_sensor_value[i] == 0) {
                update_counter(i);
                log_touch_event(i, counter);
                print_touch_event(i, counter);
            }

            prev_sensor_value[i] = sensor_value;
        }

        usleep(10000); // 10 ms delay
    }

    // Reset all output pins to 0
    for (i = 0; i < 8; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

