    if (!sensor4_line) {
        fprintf(stderr, "Error getting line %d: %s\n", SENSOR4_PIN, strerror(errno));
        goto cleanup_line3;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
