#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO17_PIN 17
#define GPIO18_PIN 18
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "/var/log/tilt_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
static char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static buffer to hold the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log tilt event to file
static int log_tilt_event(int sensor_number)
{
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to read sensor value
static int read_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

int main()
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17_PIN);
    line18 = gpiod_chip_get_line(chip, GPIO18_PIN);

    if (!line17 || !line18) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        if (line17) gpiod_line_release(line17);
        if (line18) gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines as inputs with pull-up
    if (gpiod_line_request_input(line17, "tilt_sensor_17") < 0) {
        fprintf(stderr, "Error requesting GPIO17 as input: %s\n", strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(line18, "tilt_sensor_18") < 0) {
        fprintf(stderr, "Error requesting GPIO18 as input: %s\n", strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_value17 = 1; // Initialize to HIGH (pull-up)
    int last_value18 = 1;
    struct timespec last_change17 = {0, 0};
    struct timespec last_change18 = {0, 0};
    struct timespec now, debounce;

    // Main loop
    while (!terminate) {
        // Read sensor values
        int value17 = read_sensor(line17);
        int value18 = read_sensor(line18);

        if (value17 < 0 || value18 < 0) {
            // Error reading sensor, but continue polling
            usleep(POLL_INTERVAL_MS * 1000); // Sleep for polling interval
            continue;
        }

        // Edge detection and debouncing for GPIO17
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (value17 == 0 && last_value17 == 1) { // Falling edge
            clock_gettime(CLOCK_MONOTONIC, &debounce);
            debounce.tv_sec -= DEBOUNCE_MS / 1000;
            debounce.tv_nsec -= (DEBOUNCE_MS % 1000) * 1000000;
            if (now.tv_sec > last_change17.tv_sec || (now.tv_sec == last_change17.tv_sec && now.tv_nsec >= last_change17.tv_nsec)) {
                log_tilt_event(1);
                last_change17 = now;
            }
        }
        last_value17 = value17;

        // Edge detection and debouncing for GPIO18
        if (value18 == 0 && last_value18 == 1) { // Falling edge
            clock_gettime(CLOCK_MONOTONIC, &debounce);
            debounce.tv_sec -= DEBOUNCE_MS / 1000;
            debounce.tv_nsec -= (DEBOUNCE_MS % 1000) * 1000000;
            if (now.tv_sec > last_change18.tv_sec || (now.tv_sec == last_change18.tv_sec && now.tv_nsec >= last_change18.tv_nsec)) {
                log_tilt_event(2);
                last_change18 = now;
            }
        }
        last_value18 = value18;

        usleep(POLL_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    // Cleanup
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    return EXIT_SUCCESS;
}

