#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define the log file name
#define LOG_FILE "obstacle_log.csv"

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
int control_led(int gpio_pin, int state);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value;
    int ret;

    ret = gpiod_line_get_value(sensor1_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    value = ret;
    return value;
}

// Function to control the LED state
int control_led(int gpio_pin, int state) {
    int ret;

    ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED %d to %d: %s\n", gpio_pin, state, strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

// Function to log the data to a file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the LED
    if (led_line != NULL) {
        control_led(LED_PIN, 0);
    }

    // Release GPIO lines
    if (sensor1_line != NULL) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line != NULL) {
        gpiod_line_release(sensor2_line);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }

