#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define MICROPHONE_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125 // 8kHz sampling rate

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int rc;
    struct timespec ts;
    time_t rawtime;
    struct tm *info;
    char buffer[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MICROPHONE_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MICROPHONE_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Microphone sampling started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read microphone input
        int mic_value = gpioRead(MICROPHONE_GPIO);
        if (mic_value < 0) {
            fprintf(stderr, "Error reading GPIO%d: %d\n", MICROPHONE_GPIO, mic_value);
            break;
        }

        // Check for peak
        if (mic_value == 1) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                break;
            }
            rawtime = ts.tv_sec;
            info = localtime(&rawtime);
            strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", info);
            printf("%s.%03ld: Peak detected\n", buffer, ts.tv_nsec / 1000000);

            // Turn on LED
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error writing to GPIO%d\n", LED_GPIO);
                break;
            }
            gpioDelay(100); // 100ms

            // Turn off LED
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error writing to GPIO%d\n", LED_GPIO);
                break;
            }
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    printf("Shutting down...\n");
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

