// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 27
#define RIGHT_SENSOR 22

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    int left_state, center_state, right_state;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);

    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP);

    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Main loop to read sensor data and log it
    while (!terminate) {
        // Read the sensor states
        left_state = gpioRead(LEFT_SENSOR);
        center_state = gpioRead(CENTER_SENSOR);
        right_state = gpioRead(RIGHT_SENSOR);

        // Log the sensor states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

