#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI1175_ADDR 0x49

// Define the ALS visible data register addresses
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the Si1175 sensor
int read_si1175_als_visible(int fd) {
    uint8_t lsb, msb;
    int result;

    // Read the LSB
    result = read(fd, &lsb, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading LSB: %s\n", strerror(errno));
        return -1;
    }

    // Read the MSB
    result = read(fd, &msb, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading MSB: %s\n", strerror(errno));
        return -1;
    }

    // Combine the LSB and MSB into a 16-bit value
    return (msb << 8) | lsb;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address for the Si1175 sensor
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log the ALS visible data
    while (1) {
        int als_visible = read_si1175_als_visible(i2c_fd);
        if (als_visible >= 0) {
            printf("ALS Visible: %d\n", als_visible);
        } else {
            fprintf(stderr, "Error reading ALS visible data\n");
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    close(i2c_fd);
    return 0;
}

