#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_LINES 3
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_LINES];
static int line_offsets[NUM_LINES] = {2, 3, 4};
static int line_values[NUM_LINES];

static void cleanup(void) {
    int i;
    for (i = 0; i < NUM_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    cleanup();
    exit(0);
}

int main() {
    int i, ret;
    struct gpiod_line_request_config config;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip 'gpiochip0'. Ensure it is available and accessible.\n");
        return 1;
    }

    // Request lines for input
    for (i = 0; i < NUM_LINES; i++) {
        config.consumer = "sensor_reader";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
        lines[i] = gpiod_chip_get_line(chip, line_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get line %d (offset %d).\n", i, line_offsets[i]);
            cleanup();
            return 1;
        }

        ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not request line %d (offset %d) for input. Check permissions.\n", i, line_offsets[i]);
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (i = 0; i < NUM_LINES; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Error: Could not read value from line %d (offset %d).\n", i, line_offsets[i]);
                cleanup();
                return 1;
            }
            line_values[i] = ret;
        }

        printf("L:%d M:%d R:%d\n", line_values[0], line_values[1], line_values[2]);
        usleep(POLL_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    return 0;
}

