#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Hue range
#define HUE_MIN 0
#define HUE_MAX 360

// Number of steps for linear interpolation
#define NUM_STEPS 50

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to generate a random hue value
int generate_random_hue() {
    return rand() % (HUE_MAX + 1);
}

// Function to convert HSV to RGB
void hsv_to_rgb(int hue, int saturation, int value, int *red, int *green, int *blue) {
    double h = (double)hue / 360.0;
    double s = (double)saturation / 255.0;
    double v = (double)value / 255.0;

    double r, g, b;
    double i = floor(h * 6);
    double f = h * 6 - i;
    double p = v * (1 - s);
    double q = v * (1 - f * s);
    double t = v * (1 - (1 - f) * s);

    switch ((int)i % 6) {
        case 0: r = v, g = t, b = p; break;
        case 1: r = q, g = v, b = p; break;
        case 2: r = p, g = v, b = t; break;
        case 3: r = p, g = q, b = v; break;
        case 4: r = t, g = p, b = v; break;
        case 5: r = v, g = p, b = q; break;
    }

    *red   = (int)(r * 255);
    *green = (int)(g * 255);
    *blue  = (int)(b * 255);
}

// Function to set the RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue) {
    // Invert the PWM duty-cycle values for common-anode LED
    int red_pwm   = 255 - red;
    int green_pwm = 255 - green;
    int blue_pwm  = 255 - blue;

    // Clamp the PWM values to the range [0, 255]
    if (red_pwm < 0)   red_pwm = 0;
    if (red_pwm > 255) red_pwm = 255;
    if (green_pwm < 0) green_pwm = 0;
    if (green_pwm > 255) green_pwm = 255;
    if (blue_pwm < 0)  blue_pwm = 0;
    if (blue_pwm > 255) blue_pwm = 255;

    // Set the PWM duty-cycle for each color channel
    gpioPWM(RED_PIN,   red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN,  blue_pwm);
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        perror("fopen");
        closelog();
        return 1;
    }
    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        perror("fread");
        fclose(urandom);
        closelog();
        return 1;
    }
    fclose(urandom);
    srand(seed);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM range
    if (gpioSetPWMrange(RED_PIN, 255) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for RED_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, 255) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GREEN_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for BLUE_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate a random hue
        int hue = generate_random_hue();

        // Convert hue to RGB
        int red, green, blue;
        hsv_to_rgb(hue, 255, 255, &red, &green, &blue);

        // Fade to the new color over 5 seconds
        for (int i = 0; i <= NUM_STEPS; i++) {
            // Calculate the interpolated RGB values
            int interpolated_red   = (int)(((float)red   * i) / NUM_STEPS);
            int interpolated_green = (int)(((float)green * i) / NUM_STEPS);
            int interpolated_blue  = (int)(((float)blue  * i) / NUM_STEPS);

            // Set the LED color
            set_led_color(interpolated_red, interpolated_green, interpolated_blue);

            // Wait for 5 seconds / NUM_STEPS
            sleep(5 / NUM_STEPS);
        }

        // Wait for 5 seconds before changing the hue again
        sleep(5);
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

