    return -1;
  }
  uint8_t buf[2];
  if (read(fd, buf, 2) != 2) {
    perror("Failed to read from I2C device");
    return -1;
  }
  *value = (buf[1] << 8) | buf[0];
  return 0;
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
  // Power on the sensor
  if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
