#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define WS2812B_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CMD_HIGH_RES 0x10
#define NUM_LEDS 10
#define LUX_MIN 0
#define LUX_MAX 1000
#define PWM_FREQUENCY 800000 // 800 kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
int read_bh1750(float *lux);
void set_led_brightness(int brightness);
int map_lux_to_brightness(float lux);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CMD_HIGH_RES); // Send command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(200); // Wait 180ms

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;
    return 0;
}

// Set LED strip brightness using PWM
void set_led_brightness(int brightness) {
    gpioPWM(WS2812B_GPIO, brightness);
}

// Map lux value to PWM duty cycle (non-linear logarithmic mapping)
int map_lux_to_brightness(float lux) {
    // Clamp lux value
    if (lux < LUX_MIN) lux = LUX_MIN;
    if (lux > LUX_MAX) lux = LUX_MAX;

    // Logarithmic mapping
    float normalized_lux = (lux - LUX_MIN) / (LUX_MAX - LUX_MIN);
    float brightness_float = log10(1 + normalized_lux * 999) / log10(1 + 999); // Logarithmic mapping

    // Scale to PWM range (0-255)
    int brightness = (int)(brightness_float * 255.0);

    return brightness;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    set_led_brightness(0); // Turn off LEDs
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO for PWM output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(WS2812B_GPIO, 255); // Set PWM range to 0-255

    float lux;
    int brightness;

    printf("Light sensor and LED control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read light level
        if (read_bh1750(&lux) == 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Error reading light sensor. Retrying...\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

