int read_bh1750(int fd) {
    uint8_t command = 0x20; // High-resolution mode
    if (write(fd, &command, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    usleep(200000); // Wait 200 ms

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

