float convert_to_lux(uint16_t raw) {
    return (float)raw / 1.2;
}

// Set APA102 brightness
int set_apa102_brightness(int fd, int brightness) {
    if (brightness < 0 || brightness > 31) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t led_frame[4];
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};

    led_frame[0] = 0xE0 | brightness;
    led_frame[1] = 0x00; // Blue
    led_frame[2] = 0x00; // Green
    led_frame[3] = 0x00; // Red

    uint8_t tx_buffer[4 + NUM_LEDS * 4 + 4];
    memcpy(tx_buffer, start_frame, 4);
    for (int i = 0; i < NUM_LEDS; i++) {
        memcpy(tx_buffer + 4 + i * 4, led_frame, 4);
    }
    memcpy(tx_buffer + 4 + NUM_LEDS * 4, end_frame, 4);

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buffer,
        .len = sizeof(tx_buffer),
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
