    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(1000000); // 1 MHz
    if (spi_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        int raw_value = read_bh1750(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
            usleep(100000); // Wait 100 ms before retrying
            continue;
        }

        float lux = convert_to_lux((uint16_t)raw_value);

        // Map lux to brightness
        int brightness = (int)(((lux - LUX_MIN) / (LUX_MAX - LUX_MIN)) * (BRIGHTNESS_MAX - BRIGHTNESS_MIN));
        if (brightness < BRIGHTNESS_MIN) {
            brightness = BRIGHTNESS_MIN;
        } else if (brightness > BRIGHTNESS_MAX) {
            brightness = BRIGHTNESS_MAX;
        }

        // Set APA102 brightness
        if (set_apa102_brightness(spi_fd, brightness) < 0) {
            fprintf(stderr, "Error setting APA102 brightness, retrying...\n");
            usleep(100000); // Wait 100 ms before retrying
            continue;
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        usleep(500000); // Wait 500 ms
    }

    // Turn off LEDs
    set_apa102_brightness(spi_fd, 0);

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

