        fprintf(stderr, "Error reading from I2C device.\n");
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Function to calculate the average lux value
int calculate_average_lux(float lux1, float lux2, float lux3) {
    float sum = 0.0;
    int count = 0;

    if (lux1 >= 0) { sum += lux1; count++; }
    if (lux2 >= 0) { sum += lux2; count++; }
    if (lux3 >= 0) { sum += lux3; count++; }

    if (count == 0) return 0; // Avoid division by zero

    return (int)(sum / count);
}

// Function to map the average lux value to a brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    // Define a reasonable range for lux values (e.g., 0-1000 lux)
    float min_lux = 0.0;
    float max_lux = 1000.0;

    // Clamp the average lux value to the defined range
    if (average_lux < min_lux) average_lux = min_lux;
    if (average_lux > max_lux) average_lux = max_lux;

    // Map the lux value to a brightness level (0-31)
    // Invert the mapping to have higher lux values result in lower brightness
    int brightness = (int)((1.0 - (average_lux - min_lux) / (max_lux - min_lux)) * 31.0);

    return brightness;
}

// Function to set the APA102 LED strip's global brightness
void set_apa102_brightness(int brightness) {
    if (spi_handle < 0) return; // Invalid handle

    // APA102 start frame (4 bytes of 0x00)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    char end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};

    // Calculate the number of bytes needed for the data frame
    int num_bytes = NUM_LEDS * 4 + 8; // 4 bytes per LED (R, G, B, brightness) + start/end frames

    // Allocate memory for the data frame
    char *data_frame = malloc(num_bytes);
    if (data_frame == NULL) {
        fprintf(stderr, "Error allocating memory for data frame.\n");
        return;
    }

    // Fill the data frame with the brightness value
    for (int i = 0; i < NUM_LEDS; i++) {
        data_frame[4 * i] = 0xE0 | (brightness & 0x1F); // Global brightness
        data_frame[4 * i + 1] = 0x00; // Blue
        data_frame[4 * i + 2] = 0x00; // Green
        data_frame[4 * i + 3] = 0x00; // Red
    }

    // Copy start and end frames
    memcpy(data_frame, start_frame, 4);
    memcpy(data_frame + num_bytes - 4, end_frame, 4);

    // Write the data frame to the SPI device
    if (spiWrite(spi_handle, data_frame, num_bytes) != num_bytes) {
        fprintf(stderr, "Error writing to SPI device.\n");
    }

    // Free the allocated memory
    free(data_frame);
}

// Signal handler for clean resource release
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off the LED strip
    set_apa102_brightness(0);

    // Close I2C handles
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);

    // Close SPI handle
    if (spi_handle >= 0) spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle_low = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    i2c_handle_high = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);

    // Open SPI device
    spi_handle = spiOpen(0, 32000000, 0); // CE0, 32MHz, Mode 0

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read lux values from BH1750 sensors
        float lux1 = read_bh1750(i2c_handle_low);
        float lux2 = read_bh1750(i2c_handle_high);

        // Attempt to read from the second sensor even if the first fails
        if (i2c_handle_low < 0 && i2c_handle_high < 0) {
            lux2 = -1.0; // Indicate failure
        } else if (i2c_handle_low < 0) {
            lux2 = read_bh1750(i2c_handle_high);
        } else if (i2c_handle_high < 0) {
            lux2 = read_bh1750(i2c_handle_low);
        }

        float lux3 = -1.0; // Placeholder, not used in this example

        // Calculate the average lux value
        int average_lux = calculate_average_lux(lux1, lux2, lux3);

        // Map the average lux value to a brightness level
        int target_brightness = map_lux_to_brightness((float)average_lux);

        // Fade the LED strip to the target brightness
        int current_brightness = 0;
        int increment = (target_brightness > current_brightness) ? 1 : -1;

        for (int i = 0; i <= FADE_TIME_MS / READ_DELAY_MS; i++) {
            current_brightness += increment;
            set_apa102_brightness(current_brightness);
            gpioDelay(READ_DELAY_MS);
        }

        // Wait before the next cycle
        gpioDelay(READ_DELAY_MS);
    }

    return 0;
}

