// Configuration
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONF_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define WS2812B_GPIO_PIN 18
#define WS2812B_FREQUENCY 800000 // 800 kHz
#define WS2812B_THRESHOLD 1000   // Threshold lux for threshold-based control
#define WS2812B_MAX_BRIGHTNESS 255
#define WS2812B_MIN_BRIGHTNESS 0
#define WS2812B_GAMMA 2.2
#define WS2812B_DUTY_CYCLE_MAX 1000000 // 1ms
#define WS2812B_DUTY_CYCLE_MIN 1000    // 0.1ms
#define WS2812B_DUTY_CYCLE_RANGE (WS2812B_DUTY_CYCLE_MAX - WS2812B_DUTY_CYCLE_MIN)
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100

// Global variables (to be minimized, but needed for signal handler)
static int i2c_fd = -1;
static int gpio_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_word_data(int fd, uint8_t reg, uint16_t data);
int i2c_read_word_data(int fd, uint8_t reg);
float veml7700_read_lux(int fd);
int ws2812b_set_brightness(int gpio_fd, int brightness);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write_word_data(int fd, uint8_t reg, uint16_t data) {
    int retries = I2C_RETRY_COUNT;
    int result;
    while (retries > 0) {
        result = i2c_smbus_write_word_data(fd, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error: %s (errno: %d). Retrying...\n", strerror(errno), errno);
            usleep(I2C_RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read_word_data(int fd, uint8_t reg) {
    int retries = I2C_RETRY_COUNT;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_word_data(fd, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "I2C read error: %s (errno: %d). Retrying...\n", strerror(errno), errno);
            usleep(I2C_RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// VEML7700 lux calculation
float veml7700_read_lux(int fd) {
    uint16_t raw_data = i2c_read_word_data(fd, VEML7700_ALS_DATA_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read ALS data.\n");
        return -1.0;
    }

    // VEML7700 datasheet values
    float integration_time = 100.0; // ms
    float gain = 1.0 / 8.0;         // 1/8x

    float lux = (float)raw_data * 0.0036 * (1.0 / gain) * (100.0 / integration_time);
    return lux;
}

// WS2812B bit-banging with PWM
int ws2812b_set_brightness(int gpio_fd, int brightness) {
    // Gamma correction
    float gamma_corrected_brightness = pow(brightness / 255.0, WS2812B_GAMMA) * 255.0;

    // Calculate duty cycle
    int duty_cycle = (int)(gamma_corrected_brightness / 255.0 * WS2812B_DUTY_CYCLE_RANGE) + WS2812B_DUTY_CYCLE_MIN;

    // Set GPIO high for duty cycle time
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duty_cycle);

    // Set GPIO low for remaining time
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO low: %s\n", strerror(errno));
        return -1;
    }
    usleep(WS2812B_DUTY_CYCLE_MAX - duty_cycle);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize VEML7700 (set integration time and gain)
    if (i2c_write_word_data(i2c_fd, VEML7700_CONF_REG, 0x0000) < 0) {
        fprintf(stderr, "Error initializing VEML7700.\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, WS2812B_GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ws2812b";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = veml7700_read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value.\n");
            continue; // Skip to the next iteration
        }

        // Map lux to brightness (threshold-based control)
        int brightness;
        if (lux < WS2812B_THRESHOLD) {
            brightness = WS2812B_MIN_BRIGHTNESS;
        } else {
            brightness = WS2812B_MAX_BRIGHTNESS;
        }

        // Set WS2812B brightness
        if (ws2812b_set_brightness(gpio_fd, brightness) < 0) {
            fprintf(stderr, "Error setting WS2812B brightness.\n");
        }

        // Print lux and brightness values
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        usleep(200000); // 200 ms
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

