#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define self-test duration and interval
#define SELF_TEST_DURATION_MS 500
#define SELF_TEST_INTERVAL_MS 100
#define SELF_TEST_RETRIES 5

// Define error logging file
#define ERROR_LOG_FILE "error.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *error_log = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_request(struct gpiod_chip *chip, const char *chipname, int pin, const char *consumer, struct gpiod_line **line);
int gpio_set_direction(struct gpiod_line *line, enum gpiod_line_direction direction);
int gpio_write(struct gpiod_line *line, int value);
int gpio_read(struct gpiod_line *line);
void gpio_release(struct gpiod_line *line);
void log_event(const char *event);
void log_error(const char *message);
void signal_handler(int signal);
void self_test();
void cleanup();

// Function to request a GPIO line
int gpio_request(struct gpiod_chip *chip, const char *chipname, int pin, const char *consumer, struct gpiod_line **line) {
    char pin_str[3];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    *line = gpiod_chip_get_line(chip, pin_str);
    if (!*line) {
        log_error("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request(*line, consumer, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        log_error("Failed to request GPIO line");
        return -1;
    }

    return 0;
}

// Function to set the direction of a GPIO line
int gpio_set_direction(struct gpiod_line *line, enum gpiod_line_direction direction) {
    if (gpiod_line_set_direction(line, direction) < 0) {
        log_error("Failed to set GPIO direction");
        return -1;
    }
    return 0;
}

// Function to write a value to a GPIO line
int gpio_write(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        log_error("Failed to write GPIO value");
        return -1;
    }
    return 0;
}

// Function to read a value from a GPIO line
int gpio_read(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_error("Failed to read GPIO value");
        return -1;
    }
    return value;
}

// Function to release a GPIO line
void gpio_release(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

// Function to log an event with timestamp
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stdout, "[%s] %s\n", timestamp, event);
    fflush(stdout);
}

// Function to log an error with timestamp
