#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define LUX_BUFFER_SIZE 60

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer for lux readings
float lux_buffer[LUX_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int i2c_init(const char *bus, int addr);
int bh1750_init(int fd);
int bh1750_read(int fd, uint16_t *raw_value);
float raw_to_lux(uint16_t raw_value);
void gpio_export(int pin);
void gpio_unexport(int pin);
void gpio_set_direction(int pin, const char *direction);
void gpio_set_value(int pin, int value);
void blink_led(int pin, float frequency);
float calculate_average_lux();
void signal_handler(int signal);

// I2C initialization function
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 initialization function
int bh1750_init(int fd) {
    uint8_t config_cmd = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

// BH1750 read function
int bh1750_read(int fd, uint16_t *raw_value) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Raw value to lux conversion function
float raw_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// GPIO export function
void gpio_export(int pin) {
    char buffer[64];
    int len;
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Error opening /sys/class/gpio/export");
        return;
    }
    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Error writing to /sys/class/gpio/export");
    }
    fclose(fp);
}

// GPIO unexport function
void gpio_unexport(int pin) {
    char buffer[64];
    int len;
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Error opening /sys/class/gpio/unexport");
        return;
    }
    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Error writing to /sys/class/gpio/unexport");
    }
    fclose(fp);
}

// GPIO set direction function
void gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening GPIO direction file");
        return;
    }
    if (fwrite(direction, 1, strlen(direction), fp) != strlen(direction)) {
        perror("Error writing to GPIO direction file");
    }
    fclose(fp);
}

// GPIO set value function
void gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening GPIO value file");
        return;
    }
    if (fprintf(fp, "%d", value) < 0) {
        perror("Error writing to GPIO value file");
    }
    fclose(fp);
}

// Blink LED function
void blink_led(int pin, float frequency) {
    float period = 1.0 / frequency;
    float half_period = period / 2.0;
    struct timespec on_time = {0, (long)(half_period * 1000000000L)};
    struct timespec off_time = {0, (long)(half_period * 1000000000L)};

    gpio_set_value(pin, 1); // Turn LED on
    nanosleep(&on_time, NULL);
    gpio_set_value(pin, 0); // Turn LED off
    nanosleep(&off_time, NULL);
}

// Calculate average lux function
float calculate_average_lux() {
    float sum = 0.0;
    for (int i = 0; i < LUX_BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / LUX_BUFFER_SIZE;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize BH1750
    if (bh1750_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_export(GPIO_PIN);
    gpio_set_direction(GPIO_PIN, "out");

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        if (bh1750_read(i2c_fd, &raw_value) == 0) {
            float lux = raw_to_lux(raw_value);

            // Update circular buffer
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % LUX_BUFFER_SIZE;

            // Calculate average lux
            float avg_lux = calculate_average_lux();

            // Calculate blink frequency
            float frequency = 0.5 + (avg_lux / 1000.0) * 4.5;
            if (frequency < 0.5) frequency = 0.5;
            if (frequency > 5.0) frequency = 5.0;

            // Blink LED
            blink_led(GPIO_PIN, frequency);
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    gpio_set_value(GPIO_PIN, 0); // Turn LED off
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

