    fclose(fp);
}

// GPIO set value function
void gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error opening GPIO value file");
        return;
    }
    if (fprintf(fp, "%d", value) < 0) {
        perror("Error writing to GPIO value file");
    }
    fclose(fp);
}

// Blink LED function
void blink_led(int pin, float frequency) {
    float period = 1.0 / frequency;
    float half_period = period / 2.0;
    struct timespec on_time = {0, (long)(half_period * 1000000000L)};
    struct timespec off_time = {0, (long)(half_period * 1000000000L)};

    gpio_set_value(pin, 1); // Turn LED on
    nanosleep(&on_time, NULL);
    gpio_set_value(pin, 0); // Turn LED off
    nanosleep(&off_time, NULL);
}

// Calculate average lux function
float calculate_average_lux() {
    float sum = 0.0;
    for (int i = 0; i < LUX_BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / LUX_BUFFER_SIZE;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize BH1750
    if (bh1750_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_export(GPIO_PIN);
    gpio_set_direction(GPIO_PIN, "out");

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        if (bh1750_read(i2c_fd, &raw_value) == 0) {
            float lux = raw_to_lux(raw_value);

            // Update circular buffer
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % LUX_BUFFER_SIZE;

            // Calculate average lux
            float avg_lux = calculate_average_lux();

            // Calculate blink frequency
            float frequency = 0.5 + (avg_lux / 1000.0) * 4.5;
            if (frequency < 0.5) frequency = 0.5;
            if (frequency > 5.0) frequency = 5.0;

            // Blink LED
            blink_led(GPIO_PIN, frequency);
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    gpio_set_value(GPIO_PIN, 0); // Turn LED off
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

