#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP 0
#define LED_PIN 17
#define BUTTON_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static volatile sig_atomic_t terminate = 0;

static void sigint_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    int ret;

    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto close_chip;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        goto release_led;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (BUTTON)");
        goto release_led;
    }

    ret = gpiod_line_request(button_line, "blink_button", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request (BUTTON)");
        goto release_button;
    }

    return 0;

release_button:
    gpiod_line_release(button_line);
release_led:
    gpiod_line_release(led_line);
close_chip:
    gpiod_chip_close(chip);
    return -1;
}

static void cleanup_gpio(void)
{
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int blink_led(void)
{
    int ret;
    struct gpiod_line_event event;

    while (!terminate) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED on)");
            return -1;
        }
        sleep(1);

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off)");
            return -1;
        }
        sleep(1);
    }

    return 0;
}

static int wait_for_button(void)
{
    int ret;
    struct gpiod_line_event event;

    ret = gpiod_line_event_wait(button_line, NULL, 1, &event);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    }

    if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        printf("Button pressed! Stopping LED blinking.\n");
        return 0;
    }

    return -1;
}

int main(void)
{
    int ret;

    signal(SIGINT, sigint_handler);

    ret = setup_gpio();
    if (ret < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d. Press Ctrl+C to exit.\n", LED_PIN);

    while (!terminate) {
        ret = blink_led();
        if (ret < 0) {
            fprintf(stderr, "LED blinking failed. Exiting.\n");
            break;
        }

        ret = wait_for_button();
        if (ret < 0) {
            fprintf(stderr, "Button waiting failed. Exiting.\n");
            break;
        }

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off)");
            break;
        }
    }

    cleanup_gpio();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

