#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5 // GPIO5 (physical pin 29)

volatile sig_atomic_t terminate = 0; // Flag to signal termination

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1; // Set termination flag
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO5 as an output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop to blink the LED
    while (!terminate)
    {
        // Turn the LED on
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout); // Flush stdout to ensure immediate output
        gpioDelay(750);  // Wait 750 ms

        // Turn the LED off
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout); // Flush stdout to ensure immediate output
        gpioDelay(750);  // Wait 750 ms
    }

    // Clean up and exit
    gpioWrite(LED_GPIO, 0); // Ensure LED is off before exiting
    gpioTerminate();        // Terminate pigpio
    return 0;              // Exit with success code
}

