#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins (BCM numbering)
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM period (nanoseconds)
#define PWM_PERIOD (1000000000 / PWM_FREQUENCY)

// Global variables for GPIO lines and chip
static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;

// Function prototypes
int initialize_gpio(void);
void set_rgb_color(int red, int green, int blue);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold RGB values
typedef struct {
    int red;
    int green;
    int blue;
} rgb_t;

// Function to generate a random RGB color
rgb_t generate_random_color(void) {
    rgb_t color;
    color.red = rand() % 101;
    color.green = rand() % 101;
    color.blue = rand() % 101;
    return color;
}

int main(void) {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Generate a random RGB color
        rgb_t color = generate_random_color();

        // Set the RGB color
        set_rgb_color(color.red, color.green, color.blue);

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(5); // Raspberry Pi 5 uses GPIO chip 5
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the lines as outputs
    struct gpiod_line_request_config config;
    config.consumer = "RGB_LED";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request_output(red_line, &config, 0) < 0) {
        perror("Error requesting red line as output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(green_line, &config, 0) < 0) {
        perror("Error requesting green line as output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(blue_line, &config, 0) < 0) {
        perror("Error requesting blue line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the RGB color using software PWM
void set_rgb_color(int red, int green, int blue) {
    // Calculate the on-time for each color based on the duty cycle
    long red_on_time = (red * PWM_PERIOD) / 100;
    long green_on_time = (green * PWM_PERIOD) / 100;
    long blue_on_time = (blue * PWM_PERIOD) / 100;

    // Set the GPIO line values
    gpiod_line_set_value(red_line, 1);
    struct timespec red_sleep;
    red_sleep.tv_sec = 0;
    red_sleep.tv_nsec = red_on_time;
    nanosleep(&red_sleep, NULL);
    gpiod_line_set_value(red_line, 0);
    struct timespec red_sleep_off;
    red_sleep_off.tv_sec = 0;
    red_sleep_off.tv_nsec = PWM_PERIOD - red_on_time;
    nanosleep(&red_sleep_off, NULL);

    gpiod_line_set_value(green_line, 1);
    struct timespec green_sleep;
    green_sleep.tv_sec = 0;
    green_sleep.tv_nsec = green_on_time;
    nanosleep(&green_sleep, NULL);
    gpiod_line_set_value(green_line, 0);
    struct timespec green_sleep_off;
    green_sleep_off.tv_sec = 0;
    green_sleep_off.tv_nsec = PWM_PERIOD - green_on_time;
    nanosleep(&green_sleep_off, NULL);

    gpiod_line_set_value(blue_line, 1);
    struct timespec blue_sleep;
    blue_sleep.tv_sec = 0;
    blue_sleep.tv_nsec = blue_on_time;
    nanosleep(&blue_sleep, NULL);
    gpiod_line_set_value(blue_line, 0);
    struct timespec blue_sleep_off;
    blue_sleep_off.tv_sec = 0;
    blue_sleep_off.tv_nsec = PWM_PERIOD - blue_on_time;
    nanosleep(&blue_sleep_off, NULL);
}

// Function to clean up GPIO lines
void cleanup_gpio(void) {
    // Release the GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

