// GPIO pin for impact indication
#define IMPACT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_gpio();
int init_accelerometer();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_g_force_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact_data(int16_t x, int16_t y, int16_t z);
void cleanup();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using G-force threshold: %.2f G\n", threshold);
    } else {
        printf("Using default G-force threshold: %.2f G\n", DEFAULT_THRESHOLD);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize accelerometer
    if (init_accelerometer() != 0) {
        fprintf(stderr, "Accelerometer initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    accelerometer_data_t accel_data;
    double g_magnitude;

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break; // Exit loop on error
        }

        // Calculate G-force magnitude
        g_magnitude = calculate_g_force_magnitude(accel_data.x, accel_data.y, accel_data.z);

        // Check for impact
        if (g_magnitude > threshold) {
            // Log impact data
            log_impact_data(accel_data.x, accel_data.y, accel_data.z);

            // Pulse GPIO HIGH for 50 ms
            gpioWrite(IMPACT_PIN, 1);
            gpioDelay(50);
            gpioWrite(IMPACT_PIN, 0);
        }

        // Delay for 100 ms (10 Hz polling rate)
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);
    gpioWrite(IMPACT_PIN, 0); // Ensure it starts LOW
    return 0;
}

// Initialize accelerometer
int init_accelerometer() {
    // Configure CTRL_REG1_A (100 Hz, enable all axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        return -1;
    }

    // Configure CTRL_REG4_A (2G full-scale)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read all six registers at once using auto-increment
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate G-force magnitude
double calculate_g_force_magnitude(int16_t x, int16_t y, int16_t z) {
    // Sensitivity for +/- 2G range: 16384 LSB/G
    double sensitivity = 16384.0;
    double x_g = (double)x / sensitivity;
    double y_g = (double)y / sensitivity;
    double z_g = (double)z / sensitivity;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to file
void log_impact_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(IMPACT_PIN, 0); // Ensure GPIO is LOW
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Exiting gracefully.\n", signal);
    cleanup();
    exit(0);
}

