        int msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);

        if (lsb >= 0 && msb >= 0) {
            return (uint16_t)((msb << 8) | lsb);
        } else {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            gpioDelay(100); // Wait 100 ms
            retries--;
        }
