#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define FXOS8700CQ_ADDR 0x1F
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define IMPACT_THRESHOLD 19.62 // 2g in m/s^2
#define SAMPLE_INTERVAL_MS 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the FXOS8700CQ sensor
int initialize_sensor() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0xC7, got 0x%X\n", who_am_i);
        return -1;
    }

    // Set XYZ_DATA_CFG to ±2g
    int write_result = i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00);
    if (write_result < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", write_result);
        return -1;
    }

    // Put sensor in active mode (200 Hz ODR)
    write_result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01);
    if (write_result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", write_result);
        return -1;
    }

    return 0;
}

// Reads acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int read_result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (read_result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", read_result);
        return -1;
    }

    // Combine MSB and LSB, shift right by 2, and convert to g's
    int16_t raw_x = (int16_t)((((uint16_t)buffer[0]) << 8) | ((uint16_t)buffer[1])) >> 2;
    int16_t raw_y = (int16_t)((((uint16_t)buffer[2]) << 8) | ((uint16_t)buffer[3])) >> 2;
    int16_t raw_z = (int16_t)((((uint16_t)buffer[4]) << 8) | ((uint16_t)buffer[5])) >> 2;

    *x = (float)raw_x / 4096.0 * 9.81;
    *y = (float)raw_y / 4096.0 * 9.81;
    *z = (float)raw_z / 4096.0 * 9.81;

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs impact data to a file
int log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Log the impact
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Error logging impact data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 50ms
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); //pigpioDelay takes microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

