#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_RATE 20 // Hz
#define CALIBRATION_DURATION 100 // seconds
#define ALERT_THRESHOLD 50.0 // dps

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *value);
int gyro_init(int fd);
int gyro_read_raw(int fd, gyro_data_t *data);
void calibrate_gyro(int fd, gyro_data_t *zero_rate);
void log_data(FILE *fp, gyro_data_t raw, gyro_data_t calibrated);
void signal_handler(int sig);
int check_who_am_i(int fd);

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    // Check WHO_AM_I register
    if (check_who_am_i(fd) != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value. Check sensor connection.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled, 100 Hz ODR)
    if (i2c_write(fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error configuring CTRL_REG1.\n");
        return -1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    if (i2c_write(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error configuring CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

// Check WHO_AM_I register
int check_who_am_i(int fd) {
    uint8_t who_am_i;
    if (i2c_read(fd, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }
    return who_am_i;
}

// Gyroscope read raw data function
int gyro_read_raw(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate gyroscope function
void calibrate_gyro(int fd, gyro_data_t *zero_rate) {
    gyro_data_t raw_data;
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    int num_samples = CALIBRATION_DURATION * SAMPLE_RATE;

    printf("Calibrating gyroscope... Please keep the sensor stationary.\n");
    for (int i = 0; i < num_samples; i++) {
        if (gyro_read_raw(fd, &raw_data) != 0) {
            fprintf(stderr, "Error reading raw data during calibration.\n");
            return;
        }
        x_sum += raw_data.x;
        y_sum += raw_data.y;
        z_sum += raw_data.z;
        usleep(1000000 / SAMPLE_RATE); // 100 ms delay
    }

    zero_rate->x = x_sum / num_samples;
    zero_rate->y = y_sum / num_samples;
    zero_rate->z = z_sum / num_samples;

    printf("Calibration complete. Zero-rate offsets: X=%d, Y=%d, Z=%d\n", zero_rate->x, zero_rate->y, zero_rate->z);
}

// Log data function
void log_data(FILE *fp, gyro_data_t raw, gyro_data_t calibrated) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(fp, "%s, Raw: X=%d, Y=%d, Z=%d, Calibrated: X=%d, Y=%d, Z=%d\n",
            timestamp, raw.x, raw.y, raw.z, calibrated.x, calibrated.y, calibrated.z);

    if (fabs(calibrated.x) > ALERT_THRESHOLD || fabs(calibrated.y) > ALERT_THRESHOLD || fabs(calibrated.z) > ALERT_THRESHOLD) {
        fprintf(stderr, "WARNING: High angular velocity detected!\n");
        fprintf(fp, "%s, ALERT: High angular velocity detected!\n", timestamp);
    }
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    gyro_data_t raw_data, calibrated_data, zero_rate;
    int i2c_bus = I2C_BUS;
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", i2c_bus);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    calibrate_gyro(i2c_fd, &zero_rate);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw data
        if (gyro_read_raw(i2c_fd, &raw_data) == 0) {
            // Apply calibration
            calibrated_data.x = raw_data.x - zero_rate.x;
            calibrated_data.y = raw_data.y - zero_rate.y;
            calibrated_data.z = raw_data.z - zero_rate.z;

            // Log data
            log_data(log_file, raw_data, calibrated_data);
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }

        // Delay
        usleep(50000); // 50 ms
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

