#include <math.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define DEVID_REG 0x00
#define POWER_CTL_REG 0x2D
#define DATA_FORMAT_REG 0x31
#define DATAX0_REG 0x32
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_adxl345();
int read_accel_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize ADXL345 sensor
int init_adxl345() {
    // Verify DEVID register
    int devid = i2cReadByteData(i2c_handle, DEVID_REG);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID value: 0x%X\n", devid);
        return -1;
    }

    // Set data format: full resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT_REG, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
