#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Sensor addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// Accelerometer registers
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// Magnetometer registers
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_accelerometer();
int init_magnetometer();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t mag_x, int16_t mag_y, int16_t accel_x, int16_t accel_y, int16_t accel_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize accelerometer
int init_accelerometer() {
    int status = i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27);
    if (status < 0) {
        fprintf(stderr, "Error initializing accelerometer: %d\n", status);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    int status = i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error initializing magnetometer: %d\n", status);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6); // Enable auto-increment
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(int16_t mag_x, int16_t mag_y, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float roll = atan2(accel_y, accel_z) * 180 / M_PI;
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;

    float mag_x_comp = mag_x * cos(pitch * M_PI / 180) + mag_y * sin(roll * M_PI / 180) * sin(pitch * M_PI / 180) - mag_z * cos(roll * M_PI / 180) * sin(pitch * M_PI / 180);
    float mag_y_comp = mag_y * cos(roll * M_PI / 180) + mag_z * sin(roll * M_PI / 180);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_accel = i2cOpen(I2C_BUS, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C bus for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(I2C_BUS, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C bus for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_accelerometer() < 0 || init_magnetometer() < 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    int16_t mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accelerometer(&accel_x, &accel_y, &accel_z) < 0 || read_magnetometer(&mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(mag_x, mag_y, accel_x, accel_y, accel_z);

        // Log data
        log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

