    if (status < 0) return status;
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_INTERRUPT_CLEAR, 0x07ff);
    if (status < 0) return status;
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_MODE_GPIO1, 0x10);
    if (status < 0) return status;

