#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// I2C bus
#define I2C_BUS 1

// Sampling interval (10 ms)
#define SAMPLE_INTERVAL_US 10000

// Log file name
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1_data;
    int16_t sensor2_data;
    long tdoa;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    // Enable continuous measurement mode for both sensors
    if (i2cWriteByteData(i2c_handle1, 0x00, 0x80) < 0) {
        fprintf(stderr, "Failed to write to sensor 1 control register: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }
    if (i2cWriteByteData(i2c_handle2, 0x00, 0x80) < 0) {
        fprintf(stderr, "Failed to write to sensor 2 control register: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from a sensor
int16_t read_sensor(int i2c_handle) {
    int16_t data = i2cReadWordData(i2c_handle, 0x01);
    if (data < 0) {
        fprintf(stderr, "Failed to read data from I2C device: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }
    return data;
}

// Function to calculate TDOA
long calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return (long)sensor1_data - (long)sensor2_data;
}

// Function to log data to file
void log_data(FILE *log_file, long sec, long nsec, int16_t sensor1_data, int16_t sensor2_data, long tdoa) {
    fprintf(log_file, "%ld,%ld,%d,%d,%ld\n", sec, nsec, sensor1_data, sensor2_data, tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    printf("Initialization complete, starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int16_t sensor1_data = read_sensor(i2c_handle1);
        int16_t sensor2_data = read_sensor(i2c_handle2);

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            continue; // Skip to the next iteration
        }
        long sec = ts.tv_sec;
        long nsec = ts.tv_nsec;

        // Calculate TDOA
        long tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Log data
        log_data(log_file, sec, nsec, sensor1_data, sensor2_data, tdoa);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting\n");
    return 0;
}

