#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025
#define SAMPLE_INTERVAL_MS 100
#define SAMPLE_DELAY_US 40
#define CSV_FILENAME "imu_data.csv"
#define HEADER_LINE "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n"

// Global variables
int spi_handle = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t running = 1;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup();
void signal_handler(int signal);

// SPI read register function
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = 0x00; // MSB of register address
    tx_buf[1] = reg_addr; // LSB of register address

    if (spiXfer(handle, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// SPI write register function
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];

    tx_buf[0] = 0x80; // MSB of register address (set write bit)
    tx_buf[1] = reg_addr; // LSB of register address
    char data_buf[2];
    data_buf[0] = (data >> 8) & 0xFF;
    data_buf[1] = data & 0xFF;

    if (spiXfer(handle, tx_buf, NULL, 1) < 0) {
