#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8 // GPIO8
#define NUM_SENSORS 2

// Define register addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Define scale factors
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

// Global variables
int spi_fd[NUM_SENSORS];
struct gpiod_chip *gpio_chip;
struct gpiod_line *cs_line[NUM_SENSORS];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int device, int mode, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_register(int fd, uint8_t reg_addr, int16_t *data);
void close_spi(int fd);
void close_gpio(struct gpiod_chip *chip, struct gpiod_line *line);
void signal_handler(int sig);

// SPI initialization function
int spi_init(int bus, int device, int mode, int speed) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_hz = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read register function
int read_register(int fd, uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set MSB of register address to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spi_transfer(fd, tx_buf, rx_buf, 2) < 0) {
        return -1;
    }

    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Close SPI function
void close_spi(int fd) {
    close(fd);
}

// Close GPIO function
void close_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for chip-select
    cs_line[0] = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line[0]) {
        perror("Error getting GPIO line for CS0");
        close_gpio(gpio_chip, NULL);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(cs_line[0], "spi_cs", 1) < 0) {
        perror("Error requesting GPIO line for CS0");
        close_gpio(gpio_chip, cs_line[0]);
        return 1;
    }

    // Initialize SPI devices
    spi_fd[0] = spi_init(SPI_BUS, SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd[0] < 0) {
        close_gpio(gpio_chip, cs_line[0]);
        return 1;
    }

    // Initialize the second sensor
    cs_line[1] = gpiod_chip_get_line(gpio_chip, CS_PIN + 1); // Assuming CS1 is GPIO9
    if (!cs_line[1]) {
        perror("Error getting GPIO line for CS1");
        close_spi(spi_fd[0]);
        close_gpio(gpio_chip, cs_line[0]);
        return 1;
    }

    if (gpiod_line_request_output(cs_line[1], "spi_cs", 1) < 0) {
        perror("Error requesting GPIO line for CS1");
        close_spi(spi_fd[0]);
        close_gpio(gpio_chip, cs_line[0]);
        close_gpio(gpio_chip, cs_line[1]);
        return 1;
    }

    spi_fd[1] = spi_init(SPI_BUS, SPI_DEVICE + 1, SPI_MODE, SPI_SPEED);
    if (spi_fd[1] < 0) {
        close_spi(spi_fd[0]);
        close_gpio(gpio_chip, cs_line[0]);
        close_gpio(gpio_chip, cs_line[1]);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        float gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g;

        // Read sensor 0 data
        gpiod_line_set_value(cs_line[0], 0); // Assert CS0
        if (read_register(spi_fd[0], XGYRO_OUT, &gyro_x) < 0) {
            fprintf(stderr, "Error reading XGYRO_OUT from sensor 0\n");
        }
        if (read_register(spi_fd[0], YGYRO_OUT, &gyro_y) < 0) {
            fprintf(stderr, "Error reading YGYRO_OUT from sensor 0\n");
        }
        if (read_register(spi_fd[0], ZGYRO_OUT, &gyro_z) < 0) {
            fprintf(stderr, "Error reading ZGYRO_OUT from sensor 0\n");
        }
        if (read_register(spi_fd[0], XACCL_OUT, &accel_x) < 0) {
            fprintf(stderr, "Error reading XACCL_OUT from sensor 0\n");
        }
        if (read_register(spi_fd[0], YACCL_OUT, &accel_y) < 0) {
            fprintf(stderr, "Error reading YACCL_OUT from sensor 0\n");
        }
        if (read_register(spi_fd[0], ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Error reading ZACCL_OUT from sensor 0\n");
        }
        gpiod_line_set_value(cs_line[0], 1); // De-assert CS0

        // Read sensor 1 data
        gpiod_line_set_value(cs_line[1], 0); // Assert CS1
        if (read_register(spi_fd[1], XGYRO_OUT, &gyro_x) < 0) {
            fprintf(stderr, "Error reading XGYRO_OUT from sensor 1\n");
        }
        if (read_register(spi_fd[1], YGYRO_OUT, &gyro_y) < 0) {
            fprintf(stderr, "Error reading YGYRO_OUT from sensor 1\n");
        }
        if (read_register(spi_fd[1], ZGYRO_OUT, &gyro_z) < 0) {
            fprintf(stderr, "Error reading ZGYRO_OUT from sensor 1\n");
        }
        if (read_register(spi_fd[1], XACCL_OUT, &accel_x) < 0) {
            fprintf(stderr, "Error reading XACCL_OUT from sensor 1\n");
        }
        if (read_register(spi_fd[1], YACCL_OUT, &accel_y) < 0) {
            fprintf(stderr, "Error reading YACCL_OUT from sensor 1\n");
        }
        if (read_register(spi_fd[1], ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Error reading ZACCL_OUT from sensor 1\n");
        }
        gpiod_line_set_value(cs_line[1], 1); // De-assert CS1

        // Convert raw data to physical units
        gyro_x_dps = gyro_x * GYRO_SCALE;
        gyro_y_dps = gyro_y * GYRO_SCALE;
        gyro_z_dps = gyro_z * GYRO_SCALE;
        accel_x_g = accel_x * ACCEL_SCALE;
        accel_y_g = accel_y * ACCEL_SCALE;
        accel_z_g = accel_z * ACCEL_SCALE;

        // Print sensor data
        printf("Sensor 0: Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        printf("Sensor 1: Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        usleep(100000); // 100 ms delay
    }

    // Clean up resources
    close_spi(spi_fd[0]);
    close_spi(spi_fd[1]);
    close_gpio(gpio_chip, cs_line[0]);
    close_gpio(gpio_chip, cs_line[1]);

    return 0;
}

