#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.00025

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from ADIS16448
int read_register(int reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Construct the transmit buffer (register address with bit 15 set)
    tx_buf[0] = (reg_addr << 1) | 0x80; // MSB = 1 for read
    tx_buf[1] = 0x00; // Dummy byte

    // Transfer the data
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the received bytes to form the 16-bit register value
    return ((rx_buf[0] << 8) | rx_buf[1]);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope and accelerometer data
        int x_gyro_raw = read_register(X_GYRO_OUT);
        int y_gyro_raw = read_register(Y_GYRO_OUT);
        int z_gyro_raw = read_register(Z_GYRO_OUT);
        int x_accl_raw = read_register(X_ACCL_OUT);
        int y_accl_raw = read_register(Y_ACCL_OUT);
        int z_accl_raw = read_register(Z_ACCL_OUT);

        // Check for read errors
        if (x_gyro_raw == -1 || y_gyro_raw == -1 || z_gyro_raw == -1 ||
            x_accl_raw == -1 || y_accl_raw == -1 || z_accl_raw == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Scale and print the data
        float x_gyro = x_gyro_raw * GYRO_SCALE;
        float y_gyro = y_gyro_raw * GYRO_SCALE;
        float z_gyro = z_gyro_raw * GYRO_SCALE;
        float x_accl = x_accl_raw * ACCL_SCALE;
        float y_accl = y_accl_raw * ACCL_SCALE;
        float z_accl = z_accl_raw * ACCL_SCALE;

        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s, Accel: X=%.6f g, Y=%.6f g, Z=%.6f g\n",
               x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl);

        // Wait for 100 ms
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

