#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }
        uint8_t value;
        if (read(fd, &value, 1) != 1) {
            perror("Failed to read register value");
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }
        return value;
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            perror("Failed to write to register");
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I);
    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }
    printf("MPU-6886 found!\n");

    // Initialize sensor
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer range\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure gyroscope range\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = (i2c_read_reg(i2c_fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_XOUT_L);
        int16_t accel_y = (i2c_read_reg(i2c_fd, ACCEL_YOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_YOUT_L);
        int16_t accel_z = (i2c_read_reg(i2c_fd, ACCEL_ZOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_ZOUT_L);

        // Read gyroscope data
        int16_t gyro_x = (i2c_read_reg(i2c_fd, GYRO_XOUT_H) << 8) | i2c_read_reg(i2c_fd, GYRO_XOUT_L);
        int16_t gyro_y = (i2c_read_reg(i2c_fd, GYRO_YOUT_H) << 8) | i2c_read_reg(i2c_fd, GYRO_YOUT_L);
        int16_t gyro_z = (i2c_read_reg(i2c_fd, GYRO_ZOUT_H) << 8) | i2c_read_reg(i2c_fd, GYRO_ZOUT_L);

        // Print raw data
        printf("Accel: X=%6d, Y=%6d, Z=%6d | Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50ms
        usleep(50000);
    }

    // Close I2C bus (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

