        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I);
    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }
    printf("MPU-6886 found!\n");

    // Initialize sensor
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer range\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure gyroscope range\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = (i2c_read_reg(i2c_fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_XOUT_L);
        int16_t accel_y = (i2c_read_reg(i2c_fd, ACCEL_YOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_YOUT_L);
        int16_t accel_z = (i2c_read_reg(i2c_fd, ACCEL_ZOUT_H) << 8) | i2c_read_reg(i2c_fd, ACCEL_ZOUT_L);

        // Read gyroscope data
        int16_t gyro_x = (i2c_read_reg(i2c_fd, GYRO_XOUT_H) << 8) | i2c_read_reg(i2c_fd, GYRO_XOUT_L);
        int16_t gyro_y = (i2c_read_reg(i2c_fd, GYRO_YOUT_H) << 8) | i2c_read_reg(i2c_fd, GYRO_YOUT_L);
        int16_t gyro_z = (i2c_read_reg(i2c_fd, GYRO_ZOUT_H) << 8) | i2c_read_reg(i2c_fd, GYRO_ZOUT_L);

        // Print raw data
        printf("Accel: X=%6d, Y=%6d, Z=%6d | Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50ms
        usleep(50000);
    }

    // Close I2C bus (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

