#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define XYZ_DATA_CFG_REG 0x0E
#define CTRL_REG1 0x2A
#define STATUS_REG 0x00
#define OUT_X_MSB_REG 0x01
#define LED_GPIO_PIN 17 // BCM numbering
#define ACCEL_THRESHOLD 2.0 // g
#define SCALE_FACTOR 0.000244 // g/LSB for +-2g range

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int verify_sensor_id(int fd);
int configure_sensor(int fd);
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(struct gpiod_line *line, int on);
void log_impact(float x, float y, float z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        return -1;
    }
    printf("MMA8451Q sensor verified\n");
    return 0;
}

// Configure sensor
int configure_sensor(int fd) {
    // Set range to +-2g
    if (i2c_write_reg(fd, XYZ_DATA_CFG_REG, 0x00) < 0) {
        fprintf(stderr, "Error setting range\n");
        return -1;
    }

    // Enable active mode, 100 Hz ODR
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error setting active mode\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    uint8_t reg = OUT_X_MSB_REG;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x * SCALE_FACTOR * SCALE_FACTOR + y * y * SCALE_FACTOR * SCALE_FACTOR + z * z * SCALE_FACTOR * SCALE_FACTOR);
}

// Control LED
void control_led(struct gpiod_line *line, int on) {
    if (gpiod_line_set_value(line, on) < 0) {
        perror("Failed to set LED value");
    }
}

// Log impact
void log_impact(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(log_file);
}

// Signal handler
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "impact_detector", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(x, y, z);

        // Check threshold
        if (magnitude > ACCEL_THRESHOLD) {
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            control_led(led_line, 1); // Turn LED on
            log_impact((float)x * SCALE_FACTOR, (float)y * SCALE_FACTOR, (float)z * SCALE_FACTOR); // Log impact
            usleep(500000); // Wait 500ms
            control_led(led_line, 0); // Turn LED off
        }

        usleep(100000); // Wait 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) close(i2c_fd);
    if (led_line) gpiod_line_release(led_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (log_file) fclose(log_file);

    return 0;
}

