#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define SAMPLE_INTERVAL_SEC 1
#define CSV_FILE "magnetic_field_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    stop_flag = 1;
}

// Function to read a 16-bit word from the I2C device
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return (buf[1] << 8) | buf[0]; // Combine bytes to form 16-bit value
}

// Function to log data to a CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    fseek(csv_file, 0, SEEK_END); // Reset file pointer to end for appending

    // Main loop
    while (!stop_flag) {
        sensor_data_t data;
        int16_t x, y, z;

