#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATAX0 0x32
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20
#define GPIO_PIN 17
#define FREEFALL_THRESHOLD 300 // mg
#define FREEFALL_TIME 100      // ms
#define SCALE_FACTOR 0.0039    // mg/LSB

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int adxl345_enable_interrupt(int fd);
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
int setup_gpio(int pin);
void cleanup_gpio(void);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    int devid = i2c_read_reg(fd, ADXL345_DEVID);
    if (devid < 0) return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%X\n", devid);
        return -1;
    }

    // Set THRESH_FF (300 mg)
    if (i2c_write_reg(fd, ADXL345_THRESH_FF, 0x0C) < 0) return -1; // 300 mg

    // Set TIME_FF (100 ms)
    if (i2c_write_reg(fd, ADXL345_TIME_FF, 0x64) < 0) return -1; // 100 ms

    // Enable freefall interrupt
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x04) < 0) return -1; // Bit 2 = 1

    // Map to INT1
    if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x00) < 0) return -1; // INT1

    // Set POWER_CTL to measure mode
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1; // Measurement mode

    return 0;
}

// ADXL345 enable interrupt function
int adxl345_enable_interrupt(int fd) {
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x04) < 0) return -1; // Bit 2 = 1
    return 0;
}

// ADXL345 read acceleration function
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    uint8_t reg = ADXL345_DATAX0;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Log data function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, (int)(x * SCALE_FACTOR), (int)(y * SCALE_FACTOR), (int)(z * SCALE_FACTOR));
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Setup GPIO function
int setup_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "adxl345_interrupt";
    config.request_type = GPIOD_LINE_REQUEST_FALLING_EDGE;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    int16_t x, y, z;
    struct gpiod_line_event event;
    struct timespec sleep_time = {0, 10000000}; // 10ms

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Setup GPIO
    if (setup_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO setup failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpio();
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    while (!terminate) {
        int event_fd = gpiod_line_event_get_fd(gpio_line);
        if (event_fd < 0) {
            perror("Failed to get event file descriptor");
            break;
        }

        // Poll for events
        fd_set fds;
        struct timeval timeout = {1, 0}; // 1 second timeout

        FD_ZERO(&fds);
        FD_SET(event_fd, &fds);

        int ret = select(event_fd + 1, &fds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("select() failed");
            break;
        } else if (ret == 0) {
            // Timeout, continue polling
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Event occurred
        if (gpiod_line_event_wait(gpio_line, &event) < 0) {
            perror("Failed to wait for event");
            break;
        }

        // Read INT_SOURCE
        int int_source = i2c_read_reg(i2c_fd, ADXL345_INT_SOURCE);
        if (int_source < 0) {
            fprintf(stderr, "Failed to read INT_SOURCE\n");
            break;
        }

        // Check if freefall interrupt is set
        if (int_source & 0x04) {
            printf("Freefall detected!\n");

            // Read acceleration data
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) < 0) {
                fprintf(stderr, "Failed to read acceleration data\n");
                break;
            }

            // Log data
            log_data(log_file, x, y, z);
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    adxl345_enable_interrupt(i2c_fd); // Disable interrupts
    fclose(log_file);
    cleanup_gpio();
    close(i2c_fd);

    return 0;
}

