#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Configuration values
#define ACCEL_FS_2G 2.0f  // +/- 2g
#define GYRO_FS_250DPS 250.0f // +/- 250 dps
#define ODR_104HZ 104.0f

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // 0.2g
#define IMPACT_THRESHOLD 2.5f   // 2.5g
#define WINDOW_DURATION 1.0f   // 1 second

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Structure to hold fall detection state
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} fall_state_t;

fall_state_t current_state = IDLE;
time_t freefall_start_time = 0;

// Function prototypes
int init_i2c();
int check_who_am_i();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(const sensor_data_t *data);
void log_data(const sensor_data_t *data);
void detect_fall(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // Bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check WHO_AM_I register
int check_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed. Value: 0x%X\n", who_am_i);
    return 0;
}

// Configure the LSM6DSR sensor
int configure_sensor() {
    // Configure accelerometer: 104 Hz, +-2g
    int result = i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x80); // 104 Hz, +-2g
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL: %d\n", result);
        return -1;
    }

    // Configure gyroscope: 104 Hz, +-250 dps
    result = i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x80); // 104 Hz, +-250 dps
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL2_G: %d\n", result);
        return -1;
    }

    printf("Sensor configured.\n");
    return 0;
}

// Read accelerometer and gyroscope data
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Extract accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    data->gyro_x = (float)gyro_x_raw / 131.0f; // Sensitivity at 250 dps is 8.75 mdps/digit
    data->gyro_y = (float)gyro_y_raw / 131.0f;
    data->gyro_z = (float)gyro_z_raw / 131.0f;
    data->accel_x = (float)accel_x_raw / 16384.0f; // Sensitivity at 2g is 8192 LSB/g
    data->accel_y = (float)accel_y_raw / 16384.0f;
    data->accel_z = (float)accel_z_raw / 16384.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(const sensor_data_t *data) {
    return sqrt(data->accel_x * data->accel_x + data->accel_y * data->accel_y + data->accel_z * data->accel_z);
}

// Log data to file
void log_data(const sensor_data_t *data) {
    FILE *fp = fopen("motion_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            rawtime, data->accel_x, data->accel_y, data->accel_z, data->gyro_x, data->gyro_y, data->gyro_z);

    fclose(fp);
}

// Detect fall
void detect_fall(const sensor_data_t *data) {
    float magnitude = calculate_acceleration_magnitude(data);
    time_t current_time = time(NULL);

    switch (current_state) {
        case IDLE:
            if (magnitude < FREEFALL_THRESHOLD) {
                current_state = FREEFALL;
                freefall_start_time = current_time;
                printf("Freefall detected!\n");
            }
            break;
        case FREEFALL:
            if (magnitude > IMPACT_THRESHOLD) {
                current_state = IMPACT;
                printf("Impact detected!\n");
            } else if (difftime(current_time, freefall_start_time) >= WINDOW_DURATION) {
                current_state = IDLE;
                printf("Fall detection window expired. Returning to IDLE.\n");
            }
            break;
        case IMPACT:
            current_state = IDLE;
            break;
    }
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Check WHO_AM_I register
    if (check_who_am_i() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(&sensor_data);

            // Detect fall
            detect_fall(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(10000); // 10ms delay (100Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

