#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I  0x56
#define ADIS16266_X_GYRO_OUT 0x14
#define ADIS16266_SMPL_PRD  0x36
#define ADIS16266_GLOB_CMD  0x68

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling Factor
#define SCALE_FACTOR 0.0305

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adis16266_read_register(int handle, uint8_t reg);
int adis16266_write_register(int handle, uint8_t reg, uint16_t value);
float adis16266_read_gyro_rate(int handle);
void log_data(FILE *fp, float rate);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a register from the ADIS16266
int adis16266_read_register(int handle, uint8_t reg) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;       // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    return (rx_buf[0] << 8) | rx_buf[1];
}

// Function to write a register in the ADIS16266
int adis16266_write_register(int handle, uint8_t reg, uint16_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = value & 0xFF; //LSB

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    tx_buf[0] = (value >> 8) & 0xFF; //MSB
    tx_buf[1] = 0x00; //Dummy byte

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the gyroscope rate
float adis16266_read_gyro_rate(int handle) {
    int raw_data = adis16266_read_register(handle, ADIS16266_X_GYRO_OUT);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading gyro rate\n");
        return 0.0;
    }
    return (float)raw_data * SCALE_FACTOR;
}

// Function to log the data to a CSV file
void log_data(FILE *fp, float rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f\n", timestamp, rate);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = adis16266_read_register(spi_handle, ADIS16266_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "WHO_AM_I mismatch: Expected 0x3F5A, got 0x%X\n", who_am_i);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADIS16266 WHO_AM_I: 0x%X\n", who_am_i);

    // Configure SMPL_PRD (Sample Period) to 10ms (adjust as needed)
    if (adis16266_write_register(spi_handle, ADIS16266_SMPL_PRD, 0x000A) < 0) {
        fprintf(stderr, "Failed to write SMPL_PRD register\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GLOB_CMD to reset (optional)
    if (adis16266_write_register(spi_handle, ADIS16266_GLOB_CMD, 0x0006) < 0) {
        fprintf(stderr, "Failed to write GLOB_CMD register\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Rate(deg/s)\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float rate = adis16266_read_gyro_rate(spi_handle);
        log_data(log_file, rate);
        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

