#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 114.285f // mdps/LSB for +-250 dps
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms in nanoseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Check WHO_AM_I register
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, WHO_AM_I_REG, 0x00); // Dummy write to trigger read
        if (status >= 0) {
            int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
            if (who_am_i == WHO_AM_I_VALUE) {
                break;
            } else {
                fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
            }
        } else {
            fprintf(stderr, "I2C write error during WHO_AM_I check: %s\n", strerror(errno));
        }
        retries--;
        gpioDelay(1000); // Wait 1 ms before retrying
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to verify WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "I2C write error during CTRL_REG1 configuration: %s\n", strerror(errno));
        }
        retries--;
        gpioDelay(1000); // Wait 1 ms before retrying
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (+-250 dps)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "I2C write error during CTRL_REG4 configuration: %s\n", strerror(errno));
        }
        retries--;
        gpioDelay(1000); // Wait 1 ms before retrying
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        data.x = 0.0f; // Set to 0 to avoid garbage values
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to degrees per second
    data.x = (float)raw_x / SENSITIVITY;
    data.y = (float)raw_y / SENSITIVITY;
    data.z = (float)raw_z / SENSITIVITY;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_NS / 1000); // Delay for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

