volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int flame_detected;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[100];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    } else {
        fprintf(log_file, "Program started\n");
        fflush(log_file);
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read flame sensor value
        flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Format log message
        if (flame_detected == 0) {
            snprintf(log_message, sizeof(log_message), "%s - Flame detected: YES\n", timestamp);
            printf("FLAME DETECTED!\n");
        } else if (flame_detected == 1) {
            snprintf(log_message, sizeof(log_message), "%s - Flame detected: NO\n", timestamp);
        } else {
            snprintf(log_message, sizeof(log_message), "%s - Error reading sensor\n", timestamp);
            fprintf(stderr, "Error reading sensor value\n");
        }

        // Log to file
        if (log_file != NULL) {
            fprintf(log_file, "%s", log_message);
            fflush(log_file);
        } else {
            fprintf(stderr, "Log file not open, cannot log: %s", log_message);
        }

        // Wait 500 milliseconds
        gpioDelay(500000); // pigpioDelay is in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fprintf(log_file, "Program terminated\n");
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

