#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x53
#define DATA_REGISTERS 0x28
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int address);
int read_sensor_data(int fd, sensor_data_t *data);
char* get_iso8601_timestamp(char *timestamp_str, size_t size);
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data from I2C
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[DATA_LENGTH];
    ssize_t bytes_read = read(fd, buffer, DATA_LENGTH);

    if (bytes_read != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %zd bytes read (expected %d)\n", bytes_read, DATA_LENGTH);
        return -1;
    }

    // Combine LSB and MSB for each axis
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char *timestamp_str, size_t size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
