#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int i2c_read_reg(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    unsigned char value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        close(i2c_fd);
        return 1;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value (0x%02X, expected 0x2A).\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg(i2c_fd, CTRL_REG1, 0x00) < 0) { // Standby mode
        fprintf(stderr, "Error writing to CTRL_REG1.\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg(i2c_fd, CTRL_REG1, 0x18) < 0) { // 100 Hz, Active mode
        fprintf(stderr, "Error writing to CTRL_REG1.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct timespec ts;
    while (program_running) {
        int x_msb = i2c_read_reg(i2c_fd, OUT_X_MSB);
        int x_lsb = i2c_read_reg(i2c_fd, OUT_X_LSB);
        int y_msb = i2c_read_reg(i2c_fd, OUT_Y_MSB);
        int y_lsb = i2c_read_reg(i2c_fd, OUT_Y_LSB);
        int z_msb = i2c_read_reg(i2c_fd, OUT_Z_MSB);
        int z_lsb = i2c_read_reg(i2c_fd, OUT_Z_LSB);

        if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
            fprintf(stderr, "Error reading accelerometer data.\n");
            continue; // Skip to the next iteration
        }

        int x = ((x_msb << 8) | x_lsb) >> 4;
        int y = ((y_msb << 8) | y_lsb) >> 4;
        int z = ((z_msb << 8) | z_lsb) >> 4;

        double tilt_angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;

        if (fabs(tilt_angle) > 45) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld, X: %d, Y: %d, Z: %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10 ms
    }

    close(i2c_fd);
    fclose(log_file);
    return 0;
}

