// I2C write function with retry
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        }
        perror("I2C write failed");
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    int retries = 3;
    while (retries > 0) {
        if (read(fd, value, 1) == 1) {
            return 0; // Success
        }
        perror("I2C read failed");
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// LIS3MDL initialization function
int lis3mdl_init(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (i2c_read(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D.\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (ODR = 80 Hz, continuous conversion)
    if (i2c_write(fd, CTRL_REG1, 0x70) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1.\n");
        return -1;
    }

    // Configure CTRL_REG3 (Continuous conversion mode)
    if (i2c_write(fd, CTRL_REG3, 0x00) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG3.\n");
        return -1;
    }

    // Configure CTRL_REG4 (High-performance mode on all axes)
    if (i2c_write(fd, CTRL_REG4, 0x0C) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4.\n");
        return -1;
    }

    printf("LIS3MDL initialized successfully.\n");
    return 0;
}

// Read magnetometer data function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read all 6 bytes in one go
    if (write(fd, (uint8_t[1]){OUT_X_L}, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to milliGauss
void convert_to_mg(int16_t x, int16_t y, int16_t z, float *x_mg, float *y_mg, float *z_mg) {
    *x_mg = (float)x * SENSITIVITY * X_SCALE + X_OFFSET;
    *y_mg = (float)y * SENSITIVITY * Y_SCALE + Y_OFFSET;
    *z_mg = (float)z * SENSITIVITY * Z_SCALE + Z_OFFSET;
}

// Log data to file
void log_data(float x_mg, float y_mg, float z_mg) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_mg, y_mg, z_mg);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Metal detector alert
void metal_detected(float x_mg, float y_mg, float z_mg) {
    float magnitude = sqrt(x_mg * x_mg + y_mg * y_mg + z_mg * z_mg);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Magnitude: %.3f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    float x_mg, y_mg, z_mg;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
