    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize LIS3MDL
    if (lis3mdl_init(i2c_fd) != 0) {
        fprintf(stderr, "LIS3MDL initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to milliGauss
            convert_to_mg(raw_x, raw_y, raw_z, &x_mg, &y_mg, &z_mg);

            // Log data
            log_data(x_mg, y_mg, z_mg);

