    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    return rx[1];
}

// Function to write a single register in the ADXL354B
int adxl354b_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write
    tx[1] = value;

    if (spiWrite(handle, tx, 2) != 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to reset the ADXL354B
int adxl354b_reset(int handle) {
    if (adxl354b_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Error resetting ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to configure the ADXL354B for measurement mode
int adxl354b_configure(int handle) {
    // Clear RUN bit in POWER_CTL
    if (adxl354b_write_register(handle, ADXL354B_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error clearing RUN bit in POWER_CTL\n");
        return -1;
    }

    // Wait for STABLE bit to be set in STATUS
    int status;
    do {
        status = adxl354b_read_register(handle, ADXL354B_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading STATUS register\n");
            return -1;
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    } while ((status & 0x08) == 0); // Check STABLE bit (bit 3)

    // Set RUN bit in POWER_CTL
    if (adxl354b_write_register(handle, ADXL354B_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Error setting RUN bit in POWER_CTL\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z) {
    char tx[7], rx[7];
    tx[0] = ADXL354B_XDATA_L | 0x80; // Read XDATA_L
    tx[1] = 0x00; // Dummy bytes for XDATA_H, YDATA_L, YDATA_H, ZDATA_L, ZDATA_H
    tx[2] = 0x00;
    tx[3] = 0x00;
    tx[4] = 0x00;
    tx[5] = 0x00;
    tx[6] = 0x00;

    if (spiXfer(handle, tx, rx, 7) != 0) {
        fprintf(stderr, "SPI read error for acceleration data\n");
        return -1;
    }

    // Combine bytes to form 20-bit signed integers
    int32_t x_raw = ((int32_t)rx[2] << 12) | ((int32_t)rx[1] << 4) | ((int32_t)rx[0] >> 4);
    int32_t y_raw = ((int32_t)rx[4] << 12) | ((int32_t)rx[3] << 4) | ((int32_t)rx[2] >> 4);
    int32_t z_raw = ((int32_t)rx[6] << 12) | ((int32_t)rx[5] << 4) | ((int32_t)rx[4] >> 4);

    // Sign extend 20-bit integers to 32-bit
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    // Convert to g-force units
    *x = (float)x_raw * 0.0000039;
    *y = (float)y_raw * 0.0000039;
    *z = (float)z_raw * 0.0000039;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence by reading PARTID
    int partid = adxl354b_read_register(spi_handle, ADXL354B_PARTID);
    if (partid != 0x1D) {
        fprintf(stderr, "ADXL354B not detected (PARTID = 0x%02X)\n", partid);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (adxl354b_configure(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B configuration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            // Log the data
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

