#define ACCEL_SCALE 0.0025

// Define delay between reads (approximately 100 Hz)
#define READ_DELAY_US 10000 // 10 ms

// Global variables for graceful shutdown
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a 16-bit register from ADIS16362
int16_t read_register(int spi_handle, uint8_t reg_addr) {
    char tx_buf[3];
    char rx_buf[3];
    int result;

    // Construct the transmit buffer: register address (MSB set) and dummy byte
    tx_buf[0] = reg_addr | 0x80; // MSB set to initiate read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

