        x_accel = read_register(spi_handle, X_ACCL);
        y_accel = read_register(spi_handle, Y_ACCL);
        z_accel = read_register(spi_handle, Z_ACCL);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break; // Exit loop on error
        }

        // Log data if read was successful
        if (x_gyro != -1 && y_gyro != -1 && z_gyro != -1 &&
            x_accel != -1 && y_accel != -1 && z_accel != -1) {
            log_data(log_file, ts, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);
        }

        // Delay for approximately 100 Hz
        usleep(READ_DELAY_US);
    }

    // Close SPI channel and log file
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

