#include <string.h>

#define GPIO_PIN 17
#define POLL_INTERVAL_SEC 1

static volatile int keepRunning = 1;
static int gpio_handle = -1;

void signalHandler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        keepRunning = 0;
    }
}

int main() {
    int rc;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT
    signal(SIGINT, signalHandler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpio_handle = gpioOpen(GPIO_PIN, 0, 0); // Open GPIO17 for reading
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %d\n", GPIO_PIN, gpio_handle);
        gpioTerminate();
        return 1;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        // Read GPIO value
        int value = gpioRead(gpio_handle);

        if (value == 0) { // Obstacle detected (LOW)
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log self-parking sequence start
            printf("[%s] Self-parking sequence started\n", timestamp);

            // Simulate self-parking sequence (sleep for 5 seconds)
            gpioDelay(5000000); // 5 seconds

            // Log self-parking sequence completion
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Self-parking sequence completed\n", timestamp);
        }

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    // Clean up and exit
    gpioClose(gpio_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

