#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO27 27

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int handle;
    int values[2];
    int ret;
    struct timespec ts;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    handle = gpioOpen(GPIO17, 0, 0); // Open GPIO17, doesn't matter what we pass as flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 and GPIO27 as inputs
    gpioSetMode(GPIO17, PI_INPUT);
    gpioSetMode(GPIO27, PI_INPUT);

    // Set pull-up/down resistor (optional, depends on sensor wiring)
    gpioSetPullUpDown(GPIO17, PI_PUD_UP);
    gpioSetPullUpDown(GPIO27, PI_PUD_UP);

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read GPIO17 and GPIO27 values
        ret = gpioReadBulk(handle, values, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO values: %d\n", ret);
            break; // Exit loop on error
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break; // Exit loop on error
        }

        // Log obstacle detection status
        printf("%ld.%09ld: Sensor 1: %d, Sensor 2: %d\n", ts.tv_sec, ts.tv_nsec, values[0], values[1]);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and exit
    gpioClose(handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

