#include <errno.h>
#include <string.h>

// Define SPI and GPIO parameters
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE 3
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)

// Define ADIS16266 register addresses
#define MSC_CTRL 0x24
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08

// Define scale factor
#define SCALE_FACTOR 0.02

// Global variables for GPIO and SPI resources
struct gpiod_chip *gpio_chip;
struct gpiod_line *cs_line;
int spi_fd;

// Function prototypes
int spi_init(int bus, int device, int mode, int speed);
int gpio_init(int pin);
int spi_write(int fd, uint8_t data);
int spi_read(int fd, uint8_t *data, int len);
int adis16266_read_register(int fd, uint8_t reg_addr, int16_t *data);
void cleanup();
void signal_handler(int sig);

// Structure to hold gyroscope data
typedef struct {
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO and SPI
    if (gpio_init(CS_PIN) < 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    if ((spi_fd = spi_init(SPI_BUS, SPI_DEVICE, SPI_MODE, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Enable data ready mode in ADIS16266
    uint8_t msc_ctrl_data[2];
    msc_ctrl_data[0] = MSC_CTRL | 0x80; // MSB set for write
    msc_ctrl_data[1] = 0x04;            // Enable data ready mode

    if (spi_write(spi_fd, msc_ctrl_data[1]) < 0) {
        fprintf(stderr, "Failed to write to MSC_CTRL register. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop to read and log gyroscope data
    while (1) {
        gyro_data_t gyro_data;

        // Read X, Y, and Z angular rates
        if (adis16266_read_register(spi_fd, X_GYRO_OUT, &gyro_data.x_rate) < 0) {
            fprintf(stderr, "Failed to read X gyro data.\n");
        }
        if (adis16266_read_register(spi_fd, Y_GYRO_OUT, &gyro_data.y_rate) < 0) {
            fprintf(stderr, "Failed to read Y gyro data.\n");
        }
        if (adis16266_read_register(spi_fd, Z_GYRO_OUT, &gyro_data.z_rate) < 0) {
            fprintf(stderr, "Failed to read Z gyro data.\n");
        }

        // Log the data
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n",
               gyro_data.x_rate * SCALE_FACTOR,
               gyro_data.y_rate * SCALE_FACTOR,
               gyro_data.z_rate * SCALE_FACTOR);

        // Wait 100 ms
        usleep(100000);
    }

    return 0;
}

// Initialize SPI device
int spi_init(int bus, int device, int mode, int speed) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_data = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_data) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_data = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_data) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO pin for chip select
int gpio_init(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "adis16266", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Write data to SPI device
int spi_write(int fd, uint8_t data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)&data,
        .len = 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error writing to SPI device");
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    return 0;
}

// Read data from SPI device
int spi_read(int fd, uint8_t *data, int len) {
    struct spi_ioc_transfer transfer = {
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error reading from SPI device");
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    return 0;
}

// Read a register from the ADIS16266
int adis16266_read_register(int fd, uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Send register address with MSB set for read
    tx_buf[0] = reg_addr | 0x80; // MSB set for read
    tx_buf[1] = 0x00;            // Dummy byte for reading MSB
    tx_buf[2] = 0x00;            // Dummy byte for reading LSB

    struct spi_ioc_transfer transfer[2];

    transfer[0].tx_buf = (unsigned long)&tx_buf[0];
    transfer[0].rx_buf = 0; // No RX buffer for the first transfer
    transfer[0].len = 1;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0;

    transfer[1].tx_buf = (unsigned long)&tx_buf[1];
    transfer[1].rx_buf = (unsigned long)&rx_buf[1];
    transfer[1].len = 2;
    transfer[1].speed_hz = SPI_SPEED;
    transfer[1].bits_per_word = 8;
    transfer[1].delay_usecs = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(2), transfer) < 0) {
        perror("Error reading from SPI device");
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
        }
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd > 0) {
        close(spi_fd);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

