#define GYRO_SENSITIVITY 0.00875f  // dps/LSB
#define ACCEL_SENSITIVITY 0.000061f // g/LSB

// Global I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, int reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, int reg, int value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x6B, got 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("LSM6DSR sensor found\n");

    // Configure accelerometer and gyroscope
    if (write_register(i2c_handle, CTRL1_XL, 0x42) < 0) { // 104 Hz, +-2g
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, CTRL2_G, 0x42) < 0) { // 104 Hz, +-250 dps
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyro data
        int gyro_x_l = read_register(i2c_handle, OUTX_L_G);
        int gyro_x_h = read_register(i2c_handle, OUTX_H_G);
        int gyro_y_l = read_register(i2c_handle, OUTY_L_G);
        int gyro_y_h = read_register(i2c_handle, OUTY_H_G);
        int gyro_z_l = read_register(i2c_handle, OUTZ_L_G);
        int gyro_z_h = read_register(i2c_handle, OUTZ_H_G);

        if (gyro_x_l < 0 || gyro_x_h < 0 || gyro_y_l < 0 || gyro_y_h < 0 || gyro_z_l < 0 || gyro_z_h < 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }

        // Read accelerometer data
        int accel_x_l = read_register(i2c_handle, OUTX_L_XL);
        int accel_x_h = read_register(i2c_handle, OUTX_H_XL);
        int accel_y_l = read_register(i2c_handle, OUTY_L_XL);
        int accel_y_h = read_register(i2c_handle, OUTY_H_XL);
        int accel_z_l = read_register(i2c_handle, OUTZ_L_XL);
        int accel_z_h = read_register(i2c_handle, OUTZ_H_XL);

        if (accel_x_l < 0 || accel_x_h < 0 || accel_y_l < 0 || accel_y_h < 0 || accel_z_l < 0 || accel_z_h < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            break;
        }

        // Combine high and low bytes
        short gyro_x = (gyro_x_h << 8) | gyro_x_l;
        short gyro_y = (gyro_y_h << 8) | gyro_y_l;
        short gyro_z = (gyro_z_h << 8) | gyro_z_l;
        short accel_x = (accel_x_h << 8) | accel_x_l;
        short accel_y = (accel_y_h << 8) | accel_y_l;
        short accel_z = (accel_z_h << 8) | accel_z_l;

        // Convert to physical units
        float gyro_x_dps = gyro_x * GYRO_SENSITIVITY;
        float gyro_y_dps = gyro_y * GYRO_SENSITIVITY;
        float gyro_z_dps = gyro_z * GYRO_SENSITIVITY;
        float accel_x_g = accel_x * ACCEL_SENSITIVITY;
        float accel_y_g = accel_y * ACCEL_SENSITIVITY;
        float accel_z_g = accel_z * ACCEL_SENSITIVITY;

        // Print data
        printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps  Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

