#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// Global I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    // Check WHO_AM_I register
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
        if (status >= 0) {
            if (status == 0xC7) {
                printf("FXOS8700 sensor found.\n");
                break;
            } else {
                fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", status);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1: Hybrid mode, 100 Hz data rate
    status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x15); // Active mode, 100 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure CTRL_REG2: High resolution
    status = i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x02); // High resolution
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %d\n", status);
        return -1;
    }

    // Configure M_CTRL_REG1: Hybrid mode, 100 Hz data rate
    status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x15); // Active mode, 100 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure M_CTRL_REG2: High resolution
    status = i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x02); // High resolution
    if (status < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2: %d\n", status);
        return -1;
    }

    return 0;
}

