// Read acceleration data from ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate tilt angle using atan2
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = x * SCALE_FACTOR;
    double y_g = y * SCALE_FACTOR;
    double z_g = z * SCALE_FACTOR;

    double tilt_x = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180 / M_PI;
    double tilt_y = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180 / M_PI;

    return tilt_x;
}

// Log tilt event to file
void log_event(double x_angle, double y_angle, double z_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Tilt: X=%.2f, Y=%.2f, Z=%.2f\n", s, x_angle, y_angle, z_angle);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    double tilt_angle;

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Log event if tilt exceeds threshold
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                log_event(tilt_angle, tilt_angle, tilt_angle); // Log all axes with the same value
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Tilt monitoring stopped.\n");

    return 0;
}

