#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_WINDOW_MS 5000
#define SAMPLE_INTERVAL_US 1000 // 1ms

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        high_count = 0;
        for (int i = 0; i < SAMPLE_WINDOW_MS; i++) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (high_count > threshold) {
            printf("%s ALERT: High readings: %d\n", timestamp, high_count);
        } else {
            printf("%s Status: High readings: %d\n", timestamp, high_count);
        }

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

