#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;
static int current_code = 0;

// Function prototypes
int initialize_gpio(void);
int generate_code(void);
int unlock_door(int door);
int lock_door(int door);
int log_access(int code);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Lock both doors
    lock_door(0); // Door A
    lock_door(1); // Door B

    // Release GPIO lines
    if (door_a_line) {
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_release(door_b_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

// Initialize GPIO pins
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Get GPIO line for Door A
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_chip;
    }

    // Get GPIO line for Door B
    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup_line_a;
    }

    // Request GPIO line for Door A as output
    ret = gpiod_line_request_output(door_a_line, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_line_b;
    }

    // Request GPIO line for Door B as output
    ret = gpiod_line_request_output(door_b_line, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup_line_a_request;
    }

    return 0;

cleanup_line_a_request:
    gpiod_line_release(door_a_line);
cleanup_line_b:
    gpiod_line_release(door_b_line);
cleanup_line_a:
    gpiod_chip_close(chip);
cleanup_chip:
    chip = NULL;
    return -1;
}

// Generate a random 6-digit security code
int generate_code(void) {
    int code = (rand() % 900000) + 100000; // Generate a random number between 100000 and 999999
    return code;
}

// Unlock a door
int unlock_door(int door) {
    int ret;
    struct gpiod_line *line = (door == 0) ? door_a_line : door_b_line;

    if (!line) {
        fprintf(stderr, "Error: Invalid door number %d\n", door);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1); // Set GPIO HIGH
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    sleep(5); // Keep unlocked for 5 seconds

    ret = gpiod_line_set_value(line, 0); // Set GPIO LOW
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Lock a door
int lock_door(int door) {
    int ret;
    struct gpiod_line *line = (door == 0) ? door_a_line : door_b_line;

    if (!line) {
        fprintf(stderr, "Error: Invalid door number %d\n", door);
        return -1;
    }

    ret = gpiod_line_set_value(line, 0); // Set GPIO LOW
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Log access event to file
int log_access(int code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%06d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, code);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

int main(void) {
    int user_code;
    char input[10]; // Buffer for user input
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Generate and print the initial security code
    current_code = generate_code();
    printf("Initial security code: %06d\n", current_code);

    // Main loop
    while (!terminate) {
        printf("Enter security code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            // Handle EOF or error
            if (feof(stdin)) {
                printf("End of input.\n");
                break;
            } else {
                fprintf(stderr, "Error reading input: %s\n", strerror(errno));
                continue; // Or handle the error as appropriate
            }
        }

        // Remove trailing newline character
        input[strcspn(input, "\n")] = 0;

        // Validate input
        for (i = 0; input[i] != '\0'; i++) {
            if (!isdigit(input[i])) {
                printf("Invalid input. Please enter a 6-digit number.\n");
                // Clear the input buffer
                while (getchar() != '\n');
                break;
            }
        }

        if (input[i] != '\0') continue; // If there were non-digit characters, skip the rest of the loop

        // Convert input to integer
        user_code = atoi(input);

        // Check if the entered code matches the current code
        if (user_code == current_code) {
            printf("Access granted!\n");
            unlock_door(0); // Unlock Door A
            sleep(1); // Small delay
            lock_door(0);  // Lock Door A
            log_access(current_code);
            current_code = generate_code();
            printf("New security code: %06d\n", current_code);
        } else {
            printf("Access denied!\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

