#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CMD_HIGH_RES 0x21
#define LOG_FILE "light_log.txt"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int i2c_fd;
    FILE *log_file;
    uint8_t buffer[2];
    uint16_t raw_value;
    float lux;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Send high-resolution mode command
        if (write(i2c_fd, &BH1750_CMD_HIGH_RES, 1) != 1) {
            perror("Error writing to I2C bus");
            break;
        }

        // Wait for conversion (180ms)
        usleep(180000);

        // Read 2 bytes of data
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Error reading from I2C bus");
            break;
        }

        // Combine bytes into raw value
        raw_value = (buffer[0] << 8) | buffer[1];

        // Calculate lux value
        lux = (raw_value * 5.0) / 6.0;

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log data to file
        fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
        fflush(log_file); // Ensure data is written immediately

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

