#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQUENCY 440
#define SERVER_PORT 12345
#define MOTION_DETECT_COMMAND "MOTION_DETECTED:MySecretKey"
#define LOG_FILE "frequency_log.txt"

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_handle;
int server_socket;
FILE *log_file;

// Function prototypes
int initialize_mpr121();
int read_touch_data(int *touch_data);
float map_touch_to_frequency(int touch_data);
void play_tones(float frequency, int duration_ms);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_socket >= 0) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the MPR121 sensor
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure electrode sensitivity and baseline filtering (example values)
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) { // Set USL
        fprintf(stderr, "Error: Failed to write CONFIG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) { // Set LSL
        fprintf(stderr, "Error: Failed to write CONFIG2\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Reads the touch data from the MPR121 sensor
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = ((int)buf[1] << 8) | (int)buf[0];
    return 0;
}

// Maps the touch data to a frequency using a logarithmic scale
float map_touch_to_frequency(int touch_data) {
    // Assuming touch_data is a value between 0 and 1023
    float frequency = 220.0 + (880.0 - 220.0) * (log10((float)touch_data / 1023.0) / log10(1.0));
    return frequency;
}

// Plays a tone using hardware PWM
void play_tones(float frequency, int duration_ms) {
    gpioSetPWMfrequency(PWM_GPIO, (int)frequency);
    gpioPWM(PWM_GPIO, 128); // 50% duty cycle
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioPWM(PWM_GPIO, 0); // Stop PWM
}

// Logs the frequency to a file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Frequency = %.2f Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handles a client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        if (strncmp(buffer, MOTION_DETECT_COMMAND, strlen(MOTION_DETECT_COMMAND)) == 0) {
            printf("Motion detected! Playing tones...\n");
            int touch_data;
            if (read_touch_data(&touch_data) == 0) {
                float frequency = map_touch_to_frequency(touch_data);
                play_tones(frequency, 5000); // Play for 5 seconds
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Error: Failed to read touch data during motion detection\n");
            }
        }
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else {
        perror("recv failed");
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO mode
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    // Accept connections and handle them
    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        handle_client(client_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_socket);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

