#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000 // 1ms
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line_request_config pwm_config;
static int running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(int brightness);
void signal_handler(int sig);
int initialize_i2c();
int initialize_gpio();
int initialize_pwm();
void cleanup();

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Magnitude calculation function
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf(x * x + y * y + z * z);
}

// LED brightness control function
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    struct gpiod_line_request_config pwm_config;
    memset(&pwm_config, 0, sizeof(pwm_config));
    pwm_config.consumer = "magnetometer_led";
    pwm_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &pwm_config, 0) < 0) {
        perror("Failed to request LED line");
        return -1;
    }

    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Failed to set LED high");
        gpiod_line_release(led_line);
        return -1;
    }

    // Simple PWM: Set the line high for a portion of the period
    struct timespec on_time = {0, brightness * PWM_PERIOD_NS / 256};
    struct timespec off_time = {0, (256 - brightness) * PWM_PERIOD_NS / 256};

    nanosleep(&on_time, NULL);
    nanosleep(&off_time, NULL);

    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to set LED low");
        gpiod_line_release(led_line);
        return -1;
    }

    gpiod_line_release(led_line);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

// I2C initialization function
int initialize_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // Initialize magnetometer (10 Hz, continuous conversion)
    if (i2c_write_byte(i2c_fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// PWM initialization function
int initialize_pwm() {
    pwm_config.consumer = "magnetometer_led";
    pwm_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &pwm_config, 0) < 0) {
        perror("Failed to request LED line for PWM");
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
