#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define CONFIG_A_VALUE 0x70 // 8-sample averaging, 15 Hz output rate
#define CONFIG_B_VALUE 0x20 // Gain setting of 1.3 Gauss
#define MODE_CONTINUOUS 0x00 // Continuous measurement mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    double x_offset;
    double y_offset;
    double z_offset;
} hard_iron_offsets_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to write a byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int handle, magnetometer_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate hard-iron offsets
void calculate_hard_iron_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t *offsets, int num_samples) {
    static double x_sum = 0.0;
    static double y_sum = 0.0;
    static double z_sum = 0.0;
    static int sample_count = 0;

    x_sum += raw_data.x;
    y_sum += raw_data.y;
    z_sum += raw_data.z;
    sample_count++;

    if (sample_count >= num_samples) {
        offsets->x_offset = x_sum / num_samples;
        offsets->y_offset = y_sum / num_samples;
        offsets->z_offset = z_sum / num_samples;

        x_sum = 0.0;
        y_sum = 0.0;
        z_sum = 0.0;
        sample_count = 0;
    }
}

// Function to apply hard-iron offsets
void apply_hard_iron_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t offsets, magnetometer_data_t *corrected_data) {
    corrected_data->x = raw_data.x - offsets.x_offset;
    corrected_data->y = raw_data.y - offsets.y_offset;
    corrected_data->z = raw_data.z - offsets.z_offset;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (write_register(i2c_handle, HMC5883L_CONFIG_A, CONFIG_A_VALUE) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, HMC5883L_CONFIG_B, CONFIG_B_VALUE) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, HMC5883L_MODE, MODE_CONTINUOUS) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    magnetometer_data_t raw_data, corrected_data;
    hard_iron_offsets_t offsets;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_handle, &raw_data) == 0) {
            // Calculate hard-iron offsets
            calculate_hard_iron_offsets(raw_data, &offsets, 100);

            // Apply hard-iron offsets
            apply_hard_iron_offsets(raw_data, offsets, &corrected_data);

            // Print corrected data
            printf("X: %d, Y: %d, Z: %d\n", corrected_data.x, corrected_data.y, corrected_data.z);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // pigpio uses microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

