#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DURATION 0x33
#define OUT_X_L_A 0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x, y, z;
} accel_data_t;

// Global variables
int i2c_fd;
struct gpiod_line *gpio_line;
struct gpiod_chip *gpio_chip;
accel_data_t accel_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte(int reg);
int i2c_write_byte(int reg, int val);
int i2c_read_block(int reg, int len, uint8_t *buf);
int init_lsm303d();
void interrupt_handler(int signum);
void signal_handler(int signum);
void dump_buffer();

// I2C read byte function
int i2c_read_byte(int reg) {
    int result;
    uint8_t buf[1];

    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %d\n", reg);
        return -1;
    }

    result = read(i2c_fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %d\n", reg, result);
        return -1;
    }

    return buf[0];
}

// I2C write byte function
int i2c_write_byte(int reg, int val) {
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = val;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing byte to register 0x%02X: %d\n", reg, val);
        return -1;
    }

    return 0;
}

// I2C read block function
int i2c_read_block(int reg, int len, uint8_t *buf) {
    int result;
    uint8_t reg_buf[1];

    reg_buf[0] = reg;
    if (write(i2c_fd, reg_buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read: 0x%02X\n", reg);
        return -1;
    }

    result = read(i2c_fd, buf, len);
