#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define the duration of each solenoid activation (in milliseconds)
#define SOLENOID_DURATION 500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Set initial state of solenoids to OFF (LOW)
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to alternate solenoid activation
    while (program_running) {
        // Activate solenoid 1
        gpioWrite(SOLENOID_1_PIN, 1);
        gpioWrite(SOLENOID_2_PIN, 0);
        gpioDelay(SOLENOID_DURATION * 1000); // Delay for 500ms (in microseconds)

        // Deactivate solenoid 1 and activate solenoid 2
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 1);
        gpioDelay(SOLENOID_DURATION * 1000); // Delay for 500ms (in microseconds)

        // Deactivate solenoid 2
        gpioWrite(SOLENOID_2_PIN, 0);
    }

    // Clean up and exit
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return 0;
}

