#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

// Define GPIO pins for the door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART device paths
#define UART0_PATH "/dev/serial0"
#define UART1_PATH "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 5

// Global variables for UART file descriptors and pigpio initialization status
int uart0_fd = -1;
int uart1_fd = -1;
int pigpio_initialized = 0;

// Function prototypes
int initialize_pigpio();
int open_uart(const char *device_path);
int read_code(int fd, char *buffer, int buffer_size, int timeout_sec);
int compare_codes(const char *code1, const char *code2);
int unlock_doors();
int lock_doors();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Shutting down gracefully...\n", signal);

    // Unlock doors on shutdown
    unlock_doors();

    // Close UART ports
    if (uart0_fd != -1) {
        close(uart0_fd);
    }
    if (uart1_fd != -1) {
        close(uart1_fd);
    }

    // Terminate pigpio
    if (pigpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;
    return 0;
}

// Function to open a UART port
int open_uart(const char *device_path) {
    int fd = open(device_path, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device_path, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        fprintf(stderr, "Error setting baud rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a code from a UART port
int read_code(int fd, char *buffer, int buffer_size, int timeout_sec) {
    int bytes_read = 0;
    int start_time = time(NULL);

    while (time(NULL) - start_time < timeout_sec) {
        int available = 0;
        ioctl(fd, FIONREAD, &available);

        if (available > 0) {
            char c;
            if (read(fd, &c, 1) == 1) {
                if (c >= '0' && c <= '9') {
                    buffer[bytes_read++] = c;
                    if (bytes_read == buffer_size) {
                        fprintf(stderr, "Buffer overflow\n");
                        bytes_read = 0; // Reset buffer
                        break;
                    }
                } else {
                    fprintf(stderr, "Invalid character received: %c\n", c);
                    bytes_read = 0; // Reset buffer on invalid character
                    break;
                }
            } else {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                bytes_read = 0; // Reset buffer on read error
                break;
            }
        } else {
