#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME_MS 1000
#define FAILSAFE_TIMEOUT_S 10
#define POLL_INTERVAL_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_pir_sensor(void);
int control_relay(int on);
void log_message(int priority, const char *message);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    // Get PIR pin line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR pin line");
        goto cleanup_chip;
    }

    // Request PIR pin as input
    ret = gpiod_line_request(pir_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request PIR pin as input");
        goto cleanup_pir_line;
    }

    // Get relay pin line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_message(LOG_ERR, "Failed to get relay pin line");
        goto cleanup_pir_line;
    }

    // Request relay pin as output
    ret = gpiod_line_request(relay_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request relay pin as output");
        goto cleanup_relay_line;
    }

    return 0;

cleanup_relay_line:
    gpiod_line_release(relay_line);
cleanup_pir_line:
    gpiod_line_release(pir_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value;

    value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }

    return value;
}

// Control relay state
int control_relay(int on) {
    int ret;

    ret = gpiod_line_set_value(relay_line, on);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to set relay value");
        return -1;
    }

    return 0;
}

// Log message to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Cleanup GPIO lines
void cleanup(void) {
    log_message(LOG_INFO, "Cleaning up GPIO lines...");

    // Release lines
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close syslog
    closelog();
}

int main(void) {
    time_t last_motion_time = 0;
    int pir_state = 0; // 0 = LOW, 1 = HIGH
    int failsafe_triggered = 0;

    // Open syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Door strike system started");

    // Main loop
    while (!terminate) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            log_message(LOG_ERR, "Failed to read PIR sensor, exiting");
            break;
        }

        if (pir_value == 1 && pir_state == 0) {
            // Motion detected
            log_message(LOG_INFO, "Motion detected");
            control_relay(1); // Energize relay
            last_motion_time = time(NULL);
            failsafe_triggered = 0;
            pir_state = 1;
        } else if (pir_value == 0 && pir_state == 1) {
            // Motion stopped
            log_message(LOG_INFO, "Motion stopped");
            control_relay(0); // De-energize relay
            pir_state = 0;
        }

        // Failsafe mechanism
        if (pir_state == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) > FAILSAFE_TIMEOUT_S) {
                if (!failsafe_triggered) {
                    log_message(LOG_WARNING, "Failsafe triggered: PIR sensor remains HIGH for more than 10 seconds");
                    failsafe_triggered = 1;
                }
                control_relay(0); // De-energize relay
                pir_state = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

