#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// I2C Addresses
#define MPU6050_ADDR_1 0x68
#define MPU6050_ADDR_2 0x69

// Accelerometer Range
#define ACCEL_RANGE_2G 0x00

// Scaling Factor
#define ACCEL_SCALE 16384.0f

// Circular Buffer Size
#define BUFFER_SIZE 100

// Sysfs Path
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
    int id;
    int present;
} Sensor;

// Circular Buffer Structure
typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
static volatile int running = 1;
static int i2c_fd = -1;
static int sensor_count = 0;
static Sensor sensors[2];
static CircularBuffer buffer;
static int sysfs_fd = -1;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mpu6050(int fd, int address);
AccelData read_accel_data(int fd);
void add_to_buffer(CircularBuffer *buffer, AccelData data);
AccelData get_latest_data(CircularBuffer *buffer);
void signal_handler(int sig);
int create_sysfs_entry();
int remove_sysfs_entry();
int write_to_sysfs(const char *data);

// I2C Read Register Function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return buf[0];
}

// I2C Write Register Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Initialize MPU6050 Function
int init_mpu6050(int fd, int address) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU6050 at address 0x%02X\n", address);
        return -1;
    }
    if (i2c_write_reg(fd, ACCEL_CONFIG, ACCEL_RANGE_2G) < 0) {
        fprintf(stderr, "Error setting accelerometer range for MPU6050 at address 0x%02X\n", address);
        return -1;
    }
    return 0;
}

// Read Acceleration Data Function
AccelData read_accel_data(int fd) {
    AccelData data;
    int16_t raw_x, raw_y, raw_z;

    raw_x = (i2c_read_reg(fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 1);
    raw_y = (i2c_read_reg(fd, ACCEL_YOUT_H) << 8) | i2c_read_reg(fd, ACCEL_YOUT_H + 1);
    raw_z = (i2c_read_reg(fd, ACCEL_ZOUT_H) << 8) | i2c_read_reg(fd, ACCEL_ZOUT_H + 1);

    data.x = (float)raw_x / ACCEL_SCALE;
    data.y = (float)raw_y / ACCEL_SCALE;
    data.z = (float)raw_z / ACCEL_SCALE;

    return data;
}

// Add Data to Circular Buffer Function
void add_to_buffer(CircularBuffer *buffer, AccelData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get Latest Data from Circular Buffer Function
AccelData get_latest_data(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        AccelData empty = {0.0f, 0.0f, 0.0f};
        return empty;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Signal Handler Function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Create Sysfs Entry Function
int create_sysfs_entry() {
    sysfs_fd = open(SYSFS_PATH, O_WRONLY | O_CREAT, 0644);
    if (sysfs_fd < 0) {
        perror("Failed to create sysfs entry");
        return -1;
    }
    return 0;
}

// Remove Sysfs Entry Function
int remove_sysfs_entry() {
    if (sysfs_fd >= 0) {
        close(sysfs_fd);
        if (unlink(SYSFS_PATH) < 0) {
            perror("Failed to remove sysfs entry");
            return -1;
        }
    }
    return 0;
}

// Write to Sysfs Function
int write_to_sysfs(const char *data) {
    if (sysfs_fd < 0) {
        fprintf(stderr, "Sysfs entry not created\n");
        return -1;
    }
    ssize_t bytes_written = write(sysfs_fd, data, strlen(data));
    if (bytes_written < 0) {
        perror("Failed to write to sysfs");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize Circular Buffer
    buffer.head = 0;
    buffer.count = 0;

    // Initialize Sensors
    sensors[0].address = MPU6050_ADDR_1;
    sensors[0].id = 1;
    sensors[0].present = 0;
    sensors[1].address = MPU6050_ADDR_2;
    sensors[1].id = 2;
    sensors[1].present = 0;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize Sensors
    for (int i = 0; i < 2; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, sensors[i].address) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            continue;
        }
        if (init_mpu6050(i2c_fd, sensors[i].address) == 0) {
            sensors[i].present = 1;
            sensor_count++;
        }
    }

    if (sensor_count == 0) {
        fprintf(stderr, "No MPU6050 sensors found. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Create Sysfs Entry
    if (create_sysfs_entry() < 0) {
        fprintf(stderr, "Failed to create sysfs entry. Continuing without sysfs.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec sleep_time = {0, 10000000}; // 100 Hz
    while (running) {
        for (int i = 0; i < 2; i++) {
            if (sensors[i].present) {
                if (ioctl(i2c_fd, I2C_SLAVE, sensors[i].address) < 0) {
                    perror("Failed to acquire bus access and/or talk to slave");
                    continue;
                }
                AccelData data = read_accel_data(i2c_fd);
                char data_str[100];
                snprintf(data_str, sizeof(data_str), "%.2f,%.2f,%.2f,%d\n", data.x, data.y, data.z, sensors[i].id);
                add_to_buffer(&buffer, data);
                if (write_to_sysfs(data_str) < 0) {
                    fprintf(stderr, "Failed to write to sysfs. Continuing.\n");
                }
            }
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    if (create_sysfs_entry() == 0) {
        write_to_sysfs("0.0,0.0,0.0,0\n");
    }
    remove_sysfs_entry();

    return 0;
}

