        return -1;
    }
    return 0;
}

int main() {
    // Initialize Circular Buffer
    buffer.head = 0;
    buffer.count = 0;

    // Initialize Sensors
    sensors[0].address = MPU6050_ADDR_1;
    sensors[0].id = 1;
    sensors[0].present = 0;
    sensors[1].address = MPU6050_ADDR_2;
    sensors[1].id = 2;
    sensors[1].present = 0;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize Sensors
    for (int i = 0; i < 2; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, sensors[i].address) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            continue;
        }
        if (init_mpu6050(i2c_fd, sensors[i].address) == 0) {
            sensors[i].present = 1;
            sensor_count++;
        }
    }

    if (sensor_count == 0) {
        fprintf(stderr, "No MPU6050 sensors found. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Create Sysfs Entry
    if (create_sysfs_entry() < 0) {
        fprintf(stderr, "Failed to create sysfs entry. Continuing without sysfs.\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec sleep_time = {0, 10000000}; // 100 Hz
    while (running) {
        for (int i = 0; i < 2; i++) {
            if (sensors[i].present) {
                if (ioctl(i2c_fd, I2C_SLAVE, sensors[i].address) < 0) {
                    perror("Failed to acquire bus access and/or talk to slave");
                    continue;
                }
                AccelData data = read_accel_data(i2c_fd);
                char data_str[100];
                snprintf(data_str, sizeof(data_str), "%.2f,%.2f,%.2f,%d\n", data.x, data.y, data.z, sensors[i].id);
                add_to_buffer(&buffer, data);
                if (write_to_sysfs(data_str) < 0) {
                    fprintf(stderr, "Failed to write to sysfs. Continuing.\n");
                }
            }
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    if (create_sysfs_entry() == 0) {
        write_to_sysfs("0.0,0.0,0.0,0\n");
    }
    remove_sysfs_entry();

    return 0;
}

