int request_gpio_line(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int toggle_relay(int gpio_pin);
int calculate_interval(int prime_number);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    set_gpio_value(GPIO_18, 0);
    set_gpio_value(GPIO_23, 0);
    set_gpio_value(GPIO_24, 0);
    set_gpio_value(GPIO_25, 0);

    // Release GPIO lines
    gpiod_line_release(line_18);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    gpiod_line_release(line_25);

    // Close GPIO chip
    gpiod_chip_close(chip);

    exit(0);
}

// Function to request a GPIO line
int request_gpio_line(int gpio_pin) {
    struct gpiod_line_request_config config;
    int ret;

    // Configure the line request
    config.consumer = "smart_lighting";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    // Request the GPIO line
    switch (gpio_pin) {
        case GPIO_18:
            ret = gpiod_line_request(line_18, &config, 0);
            break;
        case GPIO_23:
            ret = gpiod_line_request(line_23, &config, 0);
            break;
        case GPIO_24:
            ret = gpiod_line_request(line_24, &config, 0);
            break;
        case GPIO_25:
            ret = gpiod_line_request(line_25, &config, 0);
            break;
        default:
            fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
            return -1;
    }

    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d: %s\n", gpio_pin, strerror(-ret));
        return -1;
    }

    return 0;
}

