        sleep(calculate_interval(PRIME_3_INTERVAL));

        if (toggle_relay(GPIO_24) < 0) goto cleanup;
        sleep(calculate_interval(PRIME_5_INTERVAL));

        if (toggle_relay(GPIO_25) < 0) goto cleanup;
        sleep(calculate_interval(PRIME_7_INTERVAL));
    }

cleanup:
