    set_gpio_value(GPIO_23, 0);
    set_gpio_value(GPIO_24, 0);
    set_gpio_value(GPIO_25, 0);
    gpiod_line_release(line_18);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    gpiod_line_release(line_25);
    gpiod_chip_close(chip);
    return 1;
}

