#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 500

// Define alarm duration (in seconds)
#define ALARM_DURATION 3

// Global variables
static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm();
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Check for sound detection and debounce
        if (sound_detected && (gpioTick() - last_trigger_time) > DEBOUNCE_TIME * 1000) {
            printf("Sound detected! Activating alarm.\n");
            activate_relay();
            log_alarm();
            last_trigger_time = gpioTick();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input (sound sensor)
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set GPIO27 as output (relay)
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially off
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay for 3 seconds
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn on relay
    gpioDelay(ALARM_DURATION * 1000); // Wait for 3 seconds
    gpioWrite(RELAY_PIN, 0); // Turn off relay
}

// Log alarm activation to file
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

// Cleanup function to turn off relay and terminate pigpio
void cleanup() {
    // Turn off relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
}

