#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"
#define READ_INTERVAL 5 // seconds

int uart_handle;
FILE *log_file, *error_file;

// Function prototypes
int read_co2(int *co2_ppm);
int validate_checksum(unsigned char *data);
void log_data(long long timestamp, int co2_ppm, int error_flag);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    serClose(uart_handle);
    if (log_file != NULL) fclose(log_file);
    if (error_file != NULL) fclose(error_file);
    gpioTerminate();
    exit(0);
}

// Reads CO2 concentration from the MH-Z19B sensor
int read_co2(int *co2_ppm) {
    unsigned char command[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[9];
    int bytes_read, i;
    long long start_time = gpioTick();

    // Send the read command
    if (serWrite(uart_handle, command, sizeof(command)) != sizeof(command)) {
        log_error("Failed to send read command");
        return -1;
    }

    // Wait for the response or timeout
    while (gpioTick() - start_time < 1000000) {
        bytes_read = serDataAvailable(uart_handle);
        if (bytes_read == 9) {
            break;
        }
        gpioDelay(1000); // Check every 1 ms
    }

    if (bytes_read != 9) {
        log_error("Timeout waiting for response");
        return -1;
    }

    // Read the response
    if (serRead(uart_handle, response, 9) != 9) {
        log_error("Failed to read response");
        return -1;
    }

    // Validate the checksum
    if (!validate_checksum(response)) {
        log_error("Checksum validation failed");
        return -1;
    }

    // Extract CO2 concentration
    *co2_ppm = (response[2] << 8) | response[3];
    return 0;
}

// Validates the checksum of the received data
int validate_checksum(unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += data[i];
    }
    if (checksum != data[8]) {
        return 0; // Checksum failed
    }
    return 1; // Checksum passed
}

// Logs the CO2 data to a JSON file
void log_data(long long timestamp, int co2_ppm, int error_flag) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "{\"timestamp\": %lld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_ns, co2_ppm, error_flag);
    fflush(log_file);
    printf("{\"timestamp\": %lld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_ns, co2_ppm, error_flag);
}

// Logs errors to a file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(error_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(error_file);
}

int main() {
    int co2_ppm;
    long long timestamp;
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the serial port
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open serial port: %s\n", UART_DEVICE);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Open the error log file
    error_file = fopen(ERROR_LOG, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", ERROR_LOG);
        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_co2(&co2_ppm) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
            log_data(timestamp, co2_ppm, 0); // Log data with error flag 0
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
            log_data(timestamp, 0, 1); // Log data with error flag 1
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    fclose(log_file);
    fclose(error_file);
    serClose(uart_handle);
    gpioTerminate();
    return 0;
}

