#include <math.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
double heading_buffer[HEADING_BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_heading(int16_t x, int16_t y);
void update_gpio(int gpio_pin, double current_heading);
void store_heading(double heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize HMC5883L sensor
int init_hmc5883l() {
    char config_a_value = 0x70; // 8-average, 15 Hz, normal measurement
    char config_b_value = 0x20; // 1.3 Gauss gain
    char mode_value = 0x00;    // Continuous measurement mode

    if (i2cWriteByteData(i2c_handle, CONFIG_A, config_a_value) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_B, config_b_value) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MODE, mode_value) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_START, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
double calculate_heading(int16_t x, int16_t y) {
    double heading = atan2((double)y, (double)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Update GPIO pin based on heading deviation
void update_gpio(int gpio_pin, double current_heading) {
    double deviation = fabs(current_heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(gpio_pin, 1); // Set GPIO high
    } else {
        gpioWrite(gpio_pin, 0); // Set GPIO low
    }
}

// Store heading in circular buffer
void store_heading(double heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % HEADING_BUFFER_SIZE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L sensor
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Store heading
            store_heading(heading);

            // Update GPIO
            update_gpio(GPIO_PIN, heading);

            // Print heading (optional)
            printf("Heading: %.2f degrees\n", heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

