#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_RED 50.0
#define LUX_THRESHOLD_GREEN 150.0
#define LUX_THRESHOLD_BLUE 300.0

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_bh1750(float *lux);
int set_relay_state(int red, int green, int blue);
int log_data(float lux, int red, int green, int blue);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C bus
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    uint8_t config_cmd = 0x10;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO pins
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    red_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    if (!red_line) {
        perror("Error getting red relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    green_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    if (!green_line) {
        perror("Error getting green relay GPIO line");
        gpiod_line_release(red_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);
    if (!blue_line) {
        perror("Error getting blue relay GPIO line");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(red_line, "lighting", 0) < 0) {
        perror("Error requesting red relay GPIO line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(green_line, "lighting", 0) < 0) {
        perror("Error requesting green relay GPIO line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(blue_line, "lighting", 0) < 0) {
        perror("Error requesting blue relay GPIO line as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t data[2];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, data, 2) == 2) {
            uint16_t raw_value = (data[0] << 8) | data[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    return -1; // Failure after multiple retries
}

// Set relay states
int set_relay_state(int red, int green, int blue) {
    if (gpiod_line_set_value(red_line, red) < 0) {
        perror("Error setting red relay state");
        return -1;
    }

    if (gpiod_line_set_value(green_line, green) < 0) {
        perror("Error setting green relay state");
        return -1;
    }

    if (gpiod_line_set_value(blue_line, blue) < 0) {
        perror("Error setting blue relay state");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float lux;
    int red, green, blue;
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Determine relay states based on lux value
            if (lux < LUX_THRESHOLD_RED) {
                red = 1; green = 0; blue = 0;
            } else if (lux < LUX_THRESHOLD_GREEN) {
                red = 0; green = 1; blue = 0;
            } else if (lux < LUX_THRESHOLD_BLUE) {
                red = 0; green = 0; blue = 1;
            } else {
                red = 0; green = 0; blue = 0;
            }

            // Set relay states
            if (set_relay_state(red, green, blue) < 0) {
                fprintf(stderr, "Failed to set relay states.\n");
            }

            // Log data
            if (log_data(lux, red, green, blue) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (log_file) fclose(log_file);

    return 0;
}

