    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float lux;
    int red, green, blue;
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Determine relay states based on lux value
            if (lux < LUX_THRESHOLD_RED) {
                red = 1; green = 0; blue = 0;
            } else if (lux < LUX_THRESHOLD_GREEN) {
                red = 0; green = 1; blue = 0;
            } else if (lux < LUX_THRESHOLD_BLUE) {
                red = 0; green = 0; blue = 1;
            } else {
                red = 0; green = 0; blue = 0;
            }

            // Set relay states
            if (set_relay_state(red, green, blue) < 0) {
                fprintf(stderr, "Failed to set relay states.\n");
            }

            // Log data
            if (log_data(lux, red, green, blue) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (log_file) fclose(log_file);

    return 0;
}

