#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD 20000 // 20ms period (50Hz)
#define PWM_DUTY_CYCLE_MIN 500000 // 5ms pulse (50Hz)
#define PWM_DUTY_CYCLE_MAX 2500000 // 25ms pulse (50Hz)
#define SERVO_RANGE 180.0 // Degrees
#define SERVO_CENTER 90.0 // Degrees
#define LOG_FILE "solar_tracker.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
int pwm_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mpu6050_init(int fd);
int read_mpu6050_data(int fd, float *pitch, float *roll);
int set_servo_angle(int fd, float angle);
int log_data(float pitch, float roll, float servo_angle);
void signal_handler(int sig);

// I2C read function with exponential backoff
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = RETRY_COUNT;
    int delay_ms = RETRY_DELAY_MS;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        result = read(fd, &reg, 1);
        if (result == 1) {
            return reg;
        } else {
            syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }

    syslog(LOG_ERR, "Failed to read from I2C after multiple retries.");
    return -1; // Indicate failure
}

// I2C write function with exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = RETRY_COUNT;
    int delay_ms = RETRY_DELAY_MS;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
        }
    }

    syslog(LOG_ERR, "Failed to write to I2C after multiple retries.");
    return -1; // Indicate failure
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0) < 0) {
        syslog(LOG_ERR, "Failed to wake up MPU6050.");
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int fd, float *pitch, float *roll) {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_x_g, accel_y_g, accel_z_g;

    // Read accelerometer data
    accel_x = (i2c_read_reg(fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 1);
    accel_y = (i2c_read_reg(fd, ACCEL_XOUT_H + 2) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 3);
    accel_z = (i2c_read_reg(fd, ACCEL_XOUT_H + 4) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 5);

    // Read gyroscope data
    gyro_x = (i2c_read_reg(fd, GYRO_XOUT_H) << 8) | i2c_read_reg(fd, GYRO_XOUT_H + 1);
