// I2C read function with exponential backoff
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = RETRY_COUNT;
    int delay_ms = RETRY_DELAY_MS;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries--;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        result = read(fd, &reg, 1);
        if (result == 1) {
            return reg;
        } else {
