#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global array to store the schedule entries
schedule_entry_t schedule[100]; // Assuming a maximum of 100 entries
int schedule_size = 0;

// Function prototypes
int read_schedule(const char *filename);
int parse_schedule_line(const char *line, schedule_entry_t *entry);
void set_relay_state(int relay_number, int on_off);
void fade_brightness(int relay_number, int target_brightness, int duration_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read the schedule from the file
int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_line(line, &schedule[schedule_size]) == 0) {
            schedule_size++;
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse a schedule line
int parse_schedule_line(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->on_off) != 5) {
        fprintf(stderr, "Error parsing schedule line: %s", line);
        return -1;
    }

    // Validate relay number
    if (entry->relay_number < 1 || entry->relay_number > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", entry->relay_number);
        return -1;
    }

    // Validate on/off value
    if (entry->on_off != 0 && entry->on_off != 1) {
        fprintf(stderr, "Invalid on/off value: %d\n", entry->on_off);
        return -1;
    }

    return 0;
}

// Function to set the state of a relay
void set_relay_state(int relay_number, int on_off) {
    int gpio_pin;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_PIN;
            break;
        case 2:
            gpio_pin = RELAY2_PIN;
            break;
        case 3:
            gpio_pin = RELAY3_PIN;
            break;
        case 4:
            gpio_pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(gpio_pin, on_off);
}

// Function to fade the brightness of a lamp
void fade_brightness(int relay_number, int target_brightness, int duration_seconds) {
    int gpio_pin;
    int current_brightness;
    int increment;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_PIN;
            break;
        case 2:
            gpio_pin = RELAY2_PIN;
            break;
        case 3:
            gpio_pin = RELAY3_PIN;
            break;
        case 4:
            gpio_pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    // Get the current brightness
    current_brightness = gpioGetPWMdutycycle(gpio_pin);

    // Calculate the increment
