// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 30.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables
static volatile int running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float measure_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        running = 0;
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Trigger pulse generation function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            start_tick = tick;
            echo_received = 1;
        } else if (level == 0 && echo_received) {
            end_tick = tick;
            echo_received = 0;
        }
    }
}

// Distance measurement function
float measure_distance() {
    start_tick = 0;
    end_tick = 0;
    echo_received = 0;

    trigger_pulse();

    uint32_t start = gpioTick();
    while (!echo_received && (gpioTick() - start) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate timeout error
    }

    uint32_t pulse_width = end_tick - start_tick;

    if (pulse_width <= 0) {
        fprintf(stderr, "Error: Invalid pulse width: %u\n", pulse_width);
        return -1.0; // Indicate invalid pulse width
    }

    // Speed of sound approximation (cm/us) - adjust as needed
    float speed_of_sound = 0.0343; // cm/us
    float distance = (pulse_width * speed_of_sound) / 2.0;

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linear mapping
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    return frequency;
}

// Function to set buzzer frequency
void set_buzzer_frequency(float frequency) {
    if (frequency <= 0) {
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    } else {
        int range = 1000; // PWM range (adjust as needed)
        int duty_cycle = (int)((frequency / MAX_FREQUENCY) * range); // Map frequency to duty cycle
        gpioPWM(BUZZER_PIN, duty_cycle); // Set PWM duty cycle
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 1000);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // 1 kHz

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(60); // 60 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate(); // Terminate pigpio

    return 0;
}

