#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(float red, float green, float blue) {
    // Validate input values
    if (red < 0.0 || red > 1.0 || green < 0.0 || green > 1.0 || blue < 0.0 || blue > 1.0) {
        fprintf(stderr, "Error: Invalid color values. Must be between 0.0 and 1.0.\n");
        return;
    }

    // Calculate PWM duty cycle for each color
    int red_pwm   = (int)(red   * 255.0);
    int green_pwm = (int)(green * 255.0);
    int blue_pwm  = (int)(blue  * 255.0);

    // Set PWM duty cycle for each color
    gpioPWM(RED_PIN,   red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN,  blue_pwm);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency for each color
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate simulated proximity value using sine wave
        float proximity = 0.5 + 0.5 * sin(gpioTick() / 1000000.0); // Sine wave between 0 and 1

        // Map proximity value to RGB color values
        float red   = 1.0 - proximity;
        float green = proximity;
        float blue  = 0.0;

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for 50 milliseconds
        gpioDelay(50000);
    }

    // Turn off the LED
    set_led_color(0.0, 0.0, 0.0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

