#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 register addresses
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor for ±250 deg/s
#define GYRO_SCALE 131.0f

// File descriptor for I2C device
int i2c_fd = -1;

// File pointer for log file
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the sensor (set PWR_MGMT_1 to 0)
    uint8_t wake_up_value = 0x00;
    if (write(fd, &wake_up_value, 1) != 1) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buffer[6];
    // Read 6 bytes of gyroscope data starting from GYRO_XOUT_H
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees/second
    *x = (float)gyro_x / GYRO_SCALE;
    *y = (float)gyro_y / GYRO_SCALE;
    *z = (float)gyro_z / GYRO_SCALE;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    float x, y, z;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Log data to file
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        // Wait for 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup in case the loop were to terminate.
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

