// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequency, duration in ms)
const struct {
    int frequency;
    int duration;
} melody[] = {
    {440, 200},   // A4
    {494, 200},   // B4
    {523, 200},   // C5
    {587, 200},   // D5
    {659, 200},   // E5
    {698, 200},   // F5
    {784, 200},   // G5
    {880, 200},   // A5
    {988, 200},   // B5
    {1046, 200},  // C6
    {1175, 200},  // D6
    {1319, 200},  // E6
    {1397, 200},  // F6
    {1568, 200},  // G6
    {1760, 200},  // A6
    {1976, 200},  // B6
    {2093, 200},  // C7
    {2349, 200},  // D7
    {2637, 200},  // E7
    {2794, 200},  // F7
    {3136, 200},  // G7
    {3520, 200},  // A7
    {3951, 200},  // B7
    {4186, 200},  // C8
    {4699, 200},  // D8
    {5274, 200},  // E8
    {5588, 200},  // F8
    {6272, 200},  // G8
    {7040, 200},  // A8
    {7902, 200},  // B8
    {0, 0}        // End of melody
};

// Global variables
volatile int play_melody = 0;
volatile unsigned long last_interrupt_time = 0;

// Function prototypes
void button_callback(int gpio, int level, unsigned int tick, void *user_data);
void play_note(int frequency, int duration);
void stop_melody();
void signal_handler(int signal);

// Interrupt handler for the button press
void button_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();
    if (current_time - last_interrupt_time > 50000) { // 50ms debounce
        play_melody = !play_melody; // Toggle melody playback
        last_interrupt_time = current_time;
    }
}

// Function to play a single note
void play_note(int frequency, int duration) {
    if (frequency > 0) {
        gpioHardwarePWM(BUZZER_PIN, frequency, 500000); // 50% duty cycle
    } else {
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
    }
    gpioDelay(duration * 1000); // Delay in microseconds
}

// Function to stop the melody
void stop_melody() {
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell is ready. Press the button to play the melody.\n");

    // Main loop
    while (1) {
        if (play_melody) {
            int i = 0;
            while (melody[i].duration != 0) {
                play_note(melody[i].frequency, melody[i].duration);
                i++;
            }
            play_melody = 0; // Stop after one cycle
        }
        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

