#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define LOG_FILE "vibration_events.log"

// Structure to hold vibration event data
typedef struct {
    struct timespec timestamp;
    int value;
} VibrationEvent;

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static VibrationEvent event_window[WINDOW_SIZE];
static int window_index = 0;

// Function prototypes
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int read_gpio(struct gpiod_line *line, int *value);
int log_event(FILE *fp, struct timespec ts, int value);
void earthquake_alert(struct timespec ts);
void signal_handler(int sig);
void cleanup(struct gpiod_line *line, FILE *fp);

// Initialize GPIO line for input
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    struct gpiod_chip *chip_tmp = NULL;
    struct gpiod_line *line_tmp = NULL;

    chip_tmp = gpiod_chip_open_by_name("gpiochip0");
    if (!chip_tmp) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line_tmp = gpiod_chip_get_line(chip_tmp, GPIO_PIN);
    if (!line_tmp) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_tmp);
        return -1;
    }

    if (gpiod_line_request_input(line_tmp, "vibration_sensor") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_line_release(line_tmp);
        gpiod_chip_close(chip_tmp);
        return -1;
    }

    *chip = chip_tmp;
    *line = line_tmp;
    return 0;
}

// Read GPIO line value
int read_gpio(struct gpiod_line *line, int *value) {
    int ret;
    struct gpiod_line_event event;

    ret = gpiod_line_event_wait(line, NULL);
    if (ret < 0) {
        perror("Error waiting for GPIO event");
        return -1;
    }

    ret = gpiod_line_event_read(line, &event);
    if (ret < 0) {
        perror("Error reading GPIO event");
        return -1;
    }

    *value = event.value;
    return 0;
}

// Log vibration event to file
int log_event(FILE *fp, struct timespec ts, int value) {
    char timestamp_str[30];
    struct tm tm_info;

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", &tm_info);

    fprintf(fp, "%s.%09ld,%d\n", timestamp_str, ts.tv_nsec, value);
    fflush(fp);
    return 0;
}

// Check for earthquake alert
void earthquake_alert(struct timespec ts) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (event_window[i].value == 1) {
            high_count++;
        }
    }

    if (high_count >= EARTHQUAKE_THRESHOLD) {
        char timestamp_str[30];
        struct tm tm_info;

        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", &tm_info);

        fprintf(stderr, "EARTHQUAKE ALERT: %s.%09ld\n", timestamp_str, ts.tv_nsec);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, exiting...\n");
}

// Cleanup resources
void cleanup(struct gpiod_line *line, FILE *fp) {
    if (line) {
        gpiod_line_release(line);
    }
    if (fp) {
        fclose(fp);
    }
    gpiod_chip_close(NULL); // Close the chip if it was opened
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = 1000; // Default timeout
    struct gpiod_chip *chip = NULL;
    int ret;
    int value;
    struct timespec ts;

    // Parse command-line argument
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default value: %d ms\n", poll_timeout_ms);
        }
    }

    // Initialize GPIO
    if (init_gpio(&chip, &gpio_line) < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup(gpio_line, NULL);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        ret = read_gpio(gpio_line, &value);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO, exiting...\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        log_event(log_file, ts, value);

        // Update earthquake alert window
        event_window[window_index].timestamp = ts;
        event_window[window_index].value = value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        earthquake_alert(ts);

        // Use select() with a timeout to avoid busy-waiting
        struct timeval timeout;
        timeout.tv_sec = poll_timeout_ms / 1000;
        timeout.tv_usec = (poll_timeout_ms % 1000) * 1000;

        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(gpio_line->fd, &rfds);

        int select_ret = select(gpio_line->fd + 1, &rfds, NULL, NULL, &timeout);

        if (select_ret < 0) {
            perror("select() failed");
            break;
        } else if (select_ret == 0) {
            // Timeout occurred, continue polling
            continue;
        }
    }

    // Cleanup resources before exiting
    cleanup(gpio_line, log_file);

    return 0;
}

