#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MAGNETOMETER_ADDRESS 0x1E
#define CONTINUOUS_CONVERSION_MODE 0x00
#define DATA_RATE_15HZ 0x14
#define X_AXIS_MSB 0x03
#define X_AXIS_LSB 0x04
#define Z_AXIS_MSB 0x05
#define Z_AXIS_LSB 0x06
#define Y_AXIS_MSB 0x07
#define Y_AXIS_LSB 0x08
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f
#define HEADING_THRESHOLD 22.5f

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int16_t combine_msb_lsb(int16_t msb, int16_t lsb);
float calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z);
float calculate_heading(float calibrated_x, float calibrated_y);
const char *determine_direction(float heading);
void log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Combine MSB and LSB to form a 16-bit signed integer
int16_t combine_msb_lsb(int16_t msb, int16_t lsb) {
    return (msb << 8) | lsb;
}

// Calibrate magnetometer data
float calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    return (float)(raw_x - X_OFFSET);
}

// Calculate compass heading in degrees
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2f(calibrated_y, calibrated_x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

// Determine compass direction
const char *determine_direction(float heading) {
    if (heading >= 0 && heading < 22.5f) {
        return "N";
    } else if (heading >= 22.5f && heading < 67.5f) {
        return "NE";
    } else if (heading >= 67.5f && heading < 112.5f) {
        return "E";
    } else if (heading >= 112.5f && heading < 157.5f) {
        return "SE";
    } else if (heading >= 157.5f && heading < 202.5f) {
        return "S";
    } else if (heading >= 202.5f && heading < 247.5f) {
        return "SW";
    } else if (heading >= 247.5f && heading < 292.5f) {
        return "W";
    } else if (heading >= 292.5f && heading < 337.5f) {
        return "NW";
    } else {
        return "N";
    }
}

// Log data to CSV file
void log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
            timestamp, calibrated_x, calibrated_y, calibrated_z, heading, determine_direction(heading));
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MAGNETOMETER_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure magnetometer for continuous conversion mode and 15 Hz data rate
    if (i2c_write_reg(i2c_fd, CONTINUOUS_CONVERSION_MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to configure continuous conversion mode\n");
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, DATA_RATE_15HZ, 0x00) < 0) {
        fprintf(stderr, "Failed to configure data rate\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        int16_t raw_x = combine_msb_lsb(i2c_read_reg(i2c_fd, X_AXIS_MSB), i2c_read_reg(i2c_fd, X_AXIS_LSB));
        int16_t raw_y = combine_msb_lsb(i2c_read_reg(i2c_fd, Y_AXIS_MSB), i2c_read_reg(i2c_fd, Y_AXIS_LSB));
        int16_t raw_z = combine_msb_lsb(i2c_read_reg(i2c_fd, Z_AXIS_MSB), i2c_read_reg(i2c_fd, Z_AXIS_LSB));

        // Check for I2C read errors
        if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
            sleep(1);
            continue;
        }

        // Calibrate magnetometer data
        float calibrated_x = calibrate_magnetometer(raw_x, raw_y, raw_z);
        float calibrated_y = calibrate_magnetometer(raw_y, raw_x, raw_z);
        float calibrated_z = calibrate_magnetometer(raw_z, raw_x, raw_y);

        // Calculate compass heading
        float heading = calculate_heading(calibrated_x, calibrated_y);

        // Determine compass direction
        const char *direction = determine_direction(heading);

        // Log data
        log_data(calibrated_x, calibrated_y, calibrated_z, heading);

        // Print to console
        printf("Calibrated X: %.2f, Calibrated Y: %.2f, Calibrated Z: %.2f, Heading: %.2f, Direction: %s\n",
               calibrated_x, calibrated_y, calibrated_z, heading, direction);

        // Wait for 1 second
        sleep(1);
    }

    // Close resources
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

