#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
}

// Function to log relay state to file
void log_relay_state() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, not logging.\n");
        return;
    }

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Interrupt service routine (ISR) for touch sensor
void touch_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    if (level == 1) { // Touch detected (HIGH)
        if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) { // Debounce
            toggle_relay();
            log_relay_state();
            last_touch_time = current_time;
        }
    }
}

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);

    // Log the final relay state
    log_relay_state();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on touch pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Initialize relay to OFF
    gpioWrite(RELAY_PIN, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Register ISR for touch sensor
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

