// Function prototypes
int setup_gpio(void);
int read_moisture(void);
int activate_relay(int relay_number);
int deactivate_relay(int relay_number);
int log_event(int relay_number, int moisture_level);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

// Setup GPIO pins
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get GPIO lines
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY1_PIN, strerror(errno));
        goto error;
    }

    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY2_PIN, strerror(errno));
        goto error;
    }

    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!relay3_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY3_PIN, strerror(errno));
        goto error;
    }

    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!relay4_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY4_PIN, strerror(errno));
        goto error;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(relay1_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY1_PIN, strerror(errno));
        goto error;
    }

    ret = gpiod_line_request_output(relay2_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY2_PIN, strerror(errno));
        goto error;
    }

    ret = gpiod_line_request_output(relay3_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY3_PIN, strerror(errno));
        goto error;
    }

    ret = gpiod_line_request_output(relay4_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY4_PIN, strerror(errno));
        goto error;
    }

    return 0;

error:
    cleanup_gpio();
    return -1;
}

// Read soil moisture value
int read_moisture(void) {
    return rand() % 101; // Simulate moisture level between 0 and 100
}

// Activate a relay
int activate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    int ret;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    if (!line) {
        fprintf(stderr, "Invalid relay line for relay number: %d\n", relay_number);
        return -1;
    }

    ret = gpiod_line_set_value(line, 0); // Active-low
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Deactivate a relay
int deactivate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    int ret;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    if (!line) {
        fprintf(stderr, "Invalid relay line for relay number: %d\n", relay_number);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1); // Active-low
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Log irrigation event
int log_event(int relay_number, int moisture_level) {
    time_t now;
    struct tm *tm_info;
    char timestamp[30];
    int ret;

    // Get current time
    time(&now);
    tm_info = localtime(&now);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Write to log file
    ret = fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    if (ret < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    // Flush log file
    fflush(log_file);

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int moisture_level;
    int i;

    // Seed random number generator
    srand(time(NULL));

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture level
        moisture_level = read_moisture();
        printf("Moisture level: %d\n", moisture_level);

        // Check moisture threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold, activating relays...\n");

            // Activate relays sequentially
            for (i = 1; i <= 4; i++) {
                if (activate_relay(i) < 0) {
                    fprintf(stderr, "Error activating relay %d\n", i);
                    continue; // Continue to the next relay
                }
                if (log_event(i, moisture_level) < 0) {
                    fprintf(stderr, "Error logging event for relay %d\n", i);
                }
                sleep(RELAY_DURATION);

                if (deactivate_relay(i) < 0) {
                    fprintf(stderr, "Error deactivating relay %d\n", i);
                    continue; // Continue to the next relay
                }
                sleep(RELAY_GAP);
            }
        } else {
            printf("Moisture level above threshold, no irrigation needed.\n");
        }

        sleep(10); // Check every 10 seconds
    }

    // Deactivate all relays
    printf("Deactivating all relays...\n");
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Cleanup GPIO resources
    cleanup_gpio();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

