#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servo control
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 51

// Define servo pulse widths (microseconds)
#define SERVO_CLOSED 500
#define SERVO_OPEN 1500
#define SERVO_0_DEGREES 500
#define SERVO_45_DEGREES 750
#define SERVO_90_DEGREES 1250
#define SERVO_135_DEGREES 1750
#define SERVO_180_DEGREES 2500

// Define watering cycle duration (seconds)
#define WATERING_DURATION 10

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, stopping watering...\n");
}

// Function to set servo position with retry logic
int set_servo_position(int pin, int pulse_width)
{
    int retries = 3;
    int result;

    while (retries > 0)
    {
        result = gpioServo(pin, pulse_width);
        if (result == 0)
        {
            return 0; // Success
        }
        else
        {
            fprintf(stderr, "Error setting servo position (pin %d, pulse width %d): %d. Retrying...\n", pin, pulse_width, result);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to set servo position (pin %d, pulse width %d) after multiple retries.\n", pin, pulse_width);
    return -1; // Failure
}

// Function to open the water valve
int open_valve()
{
    printf("Opening water valve...\n");
    if (set_servo_position(VALVE_SERVO_PIN, SERVO_OPEN) != 0)
    {
        fprintf(stderr, "Error opening valve.\n");
        return -1;
    }
    return 0;
}

// Function to close the water valve
int close_valve()
{
    printf("Closing water valve...\n");
    if (set_servo_position(VALVE_SERVO_PIN, SERVO_CLOSED) != 0)
    {
        fprintf(stderr, "Error closing valve. Critical warning!\n");
        return -1;
    }
    return 0;
}

// Function to set the nozzle angle
int set_nozzle_angle(int angle)
{
    int pulse_width;

    switch (angle)
    {
    case 0:
        pulse_width = SERVO_0_DEGREES;
        break;
    case 45:
        pulse_width = SERVO_45_DEGREES;
        break;
    case 90:
        pulse_width = SERVO_90_DEGREES;
        break;
    case 135:
        pulse_width = SERVO_135_DEGREES;
        break;
    case 180:
        pulse_width = SERVO_180_DEGREES;
        break;
    default:
        fprintf(stderr, "Invalid nozzle angle: %d\n", angle);
        return -1;
    }

    printf("Setting nozzle angle to %d degrees...\n", angle);
    if (set_servo_position(NOZZLE_SERVO_PIN, pulse_width) != 0)
    {
        fprintf(stderr, "Error setting nozzle angle to %d degrees.\n", angle);
        return -1;
    }
