#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for ±250 deg/s
#define GYRO_SCALE 131.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int wake_sensor();
int read_gyro_data(gyro_data_t *data);
gyro_data_t convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z);
int log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Wake the MPU-6050 sensor
int wake_sensor() {
    int result = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error waking sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, and convert to signed 16-bit integer
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    *data = convert_to_dps(raw_x, raw_y, raw_z);
    return 0;
}

// Convert raw gyroscope data to degrees/second
gyro_data_t convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    gyro_data_t data;
    data.x = (float)raw_x / GYRO_SCALE;
    data.y = (float)raw_y / GYRO_SCALE;
    data.z = (float)raw_z / GYRO_SCALE;
    return data;
}

// Log data to file
int log_data(gyro_data_t data) {
    time_t now = time(NULL);
    if (fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", now, data.x, data.y, data.z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Wake the sensor
    if (wake_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gyro_data_t gyro_data;
    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            if (log_data(gyro_data) != 0) {
                break; // Exit loop if logging fails
            }
        } else {
            fprintf(stderr, "Error reading gyro data, exiting...\n");
            break;
        }

        gpioDelay(100000); // 10 Hz sampling rate (100000 us = 0.1 s)
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

