#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for stepper motor coils
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define steps per revolution for 28BYJ-48 (with gear ratio)
#define STEPS_PER_REVOLUTION 2048  // 512 steps * 2 (full-step)

// Define delay between steps (microseconds)
#define STEP_DELAY 3000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void set_coil(int coil, int state);
void rotate_steps(int steps, int direction);
void lock_door();
void unlock_door();
void cleanup();
void signal_handler(int signal);

// Function to set the state of a specific coil
void set_coil(int coil, int state) {
    switch (coil) {
        case 1:
            gpioWrite(IN1, state);
            break;
        case 2:
            gpioWrite(IN2, state);
            break;
        case 3:
            gpioWrite(IN3, state);
            break;
        case 4:
            gpioWrite(IN4, state);
            break;
        default:
            fprintf(stderr, "Error: Invalid coil number: %d\n", coil);
            break;
    }
}

// Function to rotate the stepper motor a specified number of steps
void rotate_steps(int steps, int direction) {
    int i;
    int coil_states[] = {0b1000, 0b1100, 0b0100, 0b0110, 0b0010, 0b0011, 0b0001, 0b1001};

    for (i = 0; i < steps; i++) {
        int step_index = i % 8; // Full-step sequence has 8 steps

        // Apply coil states based on the direction
        if (direction == 1) { // Clockwise
            set_coil(1, (coil_states[step_index] & 0b1000) ? 1 : 0);
            set_coil(2, (coil_states[step_index] & 0b0100) ? 1 : 0);
            set_coil(3, (coil_states[step_index] & 0b0010) ? 1 : 0);
            set_coil(4, (coil_states[step_index] & 0b0001) ? 1 : 0);
        } else { // Counter-clockwise
            set_coil(1, (coil_states[7 - step_index] & 0b1000) ? 1 : 0);
            set_coil(2, (coil_states[7 - step_index] & 0b0100) ? 1 : 0);
            set_coil(3, (coil_states[7 - step_index] & 0b0010) ? 1 : 0);
            set_coil(4, (coil_states[7 - step_index] & 0b0001) ? 1 : 0);
        }

        gpioDelay(STEP_DELAY);
    }
}

// Function to lock the door (rotate clockwise)
void lock_door() {
    printf("Locking door...\n");
    rotate_steps(STEPS_PER_REVOLUTION / 2, 1); // Rotate 1/4 turn clockwise
    printf("Door locked.\n");
}

// Function to unlock the door (rotate counter-clockwise)
void unlock_door() {
    printf("Unlocking door...\n");
    rotate_steps(STEPS_PER_REVOLUTION / 2, 0); // Rotate 1/4 turn counter-clockwise
    printf("Door unlocked.\n");
}

// Function to de-energize all coils
void cleanup() {
    printf("Cleaning up and de-energizing coils...\n");
    set_coil(1, 0);
    set_coil(2, 0);
    set_coil(3, 0);
    set_coil(4, 0);
    program_running = 0; // Signal the main loop to exit
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        cleanup();
        exit(0);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for coils
    if (gpioSetMode(IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for IN1\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for IN2\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for IN3\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for IN4\n");
        cleanup();
        return 1;
    }

    // Set GPIO modes for buttons and enable pull-up resistors
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LOCK_BUTTON\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for UNLOCK_BUTTON\n");
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for LOCK_BUTTON\n");
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for UNLOCK_BUTTON\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door lock/unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON) == 0) { // Button is active low
            gpioDelay(50); // Debounce delay
            if (gpioRead(LOCK_BUTTON) == 0) {
                lock_door();
                gpioDelay(500); // Short delay to prevent multiple triggers
            }
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON) == 0) { // Button is active low
            gpioDelay(50); // Debounce delay
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                unlock_door();
                gpioDelay(500); // Short delay to prevent multiple triggers
            }
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    return 0;
}

