#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_GUARD_TIME 60      // ms
#define TIMEOUT 50000           // us (50ms)

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
  printf("Caught signal %d, exiting gracefully...\n", signal);
  running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return -1;
  }

  gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
  gpioSetMode(ECHO_PIN, PI_INPUT);

  gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
  gpioDelay(100);            // Small delay after setup

  return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
  gpioWrite(TRIGGER_PIN, 1);
  gpioDelay(10); // 10 us trigger pulse
  gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width with timeout
long measure_pulse_width() {
  long start_tick, end_tick, pulse_width;

  // Wait for rising edge with timeout
  int count = 0;
  while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
    count++;
    gpioDelay(1); // Check every 1 us
  }

  if (count >= TIMEOUT) {
    fprintf(stderr, "Timeout waiting for rising edge\n");
    return -1; // Timeout
  }

  start_tick = gpioTick();

  // Wait for falling edge with timeout
  count = 0;
  while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
    count++;
    gpioDelay(1); // Check every 1 us
  }

  if (count >= TIMEOUT) {
    fprintf(stderr, "Timeout waiting for falling edge\n");
    return -1; // Timeout
  }

  end_tick = gpioTick();

  pulse_width = end_tick - start_tick;
  if (pulse_width < 0) {
    pulse_width += 0xFFFFFFFF; // Handle tick rollover
  }

  return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
  return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, then by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(float distance) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[80];

  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  if (log_file != NULL) {
    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
  } else {
    fprintf(stderr, "Error: Log file is not open.\n");
  }
}

int main() {
  // Register signal handlers for graceful shutdown
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize GPIO
  if (initialize_gpio() != 0) {
    return 1;
  }

  // Open the log file in append mode
  log_file = fopen("distance_log.txt", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Error opening log file!\n");
    gpioTerminate();
    return 1;
  }

  time_t last_measurement_time = 0;

  // Main loop
  while (running) {
    time_t current_time = time(NULL);

    // Check if enough time has passed since the last measurement
    if (difftime(current_time, last_measurement_time) >= (double)MIN_GUARD_TIME / 1000.0) {
      trigger_sensor();

      long pulse_width = measure_pulse_width();

      if (pulse_width > 0) {
        float distance = calculate_distance(pulse_width);
        log_distance(distance);
        printf("Distance: %.2f cm\n", distance);
      } else {
        fprintf(stderr, "Error: Invalid pulse width\n");
        fprintf(log_file, "-1\n");
        fflush(log_file);
      }

      last_measurement_time = current_time;
    }

    gpioDelay(1000); // Wait for 1 second
  }

  // Cleanup
  printf("Cleaning up...\n");
  fclose(log_file);
  gpioTerminate();

  return 0;
}

