#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Full-scale range: ±250 dps
#define GYRO_SENSITIVITY 131.0f

// I2C bus file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error setting gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buf[6];

    // Read 6 bytes of gyroscope data starting from GYRO_XOUT_H
    if (write(fd, (uint8_t[]){GYRO_XOUT_H}, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully\n");

    // Main loop
    while (1) {
        int16_t gyro_x, gyro_y, gyro_z;

        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue; // Continue to the next iteration
        }

        // Convert raw data to degrees/second
        float gyro_x_dps = (float)gyro_x / GYRO_SENSITIVITY;
        float gyro_y_dps = (float)gyro_y / GYRO_SENSITIVITY;
        float gyro_z_dps = (float)gyro_z / GYRO_SENSITIVITY;

        // Print the gyroscope readings
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);

        // Delay for 100ms
        usleep(100000);
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    close(i2c_fd);
    return 0;
}

