void log_watering_cycle(int gpio_pin);
void signal_handler(int sig);
char* get_current_time(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to get current timestamp
char* get_current_time(void) {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    return buffer;
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines as outputs
    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 17); // GPIO17, GPIO18, GPIO27, GPIO22
        if (!lines[i]) {
            perror("Error getting GPIO line");
            cleanup_gpio();
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "watering";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line as output");
            cleanup_gpio();
            return -1;
        }

        // Set initial state to HIGH (inactive)
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            perror("Error setting GPIO line value");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

