void water_plant(int gpio_pin) {
    int i;
    int pin_index = -1;

    // Find the index of the GPIO pin in the lines array
    for (i = 0; i < 4; i++) {
        if (lines[i]->offset == gpio_pin) {
            pin_index = i;
            break;
        }
    }

    if (pin_index == -1) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return;
    }

    // Activate the relay (set LOW)
    if (gpiod_line_set_value(lines[pin_index], 0) < 0) {
        perror("Error setting GPIO line value (LOW)");
        return;
    }

    printf("Watering plant on GPIO %d (BCM %d) for %d seconds...\n", gpio_pin, gpio_pin, WATERING_DURATION);
    sleep(WATERING_DURATION);

    // Deactivate the relay (set HIGH)
    if (gpiod_line_set_value(lines[pin_index], 1) < 0) {
        perror("Error setting GPIO line value (HIGH)");
        return;
    }

    printf("Plant on GPIO %d (BCM %d) watered.\n", gpio_pin, gpio_pin);
}

// Function to log watering cycle
void log_watering_cycle(int gpio_pin) {
    char *timestamp = get_current_time();
    fprintf(log_file, "%s - Watering plant on GPIO %d (BCM %d)\n", timestamp, gpio_pin, gpio_pin);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release GPIO lines
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int i;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Water each plant sequentially
        for (i = 0; i < 4; i++) {
            water_plant(lines[i]->offset);
            log_watering_cycle(lines[i]->offset);
        }

        // Wait for the watering interval
        sleep(WATERING_INTERVAL);
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

