#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Sunrise duration (30 minutes)
#define SUNRISE_DURATION 1800 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_state(int gpio, int state);
void set_pwm_duty_cycle(int gpio, int duty_cycle);
void sunrise_simulation();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency for all relays
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    log_event("GPIO initialisation complete");
    return 0; // Indicate success
}

// Function to set the state of a relay (ON/OFF)
void set_relay_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to set the PWM duty cycle for a relay
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to simulate the sunrise effect
void sunrise_simulation() {
    time_t start_time = time(NULL);
    time_t current_time;
    int elapsed_time;
    int duty_cycle;

    while (program_running && (current_time = time(NULL)) - start_time < SUNRISE_DURATION) {
        elapsed_time = (int)(current_time - start_time);
        duty_cycle = (int)(((float)elapsed_time / SUNRISE_DURATION) * 255.0);

        // Ensure duty cycle stays within valid range
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

        set_pwm_duty_cycle(RELAY1_GPIO, duty_cycle);
        set_pwm_duty_cycle(RELAY2_GPIO, duty_cycle);
        set_pwm_duty_cycle(RELAY3_GPIO, duty_cycle);
        set_pwm_duty_cycle(RELAY4_GPIO, duty_cycle);

        gpioDelay(1000); // Wait for 1 second
    }

    // Ensure all relays are fully on at the end of the simulation
    set_pwm_duty_cycle(RELAY1_GPIO, 255);
    set_pwm_duty_cycle(RELAY2_GPIO, 255);
    set_pwm_duty_cycle(RELAY3_GPIO, 255);
    set_pwm_duty_cycle(RELAY4_GPIO, 255);

    log_event("Sunrise simulation complete");
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialisation failed, exiting");
        return 1;
    }

    log_event("Starting smart lighting simulation");

    // Run the sunrise simulation
    sunrise_simulation();

    // Clean up GPIO resources before exiting
    gpioTerminate();
    log_event("pigpio terminated");

    return 0;
}

