#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define LED_GPIO 17
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD (1000 / SAMPLE_RATE) // ms
#define BUFFER_SIZE 100

// Data structure for gyroscope readings
typedef struct {
    int16_t x, y, z;
    long timestamp;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void store_reading(int16_t x, int16_t y, int16_t z);
void check_thresholds(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1, retrying...\n");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set sample rate divider
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV, retrying...\n");
            retries--;
            gpioDelay(100);
            continue;
        }

        // Set gyroscope configuration
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG, retrying...\n");
            retries--;
            gpioDelay(100);
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, 0x75);
        if (who_am_i < 0 || who_am_i != 0x68) {
            fprintf(stderr, "Error reading WHO_AM_I register or incorrect value: 0x%x, retrying...\n", who_am_i);
            retries--;
            gpioDelay(100);
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) == 6) {
            *x = (int16_t)((buffer[0] << 8) | buffer[1]);
            *y = (int16_t)((buffer[2] << 8) | buffer[3]);
            *z = (int16_t)((buffer[4] << 8) | buffer[5]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            retries--;
            gpioDelay(100);
        }
    }

    fprintf(stderr, "Failed to read gyro data after multiple retries.\n");
    return -1; // Failure
}

// Store reading in circular buffer
void store_reading(int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    gyro_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check thresholds and control LED
void check_thresholds(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            store_reading(x, y, z);
            check_thresholds(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

