#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// MPU-9250 Registers
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_L 0x48

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_CS_GPIO_CHIP 0
#define SPI_CS_GPIO_LINE 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(void);
int gpio_set_value(int value);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed hz
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_number(SPI_CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, SPI_CS_GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(gpio_line, "spi_cs", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int value) {
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log Data
int log_data(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        return -1;
    }

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

int main(void) {
    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open Log File
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    uint8_t tx_buf[7] = {GYRO_XOUT_H | 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}; // Read 6 bytes
    uint8_t rx_buf[7] = {0};

    // Main Loop
    while (!terminate) {
        // Assert CS
        if (gpio_set_value(0) < 0) {
            fprintf(stderr, "Failed to assert CS. Continuing.\n");
            continue;
        }

        // Transfer Data
        if (spi_transfer(tx_buf, rx_buf, 7) < 0) {
            fprintf(stderr, "SPI transfer failed. Retrying.\n");
            gpio_set_value(1);
            usleep(10000); // 10ms
            continue;
        }

        // De-assert CS
        if (gpio_set_value(1) < 0) {
            fprintf(stderr, "Failed to de-assert CS. Continuing.\n");
            continue;
        }

        // Convert Data
        int16_t x = (rx_buf[1] << 8) | rx_buf[2];
        int16_t y = (rx_buf[3] << 8) | rx_buf[4];
        int16_t z = (rx_buf[5] << 8) | rx_buf[6];

        // Log Data
        if (log_data(x, y, z) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        usleep(10000); // 10ms
    }

    // Cleanup
    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);

    return 0;
}

