#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define GYRO_SENSITIVITY 131.0
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define STABILITY_THRESHOLD 200.0

// MPU-6050 Registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_reading_t;

// Circular buffer
gyro_reading_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int spi_init();
int spi_read_register(int reg);
int spi_write_register(int reg, int value);
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_stability(float x, float y, float z);
void blink_led();
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI read register function
int spi_read_register(int reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read
    tx[1] = 0x00;       // Dummy byte

    gpioWrite(8, 0); // Assert CS
    spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(8, 1); // De-assert CS

    return rx[1];
}

// SPI write register function
int spi_write_register(int reg, int value) {
    char tx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write
    tx[1] = value;

    gpioWrite(8, 0); // Assert CS
    spiWrite(spi_handle, tx, 2);
    gpioWrite(8, 1); // De-assert CS

    return 0;
}

// Read gyroscope data function
int read_gyro_data(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int x_high, x_low, y_high, y_low, z_high, z_low;

    x_high = spi_read_register(GYRO_XOUT_H);
    x_low = spi_read_register(GYRO_XOUT_H + 1);
    y_high = spi_read_register(GYRO_YOUT_H);
    y_low = spi_read_register(GYRO_YOUT_H + 1);
    z_high = spi_read_register(GYRO_ZOUT_H);
    z_low = spi_read_register(GYRO_ZOUT_H + 1);

    raw_x = (int16_t)((x_high << 8) | x_low);
    raw_y = (int16_t)((y_high << 8) | y_low);
    raw_z = (int16_t)((z_high << 8) | z_low);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer function
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check stability function
void check_stability(float x, float y, float z) {
    if (fabs(x) > STABILITY_THRESHOLD || fabs(y) > STABILITY_THRESHOLD || fabs(z) > STABILITY_THRESHOLD) {
        blink_led();
    }
}

// Blink LED function
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(500);         // Wait 500ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(500);         // Wait 500ms
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(8, PI_OUTPUT); // CE0
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050
    spi_write_register(PWR_MGMT_1, 0x00);
    spi_write_register(SMPLRT_DIV, 0x07); // Set sample rate to 125 Hz
    spi_write_register(GYRO_CONFIG, 0x00); // Set gyro full scale to +/- 250 deg/s

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    printf("Timestamp,X,Y,Z\n");

    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_stability(x, y, z);
            printf("%ld.%09ld,%.2f,%.2f,%.2f\n", gyro_buffer[buffer_index].timestamp.tv_sec, gyro_buffer[buffer_index].timestamp.tv_nsec, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }
        gpioDelay(10); // Delay 10ms
    }

    return 0;
}

