#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"

// Global variables (to be cleaned up in signal handlers)
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void set_gpio_value(int value);
void signal_handler(int sig);

// I2C read function with retry and exponential backoff
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int delay_ms = 10;
    int result;
    uint8_t buf[1];

    buf[0] = reg;

    while (retries > 0) {
        if (write(fd, buf, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %m\n");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        if (read(fd, buf, 1) != 1) {
            fprintf(stderr, "Error reading from I2C device: %m\n");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        return buf[0];
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// I2C write function with retry and exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int delay_ms = 10;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            fprintf(stderr, "Error writing to I2C device: %m\n");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }
        return 0; // Success
    }

    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to read ambient light and proximity values from the sensor
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int ambient_low, ambient_high, proximity_low, proximity_high;

    ambient_low = i2c_read_reg(fd, AMBIENT_LIGHT_REG);
    if (ambient_low < 0) return -1;
    ambient_high = i2c_read_reg(fd, AMBIENT_LIGHT_REG + 1);
    if (ambient_high < 0) return -1;

    proximity_low = i2c_read_reg(fd, PROXIMITY_REG);
    if (proximity_low < 0) return -1;
    proximity_high = i2c_read_reg(fd, PROXIMITY_REG + 1);
    if (proximity_high < 0) return -1;

    *ambient_light = (uint16_t)((ambient_high << 8) | ambient_low);
    *proximity = (uint16_t)((proximity_high << 8) | proximity_low);

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to set the GPIO pin value
void set_gpio_value(int value) {
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %m\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    uint16_t ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %m\n");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %m\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %m\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "biometric", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %m\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %m\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);

            if (proximity > PROXIMITY_THRESHOLD) {
                set_gpio_value(1); // Set GPIO high
            } else {
                set_gpio_value(0); // Set GPIO low
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        usleep(100000); // 100 ms delay
    }

    return 0; // This line will not be reached due to the infinite loop
}

