    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int reinit_attempts = 0;
    int16_t x_rate, y_rate;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        x_rate = read_gyro_axis(spi_handle, 0x02);
        y_rate = read_gyro_axis(spi_handle, 0x04);

