#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

void log_event(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

void seismic_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_trigger_time = 0;
    uint32_t current_time = gpioTick();

    if (level == PI_HIGH) {
        if (current_time - last_trigger_time >= 500000) { // 500ms in microseconds
            log_event("Seismic event detected!");
            gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
            gpioDelay(2000000);      // Wait for 2 seconds
            gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
            last_trigger_time = current_time;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    gpioSetAlertFunc(SENSOR1_PIN, seismic_callback);
    gpioSetAlertFunc(SENSOR2_PIN, seismic_callback);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100); // Reduce CPU usage
    }

    printf("Cleaning up...\n");

    gpioSetAlertFunc(SENSOR1_PIN, NULL); // Disable callback
    gpioSetAlertFunc(SENSOR2_PIN, NULL);

    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

