#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define LED_GPIO 17
#define ANGULAR_RATE_THRESHOLD 20.0
#define BUFFER_SIZE 100

// Structure for storing gyroscope data
typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
float convert_to_dps(int16_t raw_rate);
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float x_rate, float y_rate);
int check_threshold(float x_rate, float y_rate);
void control_led(int on);
void *monitor_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float x_rate, float y_rate) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].x_rate = x_rate;
    buffer->buffer[buffer->head].y_rate = y_rate;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Check if angular rate exceeds threshold
int check_threshold(float x_rate, float y_rate) {
    return (fabs(x_rate) > ANGULAR_RATE_THRESHOLD || fabs(y_rate) > ANGULAR_RATE_THRESHOLD);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Read gyroscope data
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buffer[2];
    char rx_buffer[2];
    int status;

    // Read X-axis rate
    tx_buffer[0] = 0x82; // RATE_XL (read)
    tx_buffer[1] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading X-axis rate: %d\n", status);
        return -1;
    }
    *x_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[0]);

    // Read Y-axis rate
    tx_buffer[0] = 0x83; // RATE_YL (read)
    tx_buffer[1] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading Y-axis rate: %d\n", status);
        return -1;
    }
    *y_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[0]);

    return 0;
}

