    tx_buffer[0] = 0x82; // RATE_XL (read)
    tx_buffer[1] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading X-axis rate: %d\n", status);
        return -1;
