    int i;
    float step_size = 255.0 / duration; // Calculate step size

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    // Fade up
    for (i = 0; i <= 255; i++) {
        gpioPWM(gpio, i);
        gpioDelay(1000); // Delay for 1ms (adjust as needed)
    }

    // Fade down
    for (i = 255; i >= 0; i--) {
        gpioPWM(gpio, i);
        gpioDelay(1000); // Delay for 1ms (adjust as needed)
    }

    printf("Lamp on GPIO %d faded for %d seconds.\n", gpio, duration);
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
