#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define YELLOW_RELAY_PIN 22
#define GREEN_RELAY_PIN 23
#define YELLOW_RELAY_PIN2 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *yellow_line, *green_line, *yellow_line2;

// Function prototypes
int initialize_gpio(void);
void set_relay_state(int pin, int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold relay states
typedef struct {
    int red;
    int yellow;
    int green;
    int yellow2;
} relay_states_t;

// Function to set relay states
void set_relay_states(relay_states_t states) {
    set_relay_state(RED_RELAY_PIN, states.red);
    set_relay_state(YELLOW_RELAY_PIN, states.yellow);
    set_relay_state(GREEN_RELAY_PIN, states.green);
    set_relay_state(YELLOW_RELAY_PIN2, states.yellow2);
}

int main(void) {
    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Red state (10 seconds)
        printf("Transitioning to RED\n");
        set_relay_states((relay_states_t){1, 0, 0, 0});
        sleep(10);

        // Red + Yellow state (2 seconds)
        printf("Transitioning to RED + YELLOW\n");
        set_relay_states((relay_states_t){0, 1, 0, 0});
        sleep(2);

        // Green state (10 seconds)
        printf("Transitioning to GREEN\n");
        set_relay_states((relay_states_t){0, 0, 1, 0});
        sleep(10);

        // Yellow state (3 seconds)
        printf("Transitioning to YELLOW\n");
        set_relay_states((relay_states_t){0, 0, 0, 1});
        sleep(3);
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    yellow_line2 = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN2);

    if (!red_line || !yellow_line || !green_line || !yellow_line2) {
        perror("gpiod_chip_get_line");
        cleanup_gpio();
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    config.consumer = "traffic_light_simulator";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(red_line, &config, 0) ||
        gpiod_line_request(yellow_line, &config, 0) ||
        gpiod_line_request(green_line, &config, 0) ||
        gpiod_line_request(yellow_line2, &config, 0)) {
        perror("gpiod_line_request");
        cleanup_gpio();
        return 1;
    }

    return 0;
}

// Function to set relay state
void set_relay_state(int pin, int state) {
    struct gpiod_line *line = NULL;

    if (pin == RED_RELAY_PIN) {
        line = red_line;
    } else if (pin == YELLOW_RELAY_PIN) {
        line = yellow_line;
    } else if (pin == GREEN_RELAY_PIN) {
        line = green_line;
    } else if (pin == YELLOW_RELAY_PIN2) {
        line = yellow_line2;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", pin);
        return;
    }

    if (gpiod_line_set_value(line, !state)) { // Active low
        perror("gpiod_line_set_value");
    }
}

// Function to cleanup GPIO
void cleanup_gpio(void) {
    if (red_line) gpiod_line_release(red_line);
    if (yellow_line) gpiod_line_release(yellow_line);
    if (green_line) gpiod_line_release(green_line);
    if (yellow_line2) gpiod_line_release(yellow_line2);
    if (chip) gpiod_chip_close(chip);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);
    cleanup_gpio();
    exit(0);
}

