#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_STATUS_LSB 0x00
#define TOUCH_STATUS_MSB 0x01
#define ELECTRODE_TOGGLE 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_mpr121();
int read_touch_status(uint16_t *touch_status);
int toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("I2C open failed");
        return -1;
    }
    return 0;
}

// Function to configure the MPR121
int configure_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("MPR121 reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("MPR121 stop mode failed");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("MPR121 enable electrode 0 failed");
        return -1;
    }

    // Touch threshold
    if (i2cWriteByteData(i2c_handle, 0x41, 0x0A) < 0) {
        log_message("MPR121 touch threshold failed");
        return -1;
    }

    // Release threshold
    if (i2cWriteByteData(i2c_handle, 0x42, 0x08) < 0) {
        log_message("MPR121 release threshold failed");
        return -1;
    }

    // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("MPR121 debounce failed");
        return -1;
    }

    // Charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("MPR121 charge time failed");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0D) < 0) {
        log_message("MPR121 run mode failed");
        return -1;
    }

    return 0;
}

// Function to read the touch status
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, TOUCH_STATUS_LSB, buf, 2) != 2) {
        log_message("MPR121 read touch status failed");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
int toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    uint16_t last_touch_status = 0;
    uint16_t current_touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&current_touch_status) == 0) {
            if ((current_touch_status & (1 << ELECTRODE_TOGGLE)) && !(last_touch_status & (1 << ELECTRODE_TOGGLE))) {
                // Electrode 0 touched, toggle relay
                toggle_relay();
                log_message("Electrode 0 touched, toggling relay");
            }
            last_touch_status = current_touch_status;
        } else {
            log_message("Failed to read touch status, retrying...");
        }
        gpioDelay(10); // Check every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

