#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor(int pin);
void activate_buzzer(int pin, int duration_ms);
void activate_led(int pin, int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor(int pin) {
    int i, value;
    int consistent_reads = 0;

    for (i = 0; i < 3; i++) {
        value = gpioRead(pin);
        if (value == 0) { // Active low
            consistent_reads++;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }

    if (consistent_reads == 3) {
        return 0; // Flame detected (consistent LOW)
    } else {
        return 1; // No flame detected
    }
}

// Function to activate the buzzer for a specified duration
void activate_buzzer(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(pin, 0); // Turn buzzer off
}

// Function to activate the LED for a specified duration
void activate_led(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(pin, 0); // Turn LED off
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Release GPIO lines
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(BUZZER_PIN, PI_INPUT); // Set back to input
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_flame_sensor(FLAME_SENSOR_PIN) == 0) {
            printf("Flame detected!\n");
            log_event("Flame Detected");
            activate_buzzer(BUZZER_PIN, 2000); // Activate buzzer for 2 seconds
            activate_led(LED_PIN, 2000);       // Activate LED for 2 seconds
        }
        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(BUZZER_PIN, PI_INPUT); // Set back to input
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input
    fclose(log_file);
    gpioTerminate();

    return 0;
}

