#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (milliseconds)
#define DISPENSE_DURATION 1000

// Define dispense interval (milliseconds)
#define DISPENSE_INTERVAL 5000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int configure_gpio(int pin, int mode);
int activate_solenoid(int pin);
int deactivate_solenoid(int pin);
int dispense_cycle();
int log_dispense_event(int pin1, int pin2, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to configure a GPIO pin as output
int configure_gpio(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return 1;
    }
    return 0;
}

// Function to activate a solenoid (set GPIO pin HIGH)
int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO %d\n", pin);
        return 1;
    }
    return 0;
}

// Function to deactivate a solenoid (set GPIO pin LOW)
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO %d\n", pin);
        return 1;
    }
    return 0;
}

// Function to perform a dispense cycle
int dispense_cycle() {
    // Activate solenoid 1 for half the dispense duration
    if (activate_solenoid(SOLENOID_1_PIN) != 0) return 1;
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Convert ms to microseconds
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) return 1;

    // Activate solenoid 2 for the remaining half of the dispense duration
    if (activate_solenoid(SOLENOID_2_PIN) != 0) return 1;
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Convert ms to microseconds
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) return 1;

    return 0;
}

// Function to log a dispense event to a file
int log_dispense_event(int pin1, int pin2, int duration) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - GPIO %d, GPIO %d, Duration: %d ms\n", timestamp, pin1, pin2, duration);
    fclose(fp);
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pins as outputs
    if (configure_gpio(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }
    if (configure_gpio(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Perform a dispense cycle
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Error during dispense cycle\n");
        }

        // Log the dispense event
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error logging dispense event\n");
        }

        // Wait for the dispense interval
        gpioDelay(DISPENSE_INTERVAL * 1000); // Convert ms to microseconds
    }

    // Deactivate solenoids before exiting
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);

    // Terminate pigpio
    gpioTerminate();

    printf("Dispensing system stopped.\n");

    return 0;
}

