#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Motor A pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable pins
#define ENABLE_A 24
#define ENABLE_B 25

// PID constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// Global variables
FILE *log_file;
double integral = 0.0;
double previous_error = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
double simulate_tilt();
double simulate_distance();
void set_motor_speed(int motor, int speed);
void pid_control(double tilt_error, double distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to log data to file
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to simulate tilt error
double simulate_tilt() {
    return ((double)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Function to simulate distance sensor reading
double simulate_distance() {
    return ((double)rand() / RAND_MAX) * 390.0 + 2.0;
}

// Function to set motor speed
void set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (motor == 1) { // Motor A
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENABLE_A, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENABLE_A, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENABLE_A, 0);
        }
    } else if (motor == 2) { // Motor B
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENABLE_B, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENABLE_B, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENABLE_B, 0);
        }
    }
}

// PID control function
void pid_control(double tilt_error, double distance) {
    double proportional = Kp * tilt_error;
    integral += Ki * tilt_error;
    double derivative = Kd * (tilt_error - previous_error);

    double output = proportional + integral + derivative;

    // Clamp output to -255 to 255
    if (output > 255) output = 255;
    if (output < -255) output = -255;

    // Obstacle avoidance logic
    if (distance < OBSTACLE_THRESHOLD) {
        printf("Obstacle detected! Reversing...\n");
        set_motor_speed(1, -128); // Reverse Motor A
        set_motor_speed(2, -128); // Reverse Motor B
        gpioDelay(500); // Reverse for 0.5 seconds
        set_motor_speed(1, 0); // Stop Motor A
        set_motor_speed(2, 0); // Stop Motor B
        gpioDelay(100); // Short delay
    } else {
        // Set motor speeds based on PID output
        set_motor_speed(1, (int)output);
        set_motor_speed(2, (int)output);
    }

    previous_error = tilt_error;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Seed random number generator
    srand(time(NULL));

    // Main loop
    while (!terminate) {
        // Simulate sensor readings
        double tilt_error = simulate_tilt();
        double distance = simulate_distance();

        // PID control
        pid_control(tilt_error, distance);

        // Log data
        log_data(tilt_error, distance, (int)Kp * tilt_error, (int)Kp * tilt_error);

        // Delay
        gpioDelay(50);
    }

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

