#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with error
    }

    // Configure GPIO pins
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT); // Touch sensor pin as input
    gpioSetMode(RELAY_PIN, PI_OUTPUT); // Relay pin as output
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor state
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        // Debounce and toggle relay state
        if (touch_detected == 1) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (in microseconds)
            if (gpioRead(TOUCH_SENSOR_PIN) == 1) { // Re-read after debounce
                relay_state = !relay_state; // Toggle relay state
                gpioWrite(RELAY_PIN, relay_state); // Set relay pin
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    return 0; // This line will never be reached due to the infinite loop
}

