#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define ALSA_DEVICE "default"
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2 // bytes
#define PERIOD_SIZE 1024

#define DEFAULT_SENSITIVITY 1.0
#define MIN_SENSITIVITY 0.1
#define MAX_SENSITIVITY 10.0

#define MIN_AMPLITUDE 0.01
#define MAX_AMPLITUDE 1.0

#define MIN_RMS 0.01
#define MAX_RMS 1.0

#define MIN_PWM 0
#define MAX_PWM 255

#define SINE_FREQUENCY 5.0

#define ALSA_AVAILABLE

#ifdef ALSA_AVAILABLE
static snd_pcm_t *pcm_handle;
static snd_pcm_hw_params_t *hw_params;
static int alsa_initialized = 0;
#endif

static volatile int running = 1;
static double sensitivity = DEFAULT_SENSITIVITY;

static void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting...\n", signal);
}

static int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    return 0;
}

#ifdef ALSA_AVAILABLE
static int init_alsa() {
    int err;

    if ((err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "cannot open audio device %s (%s)\n", ALSA_DEVICE, snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "cannot allocate hardware parameter structure (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "cannot initialize hardware parameter structure (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "cannot set access type (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "cannot set sample format (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "cannot set channel count (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "cannot set sample rate (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "cannot set period size (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "cannot set parameters (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    snd_pcm_hw_params_free(hw_params);

    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "cannot prepare audio interface for use (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

