    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to cycle through the phases
    while (1) {
        // Sunrise
        printf("Sunrise\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            simulate_brightness(i, SUNRISE_DURATION);
        }

        // Daytime
        printf("Daytime\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            simulate_brightness(i, DAYTIME_DURATION);
        }

        // Sunset
        printf("Sunset\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            simulate_brightness(i, SUNSET_DURATION);
        }

        // Nighttime
        printf("Nighttime\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
