    // Get the lines for the relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        char line_name[3];
        snprintf(line_name, sizeof(line_name), "%d", (i == 0) ? RELAY1_PIN : (i == 1) ? RELAY2_PIN : (i == 2) ? RELAY3_PIN : RELAY4_PIN);
        relay_lines[i] = gpiod_chip_get_line(chip, line_name);
        if (!relay_lines[i]) {
            perror("Error getting GPIO line");
            cleanup_gpio();
            return 1;
        }
    }

    // Request the lines for output
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(relay_lines[i], "sunrise_simulator", 0) != 0) {
            perror("Error requesting GPIO line for output");
            cleanup_gpio();
            return 1;
        }
    }

    return 0;
}

// Function to set the state of a relay
