    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return;
    }

    if (gpiod_line_set_value(relay_lines[relay_num], state) != 0) {
        perror("Error setting GPIO line value");
    }
    current_states.state[relay_num] = state;
}

// Function to simulate brightness using PWM-like toggling
void simulate_brightness(int relay_num, int duration) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return;
    }

    int on_time = duration / 2; // 50% duty cycle
    int off_time = duration / 2; // 50% duty cycle

    // Turn on the relay
    set_relay_state(relay_num, 1);
    sleep(on_time);

    // Turn off the relay
    set_relay_state(relay_num, 0);
    sleep(off_time);
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    // Release the lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_release(relay_lines[i]);
        }
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
