#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_S 5

static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_trigger_time = 0;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y%m%dT%H%M%SZ", timeinfo);
    return timestamp;
}

// Function to log motion detection event
void log_motion_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp, skipping log entry.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s Motion detected\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Log file is not open, skipping log entry.\n");
    }
    free(timestamp);
}

// Function to capture video using raspivid
void capture_video() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp, skipping video capture.\n");
        return;
    }

    char filename[100];
    snprintf(filename, sizeof(filename), "/home/pi/videos/%s.h264", timestamp);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_S * 1000);

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
    }

    free(timestamp);
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    if (level == 0) { // Obstacle detected (LOW signal)
        if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS * 1000) { // Debounce
            log_motion_event();
            capture_video();
            last_trigger_time = current_time;
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up resistor (optional, depending on sensor module)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen("/home/pi/logs/motion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback function for motion detection
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

