#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050. Retrying...\n");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set sample rate divider to 125 Hz (1kHz / (1 + SMPLRT_DIV))
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error: Could not set sample rate divider. Retrying...\n");
            retries--;
            gpioDelay(100);
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error: Could not set gyroscope full-scale range. Retrying...\n");
            retries--;
            gpioDelay(100);
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read raw gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        return -1;
    }

    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_degps(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_degps, float *gyro_y_degps, float *gyro_z_degps) {
    *gyro_x_degps = (float)gyro_x / GYRO_SENSITIVITY;
    *gyro_y_degps = (float)gyro_y / GYRO_SENSITIVITY;
    *gyro_z_degps = (float)gyro_z / GYRO_SENSITIVITY;
}

// Function to log data to a CSV file
int log_data(time_t timestamp, float gyro_x_degps, float gyro_y_degps, float gyro_z_degps) {
    struct tm *timeinfo;
    char timestamp_str[30];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s.%03ld,%.3f,%.3f,%.3f\n", timestamp_str, (long)(timestamp % 1000), gyro_x_degps, gyro_y_degps, gyro_z_degps);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }
    fflush(log_file);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t gyro_x, gyro_y, gyro_z;
    float gyro_x_degps, gyro_y_degps, gyro_z_degps;
    time_t current_time;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert to degrees per second
            convert_to_degps(gyro_x, gyro_y, gyro_z, &gyro_x_degps, &gyro_y_degps, &gyro_z_degps);

            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(current_time, gyro_x_degps, gyro_y_degps, gyro_z_degps);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Attempting re-initialization...\n");
            // Attempt re-initialization
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: Failed to re-initialize MPU-6050.\n");
            }
        }

        // Delay for 10 ms (100 Hz sampling rate)
        gpioDelay(10);
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

