#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Alarm GPIO pin
#define ALARM_PIN 27

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init();
accelerometer_data_t read_accelerometer_data();
int detect_freefall(accelerometer_data_t data);
void alarm_on();
void alarm_off();
void log_freefall_event(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345
int adxl345_init() {
    // Set data format to ±2g and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];
    int16_t x, y, z;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0; // Set to 0 to avoid using uninitialized values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Detect freefall
int detect_freefall(accelerometer_data_t data) {
    static time_t start_time = 0;
    static int freefall_count = 0;

    if (abs(data.x) < FREEFALL_THRESHOLD &&
        abs(data.y) < FREEFALL_THRESHOLD &&
        abs(data.z) < FREEFALL_THRESHOLD) {
        freefall_count++;
    } else {
        freefall_count = 0;
    }

    if (freefall_count >= (int)(FREEFALL_DURATION * 10)) { // 10 samples per second
        if (start_time == 0) {
            start_time = time(NULL);
        } else if (time(NULL) - start_time >= 1) {
            return 1; // Freefall confirmed
        }
    } else {
        start_time = 0; // Reset start time if not in freefall
    }

    return 0;
}

// Turn alarm on
void alarm_on() {
    gpioWrite(ALARM_PIN, 1);
}

// Turn alarm off
void alarm_off() {
    gpioWrite(ALARM_PIN, 0);
}

// Log freefall event to file
void log_freefall_event(accelerometer_data_t data) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();

        if (detect_freefall(data)) {
            printf("Freefall detected!\n");
            alarm_on();
            gpioDelay(5000000); // 5 seconds
            alarm_off();
            log_freefall_event(data);
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    alarm_off();
    gpioTerminate();

    return 0;
}

