// Turn alarm on
void alarm_on() {
    gpioWrite(ALARM_PIN, 1);
}

// Turn alarm off
void alarm_off() {
    gpioWrite(ALARM_PIN, 0);
}

// Log freefall event to file
void log_freefall_event(accelerometer_data_t data) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();

        if (detect_freefall(data)) {
            printf("Freefall detected!\n");
            alarm_on();
            gpioDelay(5000000); // 5 seconds
            alarm_off();
            log_freefall_event(data);
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    alarm_off();
    gpioTerminate();

    return 0;
}

