#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 23200.0   // cm
#define TIMEOUT_US 100         // 100 ms timeout
#define TRIGGER_PULSE_US 10    // 10 us trigger pulse

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
int init_gpio();
int init_logging();
void cleanup();

// Function to send a 10µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PIN, TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1; // Set echo_received flag
    }
    pthread_mutex_unlock(&mutex);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Initialize logging file
int init_logging() {
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
}

int main() {
    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        return 1;
    }

    // Initialize pigpio
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt callback for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        // Send trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        uint32_t start_time_ns = start_time.tv_sec * 1000000000LL + start_time.tv_nsec;

        pthread_mutex_lock(&mutex);
        echo_received = 0; // Reset flag before waiting
        pthread_mutex_unlock(&mutex);

        while (!echo_received && running) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            uint32_t elapsed_ns = (now.tv_sec - start_time.tv_sec) * 1000000000LL + (now.tv_nsec - start_time.tv_nsec);

            if (elapsed_ns > TIMEOUT_US * 1000) {
                pthread_mutex_lock(&mutex);
                echo_received = 1; // Simulate echo timeout
                pthread_mutex_unlock(&mutex);
                break;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Calculate pulse width and distance
        uint32_t pulse_width = 0;
        pthread_mutex_lock(&mutex);
        if (echo_received) {
            if (end_tick > start_tick) {
                pulse_width = end_tick - start_tick;
            } else {
                pulse_width = (0xFFFFFFFF - start_tick) + end_tick; // Handle tick wrap-around
            }

            if (pulse_width > 0 && pulse_width <= 0xFFFF) {
                double distance = (pulse_width * SPEED_OF_SOUND) / 20000.0; // Divide by 2 for one-way distance and by 1000000 for us to s conversion
                if (distance > 0 && distance <= MAX_DISTANCE) {
                    // Get current timestamp
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000LL + (uint64_t)ts.tv_nsec;

                    // Log distance measurement
                    fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
                    fflush(log_file); // Ensure data is written to file immediately
                    printf("Distance: %.2f cm, Timestamp: %llu ns\n", distance, timestamp_ns);
                } else {
                    fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
                }
            } else {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            }
        } else {
            fprintf(stderr, "Timeout occurred\n");
        }
        pthread_mutex_unlock(&mutex);

        gpioDelay(200); // Wait 200 ms before next measurement
    }

    cleanup();
    return 0;
}

