    if (set_gpio_level(MOTOR1_IN2, step_sequence[step][1]) != 0) return;
    if (set_gpio_level(MOTOR1_IN3, step_sequence[step][2]) != 0) return;
    if (set_gpio_level(MOTOR1_IN4, step_sequence[step][3]) != 0) return;
