#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <math.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_DATA_RATE 100 // Hz

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
int data_rate = DEFAULT_DATA_RATE;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int address);
int configure_lis3dh(int handle, int address);
int read_acceleration_data(int handle, int address, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int check_threshold(float x, float y, float z, float threshold);
void log_event(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", handle);
        return -1;
    }
    return handle;
}

// Configure LIS3DH
int configure_lis3dh(int handle, int address) {
    // CTRL_REG1: 0x57 (ODR = 100Hz, Enable X, Y, Z axes)
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        syslog(LOG_ERR, "Failed to write to CTRL_REG1");
        return -1;
    }

    // CTRL_REG4: 0x88 (±2g, High-resolution, Left justified)
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        syslog(LOG_ERR, "Failed to write to CTRL_REG4");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration_data(int handle, int address, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(handle, OUT_X_L | 0x80, buffer, 6) != 6) { // Read multiple bytes, auto-increment
        syslog(LOG_ERR, "Failed to read acceleration data");
        *x = 0; *y = 0; *z = 0; // Return zeros on error
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 2048.0f; // 2^11 - 1
}

// Check threshold
int check_threshold(float x, float y, float z, float threshold) {
    if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
        return 1;
    }
    return 0;
}

// Log event
void log_event(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "High acceleration event: %s, X: %.3f g, Y: %.3f g, Z: %.3f g", timestamp, x, y, z);
}

// Shutdown system
void shutdown_system() {
    syslog(LOG_INFO, "Initiating system shutdown...");
    system("sudo shutdown -h now");
}

// Cleanup
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Threshold must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize syslog
    openlog("high_acceleration", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "pigpio initialization failed, exiting");
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(i2c_address);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "I2C open failed, exiting");
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle, i2c_address) != 0) {
        syslog(LOG_ERR, "LIS3DH configuration failed, exiting");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration_data(i2c_handle, i2c_address, &x_raw, &y_raw, &z_raw) == 0) {
            // Convert to g
            x_g = convert_to_g(x_raw);
            y_g = convert_to_g(y_raw);
            z_g = convert_to_g(z_raw);

            // Check threshold
            if (check_threshold(x_g, y_g, z_g, threshold)) {
                log_event(x_g, y_g, z_g);
                shutdown_system();
                break; // Exit loop after shutdown
            }
        } else {
            syslog(LOG_WARNING, "Failed to read acceleration data, continuing...");
        }

        // Wait for the next sample
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

