int check_buffer(int *buffer) {
    int first_value = buffer[0];
    for (int i = 1; i < BUFFER_SIZE; i++) {
        if (buffer[i] != first_value) {
            return 0; // Not all elements are the same
        }
    }
    return 1; // All elements are the same
}

