void line_following_logic() {
    int left_value = read_sensor(LEFT_SENSOR);
    int center_value = read_sensor(CENTER_SENSOR);
    int right_value = read_sensor(RIGHT_SENSOR);

    update_buffer(left_buffer, left_value);
    update_buffer(center_buffer, center_value);
    update_buffer(right_buffer, right_value);

    if (check_buffer(center_buffer) == 0) {
        // Center sensor is reading no line
        if (check_buffer(left_buffer) == 1 && check_buffer(right_buffer) == 1) {
            // Both left and right sensors are reading line
            if (left_value == 0) {
                // Turn left
                printf("Turning left\n");
            } else if (right_value == 0) {
                // Turn right
                printf("Turning right\n");
            } else {
                // Stop
                printf("Stopping\n");
            }
        } else {
            // One or both sensors are reading no line
            printf("Stopping\n");
        }
    } else {
        // Center sensor is reading line
        printf("Moving forward\n");
    }
}

