    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize circular buffers to 1 (line detected)
    for (int i = 0; i < BUFFER_SIZE; i++) {
        left_buffer[i] = 1;
        center_buffer[i] = 1;
        right_buffer[i] = 1;
    }

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        line_following_logic();
        usleep(10000); // Wait 10 ms
    }

    return 0;
}

