#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 5.0 // mT
#define FIELD_THRESHOLD_RAW (FIELD_THRESHOLD * 100) // Convert to raw value
#define SAMPLE_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_register(int handle, int reg);
int write_register(int handle, int reg, int value);
int read_field_raw(int handle);
float convert_to_mT(int raw_value);
void control_relay(int gpio, int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read a single byte from an I2C register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        char error_message[100];
        sprintf(error_message, "Failed to read register 0x%02X: %d", reg, result);
        log_event("ERROR", error_message);
        return -1; // Indicate failure
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        char error_message[100];
        sprintf(error_message, "Failed to write 0x%02X to register 0x%02X: %d", value, reg, result);
        log_event("ERROR", error_message);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to read the raw magnetic field data from the sensor
int read_field_raw(int handle) {
    int lsb, msb;

    // Start a conversion
    if (write_register(handle, 0xC1, 0x01) < 0) {
        return -1; // Error already logged in write_register
    }

    // Poll for conversion completion
    int poll_attempts = 0;
    while (1) {
        int status = read_register(handle, 0xC1);
        if (status < 0) {
            return -1; // Error already logged in read_register
        }
        if (status == 0) {
            break; // Conversion complete
        }
        gpioDelay(1); // Small delay
        poll_attempts++;
        if (poll_attempts > MAX_POLL_ATTEMPTS) {
            log_event("ERROR", "Timeout waiting for conversion to complete.");
            return -1; // Timeout
        }
    }

    // Read the raw data (2 bytes)
    lsb = read_register(handle, 0xC0);
    if (lsb < 0) {
        return -1; // Error already logged in read_register
    }

    msb = read_register(handle, 0xC1);
    if (msb < 0) {
        return -1; // Error already logged in read_register
    }

    // Combine the bytes into a 16-bit value
    int raw_value = (msb << 8) | lsb;

    return raw_value;
}

// Function to convert the raw magnetic field data to milliTesla
float convert_to_mT(int raw_value) {
    return (float)raw_value * 25.0 / 1000.0;
}

// Function to control the relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        perror("Error opening magnetic_events.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s [%s] %s\n", timestamp, event_type, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("INFO", "Received signal, shutting down...");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("ERROR", "pigpio initialisation failed");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        char error_message[100];
        sprintf(error_message, "Failed to open I2C bus: %d", i2c_handle);
        log_event("ERROR", error_message);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Install signal handler
    signal(SIGINT, signal_handler);

    log_event("INFO", "System started");

    // Main loop
    while (!terminate) {
        // Read raw magnetic field data
        int raw_value = read_field_raw(i2c_handle);
        if (raw_value < 0) {
            // Error already logged in read_field_raw
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before retrying
            continue;
        }

        // Convert to milliTesla
        float field_mT = convert_to_mT(raw_value);

        // Check if threshold is exceeded
        int relay_state = (field_mT > FIELD_THRESHOLD) ? 1 : 0;

        // Control the relay
        control_relay(RELAY_GPIO, relay_state);

        // Log the event
        char event_message[100];
        sprintf(event_message, "Field: %.2f mT, Relay: %s", field_mT, relay_state ? "ON" : "OFF");
        log_event("INFO", event_message);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(RELAY_GPIO, 0); // Deactivate relay
    gpioTerminate();
    log_event("INFO", "System stopped");

    return 0;
}

