#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int handle_client(int client_socket);
void log_event(const char *event);
void signal_handler(int signum);

// Function to log events with timestamps
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Event: %s\n", event);
    }
}

// Function to handle client connections
int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        log_event("Error receiving data");
        close(client_socket);
        return -1;
    } else if (bytes_received == 0) {
        log_event("Client disconnected");
        close(client_socket);
        return 0;
    }

    buffer[bytes_received] = '\0'; // Null-terminate the received data

    // Remove trailing whitespace
    char *end = buffer + strlen(buffer) - 1;
    while (end > buffer && isspace((unsigned char)*end)) end--;
    end[1] = '\0';

    if (strcasecmp(buffer, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1); // Turn relay ON
        log_event("Relay turned ON");
        printf("Relay turned ON\n");
    } else if (strcasecmp(buffer, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0); // Turn relay OFF
        log_event("Relay turned OFF");
        printf("Relay turned OFF\n");
    } else {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Invalid command: %s", buffer);
        log_event(log_message);
        fprintf(stderr, "Invalid command: %s\n", buffer);
    }

    close(client_socket);
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        log_event("Received shutdown signal");

        // Close server socket
        if (server_fd != -1) {
            close(server_fd);
            log_event("Server socket closed");
        }

        // Turn off the relay
        gpioWrite(GPIO_PIN, 0);
        log_event("Relay turned OFF");

        // Terminate pigpio
        gpioTerminate();
        log_event("pigpio terminated");

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
            log_event("Log file closed");
        }

        program_running = 0;
        exit(0);
    }
}

int main() {
    int client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }
    log_event("Program started");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
