#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_SCALE 1.0/1500.0
#define FLOW_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c_device(int handle, char *data, int count);
int read_i2c_device(int handle, char *data, int count);
int crc8(const char *data, int len);
float convert_to_ml_min(int16_t raw_value);
void log_flow_data(float flow1, float flow2);
void deenergize_relay();
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
int crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to write to an I2C device
int write_i2c_device(int handle, char *data, int count) {
    int result = i2cWriteDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read from an I2C device
int read_i2c_device(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw value to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value * FLOW_SCALE;
}

// Function to log flow data to file
void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2);
    fflush(fp);
    fclose(fp);
}

// Function to de-energize the relay
void deenergize_relay() {
    gpioWrite(RELAY_GPIO, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    deenergize_relay();

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Configure relay GPIO as output and set initial state
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially de-energized

    // Start measurement command
    char start_cmd[] = {0x36, 0x08};
    if (write_i2c_device(i2c_handle1, start_cmd, 2) != 0 || write_i2c_device(i2c_handle2, start_cmd, 2) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data1[3], data2[3];
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2;

        // Read sensor 1 data
        if (read_i2c_device(i2c_handle1, data1, 3) == 0) {
            // CRC check
            if (crc8(data1, 2) == data1[2]) {
                raw_flow1 = (data1[0] << 8) | data1[1];
                flow1 = convert_to_ml_min(raw_flow1);
            } else {
                fprintf(stderr, "CRC mismatch for sensor 1\n");
                flow1 = -1.0; // Indicate error
            }
        } else {
            fprintf(stderr, "Failed to read sensor 1 data\n");
            flow1 = -1.0; // Indicate error
        }

        // Read sensor 2 data
        if (read_i2c_device(i2c_handle2, data2, 3) == 0) {
            // CRC check
            if (crc8(data2, 2) == data2[2]) {
                raw_flow2 = (data2[0] << 8) | data2[1];
                flow2 = convert_to_ml_min(raw_flow2);
            } else {
                fprintf(stderr, "CRC mismatch for sensor 2\n");
                flow2 = -1.0; // Indicate error
            }
        } else {
            fprintf(stderr, "Failed to read sensor 2 data\n");
            flow2 = -1.0; // Indicate error
        }

        // Log data if both sensors are valid
        if (flow1 >= 0 && flow2 >= 0) {
            log_flow_data(flow1, flow2);

            // Energize relay if both sensors are below threshold
            if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

