#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT1_PIN 23
#define MOTOR_INPUT2_PIN 24

// Define debounce interval (in milliseconds)
#define DEBOUNCE_INTERVAL 600

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void close_window();
void stop_motor();
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set rain sensor pin as input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Set motor control pins as output
    gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_INPUT1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_INPUT2_PIN, PI_OUTPUT);

    // Initialize motor pins to LOW
    gpioWrite(MOTOR_ENABLE_PIN, 0);
    gpioWrite(MOTOR_INPUT1_PIN, 0);
    gpioWrite(MOTOR_INPUT2_PIN, 0);

    syslog(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Closing window");

    // Set motor enable pin HIGH
    if (gpioWrite(MOTOR_ENABLE_PIN, 1) != 0) {
        syslog(LOG_WARNING, "Failed to set MOTOR_ENABLE_PIN HIGH");
    }

    // Set motor input pins HIGH and LOW to close the window
    if (gpioWrite(MOTOR_INPUT1_PIN, 1) != 0) {
        syslog(LOG_WARNING, "Failed to set MOTOR_INPUT1_PIN HIGH");
    }
    if (gpioWrite(MOTOR_INPUT2_PIN, 0) != 0) {
        syslog(LOG_WARNING, "Failed to set MOTOR_INPUT2_PIN LOW");
    }

    // Wait for 5 seconds
    gpioDelay(5000000); // 5 seconds = 5000000 microseconds

    // Stop the motor
    stop_motor();

    syslog(LOG_INFO, "Window closed");
}

// Function to stop the motor
void stop_motor() {
    syslog(LOG_INFO, "Stopping motor");

    // Set motor enable pin LOW
    if (gpioWrite(MOTOR_ENABLE_PIN, 0) != 0) {
        syslog(LOG_WARNING, "Failed to set MOTOR_ENABLE_PIN LOW");
    }

    // Set motor input pins LOW
    if (gpioWrite(MOTOR_INPUT1_PIN, 0) != 0) {
        syslog(LOG_WARNING, "Failed to set MOTOR_INPUT1_PIN LOW");
    }
    if (gpioWrite(MOTOR_INPUT2_PIN, 0) != 0) {
        syslog(LOG_WARNING, "Failed to set MOTOR_INPUT2_PIN LOW");
    }

    syslog(LOG_INFO, "Motor stopped");
}

// Function to cleanup GPIO and terminate pigpio
void cleanup() {
