#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            // Debounce
            gpioDelay(200000); // 200ms
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                printf("Lock button pressed. Locking door...\n");
                if (gpioServo(SERVO_PIN, 2000) != 0) {
                    fprintf(stderr, "Error setting lock position\n");
                }
                // Wait for button release
                while (gpioRead(LOCK_BUTTON_PIN) == 0 && !terminate) {
                    gpioDelay(10000); // 10ms
                }
                gpioDelay(200000); // Debounce
            }
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            // Debounce
            gpioDelay(200000); // 200ms
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                printf("Unlock button pressed. Unlocking door...\n");
                if (gpioServo(SERVO_PIN, 1000) != 0) {
                    fprintf(stderr, "Error setting unlock position\n");
                }
                // Wait for button release
                while (gpioRead(UNLOCK_BUTTON_PIN) == 0 && !terminate) {
                    gpioDelay(10000); // 10ms
                }
                gpioDelay(200000); // Debounce
            }
        }

        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

