#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_PIN 4
#define FLOODLIGHT_PIN 17

// Define log file path
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_floodlight();
void deactivate_floodlight();
void log_event(const char *event_type, const char *timestamp, double duration);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin mode\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Activate floodlight
void activate_floodlight() {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate floodlight\n");
        return;
    }
    printf("Floodlight activated\n");
}

// Deactivate floodlight
void deactivate_floodlight() {
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate floodlight\n");
        return;
    }
    printf("Floodlight deactivated\n");
}

// Log event to file
void log_event(const char *event_type, const char *timestamp, double duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s, %s, %.2f\n", event_type, timestamp, duration);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Smart Security Light running...\n");

    // Main loop
    while (program_running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log motion detection event
            log_event("Motion Detected", timestamp, 0.0);

            // Activate floodlight
            activate_floodlight();

            // Wait for 60 seconds
            gpioDelay(60000); // pigpio uses microseconds

            // Deactivate floodlight
            deactivate_floodlight();

            // Get deactivation timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log floodlight deactivation event
            log_event("Floodlight Deactivated", timestamp, 60.0);
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off floodlight
    deactivate_floodlight();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

