#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define ELECTRODE_TOUCH_STATUS_REG 0x00
#define ELECTRODE_TOGGLE_ELECTRODE 0
#define DEBOUNCE_TIME_MS 200

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error: MHD config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) {
        fprintf(stderr, "Error: NHD config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) {
        fprintf(stderr, "Error: NCL config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) {
        fprintf(stderr, "Error: FDL config failed\n");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x06) < 0) {
        fprintf(stderr, "Error: Debounce config failed\n");
        return -1;
    }

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x24) < 0) {
        fprintf(stderr, "Error: FFI/SFI/CDT config failed\n");
        return -1;
    }

    // Auto-config
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: Auto-config failed\n");
        return -1;
    }

    // Enable electrodes 0-11
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: Enable electrodes failed\n");
        return -1;
    }

    return 0;
}

// Read touch status function
int read_touch_status(int i2c_handle) {
    int touch_status = i2cReadWordData(i2c_handle, ELECTRODE_TOUCH_STATUS_REG);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Relay toggle function
void toggle_relay(int gpio_pin) {
    int current_level = gpioRead(gpio_pin);
    int new_level = (current_level == 0) ? 1 : 0;
    gpioWrite(gpio_pin, new_level);
    printf("Relay toggled to %d\n", new_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0; // 0 = not touched, 1 = touched
    unsigned long last_touch_time = 0;

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        int current_touch_state = (touch_status & (1 << ELECTRODE_TOGGLE_ELECTRODE)) ? 1 : 0;

        if (current_touch_state && !last_touch_state) {
            // Electrode 0 touched (rising edge)
            if (gpioTick() - last_touch_time > DEBOUNCE_TIME_MS * 1000) { // Debounce
                toggle_relay(RELAY_GPIO);
                last_touch_time = gpioTick();
            }
        }

        last_touch_state = current_touch_state;
