#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <pthread.h>
#include <stdarg.h>

// Constants
#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY) // microseconds
#define PWM_MIN_US 1000 // microseconds
#define PWM_MAX_US 2000 // microseconds
#define PORT 5000
#define BUFFER_SIZE 1024

// Global variables
static volatile int running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
void signal_handler(int signum);
int setup_gpio();
void cleanup_gpio();
void *pwm_thread(void *arg);
int handle_client(int client_socket);
int parse_command(const char *command, int *angle);
int read_pir_sensor();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Syslog
    vsyslog(priority, format, args);

    // File logging
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_INFO, "Received signal %d, shutting down...", signum);
        running = 0;
    }
}

// Setup GPIO
int setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line");
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// PWM thread function
void *pwm_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    struct gpiod_line *line = servo_line;
    int high_time_us = PWM_MIN_US;
    int low_time_us = PWM_PERIOD_US - PWM_MIN_US;

    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            log_message(LOG_ERR, "Failed to set servo line high");
            break;
        }
        usleep(high_time_us);

        if (gpiod_line_set_value(line, 0) < 0) {
            log_message(LOG_ERR, "Failed to set servo line low");
            break;
        }
        usleep(low_time_us);
    }

    pthread_exit(NULL);
}

// Handle client connection
int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data from client");
        return -1;
    } else if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
        return 0;
    }

    buffer[bytes_received] = '\0';
    log_message(LOG_INFO, "Received command: %s", buffer);

    int angle;
    if (parse_command(buffer, &angle) == 0) {
        // Servo command
        pthread_t pwm_thread_id;
        if (pthread_create(&pwm_thread_id, NULL, pwm_thread, NULL) != 0) {
            log_message(LOG_ERR, "Failed to create PWM thread");
            return -1;
        }
        pthread_detach(pwm_thread_id); // Detach the thread to automatically release resources when it finishes

        // PIR command
    } else if (strcmp(buffer, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        char response[32];
        snprintf(response, sizeof(response), "PIR:%d", pir_value);
        send(client_socket, response, strlen(response), 0);
        log_message(LOG_INFO, "Sent PIR response: %s", response);
    } else {
        log_message(LOG_WARNING, "Unknown command: %s", buffer);
        const char *error_message = "ERROR: Unknown command";
        send(client_socket, error_message, strlen(error_message), 0);
    }

    close(client_socket);
    return 0;
}

// Parse command
int parse_command(const char *command, int *angle) {
    if (strncmp(command, "SERVO ", 6) == 0) {
        if (sscanf(command + 6, "%d", angle) == 1) {
            if (*angle >= 0 && *angle <= 180) {
                return 0; // Success
            } else {
                log_message(LOG_WARNING, "Invalid servo angle: %d", *angle);
                return -1; // Invalid angle
            }
        } else {
            log_message(LOG_WARNING, "Invalid servo command format");
            return -1; // Invalid format
        }
    } else if (strcmp(command, "PIR") == 0) {
        return 0; // Success, PIR command
    } else {
        return -1; // Unknown command
    }
}

// Read PIR sensor
int read_pir_sensor() {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value");
        return 0; // Return 0 on error
    }
    return value;
}

int main() {
    // Initialize syslog
    openlog("security_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file");
        closelog();
        return 1;
    }

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        fclose(log_file);
        closelog();
        return 1;
    }

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message(LOG_ERR, "Failed to create socket");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        log_message(LOG_ERR, "Failed to bind socket");
        cleanup_gpio();
        close(socket_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 5) < 0) {
        log_message(LOG_ERR, "Failed to listen on socket");
        cleanup_gpio();
        close(socket_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d", PORT);

    // Main loop
    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(socket_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            log_message(LOG_ERR, "Failed to accept connection");
            continue; // Continue listening
        }

        log_message(LOG_INFO, "Accepted connection from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_socket);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    close(socket_fd);
    cleanup_gpio();
    fclose(log_file);
    closelog();

    return 0;
}

