#include <time.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int tare_offset = 0;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(int state);
void tare();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DOUT to go LOW (data ready)
    int timeout = 0;
    while (gpioRead(HX711_DOUT) == 1 && timeout < 1000000) {
        gpioDelay(1); // 1 us delay
        timeout++;
    }

    if (timeout >= 1000000) {
        log_message(LOG_ERR, "HX711 timeout waiting for data");
        return 0; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Send one more clock pulse to select Channel A, Gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Weight calculation function
double calculate_weight(int raw_value) {
    return (raw_value - tare_offset) / scale;
}

// Solenoid control function
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Tare function
void tare() {
    int i;
    int sum = 0;
    for (i = 0; i < 10; i++) {
        sum += read_hx711();
        gpioDelay(10); // Small delay between readings
    }
    tare_offset = sum / 10;
    char message[100];
    snprintf(message, sizeof(message), "Tare offset: %d", tare_offset);
    log_message(LOG_INFO, message);
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Logging function
void log_message(int priority, const char *message) {
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare();

    // Main loop
    while (running) {
        int i;
        int sum = 0;
        for (i = 0; i < 5; i++) {
            sum += read_hx711();
            gpioDelay(10); // Small delay between readings
        }
        int raw_value = sum / 5;
        double weight = calculate_weight(raw_value);

        char message[100];
        snprintf(message, sizeof(message), "Weight: %.2f grams", weight);
        log_message(LOG_INFO, message);

        if (weight > threshold) {
            control_solenoid(1); // Activate solenoid
            gpioDelay(duration);   // Keep activated for specified duration
            control_solenoid(0); // Deactivate solenoid
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog

    return 0;
}

