#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

struct mosquitto *mosq = NULL;

void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    exit(0);
}

void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            syslog(LOG_INFO, "Relay ON (GPIO %d HIGH)", GPIO_PIN);
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            syslog(LOG_INFO, "Relay OFF (GPIO %d LOW)", GPIO_PIN);
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Subscribe error: %s", mosquitto_strerror(subscribe_result));
        }
    } else {
        syslog(LOG_ERR, "Connection error: %s", mosquitto_connack_string(result));
    }
}

void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with code %d", rc);
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Out of memory");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Connection error: %s", mosquitto_strerror(connect_result));
        mosquitto_destroy(mosq);
        mosq = NULL;
    }

    while (1) {
        int rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            if (mosq) {
                mosquitto_disconnect(mosq);
                mosquitto_destroy(mosq);
                mosq = NULL;
            }
            sleep(5);
            mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
            if (!mosq) {
                syslog(LOG_ERR, "Out of memory");
                break;
            }
            mosquitto_connect_callback_set(mosq, connect_callback);
            mosquitto_disconnect_callback_set(mosq, disconnect_callback);
            mosquitto_message_callback_set(mosq, message_callback);
            connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
            if (connect_result != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Reconnection error: %s", mosquitto_strerror(connect_result));
                mosquitto_destroy(mosq);
                mosq = NULL;
            }
        }
    }

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return 0;
}

