#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

// Motor B
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

// Encoder A
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

// Encoder B
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

// Target speed (RPM)
#define TARGET_SPEED 50

// PI controller parameters
#define Kp 0.5
#define Ki 0.05
#define CONTROL_PERIOD_MS 100

// Stall detection parameters
#define STALL_THRESHOLD 0.0
#define STALL_TIME_SEC 2.0

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int running = 1;

// PI controller state
double integral_a = 0.0;
double last_error_a = 0.0;
double integral_b = 0.0;
double last_error_b = 0.0;

// Function prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
void set_motor_speed(int motor, double speed);
double calculate_pi_output(double target, double current, double *integral, double *last_error);
void stall_detection(int encoder_count);
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    if (gpio == ENCODER_A_A_PIN) {
        if (gpioRead(ENCODER_A_B_PIN) == 0) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    } else if (gpio == ENCODER_A_B_PIN) {
        if (gpioRead(ENCODER_A_A_PIN) == 0) {
            encoder_a_count--;
        } else {
            encoder_a_count++;
        }
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    if (gpio == ENCODER_B_A_PIN) {
        if (gpioRead(ENCODER_B_B_PIN) == 0) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    } else if (gpio == ENCODER_B_B_PIN) {
        if (gpioRead(ENCODER_B_A_PIN) == 0) {
            encoder_b_count--;
        } else {
            encoder_b_count++;
        }
    }
}

// Set motor speed (PWM and direction)
void set_motor_speed(int motor, double speed) {
    int pwm_pin, dir_pin;

    if (motor == 0) { // Motor A
        pwm_pin = MOTOR_A_PWM_PIN;
        dir_pin = MOTOR_A_DIR_PIN;
    } else { // Motor B
        pwm_pin = MOTOR_B_PWM_PIN;
        dir_pin = MOTOR_B_DIR_PIN;
    }

    if (speed >= 0) {
        gpioWrite(dir_pin, 1); // Forward
        gpioPWM(pwm_pin, (int)(speed * 255.0 / 100.0));
    } else {
        gpioWrite(dir_pin, 0); // Reverse
        gpioPWM(pwm_pin, (int)(-speed * 255.0 / 100.0));
    }
}

// Calculate PI output
double calculate_pi_output(double target, double current, double *integral, double *last_error) {
    double error = target - current;
    *integral += error;
    double output = Kp * error + Ki * (*integral);
    *last_error = error;
    return output;
}

// Stall detection
void stall_detection(int encoder_count) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (encoder_count == 0) {
        if (last_tick != 0 && (current_tick - last_tick) / 1000000.0 > STALL_TIME_SEC) {
            fprintf(stderr, "Warning: Motor stall detected!\n");
        }
        last_tick = current_tick;
    } else {
        last_tick = 0; // Reset stall timer
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Stopping motors and exiting...\n");
    running = 0;
    set_motor_speed(0, 0); // Stop Motor A
    set_motor_speed(1, 0); // Stop Motor B
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_A_B_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_B_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM_PIN, 10000);
    gpioSetPWMfrequency(MOTOR_B_PWM_PIN, 10000);

    // Register ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Calculate desired speed for each motor
        double desired_speed_a = TARGET_SPEED;
        double desired_speed_b = TARGET_SPEED;

        // Calculate PI output for each motor
        double output_a = calculate_pi_output(desired_speed_a, 0, &integral_a, &last_error_a);
        double output_b = calculate_pi_output(desired_speed_b, 0, &integral_b, &last_error_b);

        // Set motor speeds
        set_motor_speed(0, output_a);
        set_motor_speed(1, output_b);

        // Stall detection
        stall_detection(encoder_a_count);
        stall_detection(encoder_b_count);

        // Print motor RPM and PWM duty cycle (for debugging)
        //printf("Motor A: RPM = %.2f, PWM = %d\n", output_a, gpioGetPWMdutycycle(MOTOR_A_PWM_PIN));
        //printf("Motor B: RPM = %.2f, PWM = %d\n", output_b, gpioGetPWMdutycycle(MOTOR_B_PWM_PIN));

        // Wait for the control period
        gpioDelay(CONTROL_PERIOD_MS * 1000); // pigpioDelay takes microseconds
    }

    // Stop motors and terminate pigpio
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
    gpioTerminate();

    return 0;
}

