#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define RELAY_GPIO 17
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define DUSK_THRESHOLD 50.0
#define DAWN_THRESHOLD 200.0
#define HYSTERESIS_ON 10.0
#define HYSTERESIS_OFF 20.0
#define POLL_INTERVAL 5 // seconds
#define READ_DELAY 180 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750();
void control_relay(float lux);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
float read_bh1750() {
    char buf[2];
    int result;
    float lux = -1.0; // Default to error value

    // Send One-Time High-Resolution Mode 2 command (0x21)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x21); // No register address needed for mode
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        log_data(-1.0, -1); // Log error
        return -1.0;
    }

    // Wait for the sensor to be ready
    gpioDelay(READ_DELAY);

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2); // No register address needed for reading
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        log_data(-1.0, -1); // Log error
        return -1.0;
    }

    // Convert raw data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    lux = (float)raw_value / 1.2;

    return lux;
}

// Function to control the relay based on lux value
void control_relay(float lux) {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    static float last_lux = 0.0;

    if (lux < 0) {
        // Sensor error, turn off relay
        if (relay_state == 1) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_data(-1.0, 0); // Log relay state
        }
        return;
    }

    if (lux < DUSK_THRESHOLD && lux > last_lux - HYSTERESIS_ON) {
        // Dusk, turn on relay
        if (relay_state == 0) {
            gpioWrite(RELAY_GPIO, 1);
            relay_state = 1;
            log_data(lux, 1); // Log relay state
        }
    } else if (lux > DAWN_THRESHOLD && lux < last_lux + HYSTERESIS_OFF) {
        // Dawn, turn off relay
        if (relay_state == 1) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_data(lux, 0); // Log relay state
        }
    }

    last_lux = lux;
}

// Function to log data to file
