void control_relay(float lux) {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    static float last_lux = 0.0;

    if (lux < 0) {
        // Sensor error, turn off relay
        if (relay_state == 1) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_data(-1.0, 0); // Log relay state
        }
        return;
    }

    if (lux < DUSK_THRESHOLD && lux > last_lux - HYSTERESIS_ON) {
        // Dusk, turn on relay
        if (relay_state == 0) {
            gpioWrite(RELAY_GPIO, 1);
            relay_state = 1;
            log_data(lux, 1); // Log relay state
        }
    } else if (lux > DAWN_THRESHOLD && lux < last_lux + HYSTERESIS_OFF) {
