#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int relay_state = 0; // 0 = OFF, 1 = ON
    int touch_value;
    struct timespec ts;
    char timestamp[30];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        touch_value = gpioRead(TOUCH_PIN);

        if (touch_value == 1) {
            // Debounce and toggle relay
            gpioDelay(50000); // 50 ms
            if (gpioRead(TOUCH_PIN) == 1) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);

                // Get timestamp
                clock_gettime(CLOCK_REALTIME, &ts);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));

                // Log relay state change
                printf("%s Relay is now %s\n", timestamp, relay_state ? "ON" : "OFF");
            }
            // Wait for touch release
            while (gpioRead(TOUCH_PIN) == 1 && program_running) {
                gpioDelay(10000); // 10 ms
            }
        }
        gpioDelay(10000); // Reduce CPU usage
    }

    // Turn off relay on exit
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

