#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYS_THRESHOLD 0.5
#define DEBOUNCE_TIMEOUT 1000 // microseconds
#define LOG_FILE "water_flow.log"

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
void *monitoring_thread(void *arg);
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// ISR for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Monitoring thread function
void *monitoring_thread(void *arg) {
    (void)arg; // unused
    double lpm;
    int solenoid_state = 1; // 1 = open, 0 = closed
    int solenoid_target_state = 1; // Initial target state

    while (!terminate) {
        pthread_mutex_lock(&pulse_mutex);
        lpm = (double)pulse_count / PULSES_PER_LITER * 60.0;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        if (solenoid_target_state == 1 && lpm > LPM_THRESHOLD_HIGH) {
            solenoid_target_state = 0; // Close solenoid
        } else if (solenoid_target_state == 0 && lpm < LPM_THRESHOLD_LOW) {
            solenoid_target_state = 1; // Open solenoid
        }

        if (solenoid_state != solenoid_target_state) {
            gpioWrite(SOLENOID_GPIO, solenoid_target_state);
            solenoid_state = solenoid_target_state;
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Solenoid state changed to %s", solenoid_state ? "OPEN" : "CLOSED");
            log_message(log_message_buffer);
        }

        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "LPM: %.2f", lpm);
        log_message(log_message_buffer);

        gpioDelay(1000); // Check every 1 second
    }

    return NULL;
}

// Logging function
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(log_file);
    }
}

// Signal handler
void signal_handler(int signal) {
    char log_message_buffer[50];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Signal received: %d", signal);
    log_message(log_message_buffer);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(SOLENOID_GPIO, 1); // Ensure solenoid is open on exit
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    log_message("Cleanup complete.");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set FLOW_SENSOR_GPIO mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SOLENOID_GPIO mode\n");
        cleanup();
        return 1;
    }

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_GPIO, 1);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for FLOW_SENSOR_GPIO\n");
        cleanup();
        return 1;
    }

    // Create monitoring thread
    pthread_t monitoring_thread_id;
    if (pthread_create(&monitoring_thread_id, NULL, monitoring_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create monitoring thread\n");
        cleanup();
        return 1;
    }

    // Wait for termination signal
    pthread_join(monitoring_thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

