#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24
#define SERVO_PIN 18
#define SERVER_PORT 12345
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SERVO_PULSE_WIDTH 1500 // µs
#define TIMEOUT_ATTEMPTS 1000
#define TIMEOUT_DELAY_US 1000 // 1ms

// Global variables
static volatile int running = 1;
static int server_socket = -1;
static FILE *log_file = NULL;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = SERVER_PORT;
static int servo_pulse_width = DEFAULT_SERVO_PULSE_WIDTH;

// Function prototypes
int read_config();
int init_gpio();
int init_socket();
void handle_client(int client_socket);
int read_hx711();
double calibrate_weight(int raw_value);
int set_servo_pulse_width(int pulse_width);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config() {
    FILE *fp = fopen("config.ini", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config.ini, using default values.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *name = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (name == NULL || value == NULL) continue;

        if (strcmp(name, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(name, "server_ip") == 0) {
            strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
            server_ip[INET_ADDRSTRLEN - 1] = '\0';
        } else if (strcmp(name, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(name, "servo_pulse_width") == 0) {
            servo_pulse_width = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

