#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17

volatile sig_atomic_t program_running = 1;
int debounce_delay_ms = 50;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

void relay_on() {
    gpioWrite(RELAY_PIN, 1);
    printf("%s Relay: ON\n", __TIME__);
}

void relay_off() {
    gpioWrite(RELAY_PIN, 0);
    printf("%s Relay: OFF\n", __TIME__);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        debounce_delay_ms = atoi(argv[1]);
        if (debounce_delay_ms <= 0) {
            fprintf(stderr, "Invalid debounce delay. Using default 50ms.\n");
            debounce_delay_ms = 50;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0;
    int current_touch_state = 0;
    int relay_state = 0; // 0 = OFF, 1 = ON

    relay_off(); // Ensure relay is off at startup

    while (program_running) {
        current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            gpioDelay(debounce_delay_ms * 1000); // Debounce
            current_touch_state = gpioRead(TOUCH_PIN); // Re-read after debounce

            if (current_touch_state == 1) {
                // Stable HIGH after debounce
                if (relay_state == 0) {
                    relay_on();
                    relay_state = 1;
                } else {
                    relay_off();
                    relay_state = 0;
                }
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(1000); // Check every 1ms
    }

    relay_off(); // Ensure relay is off before exiting
    gpioTerminate();
    return 0;
}

