void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl-C pressed. Exiting gracefully.\n");
        running = 0;
    }
}

void restore_terminal() {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}

int main() {
    int angle = 90; // Initial angle
    int pulse_width_us;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency to 50 Hz (20 ms period)
    gpioSetPWMfrequency(GPIO_PIN, 50);

    // Set PWM range (resolution)
    gpioSetPWMrange(GPIO_PIN, 20000); // 20 ms period

    // Set initial pulse width (center position)
    pulse_width_us = SERVO_CENTER_US;
    gpioServo(GPIO_PIN, pulse_width_us);
    printf("Initial angle: %d\n", angle);

    // Save original terminal settings
    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
        perror("tcgetattr");
        gpioServo(GPIO_PIN, 0); // Stop PWM
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Set terminal to raw mode
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) == -1) {
        perror("tcsetattr");
        gpioServo(GPIO_PIN, 0); // Stop PWM
        gpioTerminate(); // Terminate pigpio
        restore_terminal();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int c = getchar();

        if (c == '+') {
            angle += 10;
            if (angle > 180) angle = 180;
        } else if (c == '-') {
            angle -= 10;
            if (angle < 0) angle = 0;
        } else if (c == 'q') {
            running = 0;
        } else {
            continue; // Ignore other characters
        }

        // Calculate pulse width in microseconds
        pulse_width_us = SERVO_MIN_US + (int)(((float)angle / SERVO_RANGE_DEGREES) * SERVO_RANGE_US);

        // Validate pulse width
        if (pulse_width_us < SERVO_MIN_US) pulse_width_us = SERVO_MIN_US;
        if (pulse_width_us > SERVO_MAX_US) pulse_width_us = SERVO_MAX_US;

        // Set servo pulse width
        ret = gpioServo(GPIO_PIN, pulse_width_us);
        if (ret != 0) {
            fprintf(stderr, "Error setting servo pulse width: %d\n", ret);
        }

        printf("Angle: %d\n", angle);
    }

    // Stop PWM and terminate pigpio
    gpioServo(GPIO_PIN, 0);
    gpioTerminate();

    // Restore terminal settings
    restore_terminal();

    return 0;
}

