#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int pulse_count = 0;
static struct timespec last_pulse_time = {0, 0};

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

double calculate_rpm(int pulse_count, double elapsed_time) {
    return (pulse_count / elapsed_time) * 60.0;
}

int main() {
    struct gpiod_line_event event;
    struct timespec current_time, last_sample_time;
    double rpm;
    int ret;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line as input with pull-up
    ret = gpiod_line_request_input_flags(line, "motor_rpm", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    clock_gettime(CLOCK_MONOTONIC, &last_sample_time);
    while (!terminate) {
        ret = gpiod_line_event_wait(line, &event, -1); // Wait indefinitely
        if (ret < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Debounce
            if (current_time.tv_sec - last_pulse_time.tv_sec < 0 ||
                (current_time.tv_sec - last_pulse_time.tv_sec == 0 && current_time.tv_nsec - last_pulse_time.tv_nsec < DEBOUNCE_MS * 1000000)) {
                continue; // Ignore pulse
            }

            pulse_count++;
            last_pulse_time = current_time;

            // Calculate RPM every SAMPLE_INTERVAL_SEC
            if (current_time.tv_sec - last_sample_time.tv_sec >= SAMPLE_INTERVAL_SEC) {
                double elapsed_time = (current_time.tv_sec - last_sample_time.tv_sec) + (current_time.tv_nsec - last_sample_time.tv_nsec) / 1000000000.0;
                rpm = calculate_rpm(pulse_count, elapsed_time);

                // Log RPM to file
                fprintf(log_file, "%ld.%09ld,%.2f\n", current_time.tv_sec, current_time.tv_nsec, rpm);
                fflush(log_file);

                // Print RPM to stdout
                printf("RPM: %.2f\n", rpm);

                // Reset pulse count and last sample time
                pulse_count = 0;
                last_sample_time = current_time;
            }
        }
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

