#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define FAILSAFE_TIMEOUT 10 // seconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int relay_state = 0; // 0 = OFF, 1 = ON
    int touch_count = 0;
    time_t touch_start_time = 0;
    int pigpio_init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int touch_value = gpioRead(TOUCH_PIN);

        if (touch_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading TOUCH_PIN\n");
            break; // Exit loop on error
        }

        if (touch_value == 1) {
            touch_count++;
            if (touch_start_time == 0) {
                touch_start_time = time(NULL);
            }
            if (touch_count > 20) { // Debounce: 20 * 50ms = 1 second
                if (relay_state == 0) {
                    relay_state = 1;
                    gpioWrite(RELAY_PIN, 1);
                    printf("Relay ON\n");
                } else {
                    relay_state = 0;
                    gpioWrite(RELAY_PIN, 0);
                    printf("Relay OFF\n");
                }
                touch_count = 0;
                touch_start_time = 0; // Reset for next touch
            }
        } else {
            touch_count = 0;
            touch_start_time = 0;
        }

        if (relay_state == 1 && touch_value == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, touch_start_time) > FAILSAFE_TIMEOUT) {
                relay_state = 0;
                gpioWrite(RELAY_PIN, 0);
                printf("Failsafe triggered! Relay OFF\n");
                touch_start_time = 0; // Reset failsafe
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

