}

// Function to log data to file
void log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", VALVE_GPIO);
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", VALVE_ENABLE_GPIO);
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", FLOW_SENSOR_GPIO);
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        return 1;
    }

    // Enable valve
    gpioWrite(VALVE_ENABLE_GPIO, 1);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register interrupt handler for GPIO %d\n", FLOW_SENSOR_GPIO);
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable valve
    gpioWrite(VALVE_ENABLE_GPIO, 0);

    // Set PWM to 0
    gpioPWM(VALVE_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX) {
                    fprintf(stderr, "Error: Target flow rate must be between %.2f and %.2f L/min\n", TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return 1;
        }
    }

    if (target_flow_rate == 0.0) {
        fprintf(stderr, "Error: Target flow rate is required. Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int last_pulse_count = 0;
    while (running) {
        // Sample flow rate
        int current_pulse_count = pulse_count;
        int pulses_in_interval = current_pulse_count - last_pulse_count;
        double flow_rate = calculate_flow_rate(pulses_in_interval);
        last_pulse_count = current_pulse_count;

        // Set valve position
        int valve_position = set_valve_position(flow_rate);

        // Log data
        log_data(flow_rate, valve_position);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

