// Function prototypes
int authenticate();
void lock_doors();
void unlock_doors();
void log_event(const char *message);
void signal_handler(int signal);
int read_rfid_tag(unsigned char *tag_data);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to authenticate the user
int authenticate() {
    unsigned char tag_data[10];
    int button_state;
    int i;

    // Read RFID tag
    if (read_rfid_tag(tag_data) != 0) {
        log_event("RFID read failure");
        return 0; // Authentication failed
    }

    // Check if tag is valid
    for (i = 0; i < 10; i++) {
        if (tag_data[i] != VALID_TAG[i]) {
            log_event("Invalid RFID tag");
            return 0; // Authentication failed
        }
    }

    // Check if button is pressed
    button_state = gpioRead(BUTTON_PIN);
    if (button_state == 0) { // Button is pressed (active-low)
        gpioDelay(50000); // Debounce for 50ms
        if (gpioRead(BUTTON_PIN) == 0) { // Still pressed after debounce
            log_event("Button press successful");
            return 1; // Authentication successful
        }
    }

    log_event("Button press failed");
    return 0; // Authentication failed
}

