    char tx_buffer[10] = {0}; // Transmit buffer (dummy data)
    char rx_buffer[10];       // Receive buffer

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 10);

    if (result == 10) {
        memcpy(tag_data, rx_buffer, 10);
        return 0; // Success
    } else {
        log_event("SPI transfer error");
        return -1; // Failure
    }
}

