#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Sample Time (ms)
#define SAMPLE_TIME 100

// Encoder Counts
volatile int encoder1_counts = 0;
volatile int encoder2_counts = 0;

// Mutexes for encoder counts
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void *encoder_monitor_thread(void *arg);
void signal_handler(int signal);
void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double p2, double i2, double d2, double output1, double output2);
void set_motor_speed(int motor, double speed);

// Encoder callback function
void encoder_callback(int gpio, int level, uint32_t tick, void *user)
{
    int encoder_number = (int)(intptr_t)user;
    int a_value, b_value;
    int direction;

    if (encoder_number == 1) {
        a_value = gpioRead(ENCODER1_A);
        b_value = gpioRead(ENCODER1_B);
    } else {
        a_value = gpioRead(ENCODER2_A);
        b_value = gpioRead(ENCODER2_B);
    }

    if (a_value == b_value) {
        direction = 1; // Clockwise
    } else {
        direction = -1; // Counter-clockwise
    }

    pthread_mutex_lock(&encoder1_mutex);
    if (encoder_number == 1) {
        encoder1_counts += direction;
    } else {
        encoder2_counts += direction;
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENA, 255);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,RPM1,RPM2,PID1_P,PID1_I,PID1_D,PID2_P,PID2_I,PID2_D,PID_Output1,PID_Output2\n");
    }

    // Create encoder monitoring thread
    pthread_t encoder_thread;
    if (pthread_create(&encoder_thread, NULL, encoder_monitor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder monitoring thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double integral1 = 0.0;
    double previous_error1 = 0.0;
    double derivative1 = 0.0;

    double integral2 = 0.0;
    double previous_error2 = 0.0;
    double derivative2 = 0.0;

    // Main control loop
    while (1) {
        // Calculate RPMs
        double rpm1, rpm2;
        pthread_mutex_lock(&encoder1_mutex);
        rpm1 = (double)encoder1_counts * 60.0 / 600.0; // Assuming 600 pulses per revolution
        encoder1_counts = 0; // Reset counts after reading
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        rpm2 = (double)encoder2_counts * 60.0 / 600.0; // Assuming 600 pulses per revolution
        encoder2_counts = 0; // Reset counts after reading
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate errors
        double error1 = TARGET_RPM1 - rpm1;
        double error2 = TARGET_RPM2 - rpm2;

        // Calculate PID components
        integral1 += error1;
        derivative1 = error1 - previous_error1;
        double p1 = KP * error1;
        double i1 = KI * integral1;
        double d1 = KD * derivative1;

        integral2 += error2;
        derivative2 = error2 - previous_error2;
        double p2 = KP * error2;
        double i2 = KI * integral2;
        double d2 = KD * derivative2;

        // Calculate PID output
        double output1 = p1 + i1 + d1;
        double output2 = p2 + i2 + d2;

        // Limit output to 0-255
        if (output1 > 255) output1 = 255;
        if (output1 < 0) output1 = 0;
        if (output2 > 255) output2 = 255;
        if (output2 < 0) output2 = 0;

        // Set motor speeds
        set_motor_speed(1, output1);
        set_motor_speed(2, output2);

        // Log data
        log_data(rpm1, rpm2, p1, i1, d1, p2, i2, d2, output1, output2);

        // Update previous errors
        previous_error1 = error1;
        previous_error2 = error2;

        // Sleep for sample time
        gpioDelay(SAMPLE_TIME * 1000); // Convert ms to us
    }

    return 0;
}

void *encoder_monitor_thread(void *arg)
{
    // Set up edge events for encoder A pins
    if (gpioSetAlertFuncEx(ENCODER1_A, encoder_callback, (void*)(intptr_t)1) != 0) {
        fprintf(stderr, "Failed to set alert function for encoder 1 A\n");
        pthread_exit(NULL);
    }
    if (gpioSetAlertFuncEx(ENCODER2_A, encoder_callback, (void*)(intptr_t)2) != 0) {
        fprintf(stderr, "Failed to set alert function for encoder 2 A\n");
        pthread_exit(NULL);
    }

    // Set up edge events for encoder B pins
    if (gpioSetAlertFuncEx(ENCODER1_B, encoder_callback, (void*)(intptr_t)1) != 0) {
        fprintf(stderr, "Failed to set alert function for encoder 1 B\n");
        pthread_exit(NULL);
    }
    if (gpioSetAlertFuncEx(ENCODER2_B, encoder_callback, (void*)(intptr_t)2) != 0) {
        fprintf(stderr, "Failed to set alert function for encoder 2 B\n");
        pthread_exit(NULL);
    }

    pthread_exit(NULL);
}

void signal_handler(int signal)
{
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);

    // Stop motors
    gpioWrite(MOTOR1_ENA, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_ENB, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Release GPIO lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double p2, double i2, double d2, double output1, double output2)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, rpm1, rpm2, p1, i1, d1, p2, i2, d2, output1, output2);
    fflush(log_file);
}

void set_motor_speed(int motor, double speed)
{
    int ena_pin, in1_pin, in2_pin;

    if (motor == 1) {
        ena_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else {
        ena_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    }

    // Set direction (clockwise or counter-clockwise)
    if (speed > 0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
    } else if (speed < 0) {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
        speed = -speed; // Make speed positive for PWM
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
    }

    // Set PWM duty cycle
    gpioPWM(ena_pin, (int)speed);
}

