#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x30
#define RELEASE_THRESHOLD 0x10
#define LOG_FILE "relay_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(unsigned short *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering (example values)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { //MHDR register
        fprintf(stderr, "Error: Failed to write to MHDR register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { //NHDR register
        fprintf(stderr, "Error: Failed to write to NHDR register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { //NCLR register
        fprintf(stderr, "Error: Failed to write to NCLR register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { //FDLR register
        fprintf(stderr, "Error: Failed to write to FDLR register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2F, 0x00) < 0) { //FCLR register
        fprintf(stderr, "Error: Failed to write to FCLR register\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to write to ELEPROX_EN register\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(unsigned short *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log relay state changes
void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d Relay state: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Initially turn off the relay

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned short touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                if (!relay_state) {
                    control_relay(1);
                    log_relay_state(1);
                    relay_state = 1;
                }
            } else {
                if (relay_state) {
                    control_relay(0);
                    log_relay_state(0);
                    relay_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status in main loop\n");
        }
        gpioDelay(50); // Poll every 50 ms
    }

    // Clean up
    control_relay(0); // Turn off relay on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

