#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the solenoid valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define pause durations (in milliseconds)
#define PAUSE1_DURATION 5000
#define PAUSE2_DURATION 10000

// Global variables for GPIO chip and lines
struct gpiod_chip *gpio_chip;
struct gpiod_line *valve1_line;
struct gpiod_line *valve2_line;

// Global variable for the log file
FILE *log_file;

// Function prototypes
int initialize_gpio(void);
int activate_valve(int valve_number);
int deactivate_valve(int valve_number);
int log_event(int valve_number, int duration_ms);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO chip and lines
int initialize_gpio(void) {
    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for Valve 1
    valve1_line = gpiod_chip_get_line(gpio_chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting Valve 1 GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get the GPIO line for Valve 2
    valve2_line = gpiod_chip_get_line(gpio_chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting Valve 2 GPIO line");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request the GPIO line for Valve 1 as output
    if (gpiod_line_request_output(valve1_line, "greenhouse", 0) < 0) {
        perror("Error requesting Valve 1 GPIO line as output");
        gpiod_line_release(valve2_line);
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request the GPIO line for Valve 2 as output
    if (gpiod_line_request_output(valve2_line, "greenhouse", 0) < 0) {
        perror("Error requesting Valve 2 GPIO line as output");
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to activate a valve
