#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_SECONDS 2
#define POLL_INTERVAL_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int log_event(const char *event) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + 19, 11, ".%03ld", ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

void unlock_door() {
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate relay.\n");
        log_event("Error: Failed to activate relay");
        return;
    }
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay in microseconds
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate relay.\n");
        log_event("Error: Failed to deactivate relay");
    }
    log_event("Door locked");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    log_event("System started");

    int last_state = 0; // Assume initially no motion
    unsigned long last_motion_time = 0;

    while (running) {
        int current_state = gpioRead(PIR_GPIO);

        if (current_state == 1 && last_state == 0) {
            // Rising edge detected
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            unsigned long now_ms = (now.tv_sec * 1000) + (now.tv_nsec / 1000000);

            if (now_ms - last_unlock_time > RATE_LIMIT_SECONDS * 1000) {
                unlock_door();
                last_unlock_time = now_ms;
            } else {
                log_event("Motion detected, rate-limited");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    log_event("System shutting down");

    fclose(log_file);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off before exiting
    gpioTerminate();

    return 0;
}

