#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define NUM_CALIBRATION_READINGS 100
#define TIMEOUT_US 500000 // 0.5 seconds in microseconds
#define WEIGHT_THRESHOLD 10.0 // kg

// Global variables
double scale_factor = 1.0;
double offset = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(double weight);
void log_weight(double weight);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 read timeout\n");
        return 0; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Apply the 25th clock pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Weight conversion function
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Solenoid control function
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage the solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Release the solenoid
    }
}

// Logging function
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen("calibration.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: calibration.txt not found or cannot be opened. Using default values.\n");
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data in calibration.txt. Using default values.\n");
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen("calibration.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt for writing.\n");
        return;
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Release solenoid on exit
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Initialize solenoid to unlocked state

    // Load calibration data
    load_calibration_data();

    // Perform one-time calibration
    if (scale_factor == 1.0 && offset == 0.0) {
        printf("Starting one-time calibration...\n");
        double sum = 0.0;
        for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
            sum += read_hx711();
            gpioDelay(1); // Small delay between readings
        }
        offset = sum / NUM_CALIBRATION_READINGS;
        printf("Calculated offset: %.2f\n", offset);

        // Adjust scale factor (example: 1000g = 1000 raw units)
        // You'll need to calibrate this based on your specific setup
        scale_factor = 1000.0 / (read_hx711() - offset); // Example: 1000g = 1000 raw units
        printf("Calculated scale factor: %.2f\n", scale_factor);

        // Save calibration data
        save_calibration_data();
    }

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open weight_log.txt for writing.\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int raw_value = read_hx711();
        if (raw_value != 0) {
            double weight = convert_to_weight(raw_value);
            control_solenoid(weight);
            log_weight(weight);
            printf("Weight: %.2f kg\n", weight);
        } else {
            fprintf(stderr, "Error: Failed to read HX711 value. Skipping iteration.\n");
        }
        gpioDelay(500); // Read every 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Release solenoid on exit
    gpioTerminate(); // Terminate pigpio
    fclose(log_file);

    return 0;
}

