#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define RAIN_THRESHOLD 3
#define MOTOR_DURATION_SEC 5
#define CHECK_INTERVAL_SEC 60
#define WAIT_AFTER_CLOSE_SEC 60

// Global variables
static volatile int running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int rain_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            rain_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (rain_count >= RAIN_THRESHOLD);
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 150); // 1000 Hz, 150/255 duty cycle
    gpioDelay(MOTOR_DURATION_SEC * 1000000); // Convert seconds to microseconds
    stop_motor();
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, stopping...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started.");

    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected, closing window.");
            close_window();
            gpioDelay(WAIT_AFTER_CLOSE_SEC * 1000000); // Wait before next check
        } else {
            gpioDelay(CHECK_INTERVAL_SEC * 1000000); // Check every minute
        }
    }

    // Cleanup (should not reach here if signal handler works)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

