#include <unistd.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Calibration factor (adjust this based on your load cell setup)
#define CALIBRATION_FACTOR 100.0

// Threshold weight in grams
#define WEIGHT_THRESHOLD 100.0

// Solenoid activation duration in seconds
#define SOLENOID_DURATION 5

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
long read_hx711();
double convert_to_weight(long raw_value);
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read raw data from HX711
long read_hx711() {
    long value = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low (data ready)
    int timeout = 0;
    while (gpioRead(HX711_DT) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
        if (timeout >= 1000) {
            log_event("HX711 timeout error: DT stuck high.");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        value = value << 1;
        if (gpioRead(HX711_DT)) {
            value++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Apply the 25th clock pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to convert raw value to weight in grams
double convert_to_weight(long raw_value) {
    return (double)raw_value / CALIBRATION_FACTOR;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid (HIGH)
    log_event("Solenoid activated.");
    gpioDelay(SOLENOID_DURATION * 1000); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid (LOW)
    log_event("Solenoid deactivated.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Kitchen Inventory Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        long raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error reading HX711, skipping this iteration.");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        double weight = convert_to_weight(raw_value);
        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold, activating solenoid.");
            activate_solenoid();
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

