#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Security log file name
#define SECURITY_LOG_FILE "security.log"

// Global variables
double calibration_factor = 1.0; // Default calibration factor
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_hx711();
double calibrate_load_cell(double known_weight);
double get_weight();
void control_solenoid(int state);
void log_event(double weight);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Attempt to read calibration factor from file
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file. Using default.\n");
            calibration_factor = 1.0;
        }
        fclose(fp);
    } else {
        fprintf(stderr, "Calibration file not found. Calibration required.\n");
        // Calibrate the load cell
        double known_weight;
        printf("Enter known weight in kg: ");
        if (scanf("%lf", &known_weight) != 1) {
            fprintf(stderr, "Invalid input. Exiting.\n");
            cleanup();
            exit(1);
        }
        calibration_factor = calibrate_load_cell(known_weight);
        // Save the calibration factor to the file
        fp = fopen(CALIBRATION_FILE, "w");
        if (fp != NULL) {
            fprintf(fp, "%lf", calibration_factor);
            fclose(fp);
        } else {
            fprintf(stderr, "Error writing calibration factor to file.\n");
        }
    }

    // Open the security log file
    log_file = fopen(SECURITY_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        exit(1);
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > 1000) { // Timeout after 100ms (1000 us)
            fprintf(stderr, "HX711 timeout: Data pin high for too long.\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low
    }

    // Pulse the clock pin 1 more time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the load cell
double calibrate_load_cell(double known_weight) {
    int raw_value = 0;
    double sum = 0.0;
    int num_readings = 10; // Number of readings to average

    printf("Place the known weight on the load cell.\n");
    gpioDelay(2000); // Wait 2 seconds

    for (int i = 0; i < num_readings; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711 during calibration. Using default calibration.\n");
            return 1.0; // Return default calibration factor
        }
        sum += raw_value;
        gpioDelay(100); // Small delay between readings
    }

    double average_raw = sum / num_readings;
    return average_raw / known_weight;
}

// Function to get the weight from the load cell
double get_weight() {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error reading HX711. Returning previous weight.\n");
        return 0.0; // Return 0.0 to avoid using an invalid value
    }
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log events to the security log file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Unlocking solenoid and exiting.\n");
    running = 0;
    control_solenoid(0); // Unlock the solenoid
    cleanup();
    exit(0);
}

// Function to clean up resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Weight monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = get_weight();
        printf("Weight: %.2f kg\n", weight);

        if (weight > 5.0) {
            log_event(weight);
            control_solenoid(1); // Lock the solenoid
            gpioDelay(5000000); // Wait 5 seconds (5000000 us)
            control_solenoid(0); // Unlock the solenoid
        }

        gpioDelay(100000); // Check every 0.1 seconds (100000 us)
    }

    return 0;
}

