#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define relay states
#define RELAY_ON 1
#define RELAY_OFF 0

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;
static FILE *log_file;
static int relay_state = RELAY_OFF; // Initial relay state

// Function prototypes
int initialize_gpio(void);
int read_sensor(void);
int toggle_relay(int current_state);
int log_event(int relay_state);
void cleanup_gpio(void);
void signal_handler(int signal);

int main(void) {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Check for errors during sensor reading
        if (sensor_value == -1) {
            fprintf(stderr, "Error reading sensor. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Toggle relay if obstacle is detected (sensor value is LOW)
        if (sensor_value == 0) {
            relay_state = toggle_relay(relay_state);
        }

        // Log the event
        if (log_event(relay_state) != 0) {
            fprintf(stderr, "Error logging event. Continuing.\n");
        }

        // Delay to avoid excessive CPU usage
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

// Initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request sensor line as input
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "sensor_monitor";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor_line, &input_config, 0) < 0) {
        perror("Error requesting sensor line as input");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Error getting relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request relay line as output
    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "relay_control";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay_line, &output_config, 0) < 0) {
        perror("Error requesting relay line as output");
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Open log file
    log_file = fopen("relay_events.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Toggle relay state
int toggle_relay(int current_state) {
    int new_state = (current_state == RELAY_ON) ? RELAY_OFF : RELAY_ON;
    if (gpiod_line_set_value(relay_line, new_state) < 0) {
        perror("Error setting relay value");
        return current_state; // Return the original state on error
    }
    return new_state;
}

// Log event to file
int log_event(int relay_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (fprintf(log_file, "%s, Relay State: %s\n", buf, (relay_state == RELAY_ON) ? "ON" : "OFF") < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    printf("Cleaning up GPIO resources...\n");

    // Release lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    cleanup_gpio();
    exit(0);
}

