#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define buzzer activation duration (in seconds)
#define BUZZER_DURATION 2

// Global variables for GPIO lines and chip
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *buzzer_line;

// Global flag to indicate program termination
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_pir_sensor(struct gpiod_line *pir_line);
int activate_buzzer(struct gpiod_line *buzzer_line, int duration_ms);
int log_motion_event(const char *filename);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", sig);
        terminate = 1;

        // Turn off the buzzer
        if (buzzer_line) {
            gpiod_line_set_value(buzzer_line, 0);
        }

        // Release GPIO lines
        if (pir_line) {
            gpiod_line_release(pir_line);
        }
        if (buzzer_line) {
            gpiod_line_release(buzzer_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Function to read the PIR sensor value
int read_pir_sensor(struct gpiod_line *pir_line) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        fprintf(stderr, "Error reading PIR sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer for a specified duration
int activate_buzzer(struct gpiod_line *buzzer_line, int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value to 1\n");
        return -1;
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value to 0\n");
        return -1;
    }
    return 0;
}

// Function to log a motion event with a timestamp
int log_motion_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Motion detected\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_SENSOR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Error getting PIR sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request PIR sensor line as input
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Error requesting PIR sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request buzzer line as output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int pir_value = read_pir_sensor(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor, exiting...\n");
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            if (log_motion_event("motion_log.txt") < 0) {
                fprintf(stderr, "Error logging motion event\n");
            }
            if (activate_buzzer(buzzer_line, BUZZER_DURATION * 1000) < 0) {
                fprintf(stderr, "Error activating buzzer\n");
            }
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup (in case the loop exited due to an error)
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(pir_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}

