#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Constants
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600 // Maximum watering duration in seconds

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Function prototypes
int read_config(const char *filename, int *duration);
int validate_duration(int duration);
int set_gpio_output(int gpio, int value);
int sleep_interruptible(int seconds);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stdout, "\nCaught signal %d, terminating...\n", sig);
}

// Cleanup function to release GPIO resources
void cleanup(void) {
    if (line) {
        set_gpio_output(GPIO_LINE, 0); // Ensure valve is off
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    fprintf(stdout, "Cleanup complete. Valve should be off.\n");
}

// Function to read the watering duration from the configuration file
int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Remove trailing newline character
    line[strcspn(line, "\n")] = 0;

    // Parse the duration value
    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Error: Invalid config file format. Expected 'duration=<seconds>'.\n");
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: Invalid config file format. Expected 'duration=<seconds>'.\n");
        return -1;
    }

    char *endptr;
    long val = strtol(value, &endptr, 10);

    if (*endptr != '\0' || val <= 0 || val > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid duration value. Must be an integer between 1 and %d.\n", MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
