int set_gpio_output(int gpio, int value) {
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0); // Initial value is 0 (valve off)
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", gpio, strerror(-ret));
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value to %d: %s\n", gpio, value, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to sleep with signal handling
int sleep_interruptible(int seconds) {
    struct timespec req, rem;
    req.tv_sec = seconds;
    req.tv_nsec = 0;

    while (nanosleep(&req, &rem) == -1) {
        if (errno == EINTR && terminate) {
            fprintf(stdout, "Sleep interrupted by signal.\n");
            return -1; // Indicate interrupt
        } else if (errno != EINTR) {
            fprintf(stderr, "Error during nanosleep: %s\n", strerror(errno));
            return -1;
        }
        req = rem;
    }
    return 0;
}

