#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_MOTOR_IN1 22
#define LEFT_MOTOR_IN2 23
#define LEFT_MOTOR_PWM 24
#define RIGHT_MOTOR_IN1 25
#define RIGHT_MOTOR_IN2 26
#define RIGHT_MOTOR_PWM 27

#define SENSOR_LEFT 4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT 27

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED (BASE_SPEED / 2)

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio);
void set_motor(int in1, int in2, int pwm, int speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    return (gpioRead(gpio) == 0) ? 1 : 0; // Active low
}

// Function to set motor direction and speed
void set_motor(int in1, int in2, int pwm, int speed) {
    gpioWrite(in1, 1); // Forward
    gpioWrite(in2, 0); // Forward
    gpioPWM(pwm, speed);
}

// Function to stop motors
void stop_motors() {
    gpioWrite(LEFT_MOTOR_IN1, 0);
    gpioWrite(LEFT_MOTOR_IN2, 0);
    gpioPWM(LEFT_MOTOR_PWM, 0);
    gpioWrite(RIGHT_MOTOR_IN1, 0);
    gpioWrite(RIGHT_MOTOR_IN2, 0);
    gpioPWM(RIGHT_MOTOR_PWM, 0);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(SENSOR_LEFT, PI_INPUT);
    gpioSetMode(SENSOR_MIDDLE, PI_INPUT);
    gpioSetMode(SENSOR_RIGHT, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, 1000);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, 1000);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int left_sensor = read_sensor(SENSOR_LEFT);
        int middle_sensor = read_sensor(SENSOR_MIDDLE);
        int right_sensor = read_sensor(SENSOR_RIGHT);

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            // Follow line
            set_motor(LEFT_MOTOR_IN1, LEFT_MOTOR_IN2, LEFT_MOTOR_PWM, left_speed);
            set_motor(RIGHT_MOTOR_IN1, RIGHT_MOTOR_IN2, RIGHT_MOTOR_PWM, right_speed);
        } else if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 1) {
            // Turn right
            set_motor(LEFT_MOTOR_IN1, LEFT_MOTOR_IN2, LEFT_MOTOR_PWM, left_speed);
            set_motor(RIGHT_MOTOR_IN1, RIGHT_MOTOR_IN2, RIGHT_MOTOR_PWM, TURN_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 0) {
            // Turn left
            set_motor(LEFT_MOTOR_IN1, LEFT_MOTOR_IN2, LEFT_MOTOR_PWM, TURN_SPEED);
            set_motor(RIGHT_MOTOR_IN1, RIGHT_MOTOR_IN2, RIGHT_MOTOR_PWM, right_speed);
        } else {
            // Stop
            stop_motors();
        }

        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works)
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

