#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Function to read illuminance from BH1750 sensor
float read_bh1750() {
    char buf[2];
    int result;
    float lux = -1.0f; // Default to error value

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, CONTINUOUS_HIGH_RES_MODE, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        log_data(-1.0f, -1); // Log error
        return -1.0f;
    }

    // Delay for measurement
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        log_data(-1.0f, -1); // Log error
        return -1.0f;
    }

    // Convert to lux
    lux = (float)((buf[0] << 8) | buf[1]) / 1.2f;

    return lux;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state == 1 ? "ON" : (relay_state == 0 ? "OFF" : "ERROR"));
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        log_data(-1.0f, -1); // Log error
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();

        if (lux >= 0) {
            int relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            control_relay(relay_state);
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(1000000); // Check every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Turn off relay
    gpioTerminate();

    printf("Grow lamp control stopped.\n");

    return 0;
}

