#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define servo positions
#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to handle lock button press
void handle_lock_button() {
    printf("Lock button pressed\n");
    set_servo_pulse_width(LOCKED_PULSE_WIDTH);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
}

// Function to handle unlock button press
void handle_unlock_button() {
    printf("Unlock button pressed\n");
    set_servo_pulse_width(UNLOCKED_PULSE_WIDTH);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_button_state = gpioRead(UNLOCK_BUTTON_PIN);

        // Check for button presses
        if (lock_button_state == 0) {
            handle_lock_button();
        }
        if (unlock_button_state == 0) {
            handle_unlock_button();
        }

        gpioDelay(50); // Small delay to prevent busy-waiting
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");

    return 0;
}

