#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define pulse durations (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variables for GPIO lines and chip
static struct gpiod_line *motor1_line = NULL;
static struct gpiod_line *motor2_line = NULL;
static struct gpiod_chip *chip = NULL;

// Signal handler function
static void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (motor1_line) {
        if (gpiod_line_release(motor1_line) < 0) {
            perror("Error releasing motor1_line");
        }
    }
    if (motor2_line) {
        if (gpiod_line_release(motor2_line) < 0) {
            perror("Error releasing motor2_line");
        }
    }

    // Close GPIO chip
    if (chip) {
        if (gpiod_chip_close(chip) < 0) {
            perror("Error closing chip");
        }
    }

    exit(0);
}

int main()
{
    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error registering SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error registering SIGTERM handler");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("Error getting motor1_line");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("Error getting motor2_line");
        goto cleanup;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(motor1_line, "haptic_motor1", 0) < 0) {
        perror("Error requesting motor1_line for output");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, "haptic_motor2", 0) < 0) {
        perror("Error requesting motor2_line for output");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Pulse motor 1
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            perror("Error setting motor1_line value");
            goto cleanup;
        }
        usleep(MOTOR1_DURATION * 1000); // Convert ms to microseconds
        if (gpiod_line_set_value(motor1_line, 0) < 0) {
            perror("Error setting motor1_line value");
            goto cleanup;
        }

        // Pulse motor 2
        if (gpiod_line_set_value(motor2_line, 1) < 0) {
            perror("Error setting motor2_line value");
            goto cleanup;
        }
        usleep(MOTOR2_DURATION * 1000); // Convert ms to microseconds
        if (gpiod_line_set_value(motor2_line, 0) < 0) {
            perror("Error setting motor2_line value");
            goto cleanup;
        }
    }

cleanup:
    // Release GPIO lines and close chip (if not already done)
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

