        if (!zmq_context) {
            fprintf(stderr, "Failed to create ZeroMQ context\n");
            gpioTerminate();
            return 1;
        }

        pub_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (!pub_socket) {
            fprintf(stderr, "Failed to create ZeroMQ publisher socket\n");
            zmq_ctx_destroy(zmq_context);
            gpioTerminate();
            return 1;
        }

        int bind_result = zmq_bind(pub_socket, ZMQ_ENDPOINT);
        if (bind_result != 0) {
            fprintf(stderr, "Failed to bind ZeroMQ socket: %s\n", zmq_strerror(errno));
            zmq_close(pub_socket);
            zmq_ctx_destroy(zmq_context);
            gpioTerminate();
            return 1;
        }

        printf("Sound sensor mode active. Publishing alerts to %s\n", ZMQ_ENDPOINT);

        while (running) {
            int sound_detected = !gpioRead(SOUND_SENSOR_GPIO); // Active-low
            if (sound_detected) {
                // Publish alert
                zmq_msg_t message;
                zmq_msg_init_size(&message, strlen("SOUND_ALERT"));
                memcpy(zmq_msg_data(&message), "SOUND_ALERT", strlen("SOUND_ALERT"));
                int send_result = zmq_msg_send(&message, pub_socket, 0);
                zmq_msg_close(&message);

                if (send_result == -1) {
                    fprintf(stderr, "Failed to send message: %s\n", zmq_strerror(errno));
                    running = 0; // Exit on error
                } else {
                    printf("Published SOUND_ALERT\n");
                }
            }
            gpioDelay(10000); // 10ms
        }

        zmq_close(pub_socket);
        zmq_ctx_destroy(zmq_context);
        gpioTerminate();
        printf("Sound sensor mode exited cleanly.\n");
        return 0;
    } else {
        // Alarm node mode
        zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            fprintf(stderr, "Failed to create ZeroMQ context\n");
            gpioTerminate();
            return 1;
        }

        sub_socket = zmq_socket(zmq_context, ZMQ_SUB);
        if (!sub_socket) {
            fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
            zmq_ctx_destroy(zmq_context);
            gpioTerminate();
            return 1;
        }

        int connect_result = zmq_connect(sub_socket, ZMQ_SUB_ENDPOINT);
        if (connect_result != 0) {
            fprintf(stderr, "Failed to connect ZeroMQ socket: %s\n", zmq_strerror(errno));
            zmq_close(sub_socket);
            zmq_ctx_destroy(zmq_context);
            gpioTerminate();
            return 1;
        }

        int subscribe_result = zmq_setsockopt(sub_socket, ZMQ_SUBSCRIBE, "SOUND_ALERT", strlen("SOUND_ALERT"));
        if (subscribe_result != 0) {
            fprintf(stderr, "Failed to set ZeroMQ subscribe option: %s\n", zmq_strerror(errno));
            zmq_close(sub_socket);
            zmq_ctx_destroy(zmq_context);
            gpioTerminate();
            return 1;
        }

        printf("Alarm node mode active. Subscribing to %s\n", ZMQ_SUB_ENDPOINT);

        while (running) {
            zmq_msg_t message;
            zmq_msg_init(&message);
            int recv_result = zmq_msg_recv(&message, sub_socket, 0);
            if (recv_result == -1) {
                if (errno == EINTR) {
                    // Interrupted by signal, exit gracefully
                    break;
                }
                fprintf(stderr, "Failed to receive message: %s\n", zmq_strerror(errno));
                running = 0; // Exit on error
            } else {
                char *message_data = (char *)zmq_msg_data(&message);
                size_t message_size = zmq_msg_size(&message);

                if (message_size == strlen("SOUND_ALERT") && memcmp(message_data, "SOUND_ALERT", message_size) == 0) {
                    printf("Received SOUND_ALERT, triggering alarm\n");
                    gpioWrite(ALARM_LED_GPIO, 1);
                    gpioDelay(ALARM_DURATION_MS * 1000); // Convert ms to us
                    gpioWrite(ALARM_LED_GPIO, 0);
                }
                zmq_msg_close(&message);
            }
        }

        zmq_close(sub_socket);
        zmq_ctx_destroy(zmq_context);
        gpioTerminate();
        printf("Alarm node mode exited cleanly.\n");
        return 0;
    }
}

