#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100

// NEC timing constants (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// Global variables
static volatile int pulse_count = 0;
static volatile uint32_t pulse_lengths[MAX_PULSES];
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
void pulse_callback(int gpio, int level, uint32_t tick);
int decode_nec(uint32_t *pulses, int pulse_count, uint8_t *address, uint8_t *command);
int publish_mqtt(uint8_t address, uint8_t command);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Callback function for pulse events
void pulse_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_length;

    if (level != PI_TIMEOUT) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < MAX_PULSES) {
            pulse_lengths[pulse_count++] = pulse_length;
        } else {
            syslog(LOG_WARNING, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
        }
    }
}

// Decode NEC IR signal
int decode_nec(uint32_t *pulses, int pulse_count, uint8_t *address, uint8_t *command) {
    if (pulse_count < 34) {
        syslog(LOG_WARNING, "Not enough pulses received: %d", pulse_count);
        return -1;
    }

    // Check for valid header
    if (pulses[0] < NEC_HEADER_MARK * 0.8 || pulses[0] > NEC_HEADER_MARK * 1.2 ||
        pulses[1] < NEC_HEADER_SPACE * 0.8 || pulses[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_WARNING, "Invalid NEC header");
        return -1;
    }

    *address = 0;
    *command = 0;

    // Decode address and command
    for (int i = 2; i < 34; i += 2) {
        if (pulses[i] > NEC_BIT_MARK * 0.8 && pulses[i] < NEC_BIT_MARK * 1.2) {
            if (pulses[i + 1] > NEC_ONE_SPACE * 0.8) {
                if (i < 18) {
                    *address = (*address << 1) | 1;
                } else {
                    *command = (*command << 1) | 1;
                }
            } else if (pulses[i + 1] > NEC_ZERO_SPACE * 0.8) {
                if (i < 18) {
                    *address = (*address << 1) | 0;
                } else {
                    *command = (*command << 1) | 0;
                }
            } else {
                syslog(LOG_WARNING, "Invalid bit space");
                return -1;
            }
        } else {
            syslog(LOG_WARNING, "Invalid bit mark");
            return -1;
        }
    }

    // Validate checksum (not strictly required for standard NEC)
    //uint8_t checksum = (*address ^ *command) & 0xFF;
    //if (checksum != 0) {
    //    syslog(LOG_WARNING, "Checksum mismatch");
    //    return -1;
    //}

    return 0;
}

// Publish decoded command to MQTT broker
int publish_mqtt(uint8_t address, uint8_t command) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"address\":%d,\"command\":%d}", address, command);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }

    syslog(LOG_INFO, "Published: %s", payload);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();

    gpioTerminate();

    closelog();
}

int main() {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialization failed");
        cleanup();
        return 1;
    }

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection failed");
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set alert function for GPIO pin
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    syslog(LOG_INFO, "IR decoder started");

    while (running) {
        if (pulse_count >= 34) {
            uint8_t address, command;
            if (decode_nec((uint32_t *)pulse_lengths, pulse_count, &address, &command) == 0) {
                syslog(LOG_INFO, "Decoded: Address = %d, Command = %d", address, command);
                publish_mqtt(address, command);
            } else {
                syslog(LOG_WARNING, "Decoding failed");
            }
            pulse_count = 0; // Reset pulse count after processing
        }
        usleep(10000); // Sleep for 10ms
    }

    // Cleanup and exit
    mosquitto_loop_stop(mosq, false);
    cleanup();

    return 0;
}

