#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

int i2c_set_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

int bh1750_init(int fd) {
    uint8_t mode = 0x20; // One-Time High-Resolution mode
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

int bh1750_read(int fd, float *lux) {
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;
    return 0;
}

int udp_send(const char *message, const char *addr, int port) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in addrinfo;
    memset(&addrinfo, 0, sizeof(addrinfo));
    addrinfo.sin_family = AF_INET;
    addrinfo.sin_addr.s_addr = inet_addr(addr);
    addrinfo.sin_port = htons(port);

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&addrinfo, sizeof(addrinfo)) < 0) {
        perror("Error sending UDP packet");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fds[NUM_SENSORS];
    int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};
    float lux_values[NUM_SENSORS];

    // Initialize I2C file descriptors
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(I2C_BUS);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to open I2C device for sensor %d\n", i + 1);
            lux_values[i] = NAN; // Set to NaN to indicate failure
        } else {
            if (i2c_set_slave(i2c_fds[i], sensor_addresses[i]) < 0) {
                fprintf(stderr, "Failed to set slave address for sensor %d\n", i + 1);
                lux_values[i] = NAN; // Set to NaN to indicate failure
                close(i2c_fds[i]);
            } else {
                if (bh1750_init(i2c_fds[i]) < 0) {
                    fprintf(stderr, "Failed to initialize sensor %d\n", i + 1);
                    lux_values[i] = NAN; // Set to NaN to indicate failure
                }
            }
        }
    }

    while (!terminate) {
        char message[256] = {0};
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) {
                if (bh1750_read(i2c_fds[i], &lux_values[i]) == 0) {
                    snprintf(message + strlen(message), sizeof(message) - strlen(message), "%d,%.1f;", i + 1, lux_values[i]);
                } else {
                    lux_values[i] = NAN;
                    snprintf(message + strlen(message), sizeof(message) - strlen(message), "%d,NaN;", i + 1);
                }
            } else {
                lux_values[i] = NAN;
                snprintf(message + strlen(message), sizeof(message) - strlen(message), "%d,NaN;", i + 1);
            }
        }

        // Remove trailing semicolon
        if (strlen(message) > 0) {
            message[strlen(message) - 1] = '\0';
        }

        if (udp_send(message, MULTICAST_ADDR, MULTICAST_PORT) < 0) {
            fprintf(stderr, "Failed to send UDP message\n");
        }

        sleep(1);
    }

    // Cleanup
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    return 0;
}

