#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_ADDR 0x28
#define I2C_BUS 1
#define FLOW_SCALE 0.1
#define FLOW_OFFSET 3277
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *raw_flow);
float convert_to_slpm(int raw_flow);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int raw_flow;
    float flow_rate;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(int *raw_flow) {
    char buf[2];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            *raw_flow = ((buf[0] & 0x3F) << 8) | buf[1];
            return 0; // Success
        } else if (bytes_read < 0) {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", bytes_read, retries);
            gpioDelay(100); // 100 ms delay
            retries--;
        } else {
            fprintf(stderr, "I2C read short: %d, retries remaining: %d\n", bytes_read, retries);
            gpioDelay(100); // 100 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw data to SLPM
float convert_to_slpm(int raw_flow) {
    return (raw_flow - FLOW_OFFSET) * FLOW_SCALE;
}

// Log data to file
int log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_flow;
        if (read_sensor_data(&raw_flow) == 0) {
            float flow_rate = convert_to_slpm(raw_flow);
            if (log_data(flow_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Airflow monitoring stopped.\n");
    return 0;
}

