#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_ID_REG 0x24
#define AS7341_ENABLE_REG 0x80
#define AS7341_CFG6_REG 0xAF
#define AS7341_F1_DATA_LSB 0x60
#define AS7341_F1_DATA_MSB 0x61
#define AS7341_F2_DATA_LSB 0x62
#define AS7341_F2_DATA_MSB 0x63
#define AS7341_F3_DATA_LSB 0x64
#define AS7341_F3_DATA_MSB 0x65
#define AS7341_F4_DATA_LSB 0x66
#define AS7341_F4_DATA_MSB 0x67
#define AS7341_F5_DATA_LSB 0x68
#define AS7341_F5_DATA_MSB 0x69
#define AS7341_F6_DATA_LSB 0x6A
#define AS7341_F6_DATA_MSB 0x6B
#define AS7341_F7_DATA_LSB 0x6C
#define AS7341_F7_DATA_MSB 0x6D
#define AS7341_F8_DATA_LSB 0x6E
#define AS7341_F8_DATA_MSB 0x6F
#define AS7341_CLEAR_DATA_LSB 0x70
#define AS7341_CLEAR_DATA_MSB 0x71
#define AS7341_NIR_DATA_LSB 0x72
#define AS7341_NIR_DATA_MSB 0x73

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
}

// Function to write a byte to an AS7341 register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from an AS7341 register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the AS7341 sensor
int initialize_sensor(int handle) {
    uint8_t id;

    // Verify WHO_AM_I/ID register
    if (read_register(handle, AS7341_ID_REG, &id) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }
    if (id != 0x19) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", id);
        return -1;
    }

    // Power on the sensor
    if (write_register(handle, AS7341_ENABLE_REG, 0x03) != 0) {
        fprintf(stderr, "Error powering on sensor.\n");
        return -1;
    }

    // Configure SMUX for spectral readings
    if (write_register(handle, AS7341_CFG6_REG, 0x03) != 0) {
        fprintf(stderr, "Error configuring SMUX.\n");
        return -1;
    }

    // Enable spectral measurement
    if (write_register(handle, AS7341_ENABLE_REG, 0x03) != 0) {
        fprintf(stderr, "Error enabling spectral measurement.\n");
        return -1;
    }

    return 0;
}

// Function to read spectral data from the AS7341
int read_spectral_data(int handle, uint16_t spectral_data[10]) {
    uint8_t lsb, msb;

    // F1
    if (read_register(handle, AS7341_F1_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F1_DATA_MSB, &msb) != 0) return -1;
    spectral_data[0] = ((uint16_t)msb << 8) | lsb;

    // F2
    if (read_register(handle, AS7341_F2_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F2_DATA_MSB, &msb) != 0) return -1;
    spectral_data[1] = ((uint16_t)msb << 8) | lsb;

    // F3
    if (read_register(handle, AS7341_F3_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F3_DATA_MSB, &msb) != 0) return -1;
    spectral_data[2] = ((uint16_t)msb << 8) | lsb;

    // F4
    if (read_register(handle, AS7341_F4_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F4_DATA_MSB, &msb) != 0) return -1;
    spectral_data[3] = ((uint16_t)msb << 8) | lsb;

    // F5
    if (read_register(handle, AS7341_F5_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F5_DATA_MSB, &msb) != 0) return -1;
    spectral_data[4] = ((uint16_t)msb << 8) | lsb;

    // F6
    if (read_register(handle, AS7341_F6_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F6_DATA_MSB, &msb) != 0) return -1;
    spectral_data[5] = ((uint16_t)msb << 8) | lsb;

    // F7
    if (read_register(handle, AS7341_F7_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F7_DATA_MSB, &msb) != 0) return -1;
    spectral_data[6] = ((uint16_t)msb << 8) | lsb;

    // F8
    if (read_register(handle, AS7341_F8_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_F8_DATA_MSB, &msb) != 0) return -1;
    spectral_data[7] = ((uint16_t)msb << 8) | lsb;

    // Clear
    if (read_register(handle, AS7341_CLEAR_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_CLEAR_DATA_MSB, &msb) != 0) return -1;
    spectral_data[8] = ((uint16_t)msb << 8) | lsb;

    // NIR
    if (read_register(handle, AS7341_NIR_DATA_LSB, &lsb) != 0) return -1;
    if (read_register(handle, AS7341_NIR_DATA_MSB, &msb) != 0) return -1;
    spectral_data[9] = ((uint16_t)msb << 8) | lsb;

    return 0;
}

// Function to calculate a simplified lux value (replace with a proper formula)
float calculate_lux(uint16_t spectral_data[10]) {
    // This is a placeholder; replace with a proper lux calculation
    // based on the spectral data.
    // For example, you might use a lookup table or a formula.
    // This example just returns the average of the first 8 channels.
    float sum = 0.0f;
    for (int i = 0; i < 8; i++) {
        sum += spectral_data[i];
    }
    return sum / 8.0f;
}

// Function to log the spectral data and lux value to a file
int log_data(FILE *file, uint16_t spectral_data[10], float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s", timestamp);
    for (int i = 0; i < 10; i++) {
        fprintf(file, ",%u", spectral_data[i]);
    }
    fprintf(file, ",%.2f\n", lux);
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    uint16_t spectral_data[10];
    float lux;

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(i2c_handle, spectral_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(spectral_data);

            // Log data
            log_data(log_file, spectral_data, lux);
        } else {
            fprintf(stderr, "Error reading spectral data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

