int i2c_address = DEFAULT_I2C_ADDRESS;
int interval = DEFAULT_INTERVAL;
char *filename = DEFAULT_FILENAME;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int handle, uint8_t reg, char *buf, int len);
int i2c_write_byte(int handle, uint8_t reg, uint8_t val);
float convert_to_g(int16_t raw);
void log_data(float x, float y, float z);
void log_error(const char *message);
void signal_handler(int signal);
