// I2C read function with retry and timeout
int i2c_read_bytes(int handle, uint8_t reg, char *buf, int len) {
    int retries = RETRY_COUNT;
    int result;
    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, buf, len);
        if (result >= 0) {
            return result;
        } else {
            log_error("I2C read failed, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }
    log_error("I2C read failed after multiple retries.");
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int retries = RETRY_COUNT;
    int result;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, val);
        if (result == 0) {
            return 0; // Success
        } else {
            log_error("I2C write failed, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
        }
    }
    log_error("I2C write failed after multiple retries.");
    return -1; // Indicate failure
}

