        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        fclose(data_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        char raw_data[6];
        int16_t x, y, z;

        // Read sensor data
        if (i2c_read_bytes(i2c_handle, 0x28, raw_data, 6) >= 0) {
            // Convert raw data to g
            x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
            y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
            z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

