        } else {
            log_error("Failed to read sensor data.");
        }

        // Wait for the specified interval
        sleep(interval);
    }

    // Cleanup
    fclose(data_file);
    fclose(error_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

