#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define POWER_ON 0x01
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

void cleanup(int signal) {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Power on
    if (write(i2c_fd, &POWER_ON, 1) != 1) {
        perror("Error writing power on command");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Set continuous high resolution mode
    if (write(i2c_fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Error writing continuous high resolution mode command");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_bh1750(uint16_t *raw_value) {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set TTL for multicast
    int ttl_val = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl_val, sizeof(ttl_val)) < 0) {
        perror("Error setting TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    while (1) {
        uint16_t raw_value;
        if (read_bh1750(&raw_value) == 0) {
            float lux = convert_to_lux(raw_value);
            if (send_udp_multicast(lux) != 0) {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor. Retrying in 1 second.\n");
        }

        sleep(1);
    }

    return 0;
}

