#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_1 0x0204
#define MAGIC_WORD_2 0x0306
#define MAGIC_WORD_3 0x0805
#define MAGIC_WORD_4 0x0709
#define MAX_BUFFER_SIZE 2048
#define CSV_FILE "radar_data.csv"

int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int read_uart_data(int handle, char *buffer, int max_size) {
    int bytes_read = 0;
    int total_bytes = 0;
    char temp_buffer[256];

    while (total_bytes < max_size && !terminate) {
        int result = serRead(handle, temp_buffer, sizeof(temp_buffer));
        if (result > 0) {
            if (total_bytes + result > max_size) {
                result = max_size - total_bytes;
            }
            memcpy(buffer + total_bytes, temp_buffer, result);
            total_bytes += result;
        } else if (result < 0) {
            fprintf(stderr, "Error reading from UART: %d\n", result);
            return -1; // Indicate UART read error
        } else {
            // No data available, wait a bit
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    return total_bytes;
}

int parse_tlv_data(const char *buffer, int buffer_size, FILE *csv_file) {
    int offset = 0;
    while (offset < buffer_size - 8) {
        unsigned short type = *((unsigned short *)(buffer + offset));
        unsigned short length = *((unsigned short *)(buffer + offset + 2));

        if (offset + 8 + length > buffer_size) {
            fprintf(stderr, "TLV length exceeds buffer size. Skipping.\n");
            return -1; // Indicate malformed frame
        }

        if (type == 1) { // Object data TLV
            if (length % 16 != 0) {
                fprintf(stderr, "Object data TLV length is not a multiple of 16. Skipping.\n");
                offset += 8 + length; // Move to the next TLV
                continue;
            }

            int num_objects = length / 16;
            for (int i = 0; i < num_objects; i++) {
                float range = *((float *)(buffer + offset + 8 + i * 16));
                float velocity = *((float *)(buffer + offset + 8 + i * 16 + 4));

                // Data Validation
                if (range < 0 || range > 100) { // Example range validation
                    fprintf(stderr, "Invalid range value: %f. Skipping object.\n", range);
                    continue;
                }
                if (velocity < -10 || velocity > 10) { // Example velocity validation
                    fprintf(stderr, "Invalid velocity value: %f. Skipping object.\n", velocity);
                    continue;
                }

                // Write to CSV file
                time_t now = time(NULL);
                fprintf(csv_file, "%ld,%d,%.2f,%.2f\n", now, i, range, velocity);
                fflush(csv_file);
            }
        }

        offset += 8 + length;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", UART_DEVICE);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", CSV_FILE);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char buffer[MAX_BUFFER_SIZE];
    int buffer_offset = 0;
    int magic_word_index = 0;
    unsigned char magic_word[4] = {MAGIC_WORD_1, MAGIC_WORD_2, MAGIC_WORD_3, MAGIC_WORD_4};

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        int bytes_read = read_uart_data(uart_handle, buffer + buffer_offset, MAX_BUFFER_SIZE - buffer_offset);
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        buffer_offset += bytes_read;

        // Synchronization and TLV parsing
        int i = 0;
        while (i < buffer_offset - 8) {
            if (buffer[i] == magic_word[magic_word_index]) {
                magic_word_index++;
                if (magic_word_index == 4) {
                    // Magic word found, parse TLV data
                    if (parse_tlv_data(buffer + i - 3, buffer_offset - (i - 3), csv_file) == 0) {
                        // TLV parsing successful, reset buffer and magic word index
                        buffer_offset -= (i - 3);
                        memmove(buffer, buffer + i - 3, buffer_offset);
                        magic_word_index = 0;
                    } else {
                        // Malformed frame, reset buffer and magic word index
                        buffer_offset -= i;
                        memmove(buffer, buffer + i, buffer_offset);
                        magic_word_index = 0;
                    }
                    break; // Exit inner loop and continue with outer loop
                }
            } else {
                magic_word_index = 0;
            }
            i++;
        }

        if (i == buffer_offset - 8) {
            // No magic word found, reset buffer and magic word index
            buffer_offset = 0;
            magic_word_index = 0;
        }
    }

    fprintf(stderr, "Terminating program...\n");

    serClose(uart_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

