#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 2000
#define INTERBYTE_TIMEOUT_MS 500
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int uart_init(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 0;                             // Inter-byte timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_line(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = 0;
    char c;
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_MS / 1000;
    timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("Error in select");
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return 0; // Timeout
    }

    while (bytes_read < buffer_size - 1) {
        ssize_t ret = read(fd, &c, 1);
        if (ret == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, break the loop
                break;
            }
            perror("Error reading from UART");
            return -1;
        } else if (ret == 0) {
            // End of file, break the loop
            break;
        }

        buffer[bytes_read++] = c;
        if (c == '\n') {
            break;
        }
    }

    buffer[bytes_read] = '\0';
    return bytes_read;
}

int parse_data(const char *line, time_t *timestamp, float *range) {
    char *token;
    char *str = strdup(line); // Duplicate the string for strtok
    if (str == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(str, ",");
    if (token == NULL) {
        fprintf(stderr, "Invalid data format: missing timestamp\n");
        free(str);
        return -1;
    }
    *timestamp = atoi(token);

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Invalid data format: missing range\n");
        free(str);
        return -1;
    }
    *range = strtof(token, NULL);

    free(str);
    return 0;
}

int log_detection(time_t timestamp, float range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
    return 0;
}

int main() {
    char buffer[BUFFER_SIZE];
    time_t timestamp;
    float range;
    int bytes_read;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = uart_init(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART initialized. Reading data...\n");

    while (program_running) {
        bytes_read = read_line(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (parse_data(buffer, &timestamp, &range) == 0) {
                log_detection(timestamp, range);
            } else {
                fprintf(stderr, "Failed to parse data: %s", buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            sleep(1); // Wait before retrying
        }
    }

    close(uart_fd);
    printf("UART port closed. Exiting.\n");
    return EXIT_SUCCESS;
}

