            if (parse_data(buffer, &timestamp, &range) == 0) {
                log_detection(timestamp, range);
            } else {
                fprintf(stderr, "Failed to parse data: %s", buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            sleep(1); // Wait before retrying
        }
    }

    close(uart_fd);
    printf("UART port closed. Exiting.\n");
    return EXIT_SUCCESS;
}

