#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define serial port
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables
int serial_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio);
void emergency_stop();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to handle emergency stop
void emergency_stop() {
    printf("EMERGENCY STOP!\n");
    const char *message = "EMERGENCY STOP!\n";
    int bytes_written = write(serial_handle, message, strlen(message));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to serial port: %d\n", bytes_written);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Open serial port
    serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for default flags
    if (serial_handle < 0) {
        fprintf(stderr, "Error opening serial port: %d\n", serial_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, continuing...\n");
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log sensor states
        printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left_value, middle_value, right_value);

        // Check for emergency stop condition
        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            emergency_stop();
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Close serial port and terminate pigpio
    serClose(serial_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

